INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f008ec60-f295-5377-a02f-a6912555e0f0','Oscillogram','A graph of a signal''s instantaneous amplitude plotted against time, in which the horizontal axis is time and the vertical axis is amplitude such as voltage, sound pressure, or sample value. It shows the actual shape of the waveform cycle by cycle and is the classic display produced by an oscilloscope or an equivalent software trace.','An oscillogram is a picture of a signal over time. Time runs left to right. Height shows the signal level. It shows the exact shape of the wave. An oscilloscope makes this kind of picture.','It lets a technician see the exact shape and timing of a signal directly, rather than inferring it from a meter reading.','Engineers read oscillograms on oscilloscopes and in DAW zoom views to check waveshape, clipping, timing, and glitches at the sample level.','Sound Visualization & Acoustic Imaging',ARRAY['Waveform','Time-domain display','Oscilloscope','Amplitude','Peak waveform']::text[],ARRAY['Confusing an oscillogram with a spectrum, which shows frequency rather than time','Reading amplitude as loudness without accounting for level scaling','Assuming the trace shows every cycle when the time base is too coarse to resolve them']::text[],ARRAY['Checking a sine tone for clipping on a bench oscilloscope','Zooming into a DAW clip to inspect a click at one sample','Comparing the rise time of two pulses on screen']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Oscillogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f008ec60-f295-5377-a02f-a6912555e0f0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f008ec60-f295-5377-a02f-a6912555e0f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f008ec60-f295-5377-a02f-a6912555e0f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd21c72c5-709f-51c9-a724-7550d19a529a','Time-domain display','Any visualization in which the horizontal axis represents time and the vertical axis represents an instantaneous quantity such as amplitude, sound pressure, voltage, or displacement. It presents how a signal evolves moment to moment, as opposed to a frequency-domain display that presents how energy is distributed across frequency.','A time-domain display shows a signal as time passes. Time goes across the screen. The up-and-down axis shows the level. It tells you what happens and when. It is the opposite of a frequency view.','It reveals timing, level changes, and the overall shape of events, which are hard to read from a frequency plot alone.','Waveform editors, oscilloscopes, and level-versus-time meters are time-domain displays used to edit, align, and troubleshoot audio.','Sound Visualization & Acoustic Imaging',ARRAY['Frequency-domain display','Oscillogram','Waveform','Amplitude envelope','Impulse response plot']::text[],ARRAY['Treating the time axis and frequency axis as interchangeable','Expecting to identify pitch or timbre directly from a raw time plot','Ignoring that a very short window hides slow level changes']::text[],ARRAY['Aligning two drum tracks by eye in an editor','Watching level rise and fall during a fade','Locating a dropout by scrubbing along the time axis']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-domain display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd21c72c5-709f-51c9-a724-7550d19a529a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d21c72c5-709f-51c9-a724-7550d19a529a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d21c72c5-709f-51c9-a724-7550d19a529a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab05abd0-9c81-599e-a446-afb5e1446ee5','Amplitude envelope','The smooth curve that traces the overall amplitude of a signal over time, following the peaks of the waveform rather than each individual cycle. It describes how loudness or level rises and falls across an event, and can be estimated by peak or RMS following or by the magnitude of the analytic signal from a Hilbert transform.','The amplitude envelope is the outline of a wave''s loudness. It follows the tops of the wave, not every wiggle. It shows how a sound swells and fades. A note''s attack and decay live in the envelope.','It captures the shape of loudness over time, which drives how we perceive attack, sustain, and decay independent of the fine waveform detail.','Compressors, gates, and synthesizer envelope generators act on the amplitude envelope; editors draw it to show clip dynamics.','Sound Visualization & Acoustic Imaging',ARRAY['Waveform','RMS waveform','Peak waveform','Attack time','Dynamic range']::text[],ARRAY['Confusing the envelope, which is slow, with the fast carrier waveform underneath it','Assuming a peak envelope and an RMS envelope look the same','Reading the envelope as frequency content rather than level']::text[],ARRAY['Setting a compressor to follow a vocal''s loudness swells','Designing an ADSR shape for a synth patch','Spotting a track''s quiet section from its envelope outline']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Amplitude envelope');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab05abd0-9c81-599e-a446-afb5e1446ee5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab05abd0-9c81-599e-a446-afb5e1446ee5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab05abd0-9c81-599e-a446-afb5e1446ee5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a6b3944-3245-5c14-9ccd-d214fc22c10c','Peak waveform','A waveform display in which each drawn point represents the maximum absolute sample value within a small block of samples, so the outline follows the signal''s peaks. Editors compute one peak per pixel column from an overview file, letting a whole clip be drawn quickly while still showing the highest excursions that matter for clipping.','A peak waveform shows the loudest points of a signal. The editor looks at a small chunk of samples. It draws the biggest one as the height. This makes a fast picture of the whole clip. It highlights where the signal is strongest.','It shows the highest signal excursions at a glance, which is what matters for headroom and clipping, and it lets long files draw quickly.','DAWs and audio editors draw peak waveforms for clips so engineers can spot loud transients and clipping while navigating.','Sound Visualization & Acoustic Imaging',ARRAY['Waveform','RMS waveform','Waveform overview','Amplitude envelope','Clipping']::text[],ARRAY['Reading peak height as perceived loudness, which tracks RMS more than peaks','Assuming the peak outline shows every sample rather than block maxima','Missing brief overloads hidden between drawn columns at a coarse zoom']::text[],ARRAY['Finding a transient overload in a recorded take','Trimming a clip''s edges at its loudest point','Checking headroom before mastering']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Peak waveform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a6b3944-3245-5c14-9ccd-d214fc22c10c','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a6b3944-3245-5c14-9ccd-d214fc22c10c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a6b3944-3245-5c14-9ccd-d214fc22c10c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '621c82d9-0e85-565d-be68-e61ce7633d5a','RMS waveform','A waveform or envelope display in which each drawn value is the root-mean-square level of the samples in a short window, rather than their peak. Because RMS reflects average power, an RMS waveform tracks perceived loudness more closely than a peak waveform and appears smoother, with a smaller crest above it representing the peak-to-RMS difference.','An RMS waveform shows a signal''s average power. It squares the samples, averages them, then takes the square root. This value tracks loudness better than peaks do. The picture looks smoother than a peak waveform. The gap to the peaks shows the crest factor.','It gives a loudness-related view of level over time, useful where average power, not the single highest sample, is what matters.','Loudness meters, mastering editors, and dynamics displays use RMS waveforms to gauge how loud a section actually sounds.','Sound Visualization & Acoustic Imaging',ARRAY['Peak waveform','Amplitude envelope','Crest factor','Root mean square','Loudness']::text[],ARRAY['Confusing RMS level with peak level when setting gain','Forgetting that RMS depends on the chosen window length','Treating RMS as identical to standardized loudness such as LUFS']::text[],ARRAY['Comparing the loudness of two mixes by their RMS outline','Estimating crest factor from the peak-to-RMS gap','Setting a compressor threshold against average level']::text[],'intermediate','x_rms = √( (1/N) · Σ_{n=0}^{N-1} x[n]² )','The root-mean-square value equals the square root of the average of the squared sample values taken over the window.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RMS waveform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '621c82d9-0e85-565d-be68-e61ce7633d5a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='621c82d9-0e85-565d-be68-e61ce7633d5a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='621c82d9-0e85-565d-be68-e61ce7633d5a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4760ec0d-20fc-5367-ab0b-16689714a124','Rectified waveform','A waveform that has been processed so that its sign is removed, folding it onto one side of the zero axis. Full-wave rectification takes the absolute value of every sample, while half-wave rectification keeps positive values and sets negatives to zero. Rectification is a first step in many envelope followers and amplitude-analysis displays.','A rectified waveform has its negative part flipped or removed. Full-wave rectifying takes the absolute value of each sample. Half-wave rectifying keeps only the positive half. The result sits on one side of zero. It is a first step in finding an envelope.','It converts a bipolar signal into a one-sided form whose average or smoothed value tracks amplitude, which is how many envelope followers begin.','Envelope followers in compressors, meters, and analog level detectors rectify the signal before smoothing it into a control voltage.','Sound Visualization & Acoustic Imaging',ARRAY['Amplitude envelope','Envelope follower','Absolute value','Full-wave rectification','Peak waveform']::text[],ARRAY['Confusing full-wave rectification with half-wave rectification','Assuming rectification alone gives the envelope without smoothing','Forgetting that rectification adds harmonics and a DC offset']::text[],ARRAY['Building an envelope follower for a compressor sidechain','Deriving a control signal from an audio input','Explaining how an analog level meter senses amplitude']::text[],'intermediate','full-wave: y(t) = |x(t)|;  half-wave: y(t) = max(x(t), 0)','Full-wave rectification outputs the absolute value of the signal; half-wave rectification keeps the positive part and replaces negative values with zero.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rectified waveform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4760ec0d-20fc-5367-ab0b-16689714a124','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4760ec0d-20fc-5367-ab0b-16689714a124') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4760ec0d-20fc-5367-ab0b-16689714a124');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4803ec55-014d-5b26-925e-491489a5c5a6','Zero crossing display','A visual indication of the points where a waveform crosses the zero-amplitude axis, changing sign. Editors highlight or snap to zero crossings so that cuts, loops, and joins occur where the signal is momentarily zero, which avoids the discontinuities that produce clicks. Zero-crossing spacing also relates to a signal''s dominant frequency.','A zero crossing is where a wave passes through zero. The signal changes from plus to minus there, or the reverse. Editors mark these points. Cutting or looping at a zero crossing avoids clicks. The rate of crossings hints at pitch.','It marks safe edit points where the signal is zero, so splices and loops do not create the step changes that cause audible clicks.','Sample editors snap loop points and edits to zero crossings; zero-crossing rate is also used as a simple feature in analysis.','Sound Visualization & Acoustic Imaging',ARRAY['Waveform','Click','Loop point','Zero-crossing rate','Discontinuity']::text[],ARRAY['Assuming any zero crossing is click-free regardless of slope or DC offset','Confusing zero-crossing rate with true pitch detection','Editing at a zero crossing on one channel only in a stereo file']::text[],ARRAY['Snapping a loop start and end to zero crossings','Making a clickless cut between two takes','Using zero-crossing rate to flag noisy versus tonal frames']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Zero crossing display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4803ec55-014d-5b26-925e-491489a5c5a6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4803ec55-014d-5b26-925e-491489a5c5a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4803ec55-014d-5b26-925e-491489a5c5a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dbcda9f2-60ab-5fd7-b73d-f7ced7115451','Waveform overview','A compressed, whole-file waveform drawing used for navigation, typically built from a precomputed overview or peak file that stores block minima and maxima so a long recording can be shown at once. It trades sample-accurate detail for speed, giving a map of where loud and quiet regions sit across the timeline.','A waveform overview shows a whole file at once. The editor builds a smaller summary of the audio first. That lets it draw a long file fast. You lose fine detail but gain a map. It shows where loud and quiet parts are.','It gives a fast, zoomed-out map of a recording so an operator can navigate to regions of interest without redrawing every sample.','Editors and restoration tools show a waveform overview above the main view so users can scroll and locate sections quickly.','Sound Visualization & Acoustic Imaging',ARRAY['Peak waveform','Waveform','Time-domain display','Spectrogram','Overview file']::text[],ARRAY['Expecting sample-accurate detail from a compressed overview','Confusing the overview strip with the zoomed working view','Assuming a stale overview file matches edited audio']::text[],ARRAY['Scrolling to a chorus in a long song file','Locating a gap between spoken segments','Navigating a long field recording during restoration']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Waveform overview');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dbcda9f2-60ab-5fd7-b73d-f7ced7115451','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dbcda9f2-60ab-5fd7-b73d-f7ced7115451') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dbcda9f2-60ab-5fd7-b73d-f7ced7115451');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b1e59d62-2c37-5448-b42c-97707dc43a94','Phase waveform','A time-domain display used to compare the relative timing and polarity of two related signals, such as the left and right channels of a stereo pair, by overlaying their waveforms or showing their difference. Alignment of the traces indicates similar phase, while opposition or offset reveals polarity inversion or time delay between the signals.','A phase waveform compares two signals over time. It overlays their shapes or shows the difference. If the traces line up, they are in phase. If one is flipped, polarity is reversed. An offset shows a time delay.','It exposes timing and polarity relationships between channels that a single waveform cannot show, helping catch cancellation before it reaches a mono sum.','Engineers overlay channel waveforms to spot polarity flips and delays when aligning microphones or checking a stereo file for mono compatibility.','Sound Visualization & Acoustic Imaging',ARRAY['Polarity','Phase','Stereo image display','Comb-filter display','Lissajous figure']::text[],ARRAY['Confusing polarity inversion with a phase shift that varies by frequency','Assuming aligned waveforms guarantee mono compatibility at all frequencies','Reading a pure time delay as a fixed polarity error']::text[],ARRAY['Checking two drum-mic tracks for polarity before summing','Diagnosing weak bass in a mono fold-down','Aligning a DI and a miked amp track']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase waveform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b1e59d62-2c37-5448-b42c-97707dc43a94','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b1e59d62-2c37-5448-b42c-97707dc43a94') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b1e59d62-2c37-5448-b42c-97707dc43a94');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1198f674-d967-54c4-b60c-8259909fa870','Lissajous figure','The closed curve traced when two sinusoidal signals drive the horizontal and vertical axes of an X/Y display. Its shape depends on the ratio of the two frequencies and their phase difference: equal frequencies produce a line, ellipse, or circle, while integer frequency ratios produce looped patterns. In audio it is used to view the relationship between left and right channels.','A Lissajous figure is a shape made by two signals. One signal moves the dot sideways. The other moves it up and down. Their frequencies and phase set the shape. In audio it shows the link between left and right.','It reveals the frequency ratio, phase, and correlation between two signals in one shape, which is why audio goniometers use it to show stereo behavior.','Audio goniometers and oscilloscope X/Y modes draw Lissajous figures to judge stereo width, correlation, and phase in mixing and mastering.','Sound Visualization & Acoustic Imaging',ARRAY['Goniometer','Vectorscope','X/Y display','Stereo image display','Phase']::text[],ARRAY['Reading a tilted line as a problem when it only shows a level or pan imbalance','Confusing a phase relationship with an outright polarity inversion','Assuming the figure shows frequency content like a spectrum']::text[],ARRAY['Judging stereo width on a mixing goniometer','Spotting an out-of-phase channel as a horizontal line','Matching two oscillator frequencies on a scope']::text[],'intermediate','x(t) = A·sin(a·t + δ),  y(t) = B·sin(b·t)','The horizontal position is one sine wave and the vertical position is another; the ratio of their frequencies and the phase offset between them set the figure''s shape.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lissajous figure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1198f674-d967-54c4-b60c-8259909fa870','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1198f674-d967-54c4-b60c-8259909fa870') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1198f674-d967-54c4-b60c-8259909fa870');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c69b59c-4cbb-5c38-afd7-41fa29196d9b','Vectorscope','An audio vectorscope is an X/Y instrument that plots the left and right channels against each other, usually rotated so mono content appears as a vertical line, to show stereo width, balance, and phase correlation. A dense vertical trace indicates strong mono compatibility, a tilt indicates imbalance, and a horizontal spread warns of out-of-phase energy.','An audio vectorscope shows a stereo signal as a shape. It plots left against right on a screen. Mono content shows as a vertical line. A sideways spread warns of phase problems. It helps judge width and balance.','It gives a quick visual read on stereo width, balance, and phase correlation, so engineers can catch cancellation risks before a mono sum.','Broadcast, mastering, and post engineers watch a vectorscope to keep a mix mono-compatible and correctly balanced.','Sound Visualization & Acoustic Imaging',ARRAY['Goniometer','Lissajous figure','Correlation meter','Stereo image display','Phase']::text[],ARRAY['Confusing the audio vectorscope with the video vectorscope used for color','Assuming a wide display always sounds better rather than risking phase issues','Ignoring the correlation reading while watching only the shape']::text[],ARRAY['Checking a master for mono compatibility before broadcast','Balancing left and right energy in a mix','Spotting an out-of-phase reverb return']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vectorscope');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c69b59c-4cbb-5c38-afd7-41fa29196d9b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c69b59c-4cbb-5c38-afd7-41fa29196d9b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c69b59c-4cbb-5c38-afd7-41fa29196d9b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd37d4a5f-6d2a-5bfb-8932-cd7c44dc739b','Stereo image display','Any visualization that represents the width, balance, and phase relationship of a stereo signal, showing how energy is distributed between and across the left and right channels. Implementations include goniometers, correlation meters, and balance or width indicators, often combined to convey both the spread of the image and its mono compatibility.','A stereo image display shows how wide a mix is. It shows the balance between left and right. It can also show phase between the channels. Some use a shape, others use meters. Together they show spread and mono safety.','It makes the spatial layout of a stereo mix visible, helping engineers set width and balance and avoid phase problems in a mono sum.','Mixing and mastering plug-ins present stereo image displays so engineers can monitor width, centering, and correlation while working.','Sound Visualization & Acoustic Imaging',ARRAY['Vectorscope','Goniometer','Correlation meter','Phase','Stereo width']::text[],ARRAY['Assuming a wider image is always better regardless of mono compatibility','Confusing a level imbalance with a phase problem','Trusting the display over listening on multiple systems']::text[],ARRAY['Setting stereo width on a mastering bus','Checking that a lead vocal sits centered','Monitoring correlation while adding a stereo effect']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stereo image display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd37d4a5f-6d2a-5bfb-8932-cd7c44dc739b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d37d4a5f-6d2a-5bfb-8932-cd7c44dc739b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d37d4a5f-6d2a-5bfb-8932-cd7c44dc739b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a4e4421-04d9-5fc0-9118-1c1663ed197f','Polar display','A visualization that plots a quantity on a circular, radial grid, where angle represents direction or phase and radius represents magnitude. In audio it commonly shows a microphone''s or loudspeaker''s directional response, the polar pattern, but the same format is used to display phase or the angular distribution of stereo energy.','A polar display uses a round grid. The angle shows direction or phase. The distance from the center shows level. It often shows how a mic picks up sound from each direction. The same grid can show stereo energy by angle.','It presents direction- or angle-dependent data in one round picture, which is the natural way to show how response varies with direction.','Microphone and loudspeaker datasheets use polar plots for directional response; some meters show stereo energy on a polar grid.','Sound Visualization & Acoustic Imaging',ARRAY['Polar pattern','Directivity','Goniometer','Microphone','Phase']::text[],ARRAY['Confusing a polar pattern for a fixed shape when it changes with frequency','Misreading the radial scale, which is often in decibels, as linear','Assuming the plot covers all planes when it shows only one']::text[],ARRAY['Comparing cardioid and omni patterns from a mic spec sheet','Checking a loudspeaker''s coverage angle by frequency','Viewing stereo energy spread on a polar meter']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a4e4421-04d9-5fc0-9118-1c1663ed197f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a4e4421-04d9-5fc0-9118-1c1663ed197f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a4e4421-04d9-5fc0-9118-1c1663ed197f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '22ea9c55-d828-5afc-a1d5-a328fddc809c','X/Y display','A two-axis display mode in which one signal drives the horizontal deflection and a second signal drives the vertical deflection, so the plotted point shows the instantaneous relationship between the two signals rather than either one against time. In audio it is the basis of goniometers and Lissajous displays used to compare stereo channels.','An X/Y display uses two signals at once. One moves the dot sideways. The other moves it up and down. The dot shows how the two signals relate. It is the basis of stereo goniometers.','It shows the moment-to-moment relationship between two signals directly, which time-versus-amplitude plots cannot, revealing phase and correlation.','Oscilloscopes and audio goniometers use X/Y mode to compare left and right channels and to draw Lissajous figures.','Sound Visualization & Acoustic Imaging',ARRAY['Lissajous figure','Goniometer','Vectorscope','Oscilloscope','Phase']::text[],ARRAY['Expecting a time axis when both axes carry signals instead','Confusing the X/Y plot with a normal amplitude-versus-time trace','Ignoring channel gain, which stretches the figure and misleads width reading']::text[],ARRAY['Switching a scope to X/Y mode to view two signals','Comparing left and right channels on a goniometer','Matching two oscillator frequencies visually']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='X/Y display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '22ea9c55-d828-5afc-a1d5-a328fddc809c','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='22ea9c55-d828-5afc-a1d5-a328fddc809c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='22ea9c55-d828-5afc-a1d5-a328fddc809c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '97c214c7-8794-54ed-b9b6-87faff9db08f','Frequency-domain display','A visualization in which the horizontal axis represents frequency and the vertical axis represents the amount of energy, magnitude, or power at each frequency. It shows how a signal''s content is distributed across the spectrum at an instant or on average, complementing the time-domain view obtained through a Fourier transform.','A frequency-domain display shows a signal by pitch content. Frequency runs across the screen. Height shows how much energy sits at each frequency. It answers what tones are present. It is the partner of the time view.','It reveals which frequencies a signal contains and how strong each is, information that a time-domain waveform hides.','Spectrum analyzers and EQ displays are frequency-domain views used to find tones, noise, resonances, and tonal balance.','Sound Visualization & Acoustic Imaging',ARRAY['Time-domain display','Spectrum','FFT analyzer','Spectral display','Fourier transform']::text[],ARRAY['Confusing the frequency axis with a time axis','Assuming the display shows loudness rather than energy per frequency','Forgetting that the view is an average over an analysis window']::text[],ARRAY['Finding a hum frequency in a recording','Checking tonal balance across a mix','Locating a room resonance during tuning']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-domain display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '97c214c7-8794-54ed-b9b6-87faff9db08f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='97c214c7-8794-54ed-b9b6-87faff9db08f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='97c214c7-8794-54ed-b9b6-87faff9db08f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '241c4ac9-4b4e-5b22-a988-24f5735b6c3d','Real-time analyzer','A spectrum analyzer that displays the energy of an incoming signal across frequency and updates continuously as the signal changes, classically using a bank of octave or fractional-octave band filters, or an equivalent FFT computation. It gives a live picture of spectral balance for sound-system tuning and monitoring.','A real-time analyzer shows a live spectrum. It splits sound into frequency bands. It updates the display as the sound changes. Engineers call it an RTA. It helps tune a sound system by ear and eye.','It provides a live, continuously updating view of spectral balance so an operator can adjust a system while it is running.','Sound engineers use an RTA with a measurement mic to check tonal balance and set graphic EQ during system tuning.','Sound Visualization & Acoustic Imaging',ARRAY['FFT analyzer','Fractional-octave band','Spectrum','Pink noise','Frequency-domain display']::text[],ARRAY['Reading raw RTA bumps as EQ problems without accounting for the room and mic','Confusing constant-percentage octave bands with fixed-width FFT bins','Chasing a flat RTA trace instead of trusting a target curve and listening']::text[],ARRAY['Tuning a PA with pink noise and a measurement mic','Watching band levels during a live show','Setting a graphic EQ to a house target curve']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Real-time analyzer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '241c4ac9-4b4e-5b22-a988-24f5735b6c3d','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='241c4ac9-4b4e-5b22-a988-24f5735b6c3d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='241c4ac9-4b4e-5b22-a988-24f5735b6c3d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0349264-1114-5626-b224-d80ea4709db5','FFT analyzer','An analyzer that computes the discrete Fourier transform of blocks of sampled audio using the fast Fourier transform algorithm, producing a set of evenly spaced frequency bins whose magnitude and phase describe the spectrum. Bin spacing equals the sample rate divided by the transform size, so a larger block gives finer frequency resolution at the cost of time resolution.','An FFT analyzer turns sampled sound into a spectrum. It uses a fast math method called the FFT. The result is a row of frequency bins. Each bin has a size and a phase. A bigger block gives finer frequency steps.','It efficiently converts blocks of audio into a frequency spectrum, making detailed spectral analysis practical in real time on ordinary hardware.','Measurement software and plug-ins use FFT analyzers to show spectra, find tones and noise, and drive transfer-function measurements.','Sound Visualization & Acoustic Imaging',ARRAY['Fast Fourier transform','Discrete Fourier transform','FFT magnitude spectrum','Frequency bin','Windowing']::text[],ARRAY['Forgetting that bin spacing is fixed by sample rate and block size','Ignoring windowing, which causes spectral leakage between bins','Assuming fine frequency resolution and fine time resolution at once']::text[],ARRAY['Measuring a loudspeaker''s frequency response','Identifying a feedback frequency during a show','Analyzing the harmonic content of an instrument']::text[],'intermediate','X[k] = Σ_{n=0}^{N-1} x[n]·e^{−j2πkn/N}','Each frequency bin equals the sum, over all input samples, of the sample value multiplied by a complex sinusoid at that bin''s frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='FFT analyzer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0349264-1114-5626-b224-d80ea4709db5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0349264-1114-5626-b224-d80ea4709db5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0349264-1114-5626-b224-d80ea4709db5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '19213613-8894-534c-840a-52ae6fd537d1','FFT magnitude spectrum','The frequency-domain plot of the magnitude of each complex bin produced by an FFT, showing how much energy the signal has at each analyzed frequency, usually on a decibel vertical scale. Phase is discarded. The frequency of bin k equals k times the sample rate divided by the transform size.','The FFT magnitude spectrum shows energy by frequency. It takes the size of each FFT bin. It ignores the phase part. The height is usually in decibels. Each bin''s frequency depends on the sample rate and block size.','It presents the strength of each frequency component in a readable form, which is the everyday output of a spectrum analyzer.','Engineers read the FFT magnitude spectrum to spot tones, harmonics, hum, and noise and to judge tonal balance.','Sound Visualization & Acoustic Imaging',ARRAY['FFT analyzer','Power spectrum','Complex spectrum','Frequency bin','Decibel']::text[],ARRAY['Assuming the magnitude alone captures the signal, when phase is also needed to reconstruct it','Reading a leaked skirt around a tone as separate real components','Mixing up magnitude in decibels with power in decibels']::text[],ARRAY['Finding the level of a 60 Hz hum','Comparing harmonic levels of two synth patches','Checking the noise floor of a converter']::text[],'intermediate','|X[k]| = √( Re{X[k]}² + Im{X[k]}² );  f_k = k·f_s / N','The magnitude at a bin is the length of its complex value; the bin''s frequency equals the bin number times the sample rate divided by the transform size.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='FFT magnitude spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '19213613-8894-534c-840a-52ae6fd537d1','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='19213613-8894-534c-840a-52ae6fd537d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='19213613-8894-534c-840a-52ae6fd537d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b9a4b7bb-692a-5ce6-b9c2-fabaffe5b536','Power spectrum','A frequency-domain display in which each value is the squared magnitude of the corresponding spectral bin, representing the signal power at that frequency rather than its amplitude. Because it is proportional to energy, the power spectrum is the basis for power spectral density estimates and for averaging noisy measurements.','A power spectrum shows power by frequency. It squares the size of each bin. This gives energy, not just amplitude. Squaring makes strong parts stand out more. It is used to average noisy measurements.','It expresses spectral content as power, the quantity that adds correctly when averaging and that underlies power spectral density.','Measurement and acoustics tools average power spectra to estimate noise levels and the power spectral density of signals.','Sound Visualization & Acoustic Imaging',ARRAY['FFT magnitude spectrum','Power spectral density','Spectral display','Averaging','Decibel']::text[],ARRAY['Confusing power, from squared magnitude, with amplitude magnitude','Forgetting that power spectral density normalizes power by bandwidth','Averaging magnitudes when power should be averaged instead']::text[],ARRAY['Averaging repeated measurements to lower noise','Estimating broadband noise power in a room','Comparing energy in two frequency bands']::text[],'intermediate','P[k] = |X[k]|² = Re{X[k]}² + Im{X[k]}²','The power at each frequency bin equals the squared magnitude of the complex spectrum value at that bin.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Power spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b9a4b7bb-692a-5ce6-b9c2-fabaffe5b536','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b9a4b7bb-692a-5ce6-b9c2-fabaffe5b536') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b9a4b7bb-692a-5ce6-b9c2-fabaffe5b536');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '454652a3-3435-54f5-b7af-20cde805130a','Complex spectrum','The full complex-valued output of a Fourier transform, in which each frequency bin carries both a real and an imaginary part, equivalently a magnitude and a phase. Unlike a magnitude-only spectrum, the complex spectrum retains all information needed to reconstruct the time signal through the inverse transform.','A complex spectrum keeps two numbers per bin. One is the real part, one the imaginary part. Together they give a size and a phase. Keeping both lets you rebuild the signal. A magnitude-only view cannot do that.','It carries both magnitude and phase, which is why it, not the magnitude alone, allows exact reconstruction and phase-based processing.','Convolution, filtering, and phase-vocoder effects work on the complex spectrum so that phase is preserved and altered deliberately.','Sound Visualization & Acoustic Imaging',ARRAY['FFT magnitude spectrum','Phase spectrum','Fourier transform','Frequency bin','Inverse FFT']::text[],ARRAY['Assuming magnitude alone is enough to reconstruct the signal','Neglecting phase, which controls transient shape and stereo imaging','Confusing the real and imaginary parts with magnitude and phase directly']::text[],ARRAY['Filtering audio by multiplying complex spectra','Time-stretching with a phase vocoder','Reconstructing a signal after spectral editing']::text[],'advanced','X[k] = Re{X[k]} + j·Im{X[k]} = |X[k]|·e^{jφ[k]}','Each bin is a complex number with a real and an imaginary part, equal to a magnitude multiplied by a unit phasor at that bin''s phase angle.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '454652a3-3435-54f5-b7af-20cde805130a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='454652a3-3435-54f5-b7af-20cde805130a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='454652a3-3435-54f5-b7af-20cde805130a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '49cfe834-92e9-5d95-ba00-baa843a82539','Spectral display','A general term for any visualization of a signal''s frequency content, covering line spectra, magnitude and power spectra, spectrograms, and octave-band bar displays. It denotes the family of frequency-domain pictures rather than one specific plot, and the exact axes and scaling depend on the chosen implementation.','A spectral display is any view of frequency content. It covers spectra, spectrograms, and band bar graphs. The word names the whole family. It does not fix one exact plot. The axes depend on which type is used.','It names the broad category of frequency-domain visualizations, useful when the specific plot type is unspecified or interchangeable.','Documentation and interfaces use spectral display as an umbrella label for the various frequency views an analyzer offers.','Sound Visualization & Acoustic Imaging',ARRAY['Frequency-domain display','Spectrum','Spectrogram','FFT magnitude spectrum','Real-time analyzer']::text[],ARRAY['Assuming spectral display means one specific plot rather than a family','Confusing a spectrogram, which adds time, with a single spectrum','Ignoring that axis scaling varies between implementations']::text[],ARRAY['Describing an analyzer''s frequency views in general','Choosing between a spectrum and a spectrogram for a task','Labeling a metering section in a plug-in']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '49cfe834-92e9-5d95-ba00-baa843a82539','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='49cfe834-92e9-5d95-ba00-baa843a82539') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='49cfe834-92e9-5d95-ba00-baa843a82539');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '24dbe727-e35a-5c27-8399-c8167b2e6df6','Spectral line','A single narrow component in a frequency spectrum, appearing as a discrete peak at one frequency, characteristic of a sinusoid or a stable periodic tone. In an FFT the ideal line is spread across nearby bins by the analysis window, so a real spectral line has a width set by the window and block length.','A spectral line is one narrow tone in a spectrum. It shows as a thin peak at one frequency. A pure sine wave makes one line. In an FFT the line spreads a little. The window and block length set that width.','It marks a single, stable frequency component, letting an analyst pick out tones such as hum, whistles, and harmonics.','Analysts read spectral lines to identify hum, oscillation, and instrument harmonics against a broadband background.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral peak','Harmonic spectrum','FFT magnitude spectrum','Spectral leakage','Windowing']::text[],ARRAY['Expecting an infinitely thin line when windowing gives it real width','Confusing one leaked line with several separate tones','Assuming any peak is a true line rather than a noise bump']::text[],ARRAY['Identifying a mains hum component','Tracking an instrument''s harmonics as lines','Detecting an unwanted oscillation in a device']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral line');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '24dbe727-e35a-5c27-8399-c8167b2e6df6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='24dbe727-e35a-5c27-8399-c8167b2e6df6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='24dbe727-e35a-5c27-8399-c8167b2e6df6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01f66f89-42f5-5615-baed-eda097f98808','Spectral peak','A local maximum in a frequency spectrum, a bin or region whose magnitude exceeds its neighbors, indicating a concentration of energy at that frequency. Peak-picking algorithms locate spectral peaks to find tones, formants, harmonics, and resonances, often refining the estimate by interpolating between bins.','A spectral peak is a high point in a spectrum. Its level is greater than the frequencies beside it. It marks where energy gathers. Software finds peaks to spot tones and resonances. It can refine the exact frequency between bins.','It flags where energy concentrates in frequency, which is how analyzers and algorithms locate tones, formants, and resonances.','Pitch trackers, feedback finders, and analyzers pick spectral peaks to identify dominant frequencies and resonances.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral line','Spectral centroid display','Formant','Peak-picking','Resonance']::text[],ARRAY['Treating every peak as musically meaningful rather than noise or leakage','Reading the peak''s bin center as its exact frequency without interpolation','Confusing a broad resonance with a narrow tonal peak']::text[],ARRAY['Finding a ringing feedback frequency','Tracking the loudest partial for pitch detection','Locating a room mode as a spectral peak']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral peak');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01f66f89-42f5-5615-baed-eda097f98808','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01f66f89-42f5-5615-baed-eda097f98808') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01f66f89-42f5-5615-baed-eda097f98808');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45582bc9-2fae-5429-a054-7b0953e7e166','Spectral centroid display','A visualization of the spectral centroid, the magnitude-weighted mean frequency of a spectrum, often plotted over time. Because higher-frequency energy raises the centroid, it correlates with perceived brightness and is a common timbre descriptor in audio analysis and music information retrieval.','The spectral centroid is a spectrum''s balance point. It is the average frequency weighted by level. A higher value means a brighter sound. The display often tracks it over time. It is a simple measure of brightness.','It reduces a whole spectrum to one brightness-related number, giving a compact cue to timbre that is easy to track over time.','Analysis tools and music-information-retrieval systems plot the spectral centroid to describe and compare timbral brightness.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral peak','Spectral flatness','Brightness','Timbre','FFT magnitude spectrum']::text[],ARRAY['Treating the centroid as a pitch rather than a brightness measure','Comparing centroids computed with different frequency scales','Ignoring that noise and silence skew the centroid']::text[],ARRAY['Tracking brightness changes across a note','Comparing the timbre of two instruments','Feeding a brightness feature to a classifier']::text[],'advanced','C = ( Σ_k f_k·|X[k]| ) / ( Σ_k |X[k]| )','The spectral centroid is the average of the bin frequencies weighted by their magnitudes, giving the magnitude-weighted centre frequency of the spectrum.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral centroid display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45582bc9-2fae-5429-a054-7b0953e7e166','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45582bc9-2fae-5429-a054-7b0953e7e166') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45582bc9-2fae-5429-a054-7b0953e7e166');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86630ffc-50ca-512e-b753-2e4a1a54b494','Spectral flatness','A measure, often displayed over time, of how noise-like or tone-like a spectrum is, computed as the ratio of the geometric mean of the power spectrum to its arithmetic mean. Values near one indicate a flat, noise-like spectrum, while values near zero indicate energy concentrated in a few tonal peaks.','Spectral flatness tells noise from tone. It compares two averages of the power spectrum. A value near one means noise-like. A value near zero means tone-like. The display can track it over time.','It distinguishes noisy from tonal content in one number, useful for classifying sounds and for detecting tonal components.','Codecs, noise gates, and analysis tools use spectral flatness to decide whether a frame is noisy or tonal.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral centroid display','Power spectrum','Tonality','Timbre','Noise floor']::text[],ARRAY['Confusing spectral flatness with a flat frequency response','Forgetting it uses the power spectrum, not raw magnitude','Assuming a fixed threshold separates noise from tone in every case']::text[],ARRAY['Detecting whether a frame is tonal or noisy','Steering a noise-reduction decision','Describing the texture of a sound for analysis']::text[],'advanced','SFM = geo_mean(P[k]) / arith_mean(P[k]),  P[k] = |X[k]|²','Spectral flatness is the geometric mean of the power spectrum divided by its arithmetic mean; values near one are noise-like and values near zero are tone-like.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral flatness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86630ffc-50ca-512e-b753-2e4a1a54b494','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86630ffc-50ca-512e-b753-2e4a1a54b494') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86630ffc-50ca-512e-b753-2e4a1a54b494');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0aa6afc5-0fd2-55a8-acbf-00f68902cc41','Harmonic spectrum','A frequency spectrum in which the energy sits at frequencies that are whole-number multiples of a single fundamental frequency, the pattern produced by periodic, pitched sounds. The spacing of the harmonics fixes the perceived pitch, while their relative levels shape the timbre.','A harmonic spectrum has evenly spaced tones. Each tone is a whole-number multiple of the lowest one. That lowest tone is the fundamental. The spacing sets the pitch. The levels set the timbre.','It shows the ordered overtone pattern of pitched sounds, explaining why they have a clear pitch and a recognizable timbre.','Engineers read harmonic spectra to identify pitched instruments, check tuning, and study how timbre arises from overtone levels.','Sound Visualization & Acoustic Imaging',ARRAY['Inharmonic spectrum','Fundamental frequency','Overtone','Timbre','Spectral line']::text[],ARRAY['Confusing harmonics with unrelated inharmonic overtones','Assuming the fundamental is always the loudest harmonic','Treating harmonic number and octave as the same step']::text[],ARRAY['Identifying a sustained musical note''s overtones','Checking tuning from harmonic spacing','Comparing the timbre of two instruments']::text[],'beginner','f_n = n · f_0,  n = 1, 2, 3, …','The frequency of each harmonic equals a whole-number multiple of the fundamental frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0aa6afc5-0fd2-55a8-acbf-00f68902cc41','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0aa6afc5-0fd2-55a8-acbf-00f68902cc41') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0aa6afc5-0fd2-55a8-acbf-00f68902cc41');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd60ea101-dab7-5fd6-88bd-3f808e15cd90','Inharmonic spectrum','A spectrum whose partials do not fall at exact integer multiples of a fundamental, so the overtones are stretched or scattered rather than harmonically aligned. Stiff strings, bells, and many percussion instruments produce inharmonic spectra, which sound less clearly pitched or bell-like and complicate pitch detection.','An inharmonic spectrum has scattered overtones. They do not line up as whole-number multiples. Bells and stiff piano strings do this. The pitch sounds less clear. It can confuse pitch detectors.','It describes overtone patterns that are not harmonically aligned, explaining the metallic or ambiguous pitch of bells and percussion.','Analysts recognize inharmonic spectra when studying bells, percussion, and piano string stiffness, and when pitch tracking fails.','Sound Visualization & Acoustic Imaging',ARRAY['Harmonic spectrum','Overtone','Partial','Inharmonicity','Timbre']::text[],ARRAY['Assuming every pitched sound has a strictly harmonic spectrum','Confusing inharmonic partials with added noise','Expecting reliable pitch detection from strongly inharmonic tones']::text[],ARRAY['Studying the overtones of a bell or gong','Explaining stretched tuning on a piano','Diagnosing why a pitch tracker fails on a cymbal']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inharmonic spectrum');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd60ea101-dab7-5fd6-88bd-3f808e15cd90','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d60ea101-dab7-5fd6-88bd-3f808e15cd90') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d60ea101-dab7-5fd6-88bd-3f808e15cd90');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '012bb0f7-b9ac-5aa9-827e-94957b1ff924','Comb-filter display','A frequency-response visualization showing the regularly spaced peaks and notches that arise when a signal is summed with a delayed copy of itself. The notches occur at odd multiples of one over twice the delay, and the pattern looks like the teeth of a comb; the shorter the delay, the wider the spacing.','A comb-filter display shows evenly spaced dips and peaks. They appear when a sound meets a delayed copy of itself. The dips look like comb teeth. A shorter delay spreads them wider. It reveals reflection and phase problems.','It makes the peaks and notches of delay-and-sum interference visible, so engineers can trace reflections and phase problems to a time offset.','Measurement tools show comb filtering to diagnose reflections, multi-mic bleed, and misaligned loudspeaker arrivals.','Sound Visualization & Acoustic Imaging',ARRAY['Comb filter','Interference','Phase','Reflectogram','Transfer-function magnitude display']::text[],ARRAY['Mistaking comb-filter notches for EQ problems to be equalized away','Trying to fix comb filtering with EQ instead of fixing the time offset','Assuming the notch pattern is fixed when it moves with delay']::text[],ARRAY['Diagnosing hollow sound from two mics on one source','Finding a strong early reflection in a room','Spotting misaligned arrivals between stacked loudspeakers']::text[],'intermediate','|H(f)| = |1 + e^{−j2πfτ}|;  notches at f = (2k−1)/(2τ),  k = 1, 2, …','A signal summed with a copy delayed by tau has peaks and notches; the first notch sits at one over twice the delay, with the rest at odd multiples of that.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comb-filter display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '012bb0f7-b9ac-5aa9-827e-94957b1ff924','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='012bb0f7-b9ac-5aa9-827e-94957b1ff924') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='012bb0f7-b9ac-5aa9-827e-94957b1ff924');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '529ab1f8-b3c2-58ca-b985-11d3a2871b02','Transfer-function magnitude display','A frequency-response plot of the magnitude ratio between a system''s output and input, obtained by dividing the measured output spectrum by the input spectrum, usually via a dual-channel FFT measurement. It shows how much each frequency is boosted or cut by the device, room, or loudspeaker under test, typically on a decibel scale.','This display shows a system''s frequency response. It divides the output spectrum by the input spectrum. The result is how much each frequency is boosted or cut. It uses a two-channel FFT measurement. The scale is usually in decibels.','It reveals how a system reshapes frequency by comparing its output to its input, the core of loudspeaker and room measurement.','Engineers use dual-FFT tools to measure loudspeaker and room magnitude response and to set EQ and delay during tuning.','Sound Visualization & Acoustic Imaging',ARRAY['Frequency response','Impulse response plot','Group delay plot','Coherence','Dual-channel FFT']::text[],ARRAY['Trusting magnitude readings where coherence is low and data is unreliable','Ignoring phase, which also matters for alignment','Assuming a single mic position represents the whole room']::text[],ARRAY['Measuring a loudspeaker''s response with a reference signal','Setting system EQ from a transfer-function trace','Comparing before and after a room treatment']::text[],'intermediate','|H(f)| = |Y(f) / X(f)|','The transfer-function magnitude at each frequency is the size of the output spectrum divided by the size of the input spectrum.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transfer-function magnitude display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '529ab1f8-b3c2-58ca-b985-11d3a2871b02','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='529ab1f8-b3c2-58ca-b985-11d3a2871b02') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='529ab1f8-b3c2-58ca-b985-11d3a2871b02');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'af366ce3-739b-542d-a53d-b5fb97b05792','Nyquist plot','A parametric plot in the complex plane that traces a system''s frequency response, with the real part on the horizontal axis and the imaginary part on the vertical axis as frequency varies. Used in control and systems analysis, it reveals stability margins; in electroacoustics it can appear when analyzing feedback and loop stability.','A Nyquist plot draws a system''s response on a flat map. The sideways axis is the real part. The up axis is the imaginary part. The curve is traced as frequency changes. It is used to judge stability.','It shows magnitude and phase together as one curve, letting engineers judge how close a feedback system is to instability.','Control and electroacoustic engineers use Nyquist plots to assess loop stability and margins in feedback systems.','Sound Visualization & Acoustic Imaging',ARRAY['Complex spectrum','Transfer-function magnitude display','Feedback','Stability','Bode plot']::text[],ARRAY['Confusing the control-theory Nyquist plot with the Nyquist sampling frequency','Reading it as a spectrum rather than a complex-plane trace','Ignoring the encirclement rule that governs stability']::text[],ARRAY['Assessing feedback loop stability in a system','Checking gain and phase margins','Analyzing an active loudspeaker''s control loop']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nyquist plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'af366ce3-739b-542d-a53d-b5fb97b05792','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='af366ce3-739b-542d-a53d-b5fb97b05792') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='af366ce3-739b-542d-a53d-b5fb97b05792');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'daa1c77a-19af-5cf5-82a1-f9e74c439c9c','Filter response plot','A display of a filter''s frequency response, showing magnitude versus frequency and sometimes phase, for equalizers, crossovers, and other DSP filters. It visualizes where and how much the filter boosts or cuts, along with features such as cutoff frequency, slope, Q, and gain.','A filter response plot shows what a filter does by frequency. It draws boost or cut against frequency. It may also show phase. You can read the cutoff, slope, and Q. EQ and crossover screens use it.','It makes a filter''s action visible so an engineer can set cutoff, gain, slope, and Q by eye as well as by ear.','EQ and crossover interfaces draw filter response plots so engineers can shape and verify each band''s effect.','Sound Visualization & Acoustic Imaging',ARRAY['Frequency response','Equalizer','Crossover','Cutoff frequency','Transfer-function magnitude display']::text[],ARRAY['Assuming the drawn curve exactly matches the real analog output','Ignoring the phase shift that accompanies a magnitude change','Confusing the target curve with the measured result in a room']::text[],ARRAY['Setting an EQ band''s frequency and Q on screen','Checking crossover slopes between drivers','Comparing two filter shapes before choosing one']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter response plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'daa1c77a-19af-5cf5-82a1-f9e74c439c9c','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='daa1c77a-19af-5cf5-82a1-f9e74c439c9c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='daa1c77a-19af-5cf5-82a1-f9e74c439c9c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2170bfd2-c8e0-5e19-ac34-14716612b7a5','Group delay plot','A display of group delay versus frequency, where group delay is the negative rate of change of phase with frequency and represents the time delay experienced by the envelope of a narrow band of frequencies. Non-flat group delay indicates that different frequencies are delayed by different amounts, a form of phase distortion.','A group delay plot shows delay by frequency. Group delay is how phase changes with frequency. It tells how long each frequency band is held up. A flat line means all bands arrive together. Bumps mean phase distortion.','It reveals frequency-dependent time smearing that a magnitude plot hides, helping diagnose phase distortion in filters and speakers.','Engineers read group delay to check filters, crossovers, and loudspeakers for excess delay and phase distortion.','Sound Visualization & Acoustic Imaging',ARRAY['Phase response','Group delay','Filter response plot','Transfer-function magnitude display','Linear phase']::text[],ARRAY['Confusing group delay with a single fixed latency for all frequencies','Assuming flat magnitude implies flat group delay','Overreacting to small group-delay ripple below audibility']::text[],ARRAY['Checking a crossover for excess delay near its corner','Comparing linear-phase and minimum-phase EQ','Diagnosing smeared transients in a loudspeaker']::text[],'advanced','τ_g(f) = −(1/2π)·dφ(f)/df','Group delay is the negative slope of the phase response with respect to frequency, giving the time delay of a narrow band''s envelope at each frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Group delay plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2170bfd2-c8e0-5e19-ac34-14716612b7a5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2170bfd2-c8e0-5e19-ac34-14716612b7a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2170bfd2-c8e0-5e19-ac34-14716612b7a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '224bb2ad-edbb-57c9-af48-904334c151fb','Impulse response plot','A time-domain display of a system''s output when driven by a brief impulse, showing how the system responds and settles over time. The impulse response fully characterizes a linear time-invariant system; its Fourier transform gives the frequency response, and in acoustics it captures direct sound, reflections, and decay.','An impulse response plot shows how a system reacts to a quick click. Time runs across the plot. The trace shows the output settling. It fully describes a linear system. In a room it shows reflections and decay.','It captures a system''s complete linear behavior in one time trace, from which frequency response, reflections, and decay all follow.','Acousticians and system engineers capture impulse responses to derive frequency response, find reflections, and build reverb convolution files.','Sound Visualization & Acoustic Imaging',ARRAY['Frequency response','Transfer-function magnitude display','Reflectogram','Convolution','Step response plot']::text[],ARRAY['Assuming the impulse response describes a nonlinear or time-varying system fully','Ignoring noise and windowing that corrupt the measured tail','Confusing the impulse response with the frequency response directly']::text[],ARRAY['Measuring a room''s impulse response for analysis','Capturing a reverb for convolution processing','Deriving frequency response from a measured impulse']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulse response plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '224bb2ad-edbb-57c9-af48-904334c151fb','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='224bb2ad-edbb-57c9-af48-904334c151fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='224bb2ad-edbb-57c9-af48-904334c151fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2a21341-774f-5b91-95d3-3f9dbb95701e','Step response plot','A time-domain display of a system''s output when its input jumps instantly from one constant level to another, the step being the running integral of the impulse. It reveals rise time, overshoot, ringing, and settling, and in loudspeakers it is used to judge driver timing and polarity.','A step response plot shows how a system reacts to a sudden jump. The input steps up and holds. The trace shows the output catching up. You can read rise, overshoot, and ringing. Speaker tests use it for timing and polarity.','It shows how quickly and cleanly a system follows a sudden change, exposing overshoot, ringing, and timing that spectra hide.','Loudspeaker and filter engineers read step responses to judge driver timing, polarity, and settling behavior.','Sound Visualization & Acoustic Imaging',ARRAY['Impulse response plot','Rise time','Overshoot','Settling time','Polarity']::text[],ARRAY['Confusing the step response with the impulse response','Reading overshoot as an outright fault without context','Ignoring that measurement bandwidth shapes the observed rise']::text[],ARRAY['Judging a loudspeaker''s driver timing and polarity','Checking a filter for ringing and overshoot','Evaluating a control system''s settling']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Step response plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2a21341-774f-5b91-95d3-3f9dbb95701e','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2a21341-774f-5b91-95d3-3f9dbb95701e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2a21341-774f-5b91-95d3-3f9dbb95701e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b452be36-ff0f-5f0b-878d-ab5b633588a0','Decay spectrogram','A three-axis display showing how the energy at each frequency decays after an excitation stops, plotting frequency, time, and level, often as a waterfall. Also called cumulative spectral decay, it reveals resonances and ringing that persist longer than surrounding frequencies in loudspeakers and rooms.','A decay spectrogram shows how sound fades by frequency. It plots frequency, time, and level together. It often looks like a waterfall. Long ridges mark resonances that ring on. It exposes stored energy in speakers and rooms.','It exposes frequency-specific ringing and stored energy over time, which a static spectrum cannot show, pinpointing resonances.','Loudspeaker and room measurement tools show cumulative spectral decay to find resonances and ringing that need treatment.','Sound Visualization & Acoustic Imaging',ARRAY['Spectrogram','Cumulative spectral decay','Waterfall plot','Resonance','Room decay plot']::text[],ARRAY['Confusing a decay spectrogram with a single static spectrum','Misreading windowing artifacts as real resonances','Ignoring that time and frequency resolution trade off']::text[],ARRAY['Finding a ringing resonance in a loudspeaker','Locating a room mode that decays slowly','Comparing cabinet resonances between designs']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decay spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b452be36-ff0f-5f0b-878d-ab5b633588a0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b452be36-ff0f-5f0b-878d-ab5b633588a0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b452be36-ff0f-5f0b-878d-ab5b633588a0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6b2b8dac-b546-5eeb-bbff-eee89a272573','Reflectogram','A display of the arrivals of sound energy over time at a measurement point, showing the direct sound followed by discrete reflections as a series of spikes. Derived from an impulse response, it lets an acoustician read the delay and relative level of early reflections, and it is closely related to the energy-time curve.','A reflectogram shows sound arrivals over time. The first spike is the direct sound. Later spikes are reflections. Their timing shows how far they traveled. It helps find strong early reflections in a room.','It maps when and how strongly reflections arrive, so an acoustician can identify and treat problem surfaces in a space.','Acousticians read reflectograms from impulse-response measurements to locate and time early reflections when treating rooms.','Sound Visualization & Acoustic Imaging',ARRAY['Impulse response plot','Energy-time curve','Early reflection','Room decay plot','Comb-filter display']::text[],ARRAY['Confusing a reflectogram with a frequency spectrum','Reading spike height as loudness without level scaling','Assuming the first spike is always the direct sound in a noisy measurement']::text[],ARRAY['Locating a slap-echo reflection in a control room','Timing early reflections at a mix position','Deciding where to place absorption panels']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflectogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6b2b8dac-b546-5eeb-bbff-eee89a272573','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6b2b8dac-b546-5eeb-bbff-eee89a272573') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6b2b8dac-b546-5eeb-bbff-eee89a272573');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2e997896-96d6-5b6c-8a3a-34d3dc11642b','Room decay plot','A visualization of how reverberant sound energy decays in a room over time, usually shown per frequency band, so an analyst can see how quickly each part of the spectrum dies away. It underlies reverberation-time estimates and reveals uneven decay, such as low-frequency modes that ring longer than the rest.','A room decay plot shows how a room''s sound fades. It often splits the sound into frequency bands. Each band shows its own decay. Some bands, like the bass, fade slowly. It is the basis of reverb-time estimates.','It shows how decay varies with frequency, exposing uneven reverberation that a single reverberation-time number would hide.','Acousticians use per-band room decay plots to judge reverberation and to spot modes that ring longer than others.','Sound Visualization & Acoustic Imaging',ARRAY['RT60 decay curve','Schroeder decay curve','Reverberation time','Room mode','Decay spectrogram']::text[],ARRAY['Reducing decay to one number when it varies strongly by frequency','Ignoring background noise that flattens the late decay','Assuming a straight decay when modes make it bend']::text[],ARRAY['Assessing reverberation across bands in a hall','Finding a boomy low-frequency mode that lingers','Comparing decay before and after treatment']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room decay plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2e997896-96d6-5b6c-8a3a-34d3dc11642b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2e997896-96d6-5b6c-8a3a-34d3dc11642b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2e997896-96d6-5b6c-8a3a-34d3dc11642b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fbb42d8b-7e87-579b-8993-ade3c4e1efff','RT60 decay curve','A decay curve used to estimate reverberation time, the time it would take the sound level in a room to fall by 60 decibels after the source stops. Because a full 60-decibel drop is often masked by noise, the slope is measured over a smaller usable range, such as 20 or 30 decibels, and extrapolated to 60.','An RT60 decay curve shows a room''s reverberation time. RT60 is the time for the level to fall 60 decibels. Noise often hides the full drop. So a smaller drop is measured and scaled up. The slope gives the reverberation time.','It quantifies how long a room reverberates, the key number for judging speech clarity and acoustic suitability of a space.','Acousticians measure RT60 curves per octave band to certify rooms, size treatment, and check speech intelligibility.','Sound Visualization & Acoustic Imaging',ARRAY['Reverberation time','Schroeder decay curve','Room decay plot','Sabine equation','Absorption']::text[],ARRAY['Assuming a true 60 dB decay is measured rather than extrapolated','Ignoring that RT60 varies by frequency band','Confusing early decay time with the full RT60 slope']::text[],ARRAY['Certifying reverberation time in a classroom','Sizing absorption to hit a target RT60','Checking speech intelligibility in a hall']::text[],'intermediate','T_60 = time for level to fall 60 dB;  Sabine: T_60 = 0.161·V/A  (s, V in m³, A in m² sabins)','The reverberation time is how long the sound level takes to drop by sixty decibels; by Sabine''s equation it equals a constant times the room volume divided by its total absorption.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RT60 decay curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fbb42d8b-7e87-579b-8993-ade3c4e1efff','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fbb42d8b-7e87-579b-8993-ade3c4e1efff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fbb42d8b-7e87-579b-8993-ade3c4e1efff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d19a319-2e72-5f6d-8174-1b2cf6118a63','Schroeder decay curve','A smooth energy-decay curve obtained by integrating the squared impulse response backward in time from its end, as introduced by Schroeder. This backward integration removes the fluctuation seen in a single decaying tone burst, giving a repeatable curve from one measurement from which reverberation time is read as a slope.','A Schroeder decay curve is a smooth decay line. It comes from the room''s impulse response. The squared response is added up from the end backward. This removes random wiggles. One measurement then gives a clean reverb slope.','It turns a single impulse-response measurement into a smooth, repeatable decay curve, making reverberation time reliable to read.','Room-acoustics software computes Schroeder curves from impulse responses to derive RT60 and early decay time.','Sound Visualization & Acoustic Imaging',ARRAY['RT60 decay curve','Impulse response plot','Reverberation time','Early decay time','Room decay plot']::text[],ARRAY['Forgetting to truncate noise before backward integration, which biases the curve','Confusing the Schroeder curve with a raw decaying signal','Reading one slope when the decay is clearly double-sloped']::text[],ARRAY['Deriving RT60 from a measured impulse response','Comparing early decay time and RT60 in a room','Producing a repeatable decay curve for a report']::text[],'advanced','E(t) = ∫_t^∞ h²(τ) dτ','The Schroeder curve at each time is the energy remaining in the squared impulse response, found by integrating it backward from the end toward that time.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Schroeder decay curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d19a319-2e72-5f6d-8174-1b2cf6118a63','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d19a319-2e72-5f6d-8174-1b2cf6118a63') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d19a319-2e72-5f6d-8174-1b2cf6118a63');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '138db721-a4f1-5a78-9c2d-4d1696c8b225','Sonogram','A sonogram is a two-dimensional image of a sound that plots time along one axis and frequency along the other, with the strength of each frequency shown as brightness or color. In acoustics, phonetics, and bioacoustics the word is used as a synonym for the spectrogram, the visual output of a short-time frequency analysis of a signal. Because the same word also names ultrasound medical images, audio contexts should make the acoustic meaning explicit.','A sonogram is a picture of a sound. Time runs left to right. Frequency runs bottom to top. Bright spots mark strong frequencies. In audio it means the same thing as a spectrogram.','It lets a person see how the frequencies in a sound rise, fall, and overlap over time, turning an invisible signal into a readable image.','Phoneticians and bioacousticians read sonograms in tools such as Praat or Raven to measure the frequency and timing of speech sounds and animal calls.','Sound Visualization & Acoustic Imaging',ARRAY['Spectrogram','Short-time Fourier transform','Voiceprint','Time-frequency representation','Narrowband spectrogram']::text[],ARRAY['Assuming an audio sonogram and a medical ultrasound sonogram are the same thing','Treating the image as an exact photo rather than an estimate set by analysis settings','Believing every sonogram uses the same frequency scale']::text[],ARRAY['Measuring vowel formants from a recorded word','Marking bird calls in a field recording','Comparing two speakers saying the same phrase']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '138db721-a4f1-5a78-9c2d-4d1696c8b225','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='138db721-a4f1-5a78-9c2d-4d1696c8b225') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='138db721-a4f1-5a78-9c2d-4d1696c8b225');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6cc7ea0c-9912-56cb-b3ab-9d1517ab13ae','Sonograph','A sonograph is the instrument or software display that produces a sonogram, performing a running frequency analysis of a sound and presenting the result as a time-frequency image. Early analog machines swept a bandpass filter across the spectrum and burned the output onto paper, while modern sonographs compute the short-time Fourier transform digitally. The word denotes the analyzer, whereas sonogram denotes the picture it produces.','A sonograph is the machine or program that makes a sonogram. It analyzes a sound and draws its frequencies over time. Old models used sweeping filters and paper. New ones use a computer. The tool makes the picture; the picture is the sonogram.','It automates spectral analysis so an operator can obtain a full time-frequency picture of a sound without measuring each frequency by hand.','Speech and hearing labs historically used a hardware sound analyzer, and today the same role is filled by spectrogram displays in software.','Sound Visualization & Acoustic Imaging',ARRAY['Sonogram','Spectrogram','Spectrum analyzer','Short-time Fourier transform','Voiceprint']::text[],ARRAY['Confusing the sonograph (the analyzer) with the sonogram (its output image)','Assuming all sonographs share one fixed bandwidth setting','Thinking the historical paper machine and a modern software display work identically']::text[],ARRAY['Running a speech sample through a hardware sound analyzer','Reproducing an old paper sonograph result in modern software','Teaching the history of speech visualization']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonograph');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6cc7ea0c-9912-56cb-b3ab-9d1517ab13ae','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6cc7ea0c-9912-56cb-b3ab-9d1517ab13ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6cc7ea0c-9912-56cb-b3ab-9d1517ab13ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb4c7ed3-81f9-57dc-bd6a-c4e39fb14cf6','Voicegram','A voicegram is a spectrogram of a human voice, plotting time against frequency with amplitude shown as intensity, used to display the harmonic and formant structure of speech. The term is informal and overlaps with voiceprint and speech spectrogram; it emphasizes that the analyzed signal is a voice rather than a general sound. Its detail depends on the analysis window, as with any short-time Fourier spectrogram.','A voicegram is a spectrogram of a person''s voice. It shows the voice''s pitch and tone over time. Bands of energy reveal vowels and stress. It is really just a speech spectrogram. The name points to the voice signal.','It makes the acoustic structure of speech visible so vowels, pitch, and voice quality can be inspected and compared.','Voice coaches and forensic analysts view voicegrams to study a talker''s pitch range, formants, and speaking patterns.','Sound Visualization & Acoustic Imaging',ARRAY['Voiceprint','Speech spectrogram','Formant','Narrowband spectrogram','Sonogram']::text[],ARRAY['Treating a voicegram as a unique fingerprint that identifies a speaker with certainty','Confusing it with a general-purpose spectrogram term used in physics','Ignoring how window length changes the visible harmonic detail']::text[],ARRAY['Reviewing a singer''s pitch and vibrato','Comparing recordings in a forensic voice case','Illustrating vowel formants in a phonetics class']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voicegram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb4c7ed3-81f9-57dc-bd6a-c4e39fb14cf6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb4c7ed3-81f9-57dc-bd6a-c4e39fb14cf6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb4c7ed3-81f9-57dc-bd6a-c4e39fb14cf6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5c444f44-10f9-5fbd-9ef6-f6c03179a848','Time-frequency representation','A time-frequency representation maps a one-dimensional signal into a two-dimensional function of time and frequency, describing how the signal''s spectral content evolves. The class includes linear representations such as the short-time Fourier and wavelet transforms and quadratic energy representations such as the spectrogram, Wigner-Ville distribution, and the wider Cohen''s class. Every such representation trades time resolution against frequency resolution under the Gabor-Heisenberg limit.','A time-frequency representation shows how a sound''s frequencies change over time. It turns a signal into a two-way map. One axis is time. The other is frequency. The spectrogram is the best-known example. All such maps trade timing detail against frequency detail.','It provides a general framework for analyzing signals whose frequency content changes, which a single fixed spectrum cannot capture.','Engineers pick a specific time-frequency representation, such as an STFT spectrogram or a wavelet scalogram, to match the transients or tones they need to study.','Sound Visualization & Acoustic Imaging',ARRAY['Spectrogram','Short-time Fourier transform','Wigner-Ville distribution','Cohen''s class distribution','Scalogram']::text[],ARRAY['Assuming every time-frequency representation is just a spectrogram','Ignoring the resolution trade-off shared by all such methods','Reading quadratic representations without accounting for cross-terms']::text[],ARRAY['Choosing an analysis method for a frequency-swept signal','Comparing spectrogram and wavelet views of a transient','Teaching the resolution trade-off in signal analysis']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time-frequency representation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5c444f44-10f9-5fbd-9ef6-f6c03179a848','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5c444f44-10f9-5fbd-9ef6-f6c03179a848') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5c444f44-10f9-5fbd-9ef6-f6c03179a848');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '075700ac-5bbc-5183-8499-1d1c92a4ece5','STFT spectrogram','An STFT spectrogram is a time-frequency image formed by taking the short-time Fourier transform of a signal and displaying the squared magnitude of each analysis frame as intensity, with time on one axis and frequency on the other. The signal is divided into overlapping windowed segments, each is Fourier-transformed, and the resulting complex values are converted to power, usually shown on a decibel scale. It is the standard, computationally efficient time-frequency display in audio software.','An STFT spectrogram is the common kind of spectrogram. The sound is cut into short overlapping frames. Each frame gets a Fourier transform. The result shows frequency over time. Brightness marks how strong each frequency is. Most audio tools draw it this way.','It gives a fast, standard way to see how the frequency content of a sound changes over time.','Almost every DAW and analyzer, such as iZotope RX or Audacity, draws an STFT spectrogram for editing, mixing, and noise inspection.','Sound Visualization & Acoustic Imaging',ARRAY['Short-time Fourier transform','Spectrogram','Window function','Hop size','Bin resolution']::text[],ARRAY['Forgetting that the window length fixes the time-frequency resolution trade-off','Reading the display as exact rather than as a windowed estimate','Ignoring spectral leakage from the chosen window']::text[],ARRAY['Finding a hum or click in a recording','Setting EQ by watching frequency bands','Checking a mix for harsh resonances']::text[],'beginner','S(t,f) = |STFT{x}(t,f)|²','The spectrogram equals the squared magnitude of the short-time Fourier transform, which windows the signal around each time instant and takes its Fourier transform.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='STFT spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '075700ac-5bbc-5183-8499-1d1c92a4ece5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='075700ac-5bbc-5183-8499-1d1c92a4ece5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='075700ac-5bbc-5183-8499-1d1c92a4ece5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '64ba1f8f-97a7-5abc-8c85-a695fa5c0624','Window length','Window length is the duration, in samples or seconds, of the analysis window applied to each frame in a short-time Fourier transform, and it sets the fundamental time-frequency resolution of the resulting spectrogram. A long window narrows the effective analysis bandwidth, improving frequency resolution while blurring time; a short window does the reverse. The trade-off is bounded by the Gabor-Heisenberg uncertainty principle, which limits the product of time spread and frequency spread.','Window length is how long each analysis slice of sound is. A long window sees frequency clearly but blurs timing. A short window sees timing clearly but blurs frequency. You cannot sharpen both at once. This limit is built into the math.','It is the main control an analyst sets to balance frequency detail against timing detail in a spectrogram.','In a spectrogram tool the user picks an FFT or window size, choosing a long window to resolve close harmonics or a short one to catch fast transients.','Sound Visualization & Acoustic Imaging',ARRAY['Window function','Short-time Fourier transform','Narrowband spectrogram','Wideband spectrogram','Bin resolution']::text[],ARRAY['Believing a longer window sharpens both time and frequency at once','Confusing the window length with the hop between frames','Thinking zero-padding to a larger FFT adds real frequency resolution beyond the window']::text[],ARRAY['Lengthening the window to separate two close tones','Shortening the window to locate a drum hit in time','Explaining why a hum and a click need different settings']::text[],'intermediate','Δt·Δf ≥ 1/(4π)','The product of a signal''s spread in time and its spread in frequency cannot fall below a fixed lower limit, so lengthening the window narrows frequency spread but widens time spread.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Window length');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '64ba1f8f-97a7-5abc-8c85-a695fa5c0624','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='64ba1f8f-97a7-5abc-8c85-a695fa5c0624') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='64ba1f8f-97a7-5abc-8c85-a695fa5c0624');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e1c761ff-2180-57e5-aa7c-cdb80183f660','Hop size','Hop size is the number of samples by which the analysis window advances between successive frames of a short-time Fourier transform, equal to the window length minus the overlap. It sets the time spacing of spectrogram columns and therefore the frame rate of the analysis; a smaller hop yields more columns per second and smoother time detail at higher computational cost. Adequate overlap is also required for faithful reconstruction when the STFT is inverted.','Hop size is how far the analysis window moves for each new frame. A small hop means frames overlap a lot. That gives more columns and smoother timing. A big hop skips ahead and looks coarse. It sets how often the spectrogram is sampled in time.','It controls the time spacing of spectrogram frames, trading smoothness and reconstruction quality against computation.','Analysis libraries such as librosa expose a hop-length parameter that sets frame rate for spectrograms, onset detection, and beat tracking.','Sound Visualization & Acoustic Imaging',ARRAY['Window length','Overlap','Short-time Fourier transform','Frame rate','STFT spectrogram']::text[],ARRAY['Confusing hop size with window length','Using too large a hop and missing fast events between frames','Forgetting that overlap must be sufficient to invert the STFT cleanly']::text[],ARRAY['Setting frame rate for beat tracking','Increasing overlap to smooth a spectrogram','Balancing detail against processing time in analysis']::text[],'intermediate','H = N − overlap;  frame rate = fs / H','Hop size equals the window length minus the sample overlap, and the number of frames per second equals the sample rate divided by the hop size.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hop size');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e1c761ff-2180-57e5-aa7c-cdb80183f660','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e1c761ff-2180-57e5-aa7c-cdb80183f660') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e1c761ff-2180-57e5-aa7c-cdb80183f660');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b4d0bcb-4718-5de2-9917-08474340ff75','Bin resolution','Bin resolution, or bin width, is the frequency spacing between adjacent points of a discrete Fourier transform, equal to the sample rate divided by the transform length. It states how finely the spectrum is sampled along the frequency axis, but it is not the same as true resolving power, which is governed by the analysis window''s main-lobe width. Zero-padding reduces bin width without adding genuine resolution.','Bin resolution is the frequency gap between FFT points. It equals the sample rate divided by the FFT size. A bigger FFT gives smaller gaps. But finer bins do not always mean finer detail. The window still limits what you can truly separate.','It tells the analyst how finely the frequency axis is divided, guiding FFT-size choices for a spectrogram.','When setting an analyzer''s FFT size, an engineer computes bin width to check whether two nearby tones will fall into separate bins.','Sound Visualization & Acoustic Imaging',ARRAY['FFT size','Frequency resolution','Zero-padding','Window length','Short-time Fourier transform']::text[],ARRAY['Confusing bin width with true resolving power set by the window','Assuming zero-padding adds real frequency detail','Ignoring the sample rate when estimating bin spacing']::text[],ARRAY['Choosing an FFT size to separate two close tones','Checking bin width for low-frequency analysis','Explaining why padding smooths but does not resolve']::text[],'intermediate','Δf = fs / N','The frequency spacing between transform bins equals the sample rate divided by the number of transform points.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bin resolution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b4d0bcb-4718-5de2-9917-08474340ff75','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b4d0bcb-4718-5de2-9917-08474340ff75') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b4d0bcb-4718-5de2-9917-08474340ff75');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfb374d5-bf0f-5cf4-8464-9e1b9a28f985','Leakage skirt','A leakage skirt is the spread of spectral energy into frequency bins on either side of a true sinusoidal component, appearing as sloping tails around the peak in a spectrum or spectrogram. It arises from spectral leakage, the consequence of analyzing a finite windowed segment whose edges are generally discontinuous; the window''s side-lobe pattern shapes the height and slope of the skirt. Window selection trades main-lobe width against side-lobe (skirt) level.','A leakage skirt is the smear of energy around a spectral peak. It looks like sloping tails beside a strong tone. It comes from cutting the signal into finite frames. The window shape sets how tall the tails are. A better window lowers the skirt.','It signals how much a chosen window bleeds energy from strong tones into nearby bins, which can hide weaker signals.','Choosing a window such as Hann or Blackman-Harris controls the leakage skirt when trying to see a quiet tone next to a loud one.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral leakage','Window function','Side lobe','Scalloping loss','Short-time Fourier transform']::text[],ARRAY['Mistaking a leakage skirt for real signal energy at those frequencies','Assuming a rectangular window is fine for spectral detail','Thinking more FFT points remove leakage rather than the window']::text[],ARRAY['Detecting a weak tone hidden beside a loud one','Comparing window types for a clean spectrum','Diagnosing skirts around a test signal']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Leakage skirt');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfb374d5-bf0f-5cf4-8464-9e1b9a28f985','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfb374d5-bf0f-5cf4-8464-9e1b9a28f985') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfb374d5-bf0f-5cf4-8464-9e1b9a28f985');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab64a7a6-82e6-5be2-b7b1-9fef2ba1769c','Narrowband spectrogram','A narrowband spectrogram is a short-time Fourier spectrogram computed with a long analysis window, giving fine frequency resolution at the expense of time resolution. In speech analysis it resolves individual harmonics of the voice as separate horizontal bands, making the fundamental frequency and its overtones visible, but it smears rapid events in time. Its effective analysis bandwidth is typically on the order of tens of hertz.','A narrowband spectrogram uses a long analysis window. That gives sharp frequency detail. In speech it shows each harmonic as its own line. The trade-off is blurry timing. It is good for seeing pitch and overtones.','It resolves closely spaced frequency components such as voice harmonics that a short window would blur together.','Phoneticians switch to a narrowband view in Praat to read a talker''s harmonics and pitch structure.','Sound Visualization & Acoustic Imaging',ARRAY['Wideband spectrogram','Window length','Fundamental frequency','Harmonic','Short-time Fourier transform']::text[],ARRAY['Expecting sharp timing detail from a narrowband view','Confusing resolved harmonics with formant bands','Thinking one spectrogram setting suits every task']::text[],ARRAY['Reading voice harmonics in speech','Measuring pitch from resolved overtones','Separating two close musical tones']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Narrowband spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab64a7a6-82e6-5be2-b7b1-9fef2ba1769c','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab64a7a6-82e6-5be2-b7b1-9fef2ba1769c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab64a7a6-82e6-5be2-b7b1-9fef2ba1769c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7f41b6a-589a-5028-88f5-75ef26f249a0','Wideband spectrogram','A wideband spectrogram is a short-time Fourier spectrogram computed with a short analysis window, giving fine time resolution at the expense of frequency resolution. In speech it does not resolve individual harmonics but instead shows vertical striations at each glottal pulse and clear formant bands, making rapid events and voicing visible. Its effective analysis bandwidth is typically a few hundred hertz.','A wideband spectrogram uses a short analysis window. That gives sharp timing detail. In speech it shows formant bands and each voice pulse. It does not separate single harmonics. It is good for catching fast events.','It captures rapid changes and formant structure that a long window would smear in time.','Speech scientists use a wideband view to see formant transitions and voicing pulses in consonants and vowels.','Sound Visualization & Acoustic Imaging',ARRAY['Narrowband spectrogram','Window length','Formant','Voicing','Short-time Fourier transform']::text[],ARRAY['Expecting to resolve single harmonics in a wideband view','Confusing glottal striations with noise','Assuming wideband is always the right default']::text[],ARRAY['Reading formant transitions in speech','Locating consonant bursts in time','Studying voicing onset']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wideband spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7f41b6a-589a-5028-88f5-75ef26f249a0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7f41b6a-589a-5028-88f5-75ef26f249a0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7f41b6a-589a-5028-88f5-75ef26f249a0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c2d9d50e-3874-58b6-b4da-4c254c51643a','Log-frequency spectrogram','A log-frequency spectrogram is a spectrogram whose frequency axis is spaced logarithmically rather than linearly, so that equal musical intervals occupy equal vertical distances. It matches human pitch perception and the geometric spacing of octaves, making harmonic and musical relationships easier to read than on a linear axis. The underlying analysis may be an interpolated short-time Fourier transform or a constant-Q transform.','A log-frequency spectrogram spaces frequency by ratio, not by equal steps. Each octave takes the same height. This matches how we hear pitch. Musical notes line up in an even grid. It suits music better than a linear scale.','It aligns the frequency axis with pitch perception so octaves and musical intervals appear evenly spaced.','Music software shows a log-frequency spectrogram so notes and octaves are easy to locate by eye.','Sound Visualization & Acoustic Imaging',ARRAY['Linear-frequency spectrogram','Constant-Q transform','Chroma display','Octave','Pitch']::text[],ARRAY['Assuming linear-hertz spacing when reading musical intervals','Confusing a log-frequency axis with a decibel amplitude scale','Expecting evenly spaced harmonics on a log axis']::text[],ARRAY['Viewing musical notes across octaves','Comparing intervals in a melody','Aligning a spectrogram with a piano-roll view']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Log-frequency spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c2d9d50e-3874-58b6-b4da-4c254c51643a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c2d9d50e-3874-58b6-b4da-4c254c51643a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c2d9d50e-3874-58b6-b4da-4c254c51643a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '466b9af8-06ae-5aa8-9842-3a3eee539953','Linear-frequency spectrogram','A linear-frequency spectrogram is a spectrogram whose frequency axis is spaced in equal hertz increments, the direct output of a discrete Fourier transform where each bin covers the same bandwidth. Equal frequency differences map to equal vertical distances, so evenly spaced harmonics appear equally spaced, but low musical pitches are compressed near the bottom. It is the default scale for technical and physical analysis.','A linear-frequency spectrogram spaces frequency in equal steps of hertz. Every bin covers the same width. Evenly spaced harmonics look evenly spaced. Low pitches get squeezed at the bottom. It is the plain default from an FFT.','It presents frequency in equal physical units, which suits engineering measurement and harmonic spacing.','Test and measurement tools default to a linear-hertz spectrogram when checking harmonics, hum, and equipment response.','Sound Visualization & Acoustic Imaging',ARRAY['Log-frequency spectrogram','Bin resolution','Short-time Fourier transform','Harmonic','Frequency axis']::text[],ARRAY['Expecting musical intervals to look even on a linear axis','Confusing linear frequency with linear amplitude','Overlooking that low pitches are cramped at the bottom']::text[],ARRAY['Checking evenly spaced harmonics of a tone','Measuring hum frequencies','Inspecting a device''s frequency output']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear-frequency spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '466b9af8-06ae-5aa8-9842-3a3eee539953','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='466b9af8-06ae-5aa8-9842-3a3eee539953') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='466b9af8-06ae-5aa8-9842-3a3eee539953');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '36895378-c8e6-56f0-ac13-ebccc45f5351','Mel spectrogram','A mel spectrogram is a spectrogram whose frequency axis is warped to the mel scale, a perceptual pitch scale that is roughly linear below about 1 kHz and logarithmic above, obtained by grouping short-time Fourier power into overlapping mel-spaced triangular filters. The result compresses high frequencies and emphasizes the perceptually important lower range, and its log-power form is a standard front end for speech and audio machine learning. The mel mapping follows a logarithmic relation between mel value and frequency.','A mel spectrogram warps frequency to match hearing. Low pitches get more detail. High pitches are packed together. It groups FFT energy into mel-spaced bands. Speech and machine-learning systems use it a lot. It reflects how we judge pitch.','It reshapes the frequency axis to perceptual spacing, giving compact, hearing-matched features for recognition systems.','Speech recognition and audio tagging pipelines feed log-mel spectrograms to neural networks as their main input.','Sound Visualization & Acoustic Imaging',ARRAY['Mel scale','MFCC display','Filterbank','Log-frequency spectrogram','Bark spectrogram']::text[],ARRAY['Assuming the mel axis is fully logarithmic across all frequencies','Confusing a mel spectrogram with mel-frequency cepstral coefficients','Forgetting that filter count and range change the output']::text[],ARRAY['Preparing input features for a sound classifier','Comparing speech samples perceptually','Training a keyword spotter']::text[],'intermediate','m = 2595·log₁₀(1 + f/700)','The mel value equals 2595 times the base-ten logarithm of one plus the frequency in hertz divided by 700.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mel spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '36895378-c8e6-56f0-ac13-ebccc45f5351','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='36895378-c8e6-56f0-ac13-ebccc45f5351') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='36895378-c8e6-56f0-ac13-ebccc45f5351');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3baceb1-a0e1-5122-b845-965e715860b5','CQT spectrogram','A CQT spectrogram is a time-frequency display based on the constant-Q transform, in which the ratio of center frequency to bandwidth is held constant across geometrically spaced frequency bins. This yields bins spaced by a fixed number per octave, so lower frequencies are analyzed with narrower bandwidth and longer effective windows, matching musical pitch. It gives even resolution per octave, unlike the fixed bandwidth of a short-time Fourier transform.','A CQT spectrogram keeps a fixed quality factor for every bin. Bins are spaced by musical ratio. Low notes get narrow, long analysis. High notes get wider, shorter analysis. This matches how music is tuned. Each octave gets equal detail.','It provides constant resolution per octave so musical pitches and harmonics align naturally across the range.','Music-information tools compute a CQT spectrogram for chord recognition, transcription, and pitch analysis.','Sound Visualization & Acoustic Imaging',ARRAY['Constant-Q transform','Log-frequency spectrogram','Chroma display','Bin resolution','Octave']::text[],ARRAY['Confusing constant-Q spacing with linear FFT spacing','Assuming equal time resolution across all bins','Ignoring the longer latency at low frequencies']::text[],ARRAY['Recognizing chords in a song','Transcribing a melody to notes','Analyzing tuning across octaves']::text[],'intermediate','Q = f_k/Δf_k = const,  f_k = f_min·2^(k/B)','Each bin keeps a constant ratio of center frequency to bandwidth, and center frequencies rise geometrically with B bins per octave.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='CQT spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3baceb1-a0e1-5122-b845-965e715860b5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3baceb1-a0e1-5122-b845-965e715860b5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3baceb1-a0e1-5122-b845-965e715860b5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c1bdf45-354b-54aa-a89b-308284990cac','Scalogram','A scalogram is the squared magnitude of the continuous wavelet transform displayed as a function of time and scale, where scale is inversely related to frequency. Because wavelets stretch and compress, a scalogram gives fine time resolution at high frequencies and fine frequency resolution at low frequencies, unlike the fixed grid of a spectrogram. It is the wavelet counterpart of the spectrogram.','A scalogram is a wavelet version of a spectrogram. It plots energy over time and scale. Scale acts like inverse frequency. High frequencies get sharp timing. Low frequencies get sharp frequency detail. Wavelets stretch to fit each range.','It shows signal energy with resolution that adapts to frequency, suited to transients and multi-scale structure.','Engineers use scalograms to locate clicks, transients, and short bursts that a fixed-window spectrogram would smear.','Sound Visualization & Acoustic Imaging',ARRAY['Continuous wavelet transform','Wavelet transform display','Time-frequency representation','Spectrogram','Time-scale analysis']::text[],ARRAY['Reading the scale axis as if it were linear frequency','Assuming resolution is uniform like a spectrogram','Ignoring the choice of mother wavelet']::text[],ARRAY['Locating a sharp click in a recording','Studying a signal with fast and slow parts','Comparing wavelet and FFT views of a transient']::text[],'intermediate','SC(a,b) = |Wx(a,b)|²','The scalogram equals the squared magnitude of the continuous wavelet transform at each scale and time position.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Scalogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c1bdf45-354b-54aa-a89b-308284990cac','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c1bdf45-354b-54aa-a89b-308284990cac') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c1bdf45-354b-54aa-a89b-308284990cac');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7617dbbd-2809-5556-99b9-5c99e3aea22e','Wavelet transform display','A wavelet transform display is any visualization of a signal''s wavelet transform, presenting the correlation between the signal and scaled, shifted copies of a mother wavelet across time and scale. The continuous wavelet transform integrates the signal against dilated and translated wavelets, providing multi-resolution analysis; the display may show coefficient magnitude, phase, or a scalogram. It reveals both slow trends and fast transients in one picture.','A wavelet transform display shows a signal matched against wavelets. Wavelets are short waves that stretch and shift. Wide ones catch slow parts. Narrow ones catch fast parts. The picture maps time against scale. It shows detail at many resolutions at once.','It exposes structure across many scales at once, giving good timing for fast events and good frequency detail for slow ones.','Analysts use wavelet displays for transient detection, denoising, and studying signals whose features live at different time scales.','Sound Visualization & Acoustic Imaging',ARRAY['Continuous wavelet transform','Scalogram','Mother wavelet','Multi-resolution analysis','Time-scale analysis']::text[],ARRAY['Treating scale directly as frequency without conversion','Assuming one wavelet fits every signal','Confusing the continuous and discrete wavelet transforms']::text[],ARRAY['Detecting transients in a noisy signal','Denoising with wavelet thresholding','Analyzing signals across many time scales']::text[],'advanced','Wx(a,b) = (1/√a)∫ x(t)·ψ*((t−b)/a) dt','The wavelet transform correlates the signal with a mother wavelet scaled by a and shifted by b, integrated over time.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wavelet transform display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7617dbbd-2809-5556-99b9-5c99e3aea22e','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7617dbbd-2809-5556-99b9-5c99e3aea22e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7617dbbd-2809-5556-99b9-5c99e3aea22e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3efd8dc4-7c75-5d8e-a733-90bbc20aba48','Synchrosqueezed transform','The synchrosqueezed transform is a time-frequency reassignment method that sharpens a wavelet or short-time Fourier representation by reallocating its coefficients along the frequency axis to instantaneous-frequency estimates, concentrating energy onto narrow ridges. Unlike blind reassignment, synchrosqueezing squeezes only in frequency, so the transform remains invertible and individual oscillatory components can be reconstructed. It is used to separate overlapping modes in nonstationary signals.','The synchrosqueezed transform sharpens a blurry time-frequency map. It moves energy to its true frequency line. This makes ridges thin and clear. It squeezes only along frequency. So the signal can still be rebuilt. It helps separate overlapping tones.','It concentrates smeared time-frequency energy onto sharp ridges while staying invertible, aiding mode separation in changing signals.','Researchers apply synchrosqueezing to extract instantaneous-frequency ridges from speech, vibration, or biomedical signals.','Sound Visualization & Acoustic Imaging',ARRAY['Reassignment method','Instantaneous frequency','Continuous wavelet transform','Ridge extraction','Time-frequency representation']::text[],ARRAY['Confusing synchrosqueezing with general time-frequency reassignment','Assuming it separates strongly overlapping close modes','Expecting reliable ridges from very noisy data']::text[],ARRAY['Extracting a pitch ridge from speech','Separating vibration modes in machinery','Tracking instantaneous frequency in biomedical signals']::text[],'advanced','Ts(b,ω) = ∫ Wx(a,b)·δ(ω − ω_x(a,b))·a^(−3/2) da','Synchrosqueezing reassigns each wavelet coefficient to its estimated instantaneous frequency, summing contributions that share the same frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Synchrosqueezed transform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3efd8dc4-7c75-5d8e-a733-90bbc20aba48','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3efd8dc4-7c75-5d8e-a733-90bbc20aba48') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3efd8dc4-7c75-5d8e-a733-90bbc20aba48');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b74d15c0-911e-5b6e-85ac-67949064810a','Wigner-Ville distribution','The Wigner-Ville distribution is a quadratic time-frequency representation defined as the Fourier transform, with respect to a lag variable, of the signal''s instantaneous autocorrelation. It offers the highest joint time-frequency concentration among the energy distributions and satisfies many marginal and localization properties, but being bilinear it produces interfering cross-terms between components. It is the prototypical member of Cohen''s class, with a unit kernel.','The Wigner-Ville distribution is a sharp time-frequency map. It comes from the signal''s own correlation over lag. It packs energy very tightly. But it adds false cross-terms between parts. These ghosts sit between real components. It is the base of a whole family of methods.','It gives very high time-frequency concentration for analyzing single-component signals and defines the reference for the wider distribution family.','Engineers use the Wigner-Ville distribution for high-resolution analysis of chirps and single-component transients, often smoothed to suppress cross-terms.','Sound Visualization & Acoustic Imaging',ARRAY['Cohen''s class distribution','Cross-term interference','Instantaneous frequency','Time-frequency representation','Pseudo-Wigner distribution']::text[],ARRAY['Reading cross-terms as if they were real signal energy','Applying it unsmoothed to multi-component signals','Confusing it with the spectrogram''s non-negative energy']::text[],ARRAY['Analyzing a single chirp at high resolution','Studying cross-terms in a teaching example','Comparing smoothed and raw distributions']::text[],'advanced','W(t,f) = ∫ x(t+τ/2)·x*(t−τ/2)·e^(−j2πfτ) dτ','The Wigner-Ville distribution is the Fourier transform over lag of the product of the signal at times shifted forward and back by half the lag.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wigner-Ville distribution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b74d15c0-911e-5b6e-85ac-67949064810a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b74d15c0-911e-5b6e-85ac-67949064810a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b74d15c0-911e-5b6e-85ac-67949064810a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2172412a-2d4f-50dc-aa3a-0b89533dc7d5','Cohen’s class distribution','Cohen''s class is the general family of bilinear time-frequency energy distributions that are covariant to time and frequency shifts, obtained by smoothing the Wigner-Ville distribution with a two-dimensional kernel. Choosing the kernel trades cross-term suppression against time-frequency concentration; the spectrogram, Wigner-Ville, Choi-Williams, and Zhao-Atlas-Marks distributions are all members defined by particular kernels. It provides a unifying framework for designing time-frequency representations.','Cohen''s class is a family of time-frequency maps. Each member is set by a kernel. The kernel controls the balance of sharpness and false cross-terms. The spectrogram and Wigner-Ville both belong to it. Picking a kernel picks the method. It ties many tools together.','It unifies quadratic time-frequency methods so a designer can pick a kernel that balances resolution against cross-term artifacts.','Signal analysts choose a Cohen''s-class kernel, such as Choi-Williams, to get sharper analysis than a spectrogram with fewer cross-terms than raw Wigner-Ville.','Sound Visualization & Acoustic Imaging',ARRAY['Wigner-Ville distribution','Kernel function','Cross-term interference','Choi-Williams distribution','Time-frequency representation']::text[],ARRAY['Assuming all members are cross-term free','Forgetting the spectrogram is a smoothed member of the class','Choosing a kernel without regard to the signal type']::text[],ARRAY['Selecting a kernel to reduce cross-terms','Comparing distribution members on one signal','Teaching the unifying view of time-frequency methods']::text[],'advanced','C(t,f) = (Wx ∗∗ Φ)(t,f)','A Cohen''s-class distribution is the Wigner-Ville distribution smoothed by a two-dimensional kernel that sets the trade-off between concentration and cross-term suppression.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cohen’s class distribution');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2172412a-2d4f-50dc-aa3a-0b89533dc7d5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2172412a-2d4f-50dc-aa3a-0b89533dc7d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2172412a-2d4f-50dc-aa3a-0b89533dc7d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd8307881-96f3-5978-817d-410c30fc01a6','Chroma display','A chroma display, or chromagram, is a time-frequency-derived visualization that folds spectral energy into the twelve pitch classes of the equal-tempered scale, collapsing all octaves so that the same note name maps to one chroma bin. Each column is a twelve-element vector showing how energy is distributed across the pitch classes at that time. It highlights harmonic and tonal content while discarding octave and timbre information.','A chroma display folds all octaves into twelve pitch classes. Every C lands in the same bin. Each column shows energy across the twelve notes. Octave and timbre are dropped. It reveals chords and key. It is a tool for musical harmony.','It summarizes tonal content by pitch class so chords, keys, and harmonic progressions become visible regardless of octave.','Chord-recognition and cover-song systems compute chroma features to compare harmonic content between recordings.','Sound Visualization & Acoustic Imaging',ARRAY['Chromagram','CENS chromagram','Pitch class','Constant-Q transform','Harmony']::text[],ARRAY['Expecting a chroma display to show octave or timbre','Confusing pitch class with absolute pitch','Assuming it separates simultaneous instruments']::text[],ARRAY['Detecting chords in a song','Matching cover versions by harmony','Estimating musical key']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chroma display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd8307881-96f3-5978-817d-410c30fc01a6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d8307881-96f3-5978-817d-410c30fc01a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d8307881-96f3-5978-817d-410c30fc01a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4064c101-f8f1-5616-922a-507bec3bad44','CENS chromagram','A CENS (Chroma Energy Normalized Statistics) chromagram is a smoothed and normalized chroma feature in which short-time chroma vectors are quantized, energy-normalized, then averaged over a window and downsampled, increasing robustness to dynamics, timbre, and local variation. The energy normalization removes loudness dependence and the smoothing suppresses fast fluctuations, yielding features well suited to music matching and alignment. It is a standard descriptor in music-information retrieval.','A CENS chromagram is a cleaned-up chroma feature. It normalizes energy so loudness does not matter. It smooths over a short window. This makes it steady and robust. It ignores timbre and small changes. It is used to match and align music.','It produces robust, loudness-independent chroma features that stay stable under changes in dynamics, tempo, and instrumentation.','Music-retrieval tools use CENS features for audio matching, cover-song detection, and score-to-audio alignment.','Sound Visualization & Acoustic Imaging',ARRAY['Chroma display','Chromagram','Music information retrieval','Pitch class','Feature normalization']::text[],ARRAY['Confusing plain chroma with the normalized CENS variant','Assuming CENS keeps fine temporal detail','Ignoring the smoothing window''s effect on results']::text[],ARRAY['Matching a live take to a studio recording','Detecting cover songs','Aligning audio to a musical score']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='CENS chromagram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4064c101-f8f1-5616-922a-507bec3bad44','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4064c101-f8f1-5616-922a-507bec3bad44') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4064c101-f8f1-5616-922a-507bec3bad44');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c34d356b-39d5-5442-b70e-31c6f67533ed','Tempogram','A tempogram is a time-tempo visualization showing the local strength of rhythmic periodicities in a signal as a function of time and tempo, typically computed by analyzing an onset-strength or novelty function for recurring pulses. Bright horizontal bands mark dominant tempi and their harmonics, and the display can be built by short-time Fourier analysis or autocorrelation of the novelty curve. It is a core tool for tempo estimation and beat tracking.','A tempogram shows tempo over time. One axis is time. The other is beats per minute. Bright bands mark the strongest pulse rates. It is built from a note-onset curve. It helps find the beat.','It reveals which tempi are active at each moment, supporting beat tracking, tempo estimation, and rhythm analysis.','Beat-tracking tools compute a tempogram to lock onto a song''s tempo and follow tempo changes.','Sound Visualization & Acoustic Imaging',ARRAY['Onset strength envelope','Novelty curve','Cyclic tempogram','Beat tracking','Autocorrelation']::text[],ARRAY['Confusing a tempo harmonic with the true tempo','Reading the tempo axis as frequency in hertz','Assuming a single tempo for music that speeds up or slows down']::text[],ARRAY['Estimating a song''s tempo','Following tempo drift in a live take','Feeding a beat tracker']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tempogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c34d356b-39d5-5442-b70e-31c6f67533ed','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c34d356b-39d5-5442-b70e-31c6f67533ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c34d356b-39d5-5442-b70e-31c6f67533ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'decda90a-e929-5dcc-9d8f-37f07d5af386','Cyclic tempogram','A cyclic tempogram is a tempo representation in which tempi related by integer ratios are folded into a single tempo class, analogous to how a chromagram folds octaves into pitch classes. This removes the ambiguity between a tempo and its double or half, producing a compact, tempo-octave-invariant descriptor of rhythmic content. It is used for robust tempo-based comparison and music-structure analysis.','A cyclic tempogram folds related tempi together. A tempo and its double share one class. This is like folding octaves in chroma. It removes double-or-half confusion. The result is compact and steady. It helps compare rhythm across pieces.','It yields a tempo-octave-invariant feature so pieces are compared by rhythmic feel without confusion between a tempo and its multiples.','Music-structure and similarity systems use cyclic tempograms to compare rhythmic content robustly across recordings.','Sound Visualization & Acoustic Imaging',ARRAY['Tempogram','Tempo class','Onset strength envelope','Music information retrieval','Beat tracking']::text[],ARRAY['Confusing a cyclic tempogram with a plain tempogram','Expecting it to give one absolute tempo value','Ignoring how the reference tempo sets the classes']::text[],ARRAY['Comparing rhythmic feel between songs','Analyzing music structure by tempo','Reducing octave ambiguity in tempo']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cyclic tempogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'decda90a-e929-5dcc-9d8f-37f07d5af386','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='decda90a-e929-5dcc-9d8f-37f07d5af386') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='decda90a-e929-5dcc-9d8f-37f07d5af386');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '403efe82-e90a-5a7d-8777-88e358aff193','Onset strength envelope','An onset strength envelope, or onset detection function, is a one-dimensional curve over time whose peaks indicate the likely onsets of notes or events, usually derived by measuring frame-to-frame increases in spectral energy and half-wave rectifying the result. It compresses a spectrogram into a single novelty-like signal in which sudden energy rises stand out as peaks. It is the front end for onset detection, beat tracking, and tempo analysis.','An onset strength envelope is a curve that peaks at note starts. It measures how fast energy rises between frames. Only rises count, not falls. Sharp attacks make tall peaks. It reduces a spectrogram to one line. Beat and onset tools read it.','It condenses spectral change into a single curve whose peaks mark event onsets for rhythm and onset analysis.','Onset and beat trackers compute an onset strength envelope, then pick its peaks to place note or beat times.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral flux','Onset detection','Novelty curve','Tempogram','Beat tracking']::text[],ARRAY['Treating every small peak as a true onset','Ignoring rectification so energy drops add false onsets','Using it directly as a loudness measure']::text[],ARRAY['Detecting note starts in a recording','Driving a beat tracker','Aligning percussion hits']::text[],'intermediate','O(t) = Σ_f max(0, |X(t,f)| − |X(t−1,f)|)','The onset strength at each frame sums, across frequency, the positive increases in magnitude from the previous frame.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Onset strength envelope');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '403efe82-e90a-5a7d-8777-88e358aff193','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='403efe82-e90a-5a7d-8777-88e358aff193') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='403efe82-e90a-5a7d-8777-88e358aff193');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f38a8be-c819-502e-88f9-eb7f46f49c82','Novelty curve','A novelty curve is a time function that measures how much a signal''s local content changes from moment to moment, with peaks marking boundaries, transitions, or onsets. It is commonly derived from a self-similarity matrix by correlating a checkerboard kernel along its main diagonal, or from frame-to-frame differences of spectral or chroma features. High novelty marks points where the sound shifts to a new state.','A novelty curve tracks how fast a sound changes. It peaks where content shifts. A calm passage gives a low, flat curve. A sudden change gives a tall peak. It can come from a similarity image. It helps find section edges and onsets.','It flags moments of change so structural boundaries, onsets, and transitions can be located automatically.','Music-structure tools compute a novelty curve to segment a track into intro, verse, chorus, and other sections.','Sound Visualization & Acoustic Imaging',ARRAY['Self-similarity matrix','Onset strength envelope','Checkerboard kernel','Music structure analysis','Segmentation']::text[],ARRAY['Confusing a novelty curve with a loudness envelope','Assuming every peak is a musical boundary','Ignoring the kernel size that sets the time scale of change']::text[],ARRAY['Segmenting a song into sections','Detecting scene changes in audio','Finding transitions in a long recording']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Novelty curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f38a8be-c819-502e-88f9-eb7f46f49c82','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f38a8be-c819-502e-88f9-eb7f46f49c82') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f38a8be-c819-502e-88f9-eb7f46f49c82');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '13f42b22-4c76-55f9-ad77-68687c4581e6','Self-similarity matrix','A self-similarity matrix (SSM) is a square image formed by comparing every frame of a feature sequence with every other frame, so that entry (i, j) encodes the similarity, often cosine similarity, between features at times i and j. Repeated sections appear as diagonal stripes parallel to the main diagonal, and homogeneous passages appear as square blocks. It is a central tool for visualizing and analyzing musical and acoustic structure.','A self-similarity matrix compares a sound to itself. Each point rates how alike two moments are. The main diagonal is always bright. Repeats show as parallel stripes. Steady parts show as blocks. It reveals a song''s structure.','It exposes repetition and structure by showing which moments of a signal resemble which others.','Structure-analysis tools build a self-similarity matrix from chroma or MFCC features to find choruses, repeats, and section boundaries.','Sound Visualization & Acoustic Imaging',ARRAY['Novelty curve','Recurrence plot','Feature sequence','Music structure analysis','Cosine similarity']::text[],ARRAY['Confusing diagonal stripes (repeats) with block structure (homogeneity)','Assuming any feature choice gives the same matrix','Reading the bright main diagonal as meaningful structure']::text[],ARRAY['Finding repeated choruses in a song','Visualizing musical form','Comparing feature types for structure']::text[],'advanced','S(i,j) = ⟨v_i, v_j⟩ / (‖v_i‖·‖v_j‖)','Each matrix entry is the cosine similarity between the feature vectors at frames i and j.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Self-similarity matrix');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '13f42b22-4c76-55f9-ad77-68687c4581e6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='13f42b22-4c76-55f9-ad77-68687c4581e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='13f42b22-4c76-55f9-ad77-68687c4581e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d0d1f5d-0e6d-5c9f-8f54-ac16813be542','Recurrence plot','A recurrence plot is a binary or graded square image that marks the times at which a system''s trajectory in feature or phase space returns close to a previously visited state, placing a point where the distance between two states falls below a chosen threshold. Introduced for nonlinear dynamics, it reveals periodicity, drift, and repeated patterns as diagonal and block structures. In audio it is applied to feature sequences to expose recurrence and structure.','A recurrence plot marks when a signal revisits a past state. A dot appears where two moments are close enough. Repeats form diagonal lines. Steady spells form blocks. It comes from nonlinear science. In audio it shows repeated patterns.','It visualizes when a signal returns near earlier states, exposing repetition, periodicity, and structure.','Analysts build recurrence plots from audio features to study repetition, rhythm, and structural patterns.','Sound Visualization & Acoustic Imaging',ARRAY['Self-similarity matrix','Phase space','Threshold','Music structure analysis','Nonlinear dynamics']::text[],ARRAY['Confusing a recurrence plot with a plain similarity matrix','Choosing a threshold without checking its effect','Reading noise speckle as true recurrence']::text[],ARRAY['Studying repetition in a rhythm','Analyzing a signal''s periodic structure','Comparing recurrence across passages']::text[],'advanced','R(i,j) = Θ(ε − ‖x_i − x_j‖)','An entry is one when the distance between the states at times i and j is below the threshold epsilon, and zero otherwise.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Recurrence plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d0d1f5d-0e6d-5c9f-8f54-ac16813be542','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d0d1f5d-0e6d-5c9f-8f54-ac16813be542') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d0d1f5d-0e6d-5c9f-8f54-ac16813be542');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb16215e-45f2-52b1-a9d4-17dfd6ecb010','Modulation spectrogram','A modulation spectrogram is a two-stage time-frequency display that shows how the amplitude envelope in each acoustic frequency band fluctuates, plotting acoustic frequency against modulation frequency, the rate of those envelope fluctuations. It is computed by extracting subband envelopes from a first spectral analysis and applying a second frequency analysis to each envelope. It emphasizes the slow temporal modulations that carry much of speech intelligibility.','A modulation spectrogram shows how loudness wobbles in each band. First it splits sound into frequency bands. Then it measures how fast each band''s level changes. One axis is sound frequency. The other is wobble rate. Slow wobbles carry a lot of speech meaning.','It reveals the rates at which band energies fluctuate, capturing the slow modulations important for speech and perception.','Speech-intelligibility and hearing-aid research uses modulation spectrograms to study and preserve important envelope modulation rates.','Sound Visualization & Acoustic Imaging',ARRAY['Amplitude modulation','Temporal envelope','Spectrotemporal modulation display','Filterbank','Speech intelligibility']::text[],ARRAY['Confusing modulation frequency with acoustic frequency','Assuming it is a single-stage transform','Ignoring the band spacing of the first analysis']::text[],ARRAY['Studying speech intelligibility','Designing hearing-aid processing','Analyzing envelope rates in noise']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modulation spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb16215e-45f2-52b1-a9d4-17dfd6ecb010','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb16215e-45f2-52b1-a9d4-17dfd6ecb010') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb16215e-45f2-52b1-a9d4-17dfd6ecb010');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f8bc170-3fa9-5ba0-a70c-c33b8ad1c287','Spectrotemporal modulation display','A spectrotemporal modulation display visualizes how energy in a spectrogram is modulated jointly across frequency (spectral modulation, in cycles per octave) and time (temporal modulation, in hertz), typically via a two-dimensional analysis of an auditory spectrogram. It characterizes patterns such as upward or downward frequency sweeps and rates of amplitude change, reflecting cortical receptive-field models of hearing. It is used in auditory neuroscience and in audio analysis of texture and timbre.','This display shows two kinds of change at once. One is how energy varies across frequency. The other is how it varies over time. It measures ripples up and down the spectrum. It also measures how fast levels change. It follows models of the hearing brain.','It captures joint spectral and temporal modulation patterns that models of the auditory cortex use to describe sound texture and timbre.','Auditory neuroscientists and audio researchers use spectrotemporal modulation to model perception and to characterize timbre and texture.','Sound Visualization & Acoustic Imaging',ARRAY['Modulation spectrogram','Auditory spectrogram','Spectral modulation','Temporal modulation','Cortical model']::text[],ARRAY['Confusing spectral modulation with plain frequency','Assuming it replaces a standard spectrogram','Overlooking that it builds on an auditory model']::text[],ARRAY['Modeling auditory cortex responses','Characterizing sound texture','Studying timbre perception']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectrotemporal modulation display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f8bc170-3fa9-5ba0-a70c-c33b8ad1c287','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f8bc170-3fa9-5ba0-a70c-c33b8ad1c287') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f8bc170-3fa9-5ba0-a70c-c33b8ad1c287');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e73e2a92-ec4d-543c-912d-5a1b6790dda3','Cochleagram','A cochleagram is a time-frequency display of sound energy produced by a model of cochlear filtering, in which a bank of overlapping bandpass filters with bandwidths that widen with center frequency replaces the uniform bins of a short-time Fourier transform. The filter outputs are rectified and smoothed to approximate the energy along the basilar membrane, giving frequency resolution and warping that follow the auditory system. It underlies many auditory-model and source-separation methods.','A cochleagram is a hearing-based spectrogram. It uses filters that copy the inner ear. Low bands are narrow. High bands are wide. The filter outputs are smoothed into energy. It follows the ear, not a plain FFT. It suits models of hearing.','It represents sound the way the cochlea does, giving auditory-matched frequency analysis for perception and separation models.','Computational auditory scene analysis and speech-separation systems use cochleagrams as an ear-like front end.','Sound Visualization & Acoustic Imaging',ARRAY['Gammatone spectrogram','Auditory spectrogram','Critical-band display','Basilar membrane','Filterbank']::text[],ARRAY['Assuming a cochleagram uses uniform FFT bins','Confusing it with a linear spectrogram','Ignoring that filter bandwidth grows with frequency']::text[],ARRAY['Modeling hearing in noise','Separating mixed sound sources','Building an auditory front end']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cochleagram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e73e2a92-ec4d-543c-912d-5a1b6790dda3','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e73e2a92-ec4d-543c-912d-5a1b6790dda3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e73e2a92-ec4d-543c-912d-5a1b6790dda3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7aecbbb8-3c91-5904-a3a7-11668d6ce4e3','Auditory spectrogram','An auditory spectrogram is a spectrogram computed through a model of the peripheral auditory system rather than a uniform short-time Fourier transform, using filters spaced on a perceptual scale with bandwidths matching the ear''s critical bands, followed by nonlinear compression and adaptation stages. The result emphasizes perceptually relevant detail and warps frequency toward how humans hear. It is common in perceptual audio analysis and machine hearing.','An auditory spectrogram mimics how we hear. It uses ear-like filters, not equal FFT bins. Bands follow the ear''s critical bands. Loudness is compressed like hearing. It keeps what matters to a listener. It suits perceptual and machine-hearing work.','It shapes the spectrogram to auditory perception so displayed detail reflects what a listener actually hears.','Perceptual coding and machine-hearing systems use auditory spectrograms to match analysis to human hearing.','Sound Visualization & Acoustic Imaging',ARRAY['Cochleagram','Gammatone spectrogram','Critical-band display','Bark spectrogram','Perceptual model']::text[],ARRAY['Assuming an auditory spectrogram uses linear FFT bins','Confusing perceptual warping with a simple log axis','Overlooking its compression and adaptation stages']::text[],ARRAY['Analyzing perceived loudness patterns','Feeding a machine-hearing model','Comparing perceptual and FFT views']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auditory spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7aecbbb8-3c91-5904-a3a7-11668d6ce4e3','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7aecbbb8-3c91-5904-a3a7-11668d6ce4e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7aecbbb8-3c91-5904-a3a7-11668d6ce4e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aaba3410-e6e6-5fbd-8d36-73dfe31c4055','Gammatone spectrogram','A gammatone spectrogram is a cochlea-inspired time-frequency display built from a bank of gammatone filters, whose impulse response is a gamma-distribution envelope multiplying a sinusoidal carrier, with center frequencies and bandwidths spaced on the equivalent-rectangular-bandwidth scale. Each filter''s output energy is plotted over time and center frequency, approximating the frequency selectivity of the basilar membrane. It is a standard front end in auditory modeling and computational auditory scene analysis.','A gammatone spectrogram uses ear-like filters called gammatones. Each filter is a short tone shaped by a smooth envelope. Their spacing follows the ear''s bandwidths. The filter energies are drawn over time. It copies the inner ear''s tuning. It is common in hearing models.','It provides an ear-matched filterbank front end whose tuning mimics the cochlea for auditory analysis.','Auditory models and speech-separation systems compute gammatone spectrograms as a physiologically motivated input.','Sound Visualization & Acoustic Imaging',ARRAY['Gammatone filter','Cochleagram','ERB scale','Auditory spectrogram','Filterbank']::text[],ARRAY['Confusing gammatone spacing with mel spacing','Assuming equal bandwidth across filters','Treating it as a plain FFT spectrogram']::text[],ARRAY['Modeling cochlear filtering','Separating speech from noise','Building an auditory feature front end']::text[],'advanced','g(t) = a·t^(n−1)·e^(−2πbt)·cos(2πf_c·t + φ)','A gammatone filter''s impulse response is a power-of-time gamma envelope times a decaying exponential, multiplying a cosine carrier at the center frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gammatone spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aaba3410-e6e6-5fbd-8d36-73dfe31c4055','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aaba3410-e6e6-5fbd-8d36-73dfe31c4055') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aaba3410-e6e6-5fbd-8d36-73dfe31c4055');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4ac92a1-cab2-5410-a5ea-309d3a2c1ea4','Bark spectrogram','A Bark spectrogram is a spectrogram whose frequency axis is mapped to the Bark scale, a perceptual scale of about 24 critical bands in which equal Bark distances correspond to equal perceptual widths along the basilar membrane. Short-time Fourier power is grouped into Bark-spaced bands, compressing higher frequencies to match auditory critical-band resolution. It is used in perceptual audio coding and loudness-related analysis.','A Bark spectrogram warps frequency to the Bark scale. That scale follows the ear''s critical bands. It has about 24 steps. Each step is one critical band wide. High frequencies get grouped together. It suits perceptual coding and loudness work.','It aligns the frequency axis with auditory critical bands so displayed resolution matches perceptual frequency grouping.','Perceptual audio codecs and loudness tools analyze sound on a Bark scale to match masking and critical-band effects.','Sound Visualization & Acoustic Imaging',ARRAY['Bark scale','Critical-band display','Mel spectrogram','Critical band','Perceptual model']::text[],ARRAY['Confusing the Bark scale with the mel scale','Assuming equal-hertz bands under a Bark axis','Ignoring that Bark bands widen with frequency']::text[],ARRAY['Analyzing masking for a codec','Studying critical-band loudness','Comparing Bark and mel warping']::text[],'intermediate','z = 13·arctan(0.00076f) + 3.5·arctan((f/7500)²)','The Bark value is a sum of two arctangent terms of frequency that map hertz onto the roughly twenty-four-band critical-band scale.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bark spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4ac92a1-cab2-5410-a5ea-309d3a2c1ea4','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4ac92a1-cab2-5410-a5ea-309d3a2c1ea4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4ac92a1-cab2-5410-a5ea-309d3a2c1ea4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd6a64c4c-3fa9-5643-8b1c-c9a1575cbca9','Critical-band display','A critical-band display presents sound energy grouped into the ear''s critical bands, frequency regions within which one sound strongly masks another and beyond which masking weakens. Rather than uniform Fourier bins, energy is summed into bands whose widths follow auditory measurements, such as the Bark or equivalent-rectangular-bandwidth scales, so each band reflects a roughly constant perceptual span. It supports masking, loudness, and perceptual-coding analysis.','A critical-band display groups energy by the ear''s bands. Inside one band, sounds mask each other strongly. The bands get wider at high frequency. It sums energy per band, not per FFT bin. It follows how hearing groups frequency. It helps study masking and loudness.','It groups spectral energy by auditory critical bands so masking and loudness relationships become visible.','Perceptual coders and loudness meters analyze energy per critical band to predict masking and perceived level.','Sound Visualization & Acoustic Imaging',ARRAY['Critical band','Bark scale','ERB scale','Auditory masking','Bark spectrogram']::text[],ARRAY['Assuming critical bands have equal width in hertz','Confusing a critical-band display with a plain spectrum','Ignoring that band edges are gradual, not sharp']::text[],ARRAY['Predicting masking in a codec','Estimating loudness per band','Studying auditory frequency grouping']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Critical-band display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd6a64c4c-3fa9-5643-8b1c-c9a1575cbca9','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d6a64c4c-3fa9-5643-8b1c-c9a1575cbca9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d6a64c4c-3fa9-5643-8b1c-c9a1575cbca9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0253ec81-6a77-5359-a724-db07bea4e568','Cepstrogram','A cepstrogram is a time-varying display of the cepstrum, plotting quefrency on one axis against time on the other, formed by computing the cepstrum of each short-time frame of a signal. Because the cepstrum is the inverse transform of the log-magnitude spectrum, it separates slowly varying spectral envelope from periodic fine structure, so a voiced pitch period appears as a peak at a characteristic quefrency that can be tracked over time. It is used for pitch tracking and source-filter separation.','A cepstrogram shows the cepstrum over time. The cepstrum comes from the log spectrum, transformed again. It splits the broad shape from the fine ripple. A voiced pitch shows as a peak at one quefrency. Tracking that peak follows pitch. It aids voice analysis.','It tracks cepstral features such as the pitch peak over time and helps separate spectral envelope from fine structure.','Speech tools use a cepstrogram to follow voice pitch and to separate the vocal-tract envelope from the source.','Sound Visualization & Acoustic Imaging',ARRAY['Cepstrum','Quefrency plot','Pitch track','MFCC display','Source-filter model']::text[],ARRAY['Confusing quefrency with frequency','Reading the envelope region as pitch information','Assuming a clear cepstral peak for unvoiced sounds']::text[],ARRAY['Tracking voice pitch over time','Separating source and vocal-tract shape','Analyzing periodicity in speech']::text[],'advanced','c(τ) = F⁻¹{ log|F{x(t)}| }','The cepstrum is the inverse Fourier transform of the logarithm of the magnitude of the signal''s Fourier transform, computed per frame for a cepstrogram.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cepstrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0253ec81-6a77-5359-a724-db07bea4e568','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0253ec81-6a77-5359-a724-db07bea4e568') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0253ec81-6a77-5359-a724-db07bea4e568');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '765683b0-ee11-53f9-9cf3-991cd944d321','MFCC display','An MFCC display is a visualization of mel-frequency cepstral coefficients over time, showing each frame''s low-order cepstral coefficients derived by taking a discrete cosine transform of the log energies of a mel filterbank. The coefficients compactly describe spectral-envelope shape while discarding pitch fine structure, and the display plots coefficient index against time. Mel-frequency cepstral coefficients are a long-standing feature set for speech and audio recognition.','An MFCC display shows mel cepstral coefficients over time. First energy is grouped into mel bands. Then the log is taken. A cosine transform compresses it to a few numbers. Those numbers describe the spectral shape. Speech and audio systems use them widely.','It presents a compact set of envelope-describing features per frame, the standard input for many speech and audio classifiers.','Speech recognition and audio-tagging systems compute and visualize MFCCs to inspect the features fed to their models.','Sound Visualization & Acoustic Imaging',ARRAY['Mel spectrogram','Cepstrum','Discrete cosine transform','Mel filterbank','Feature extraction']::text[],ARRAY['Confusing MFCCs with a mel spectrogram','Reading coefficient index as frequency','Keeping too many coefficients and capturing pitch fine structure']::text[],ARRAY['Preparing features for speech recognition','Inspecting classifier inputs','Comparing sounds by spectral shape']::text[],'intermediate','MFCC_k = Σ_m log(E_m)·cos[k(m−½)π/M]','Each coefficient is a discrete cosine transform of the log energies of the mel filterbank across its M bands.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='MFCC display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '765683b0-ee11-53f9-9cf3-991cd944d321','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='765683b0-ee11-53f9-9cf3-991cd944d321') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='765683b0-ee11-53f9-9cf3-991cd944d321');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c210f944-e9af-587d-89c0-bd5df20226fd','Quefrency plot','A quefrency plot displays the cepstrum of a signal against quefrency, the independent variable of the cepstral domain, which has units of time and corresponds to periodicities and echo delays in the log spectrum. Peaks at a given quefrency reveal periodic structure such as a voice pitch period or an echo, while the low-quefrency region carries the spectral envelope. The terms quefrency, cepstrum, and liftering are deliberate rearrangements of frequency, spectrum, and filtering.','A quefrency plot shows the cepstrum against quefrency. Quefrency is measured in time, not hertz. A peak marks a repeat period or echo. Low quefrency holds the broad spectral shape. A voice pitch shows as a clear peak. The odd names come from rearranged words.','It exposes periodicities and echoes as peaks in the cepstral domain, aiding pitch detection and echo analysis.','Engineers read a quefrency plot to find a voice''s pitch period or to detect an echo delay in a signal.','Sound Visualization & Acoustic Imaging',ARRAY['Cepstrum','Cepstrogram','Quefrency','Liftering','Pitch track']::text[],ARRAY['Treating quefrency as an ordinary frequency axis','Confusing the envelope region with the pitch peak','Assuming every signal shows a clear cepstral peak']::text[],ARRAY['Finding a voice pitch period','Detecting an echo delay','Separating envelope from fine structure']::text[],'advanced','c(τ) = F⁻¹{ log|X(f)| },  τ = quefrency','The cepstrum plotted against quefrency is the inverse transform of the log-magnitude spectrum, where quefrency has units of time.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quefrency plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c210f944-e9af-587d-89c0-bd5df20226fd','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c210f944-e9af-587d-89c0-bd5df20226fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c210f944-e9af-587d-89c0-bd5df20226fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '94c9bda3-2fdb-5c1c-8542-0fbc875c35bf','Pitch track','A pitch track is a time plot of a signal''s estimated fundamental frequency, tracing how perceived pitch rises and falls over the course of a sound. It is produced by a pitch-estimation algorithm operating on the waveform, its autocorrelation, or its spectrum, and is typically drawn as a curve overlaid on or beside a spectrogram. Gaps appear where the signal is unvoiced or the estimate is unreliable.','A pitch track is a line of estimated pitch over time. It follows the fundamental frequency. The line rises and falls with the melody. Gaps appear in unvoiced parts. Software guesses the pitch each frame. It shows how pitch moves.','It reduces a sound to its pitch contour so melody, intonation, and pitch changes can be read and measured.','Pitch-correction and phonetics tools display a pitch track to show a singer''s or speaker''s fundamental frequency over time.','Sound Visualization & Acoustic Imaging',ARRAY['Fundamental frequency','Pitch detection','Formant track','Autocorrelation','Cepstrogram']::text[],ARRAY['Confusing the fundamental with a stronger harmonic, an octave error','Reading tracker gaps as silence','Assuming pitch tracking works well in noise or polyphony']::text[],ARRAY['Tuning a vocal take','Studying speech intonation','Analyzing a melody''s contour']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pitch track');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '94c9bda3-2fdb-5c1c-8542-0fbc875c35bf','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='94c9bda3-2fdb-5c1c-8542-0fbc875c35bf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='94c9bda3-2fdb-5c1c-8542-0fbc875c35bf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67af5c75-4564-5eed-aea9-fc2811d22eb2','Formant track','A formant track is the trace of a speech formant, a vocal-tract resonance, as its center frequency changes over time, usually estimated by linear predictive analysis or spectral peak picking and drawn over a spectrogram. Multiple formant tracks, labeled F1, F2, F3 and upward, capture the moving resonances that distinguish vowels and shape speech. Their trajectories reveal coarticulation and vowel transitions.','A formant track follows a speech resonance over time. The vocal tract has several resonances. Each one is a formant. The track shows how a formant moves. Formants define vowels. Their paths show how speech sounds glide.','It shows how vocal-tract resonances move over time, which distinguishes vowels and reveals coarticulation in speech.','Phoneticians overlay formant tracks on a spectrogram to study vowel quality and transitions between speech sounds.','Sound Visualization & Acoustic Imaging',ARRAY['Formant','Formant plot','Linear predictive coding','Vowel','Spectrogram']::text[],ARRAY['Confusing a formant with a voice harmonic','Trusting automatic tracks in noisy or nasal speech','Mislabeling which resonance is F1 versus F2']::text[],ARRAY['Studying vowel transitions','Analyzing accents','Checking speech-synthesis output']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formant track');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67af5c75-4564-5eed-aea9-fc2811d22eb2','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67af5c75-4564-5eed-aea9-fc2811d22eb2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67af5c75-4564-5eed-aea9-fc2811d22eb2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7f39daf-fbdf-5e76-8bec-c0a49b113154','Formant plot','A formant plot is a display of speech formant frequencies, most often a two-dimensional scatter of the first formant (F1) against the second (F2) that maps the vowel space, though it may also show formant values against time or number. Because F1 relates to vowel height and F2 to backness, vowels occupy characteristic regions, making the plot a standard tool in phonetics. Points or ellipses represent vowels from one or many talkers.','A formant plot shows formant frequencies of speech. A common form plots F1 against F2. That layout maps the vowel space. Each vowel sits in its own area. F1 links to how open the vowel is. F2 links to front or back.','It arranges vowels by their formant frequencies so vowel identity and differences between talkers become visible.','Phoneticians use F1-versus-F2 formant plots to compare vowels across speakers, dialects, and languages.','Sound Visualization & Acoustic Imaging',ARRAY['Formant','Formant track','Vowel space','Linear predictive coding','Phonetics']::text[],ARRAY['Confusing a formant plot with a spectrogram','Assuming fixed formant values across all speakers','Ignoring how F1 and F2 map to vowel height and backness']::text[],ARRAY['Mapping a speaker''s vowel space','Comparing dialects by vowels','Teaching vowel acoustics']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formant plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7f39daf-fbdf-5e76-8bec-c0a49b113154','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7f39daf-fbdf-5e76-8bec-c0a49b113154') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7f39daf-fbdf-5e76-8bec-c0a49b113154');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '151e3301-b67d-55cb-9cf8-df18f652522d','Spectral ridge','A spectral ridge is a bright, locally maximal line in a time-frequency display that traces a dominant frequency component, harmonic, or resonance as it evolves over time. Ridges correspond to local energy maxima along the frequency axis and mark where the signal''s energy concentrates; ridge extraction follows these maxima to estimate instantaneous frequency. They are central to reading and parameterizing spectrograms.','A spectral ridge is a bright line in a spectrogram. It follows a strong frequency over time. It marks where energy peaks in frequency. A steady tone makes a flat ridge. A sweep makes a sloped one. Tracking ridges gives frequency over time.','It marks where energy concentrates in frequency so dominant components can be traced and their frequency read over time.','Analysts follow spectral ridges to extract the instantaneous frequency of tones, harmonics, and sweeps from a spectrogram.','Sound Visualization & Acoustic Imaging',ARRAY['Harmonic ridge','Instantaneous frequency','Ridge extraction','Chirp trace','Spectrogram']::text[],ARRAY['Confusing a leakage skirt with a true ridge','Assuming the brightest ridge is always the fundamental','Tracking a ridge through a noisy gap as if continuous']::text[],ARRAY['Extracting a tone''s frequency over time','Following a frequency sweep','Reading harmonics of a note']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral ridge');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '151e3301-b67d-55cb-9cf8-df18f652522d','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='151e3301-b67d-55cb-9cf8-df18f652522d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='151e3301-b67d-55cb-9cf8-df18f652522d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '36f5d9b3-be30-568f-89a3-527e62f333b7','Harmonic ridge','A harmonic ridge is a spectral ridge that belongs to a harmonic series, appearing as one of a set of parallel bright lines at integer multiples of a fundamental frequency in a spectrogram. As the fundamental changes, all harmonic ridges move together in a fixed ratio, so their coordinated motion identifies a single pitched source. Reading harmonic ridges supports pitch estimation and source identification.','A harmonic ridge is a bright line from a harmonic. Harmonics sit at whole-number multiples of the pitch. They appear as parallel lines. When the pitch moves, they all move together. Their spacing reveals the fundamental. This helps find pitch and source.','It marks members of a harmonic series so a pitched source and its fundamental can be identified from their coordinated motion.','Pitch and source-separation tools track harmonic ridges to group a note''s overtones and estimate its fundamental.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral ridge','Harmonic','Fundamental frequency','Overtone','Pitch detection']::text[],ARRAY['Mistaking a single harmonic for the fundamental','Assuming harmonics are always equally bright','Confusing overlapping harmonics of two sources']::text[],ARRAY['Estimating pitch from overtones','Separating a note from a mix','Reading a voice''s harmonic structure']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic ridge');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '36f5d9b3-be30-568f-89a3-527e62f333b7','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='36f5d9b3-be30-568f-89a3-527e62f333b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='36f5d9b3-be30-568f-89a3-527e62f333b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '044d6e36-3301-521e-a706-ad991c4be0fd','Chirp trace','A chirp trace is the sloped line a frequency-swept signal, a chirp, leaves in a spectrogram, rising or falling in frequency over time according to the sweep rate. A linear chirp appears as a straight diagonal and a logarithmic chirp as a curve, with the slope indicating how fast frequency changes. Chirp traces appear in test signals, sonar, radar, and many natural sounds.','A chirp trace is a sloping line in a spectrogram. It comes from a tone that sweeps in frequency. A rising sweep slopes upward. A falling sweep slopes down. The steeper the slope, the faster the sweep. Test signals and animal calls show them.','It shows a frequency sweep visually, so its direction and rate of change can be read directly from the slope.','Engineers view chirp traces to check sweep test signals, and bioacousticians see them in animal calls.','Sound Visualization & Acoustic Imaging',ARRAY['Chirp','Glissando trace','Instantaneous frequency','Spectral ridge','Sweep']::text[],ARRAY['Confusing a linear-hertz slope with a musical slide','Assuming every sweep is linear','Reading a curved log-chirp as nonlinear distortion']::text[],ARRAY['Checking a sweep test signal','Analyzing sonar or radar chirps','Reading a swept animal call']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chirp trace');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '044d6e36-3301-521e-a706-ad991c4be0fd','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='044d6e36-3301-521e-a706-ad991c4be0fd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='044d6e36-3301-521e-a706-ad991c4be0fd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65f0f967-ac8b-5cbf-b82e-28d65506b192','Glissando trace','A glissando trace is the sloped time-frequency line produced when a musical pitch slides continuously from one note to another, visible in a spectrogram as a rising or falling ridge, often accompanied by parallel harmonic ridges that slide together. On a log-frequency axis a constant musical slide appears as a straight line, matching perceived pitch change. It is the musical counterpart of a chirp trace.','A glissando trace is a sloping line from a pitch slide. A singer or slide guitar can make one. The pitch glides smoothly between notes. It shows as a rising or falling ridge. Harmonics slide along with it. It is the musical version of a chirp.','It visualizes a continuous musical pitch slide so its direction, range, and speed can be seen in the time-frequency plane.','Music analysts spot glissando traces to study slides, portamento, and pitch bends in performances.','Sound Visualization & Acoustic Imaging',ARRAY['Glissando','Chirp trace','Portamento','Harmonic ridge','Log-frequency spectrogram']::text[],ARRAY['Confusing a glissando with vibrato''s small wobble','Expecting a straight line on a linear-hertz axis','Ignoring that harmonics slide with the fundamental']::text[],ARRAY['Analyzing a vocal slide','Studying a slide-guitar phrase','Measuring a pitch bend']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Glissando trace');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65f0f967-ac8b-5cbf-b82e-28d65506b192','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65f0f967-ac8b-5cbf-b82e-28d65506b192') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65f0f967-ac8b-5cbf-b82e-28d65506b192');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ff0a933-e96d-5c48-90f6-cf505097c6e9','Transient smear','Transient smear is the visible spreading of a sharp, brief event across time in a spectrogram, caused by the finite length of the analysis window, which spreads a click or attack over the window''s duration. A longer window worsens the smear in time even as it sharpens frequency, so transients look blurred; shortening the window reduces smear at the cost of frequency resolution. It is a direct manifestation of the time-frequency resolution trade-off.','Transient smear is the blur of a sharp sound in a spectrogram. A click should be a thin vertical line. A long window spreads it out in time. This blur comes from the analysis window. A shorter window reduces it. It reflects the resolution trade-off.','It reminds the analyst that sharp events are blurred by the analysis window, guiding window choice for transient detail.','When inspecting drum hits or clicks, an engineer shortens the window to cut transient smear and see attacks clearly.','Sound Visualization & Acoustic Imaging',ARRAY['Window length','Transient','Time resolution','Wideband spectrogram','Pre-echo visualization']::text[],ARRAY['Reading transient smear as a real feature of the sound','Using a long window when timing detail matters','Assuming a smaller hop removes smear rather than the window']::text[],ARRAY['Locating a drum hit precisely','Choosing a window for percussive audio','Diagnosing blurred attacks']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Transient smear');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ff0a933-e96d-5c48-90f6-cf505097c6e9','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ff0a933-e96d-5c48-90f6-cf505097c6e9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ff0a933-e96d-5c48-90f6-cf505097c6e9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cade3ecf-b846-5a8c-9e7e-8f6a75f25f05','Pre-echo visualization','Pre-echo visualization is the display, usually in a spectrogram, of a pre-echo artifact: a faint copy or spread of a sharp transient''s energy appearing shortly before the transient itself. In transform-based audio coders, quantization spreads a transient''s energy across the whole analysis block, so reconstructed energy leaks ahead of the attack; the artifact shows as a smear preceding a click or drum hit. Viewing it helps diagnose codec block-length and windowing problems.','Pre-echo visualization shows a smear before a sharp sound. Some codecs spread a transient''s energy over a block. Part of it appears before the real attack. In a spectrogram this looks like a faint pre-smear. It reveals coding artifacts. It helps diagnose codec settings.','It exposes pre-echo artifacts before transients so coding and windowing problems can be identified and addressed.','Codec developers inspect spectrograms for pre-echo before percussive attacks to tune block switching and window design.','Sound Visualization & Acoustic Imaging',ARRAY['Pre-echo','Transient smear','Perceptual audio coding','Block switching','Transient']::text[],ARRAY['Confusing pre-echo with room reverberation','Assuming any pre-transient energy is a recording fault','Ignoring that shorter coder blocks reduce the artifact']::text[],ARRAY['Diagnosing codec artifacts on percussion','Comparing block-switching schemes','Evaluating lossy-encoder quality']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pre-echo visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cade3ecf-b846-5a8c-9e7e-8f6a75f25f05','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cade3ecf-b846-5a8c-9e7e-8f6a75f25f05') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cade3ecf-b846-5a8c-9e7e-8f6a75f25f05');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '662bb6af-e25b-5dab-9122-74581941da4c','Spectral mask','A spectral mask is a selected region of the time-frequency plane, defined over a spectrogram, that designates which time-frequency points a process should keep, attenuate, or remove. It is the operational tool behind spectral editing and source separation, where a binary or soft mask multiplies the short-time Fourier transform before resynthesis to isolate or suppress chosen content. Mask design ranges from hand-drawn selections to algorithmically estimated separation masks.','A spectral mask marks a region of a spectrogram to act on. It says which time-frequency points to keep or cut. The mask multiplies the transform before rebuilding the sound. A hard mask is on or off. A soft mask uses in-between values. It drives editing and separation.','It specifies which time-frequency components to keep or remove, enabling spectral editing, repair, and source separation.','In tools like iZotope RX a user paints a spectral mask over a noise or a note, then attenuates or extracts that region.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral selection','Spectral repair display','Source separation','Time-frequency masking','Short-time Fourier transform']::text[],ARRAY['Confusing a hard binary mask with a soft ratio mask','Expecting mask edits to be free of artifacts','Masking too tightly and cutting wanted signal']::text[],ARRAY['Removing a cough from a recording','Separating a vocal from a mix','Attenuating a narrow noise']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral mask');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '662bb6af-e25b-5dab-9122-74581941da4c','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='662bb6af-e25b-5dab-9122-74581941da4c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='662bb6af-e25b-5dab-9122-74581941da4c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '65235652-7187-57d1-a37d-c2fa37f1e3fc','Spectral selection','Spectral selection is the act of choosing audio by a region of the time-frequency plane rather than by a time range alone, selecting specific frequencies within specific time spans on a spectrogram. It lets an editor grab, for example, a single noise or note without affecting other content at the same instant, and the selected region then feeds gain, repair, or extraction operations. It is the interaction model behind spectrogram editing.','Spectral selection means picking sound by area on a spectrogram. You choose both a time span and a frequency band. This grabs one sound without touching others at the same moment. A plain time selection cannot do that. The chosen area is then edited.','It lets an editor isolate content by both time and frequency, so overlapping sounds can be targeted separately.','Spectral editors let a user draw a box or lasso around a bird chirp on a spectrogram and process only that region.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral mask','Spectral repair display','Time-frequency editing','Short-time Fourier transform','Selection']::text[],ARRAY['Confusing spectral selection with a time-only selection','Assuming selected frequencies are cut perfectly cleanly','Selecting too broad a band and altering nearby sound']::text[],ARRAY['Selecting a single noise to remove','Grabbing one note from a chord region','Isolating a chirp for processing']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral selection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '65235652-7187-57d1-a37d-c2fa37f1e3fc','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='65235652-7187-57d1-a37d-c2fa37f1e3fc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='65235652-7187-57d1-a37d-c2fa37f1e3fc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '69d69c9d-834e-5c73-b160-1b8f068d1613','Spectral repair display','A spectral repair display is the interactive spectrogram interface in restoration software where unwanted sounds are located and then removed, attenuated, or resynthesized from surrounding time-frequency content. The user selects a region containing a click, hum, or noise, and the tool interpolates or attenuates that area, often using neighboring spectral data to fill gaps. It is the working surface for modern audio restoration.','A spectral repair display is a spectrogram you edit on. You find an unwanted sound in the image. Then you select and remove or reduce it. The tool can fill the gap from nearby data. It is used to clean recordings. It is a restoration workspace.','It provides a visual workspace for finding and removing unwanted sounds by editing the time-frequency image directly.','Restoration engineers use a spectral repair display in tools like RX to erase clicks, coughs, and noises from recordings.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral repair','Spectral mask','Spectral selection','Audio restoration','Interpolation']::text[],ARRAY['Expecting repairs to leave no trace at all','Repairing too aggressively and dulling the sound','Confusing attenuation with true interpolation fill']::text[],ARRAY['Removing a cough from dialogue','Erasing a click from a record transfer','Reducing a steady hum']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral repair display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '69d69c9d-834e-5c73-b160-1b8f068d1613','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='69d69c9d-834e-5c73-b160-1b8f068d1613') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='69d69c9d-834e-5c73-b160-1b8f068d1613');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b44bf8e2-dd61-58e0-a284-bbe2f1ea76ee','Sound-field visualization','A general term for representing an acoustic field spatially, so that quantities such as sound pressure, particle velocity, acoustic intensity, or phase are displayed as maps, vector fields, or surfaces over a region of space rather than as a single time signal at one point. It turns spatially distributed acoustic data, measured with microphone arrays or computed from acoustic models, into images that reveal how the field varies from place to place.','This turns sound into a picture. It shows how sound changes from place to place. You can see where sound is loud or soft. You can also see which way it flows. The picture comes from many mics or from a model.','It exists to make the spatial structure of a sound field intelligible, letting engineers see where energy concentrates, how it flows, and how pressure or phase are distributed, which a single-point measurement cannot convey.','Engineers use it in noise-source identification, loudspeaker and room analysis, product sound-quality work, and research, pairing microphone arrays or scanning probes with software that renders pressure, intensity, or phase maps.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic imaging','Sound intensity map','Nearfield acoustic holography','Acoustic beamforming map','Wavefront visualization']::text[],ARRAY['Treating a colour map as a literal photo of sound rather than a processed estimate','Assuming one visualization type such as pressure shows energy flow, which needs intensity','Ignoring frequency dependence, since the same source looks different at different frequencies']::text[],ARRAY['Locating a rattle or leak on a car body with an array','Showing a client where a room boosts bass','Comparing loudspeaker radiation before and after a redesign']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-field visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b44bf8e2-dd61-58e0-a284-bbe2f1ea76ee','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b44bf8e2-dd61-58e0-a284-bbe2f1ea76ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b44bf8e2-dd61-58e0-a284-bbe2f1ea76ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9af64756-65e4-51ff-8dd1-0ac0766260a8','Sound camera','An informal name for an acoustic camera: a measurement instrument that combines a microphone array with an optical camera and beamforming or related processing to produce an image in which sound-source strength is overlaid, usually as a colour map, on the visual scene. The array samples the sound field at many points, the processor estimates the direction and strength of arriving sound, and the result is shown as a picture of where the sound comes from.','A sound camera shows where sound comes from. It uses many small mics and a normal camera. A computer works out which spots are loud. It paints those spots with colour on the photo. People often call it an acoustic camera.','It lets a user see and locate sound sources quickly by mapping sound strength onto a familiar visual image, turning an invisible acoustic problem into an obvious coloured spot on a photograph.','Technicians use sound cameras to find noise leaks, rattles, air leaks, and faulty parts on machines, vehicles, and buildings, and to check where a loudspeaker or PA system radiates most strongly.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic camera','Microphone array','Acoustic beamforming map','Source localization map','Acoustic heat map']::text[],ARRAY['Believing the coloured spot is exact truth rather than a resolution-limited estimate','Expecting good low-frequency images from a small array, where resolution is poor','Confusing the optical camera view with the acoustic map''s real accuracy']::text[],ARRAY['Finding a wind-noise leak on a car in a wind tunnel','Spotting a noisy bearing on a running production line','Checking which panel of an appliance radiates the most noise']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound camera');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9af64756-65e4-51ff-8dd1-0ac0766260a8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9af64756-65e4-51ff-8dd1-0ac0766260a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9af64756-65e4-51ff-8dd1-0ac0766260a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8875fddc-40f9-588f-92a2-88be3493ab14','Microphone array visualization','The use of multiple microphones arranged in a known geometry, together with array-processing methods such as beamforming, time-difference-of-arrival, or acoustic holography, to estimate and display the spatial properties of a sound field: source direction, source location, or the distribution of pressure or intensity. The array spacing and aperture set the frequency range and spatial resolution of the resulting image.','This uses many mics in a set pattern to picture sound in space. Each mic hears the sound a little differently. A computer compares these small timing and level gaps. From that it works out where sound comes from. The mic spacing sets how sharp the picture is.','It provides the raw spatial sampling that all acoustic imaging relies on; by capturing the sound field at many points at once, it lets processing recover direction, position, and field maps that a single microphone cannot give.','Engineers meet it in acoustic cameras, noise-mapping rigs, holography scanners, and direction-finding systems, choosing array size and mic count to match the frequencies and resolution a task demands.','Sound Visualization & Acoustic Imaging',ARRAY['Microphone array','Acoustic beamforming map','Nearfield acoustic holography','Direction-of-arrival map','Array aperture']::text[],ARRAY['Assuming more microphones always means a better image, ignoring geometry and aperture','Using an array below its usable frequency range, giving poor resolution','Forgetting that spatial aliasing appears when mic spacing is too large']::text[],ARRAY['Laying out a spiral array for a car pass-by noise test','Choosing mic spacing to image a two-kilohertz tonal noise','Mapping the pressure field on a vibrating panel']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone array visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8875fddc-40f9-588f-92a2-88be3493ab14','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8875fddc-40f9-588f-92a2-88be3493ab14') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8875fddc-40f9-588f-92a2-88be3493ab14');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '83000ff2-bca3-50ff-95ce-3a6cf8da77d2','Acoustic beamforming map','A spatial image produced by beamforming an array signal, in which the estimated acoustic energy arriving from each candidate direction or focus point is plotted over a two- or three-dimensional grid. The beamformer steers a spatial filter across many look directions; the output power at each direction becomes a pixel, so bright regions indicate likely source locations. Map quality is governed by array aperture, geometry, frequency, and sidelobe behaviour.','A beamforming map shows where sound seems to come from. The tool listens toward many points one by one. It measures how strong the sound is from each point. Strong points show up bright on the map. The array size and pitch set how clear it looks.','It converts multichannel array data into an intuitive image of source location and strength, letting an engineer rank and locate dominant sound sources without moving a probe around the scene.','It is the core output of acoustic cameras used for noise-source ranking on vehicles, machines, and products, and for locating leaks, squeaks, and dominant radiators during troubleshooting.','Sound Visualization & Acoustic Imaging',ARRAY['Beamforming','Beamforming power map','Sidelobe','Acoustic camera','Source localization map']::text[],ARRAY['Reading a bright sidelobe as a real second source','Trusting fine detail below the array''s resolution limit','Ignoring that dynamic range and contrast shrink at low frequencies']::text[],ARRAY['Ranking noise sources on an idling engine','Locating an aerodynamic noise source on a mirror in a wind tunnel','Finding the loudest panel on a household appliance']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic beamforming map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '83000ff2-bca3-50ff-95ce-3a6cf8da77d2','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='83000ff2-bca3-50ff-95ce-3a6cf8da77d2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='83000ff2-bca3-50ff-95ce-3a6cf8da77d2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c3806827-24d2-5be2-ab18-7552e835bbc9','Beamforming power map','A beamforming output in which the plotted quantity is the estimated output power of the beamformer as a function of steering direction or focus point. For a conventional delay-and-sum beamformer this is the steered response power, essentially the steering vector times the array cross-spectral matrix times the steering vector; the map peaks indicate directions of strong incident energy.','A beamforming power map shows the sound power from each aimed direction. The tool points at many directions in turn. For each one it adds the mic signals in phase. The result is a power value for that direction. High power shows up as a bright spot.','It expresses beamforming results as a physically meaningful power estimate, so peaks can be compared and dominant sources ranked by strength rather than by mere brightness.','It underlies steered-response-power source locators and the level readouts of acoustic cameras, where technicians compare peak levels between candidate sources.','Sound Visualization & Acoustic Imaging',ARRAY['Steered response power','Acoustic beamforming map','Cross-spectral matrix','Beamforming','Sidelobe']::text[],ARRAY['Reading map colour as calibrated sound level without proper scaling','Comparing power peaks across frequencies without normalisation','Mistaking sidelobe power for genuine source power']::text[],ARRAY['Comparing the power of two engine-bay noise sources','Setting a dynamic-range window to hide low-level sidelobes','Logging peak source power during a pass-by test']::text[],'intermediate','P(theta) = w^H(theta) R w(theta)','The map value at each look direction equals the array steering vector times the channel cross-spectral matrix times the steering vector, giving the beamformer output power.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamforming power map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c3806827-24d2-5be2-ab18-7552e835bbc9','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c3806827-24d2-5be2-ab18-7552e835bbc9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c3806827-24d2-5be2-ab18-7552e835bbc9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f47630e5-d394-5b7f-a278-a8c7018d1977','Near-field beamforming','Beamforming in which the array-processing model accounts for the curvature of wavefronts from sources close to the array, that is, within the array near field, so that steering vectors use spherical-wave, range-dependent phase and amplitude rather than a plane-wave approximation. This allows focusing on a point at finite range and improves localization for nearby sources.','Near-field beamforming aims at sound sources that are close by. Close sound waves are curved, not flat. So the tool models each source as a point at a set distance. It matches the curved wave shape when it aims. This lets it focus on a spot, not just a direction.','It exists because plane-wave beamforming fails for close sources; modelling wavefront curvature lets the array focus at a true three-dimensional point and estimate range, not just bearing.','It is used in acoustic cameras working close to a machine or panel, and in focused holography-style imaging where source and array are only a short distance apart.','Sound Visualization & Acoustic Imaging',ARRAY['Far-field beamforming','Focused beamforming','Wavefront curvature','Nearfield acoustic holography','Acoustic beamforming map']::text[],ARRAY['Using a plane-wave far-field model when the source is actually near','Assuming range can be found for very small apertures, where it is poorly conditioned','Forgetting that focus distance must be set correctly for a sharp image']::text[],ARRAY['Imaging a panel a few centimetres from a planar array','Focusing on a specific point inside an engine bay','Close-range leak detection on a pressure vessel']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Near-field beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f47630e5-d394-5b7f-a278-a8c7018d1977','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f47630e5-d394-5b7f-a278-a8c7018d1977') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f47630e5-d394-5b7f-a278-a8c7018d1977');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '788a2875-34df-5130-8378-433f6ab76ae0','Far-field beamforming','Beamforming that assumes sources are far enough from the array that arriving wavefronts are effectively planar over the aperture, so steering depends only on direction and uses plane-wave phase delays across the microphones. It estimates direction of arrival rather than range, and is the standard model when source distance is large compared with the array aperture and wavelength.','Far-field beamforming assumes sound sources are far away. Far-off sound waves reach the array nearly flat. So the tool only needs the arrival angle, not the range. It adds the mic signals using simple time delays. It tells you which way sound comes from.','It simplifies array processing to a direction-only problem, which is efficient and robust when sources are distant, and forms the basis of most direction-of-arrival estimation.','It is used in direction-finding systems, long-range noise monitoring, and any acoustic camera imaging sources many aperture-lengths away, where only bearing is needed.','Sound Visualization & Acoustic Imaging',ARRAY['Near-field beamforming','Direction-of-arrival map','Plane wave','Beamforming','Array aperture']::text[],ARRAY['Applying it to close sources, where wavefront curvature is ignored','Expecting range information, which far-field models cannot give','Ignoring spatial aliasing from too-wide microphone spacing']::text[],ARRAY['Finding the bearing of a distant siren or vehicle','Mapping the direction of arena reflections from stage sources','Tracking a flyover aircraft''s direction']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-field beamforming');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '788a2875-34df-5130-8378-433f6ab76ae0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='788a2875-34df-5130-8378-433f6ab76ae0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='788a2875-34df-5130-8378-433f6ab76ae0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4355e66f-012f-536a-a572-5626bcbb9e16','Sidelobe','A secondary maximum in the spatial or angular response of an array or aperture, occurring away from the main lobe that points at the true source direction. In beamforming maps, sidelobes appear as spurious bright regions where no source exists; their level and position depend on array geometry, element spacing, weighting, and frequency. High sidelobes reduce dynamic range and can be mistaken for real sources.','A sidelobe is a false bright spot in a sound map. The array aims at one direction but still picks up others. These weaker off-target responses show up as extra spots. They are not real sound sources. They can trick you if you do not expect them.','The concept matters because sidelobes set the usable dynamic range and reliability of an acoustic image; understanding them lets an engineer avoid false detections and choose arrays or weighting that suppress them.','Engineers weigh sidelobe level when designing arrays such as spiral layouts, applying shading, or setting a display dynamic range to hide sidelobes below the main peak.','Sound Visualization & Acoustic Imaging',ARRAY['Main lobe','Array aperture','Acoustic beamforming map','Spatial aliasing','Array shading']::text[],ARRAY['Reading a sidelobe as a genuine second source','Using a regular grid array that raises grating-lobe sidelobes','Setting display range so wide that sidelobes clutter the map']::text[],ARRAY['Choosing a spiral array to lower sidelobes for engine imaging','Setting a six-decibel display window to hide sidelobes','Explaining a phantom source to a client as a sidelobe artefact']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sidelobe');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4355e66f-012f-536a-a572-5626bcbb9e16','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4355e66f-012f-536a-a572-5626bcbb9e16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4355e66f-012f-536a-a572-5626bcbb9e16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '05c19a25-ac78-5b6c-afb6-8b9862d15d38','Point spread function','The response of an imaging system to a single ideal point source: in acoustic imaging, the spatial pattern of a main lobe plus sidelobes that one point source produces in the output map. It characterises the system spatial resolution and sidelobe behaviour; the measured image can be viewed as the true source distribution mapped through the point spread function. Deconvolution methods such as DAMAS use it to sharpen maps.','The point spread function shows how one point source looks in the image. A perfect point never appears as a perfect dot. Instead it spreads into a blob with a bright centre. It also has weaker rings or spots around it. This spread sets how sharp the picture can be.','It defines the resolution limit and artefact pattern of an imaging system, and provides the model that deconvolution algorithms invert to recover a cleaner picture of the true sources.','It is central to array design and to deconvolution methods such as DAMAS and CLEAN-SC that remove array blur and sidelobes from acoustic beamforming maps.','Sound Visualization & Acoustic Imaging',ARRAY['Beamforming','Sidelobe','Spatial resolution','Deconvolution','DAMAS']::text[],ARRAY['Assuming the raw map equals the true source map, ignoring the spread','Thinking the point spread function is fixed, when it varies with frequency and position','Skipping deconvolution and over-reading blurred detail']::text[],ARRAY['Using DAMAS to sharpen an airframe-noise map','Predicting resolution from the array''s point response','Explaining why two close sources merge into one blob']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Point spread function');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '05c19a25-ac78-5b6c-afb6-8b9862d15d38','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='05c19a25-ac78-5b6c-afb6-8b9862d15d38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='05c19a25-ac78-5b6c-afb6-8b9862d15d38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f3c1cf89-25f3-5dc1-9b2a-9473fd8a2b3f','Source localization map','A display that shows the estimated location or direction of one or more sound sources, produced by array processing methods such as beamforming, time-difference-of-arrival, or subspace estimators. The map assigns to each candidate position or direction a value reflecting the likelihood or strength of a source there, with peaks marking estimated source positions.','A source localization map shows where sound sources are. It scores many possible spots or directions. High scores mark the likely source places. The peaks point to each source. It is the main output of many sound-imaging tools.','It answers the basic question of where the sound comes from, converting multichannel measurements into an explicit spatial estimate of source position or bearing.','It is used in acoustic cameras, gunshot and drone locators, teleconferencing mic steering, and noise troubleshooting to point directly at offending sources.','Sound Visualization & Acoustic Imaging',ARRAY['Beamforming','Direction-of-arrival map','Time difference of arrival','Acoustic camera','Source localization']::text[],ARRAY['Trusting a single peak in a reverberant field where reflections mislead','Ignoring resolution limits that merge nearby sources','Confusing direction-only maps with true position maps']::text[],ARRAY['Steering a conference mic toward the active talker','Locating a gunshot with a sensor network','Finding the dominant noise source on a moving train']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source localization map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f3c1cf89-25f3-5dc1-9b2a-9473fd8a2b3f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f3c1cf89-25f3-5dc1-9b2a-9473fd8a2b3f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f3c1cf89-25f3-5dc1-9b2a-9473fd8a2b3f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b95e2053-061a-5988-ae5b-9bbca8be621a','Direction-of-arrival map','A display of estimated source bearings, the directions from which sound reaches an array, typically plotted over azimuth and elevation, with peaks indicating arrival directions. Such maps arise from far-field array processing such as delay-and-sum, MUSIC, ESPRIT, or MVDR, and give angle rather than range; resolution and ambiguity depend on aperture, geometry, and frequency.','A direction-of-arrival map shows which way sound comes from. It plots strength against angle around the array. Peaks mark the arrival directions. It gives angle, not distance. It works best for sources that are far away.','It provides bearing estimates for tracking, steering, and separation tasks, summarising where energy arrives from without needing to know source distance.','It is used in beam-steered microphones, sonar and radar-style acoustics, drone detection, and reflection analysis where the arrival angles of energy matter.','Sound Visualization & Acoustic Imaging',ARRAY['Far-field beamforming','MUSIC','Beamforming','Azimuth','Source localization map']::text[],ARRAY['Expecting range from an angle-only estimate','Ignoring front-back ambiguity in some array geometries','Under-sampling in space and reading aliased false angles']::text[],ARRAY['Tracking a talker''s angle around a conference array','Mapping arrival angles of strong room reflections','Detecting the bearing of an approaching drone']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direction-of-arrival map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b95e2053-061a-5988-ae5b-9bbca8be621a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b95e2053-061a-5988-ae5b-9bbca8be621a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b95e2053-061a-5988-ae5b-9bbca8be621a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2c5e6615-9a86-5574-934d-b3d9f2a54781','Acoustic heat map','A colour-coded spatial map in which colour represents an acoustic quantity such as sound pressure level, intensity, or estimated source strength over a scene or surface. The word heat is metaphorical: the colours, often running blue to red, encode acoustic magnitude, not temperature. Such maps are commonly the display layer of acoustic cameras and of holography or beamforming results overlaid on an optical image.','An acoustic heat map uses colour to show how loud each area is. Warm colours mean strong sound. Cool colours mean weak sound. The word heat is only a word-picture here. It shows sound level, not real temperature.','It presents acoustic magnitude in an instantly readable form, letting non-experts see loud and quiet regions at a glance by colour rather than by numbers.','It is the standard overlay on acoustic-camera images and noise surveys, and appears in room and product reports to show where sound concentrates.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic beamforming map','Sound pressure map','Acoustic camera','Sound intensity map','Colour map']::text[],ARRAY['Thinking the colours show temperature rather than sound level','Comparing maps with different colour scales as if identical','Reading absolute level from colour without a calibrated scale']::text[],ARRAY['Showing a client the loud region of a facade in colour','Overlaying a noise map on a machine photo','Presenting before-and-after treatment maps of a room']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic heat map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2c5e6615-9a86-5574-934d-b3d9f2a54781','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2c5e6615-9a86-5574-934d-b3d9f2a54781') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2c5e6615-9a86-5574-934d-b3d9f2a54781');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f3b1cac-48c6-5843-be48-4b7c25371845','Sound pressure map','A spatial representation of acoustic pressure amplitude or sound pressure level across a plane, surface, or volume, showing how loud the field is at each location. It may be measured by scanning a microphone or using an array, or computed from a model; values are typically shown as contours or a colour map of sound pressure level or root-mean-square pressure.','A sound pressure map shows how loud sound is at each spot. It measures the push of the sound wave in the air. Each point gets a level value. Colours or lines show high and low levels. It tells you where sound is strong or weak.','It reveals how sound pressure is distributed in space, exposing hot spots, quiet zones, and coverage patterns that a single meter reading cannot show.','It is used to check loudspeaker coverage in a venue, map sound level around machinery for noise exposure, and study pressure distribution on radiating surfaces.','Sound Visualization & Acoustic Imaging',ARRAY['Sound pressure level','Pressure-field map','Acoustic heat map','Sound intensity map','Coverage map']::text[],ARRAY['Treating pressure level as a measure of energy flow, which needs intensity','Ignoring standing waves that make pressure vary sharply with position','Comparing maps taken at different frequencies as if the same']::text[],ARRAY['Checking even level coverage across seats in a venue','Mapping sound level around a machine for exposure work','Studying pressure highs and lows in a small room']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound pressure map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f3b1cac-48c6-5843-be48-4b7c25371845','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f3b1cac-48c6-5843-be48-4b7c25371845') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f3b1cac-48c6-5843-be48-4b7c25371845');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dd70cd8c-c489-5ef7-9250-e692a137e9e2','Pressure-field map','A two- or three-dimensional display of the acoustic pressure field over a region of space, showing the value and sometimes the phase of sound pressure at each point. It is one of the basic products of sound-field measurement and simulation, and both beamforming and acoustic holography can yield such two-dimensional pressure pictures. It differs from an intensity map in showing the pressure scalar rather than energy flow.','A pressure-field map pictures sound pressure across a space. It gives the pressure value at each point. It can cover a flat area or a full volume. You can build it from measurements or a model. It shows pressure, not the flow of energy.','It provides the fundamental scalar picture of a sound field, from which many other views such as level, phase, or, with velocity, intensity can be derived or understood.','It appears in holography and simulation outputs, room-mode studies, and transducer characterisation where the spatial pressure pattern is the object of interest.','Sound Visualization & Acoustic Imaging',ARRAY['Sound pressure map','Nearfield acoustic holography','Sound intensity map','Wavefront visualization','Computational acoustic field map']::text[],ARRAY['Confusing a pressure-field map with an energy-flow intensity map','Ignoring phase, which pressure magnitude alone omits','Assuming a single-frequency map represents broadband behaviour']::text[],ARRAY['Viewing a holography-reconstructed pressure field on a panel','Mapping pressure highs and lows for a room mode','Comparing simulated and measured pressure fields of a source']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-field map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dd70cd8c-c489-5ef7-9250-e692a137e9e2','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dd70cd8c-c489-5ef7-9250-e692a137e9e2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dd70cd8c-c489-5ef7-9250-e692a137e9e2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc3aa80c-43e9-5152-97eb-a94ac7ddd180','Sound intensity map','A spatial display of acoustic intensity, the time-averaged rate of sound-energy flow per unit area, showing both magnitude and, often, direction at each location. Intensity is the time average of the product of instantaneous sound pressure and particle velocity; a sound intensity map therefore reveals where energy flows and how strong that flow is, distinguishing genuine radiating regions from mere pressure highs.','A sound intensity map shows how sound energy flows in space. At each point it gives the strength of the flow. It often shows the flow direction too. It comes from pressure and air motion together. It reveals which areas truly send out sound.','It identifies real sources and sound-power flow, separating active radiating areas from passive pressure build-up, which pressure maps alone cannot do.','Engineers use intensity probes and scanning to map energy flow for sound-power measurement, noise-source ranking, and finding leaks or radiating panels.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic intensity','Intensity vector field','Particle velocity map','Sound power','Sound intensity probe']::text[],ARRAY['Confusing intensity with pressure level, which ignores direction of flow','Ignoring the phase-mismatch and calibration needs of intensity probes','Trusting intensity in strong reactive near fields without care']::text[],ARRAY['Scanning a machine surface to find radiating areas','Measuring sound power of a source in place','Locating an energy leak through a wall gap']::text[],'advanced','I = <p * u>','Sound intensity is the time average of instantaneous sound pressure multiplied by the particle velocity vector.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound intensity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc3aa80c-43e9-5152-97eb-a94ac7ddd180','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc3aa80c-43e9-5152-97eb-a94ac7ddd180') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc3aa80c-43e9-5152-97eb-a94ac7ddd180');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '77f29c77-3495-5301-bc49-975dcc61c4ab','Acoustic vector map','A vector-field visualization of a directional acoustic quantity, most commonly acoustic intensity or particle velocity, in which arrows at grid points show the magnitude and direction of energy flow or air motion. Unlike a scalar colour map, it conveys directionality, making the paths along which sound energy travels explicit.','An acoustic vector map uses arrows to show sound flow. Each arrow sits at a point in space. Its length shows how strong the flow is. Its direction shows which way sound moves. This is more than a plain colour map.','It communicates direction as well as magnitude, letting an engineer trace how and where acoustic energy or air motion moves through a region.','It appears in intensity-probe surveys and simulations where the direction of energy flow, toward a leak, around a barrier, or out of a panel, must be seen, not just its level.','Sound Visualization & Acoustic Imaging',ARRAY['Intensity vector field','Sound intensity map','Particle velocity map','Sound-energy flow map','Vector field']::text[],ARRAY['Reading arrow length as sound level rather than the mapped vector quantity','Ignoring that arrows depend on frequency and phase','Overcrowding the grid so the flow pattern is unreadable']::text[],ARRAY['Showing energy flowing toward a gap in a partition','Visualising air motion around a small loudspeaker port','Tracing intensity vectors around an acoustic barrier']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic vector map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '77f29c77-3495-5301-bc49-975dcc61c4ab','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='77f29c77-3495-5301-bc49-975dcc61c4ab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='77f29c77-3495-5301-bc49-975dcc61c4ab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7969330-b0f1-5ffb-b082-4c0e1e6247a4','Particle velocity map','A spatial visualization of acoustic particle velocity, the oscillatory velocity of the medium particles as the wave passes, showing magnitude and direction of air motion rather than pressure. Particle velocity is a vector quantity linked to the pressure gradient through Euler''s equation; maps of it are produced with pressure-gradient or pressure-velocity probes, or from holographic reconstruction.','A particle velocity map shows how the air itself moves. Sound makes air particles wiggle back and forth. This map gives the speed and direction of that motion. It is not the same as pressure. It highlights motion, which pressure maps miss.','It captures the motion side of a sound field, needed with pressure to compute intensity and to understand near-field behaviour where velocity and pressure differ markedly.','It is measured with pressure-velocity intensity probes and used in near-field studies, intensity mapping, and holography where the velocity distribution on a surface is of interest.','Sound Visualization & Acoustic Imaging',ARRAY['Particle velocity','Sound intensity map','Euler''s equation','Pressure-velocity probe','Acoustic vector map']::text[],ARRAY['Confusing particle velocity with the speed of sound','Assuming velocity is in phase with pressure everywhere, which fails near sources','Ignoring probe calibration needs for accurate velocity']::text[],ARRAY['Mapping air motion just above a vibrating panel','Using a pressure-velocity probe near a loudspeaker cone','Studying velocity in the near field of a small source']::text[],'advanced','u = -(1/rho) * integral of grad p dt','Particle velocity equals the negative pressure gradient integrated over time and divided by the medium density, as given by Euler''s equation.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle velocity map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7969330-b0f1-5ffb-b082-4c0e1e6247a4','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7969330-b0f1-5ffb-b082-4c0e1e6247a4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7969330-b0f1-5ffb-b082-4c0e1e6247a4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '862b0825-8fa0-59af-84d7-76b57ee2439f','Sound-energy flow map','A visualization showing the direction and, usually, the magnitude of acoustic energy flow through space, effectively a display of the acoustic intensity field, since intensity is the flow of sound energy per unit area. It emphasises energy transport: streamlines or vectors trace the paths along which sound power moves from sources toward sinks or radiating boundaries.','A sound-energy flow map shows where sound energy goes. It draws the paths that energy follows through space. Arrows or lines trace the flow. It is based on sound intensity. It helps you see energy moving from a source outward.','It makes energy transport explicit, revealing how power leaves a source and travels through a space, which supports source ranking and leak finding better than pressure alone.','It is used in intensity surveys and simulations to trace energy from machines to openings, or to see how power radiates from a structure into a room.','Sound Visualization & Acoustic Imaging',ARRAY['Sound intensity map','Intensity vector field','Acoustic intensity','Sound power','Acoustic flow visualization']::text[],ARRAY['Equating energy flow with pressure level','Ignoring reactive near-field energy that circulates without net flow','Assuming flow lines are exact in strongly reverberant spaces']::text[],ARRAY['Tracing energy from a gearbox out through a housing gap','Showing how power radiates from a panel into a room','Following intensity streamlines around a barrier']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound-energy flow map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '862b0825-8fa0-59af-84d7-76b57ee2439f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='862b0825-8fa0-59af-84d7-76b57ee2439f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='862b0825-8fa0-59af-84d7-76b57ee2439f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '22a7bde0-ab27-5657-8ec5-6706cb78c80c','Intensity vector field','The spatial field of the acoustic intensity vector, whose value at each point gives the magnitude and direction of time-averaged sound-energy flow. Displayed as an arrow field, it is computed from the product of pressure and particle velocity. The active, time-averaged component describes net energy transport, while the reactive component describes locally oscillating energy that does not propagate.','An intensity vector field gives the flow of sound energy at every point. Each point has an arrow. The arrow shows how strong the flow is and its direction. It comes from pressure times air motion. Together the arrows show how energy moves.','It provides the full directional description of energy transport in a sound field, underpinning sound-power measurement and the tracing of energy from sources.','It is the quantity behind intensity mapping and probes used for sound-power tests, source location, and the study of active versus reactive near fields.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic intensity','Sound intensity map','Particle velocity','Reactive intensity','Sound-energy flow map']::text[],ARRAY['Confusing active and reactive intensity','Treating the field as pressure rather than energy flow','Ignoring frequency dependence of the vectors']::text[],ARRAY['Mapping the intensity field around a running motor','Separating active from reactive flow near a source','Measuring sound power by integrating intensity over a surface']::text[],'advanced','I(r) = <p(r) * u(r)>','The intensity vector at a point is the time average of sound pressure times the particle velocity vector at that point.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intensity vector field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '22a7bde0-ab27-5657-8ec5-6706cb78c80c','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='22a7bde0-ab27-5657-8ec5-6706cb78c80c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='22a7bde0-ab27-5657-8ec5-6706cb78c80c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01b2069e-d88b-5f5b-b9c8-16cd90335c55','Acoustic flow visualization','A general term for any visualization that depicts the directional propagation or energy flow of sound, such as intensity vector fields, energy streamlines, or wavefront and ray displays, rather than a static scalar level. It emphasises how sound moves through space, whether as energy transport, particle motion, or wave-propagation direction.','Acoustic flow visualization shows how sound moves through space. It focuses on direction, not just level. It can use arrows, streamlines, or wavefronts. The goal is to see sound travelling. It covers several related picture types.','It groups the visual tools that reveal directionality and propagation, helping engineers reason about where sound goes rather than only how loud it is.','It appears in intensity surveys, ray-tracing and wavefront simulations, and teaching tools that show sound spreading, reflecting, and flowing through a space.','Sound Visualization & Acoustic Imaging',ARRAY['Intensity vector field','Sound-energy flow map','Wavefront visualization','Sound ray diagram','Acoustic vector map']::text[],ARRAY['Treating any coloured map as flow, when flow needs direction','Mixing energy-flow and wavefront pictures as if identical','Assuming flow lines hold in strongly diffuse fields']::text[],ARRAY['Teaching how sound radiates and reflects in a room','Combining ray and intensity views for a design review','Showing propagation direction around an obstacle']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic flow visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01b2069e-d88b-5f5b-b9c8-16cd90335c55','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01b2069e-d88b-5f5b-b9c8-16cd90335c55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01b2069e-d88b-5f5b-b9c8-16cd90335c55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfb19c27-70c4-5a77-96a6-dca134fa0191','Isosurface of pressure','A three-dimensional surface connecting all points in a sound field that share the same acoustic pressure value, analogous to a contour line extended into three dimensions. Isosurfaces of pressure are used to visualise the shape and extent of regions at a chosen pressure or level within a simulated or measured volumetric field.','An isosurface of pressure links all points with the same pressure. It is like a contour line, but in three dimensions. It forms a curved surface in space. You pick a pressure value to draw it. It shows the shape of that pressure level.','It lets a three-dimensional pressure field be understood at a glance by outlining regions of equal pressure or level, revealing the geometry of lobes, nulls, and hot spots.','It is used in acoustic simulation post-processing, such as finite-element or boundary-element results, to show where a level threshold is reached around a source or inside a cabin.','Sound Visualization & Acoustic Imaging',ARRAY['Isobaric acoustic surface','Pressure-field map','Finite-element acoustic visualization','Sound pressure level','Contour map']::text[],ARRAY['Reading one isosurface as the whole field rather than a single level','Confusing an isosurface with a physical boundary','Choosing a threshold that hides important structure']::text[],ARRAY['Showing a ninety-decibel region around a machine in three dimensions','Outlining a pressure lobe from a simulated source','Visualising level thresholds inside a vehicle cabin']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isosurface of pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfb19c27-70c4-5a77-96a6-dca134fa0191','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfb19c27-70c4-5a77-96a6-dca134fa0191') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfb19c27-70c4-5a77-96a6-dca134fa0191');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ab5630bf-7fa8-51ad-a8a6-96698da66fdc','Isobaric acoustic surface','A surface of constant acoustic pressure within a sound field, isobaric meaning equal pressure. It is the acoustic analogue of an isobar in meteorology and is essentially synonymous with an isosurface of pressure; such surfaces help visualise the spatial structure of a pressure field and, when phase is also constant, relate to wavefronts.','An isobaric acoustic surface is a surface of equal sound pressure. Isobaric just means same pressure. Every point on it shares one pressure value. It helps show the shape of a sound field. It is much like an isosurface of pressure.','It provides a way to describe and picture regions of equal pressure in a field, aiding analysis of field structure and, where phase is constant, of wavefront shape.','It is used in acoustics teaching and simulation to depict equal-pressure regions and to connect pressure structure with wavefront and mode shapes.','Sound Visualization & Acoustic Imaging',ARRAY['Isosurface of pressure','Pressure-field map','Wavefront visualization','Sound pressure','Contour map']::text[],ARRAY['Assuming equal pressure means equal phase, which is not always true','Treating the surface as a solid barrier','Confusing meteorological isobars with acoustic ones']::text[],ARRAY['Depicting equal-pressure shells around a point source','Teaching field structure with equal-pressure surfaces','Relating pressure surfaces to wavefronts for a simple source']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isobaric acoustic surface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ab5630bf-7fa8-51ad-a8a6-96698da66fdc','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ab5630bf-7fa8-51ad-a8a6-96698da66fdc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ab5630bf-7fa8-51ad-a8a6-96698da66fdc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f73fd29-52e0-530d-863c-78d3b7c493b1','Wavefront visualization','A display of wavefronts, surfaces or, in two dimensions, lines of constant phase, as a sound wave propagates, showing the geometry and advance of the wave. Wavefronts are perpendicular to the propagation direction; visualising them reveals wave shape such as planar, spherical, or cylindrical, curvature, and how reflection, diffraction, and refraction distort them.','Wavefront visualization draws the moving front of a sound wave. A wavefront links points that share the same phase. It shows the wave''s shape as it spreads. Fronts can be flat, round, or bent. It helps you see how waves travel and bend.','It makes wave propagation intuitive, showing how fronts expand, curve, and interact with surfaces, which underlies understanding of interference, focusing, and reflection.','It is used in teaching, in wave-based simulation output, and in array and loudspeaker design to show how wavefronts combine or steer.','Sound Visualization & Acoustic Imaging',ARRAY['Phase-front visualization','Wavefront','Sound ray diagram','Diffraction visualization','Interference pattern']::text[],ARRAY['Confusing wavefronts, which are phase surfaces, with rays, which are propagation lines','Assuming all wavefronts are spherical, ignoring source and boundary effects','Reading a single frame as the whole time evolution']::text[],ARRAY['Animating spherical fronts spreading from a point source','Showing how a line array shapes its wavefront','Illustrating a wavefront bending around a barrier']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wavefront visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f73fd29-52e0-530d-863c-78d3b7c493b1','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f73fd29-52e0-530d-863c-78d3b7c493b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f73fd29-52e0-530d-863c-78d3b7c493b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53fcfb5d-2f38-54d7-a0c7-8b4a0b4dbe4b','Phase-front visualization','A visualization of constant-phase contours or surfaces in a sound field, closely related to wavefront visualization, since a wavefront is a surface of constant phase. It maps how phase advances through space at a given frequency, exposing propagation direction, curvature, and phase anomalies such as those near nodes or around obstacles.','Phase-front visualization shows lines of equal phase in a sound field. Phase tells where a wave is in its cycle. Points on one line are all at the same stage. This is basically the same as a wavefront picture. It shows how phase moves through space.','It reveals the phase structure of a field at a frequency, helping engineers see propagation direction, wavefront curvature, and places where phase behaves oddly.','It is used in single-frequency simulation and holography output, and in array analysis where phase relationships across space matter.','Sound Visualization & Acoustic Imaging',ARRAY['Wavefront visualization','Phase','Wavefront','Interference pattern','Nearfield acoustic holography']::text[],ARRAY['Confusing phase fronts with amplitude or level maps','Forgetting phase is defined per frequency, not broadband','Ignoring phase wrapping that creates apparent jumps']::text[],ARRAY['Showing constant-phase surfaces of a single-tone source','Studying phase near a diffracting edge','Checking phase alignment across an array''s output']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase-front visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53fcfb5d-2f38-54d7-a0c7-8b4a0b4dbe4b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53fcfb5d-2f38-54d7-a0c7-8b4a0b4dbe4b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53fcfb5d-2f38-54d7-a0c7-8b4a0b4dbe4b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7cf9bb5a-25ed-534e-bbac-cf15c74d2993','Sound ray diagram','A geometric-acoustics visualization that represents sound propagation as rays, straight or piecewise-straight paths drawn perpendicular to wavefronts, showing how sound travels, reflects, and sometimes refracts. Valid when wavelengths are small compared with surfaces, it traces direct and reflected paths to study coverage, reflections, and echo timing, while ignoring diffraction and wave interference.','A sound ray diagram draws sound as straight lines called rays. Each ray shows a path the sound takes. Rays bounce off walls like light in a mirror. This works best for high sounds and big surfaces. It helps study reflections and coverage.','It gives a simple, intuitive model of propagation and reflection for room and venue design, trading wave detail for clear geometric insight into paths and echoes.','It is used in room-acoustics design, ray-tracing software, and loudspeaker aiming to check coverage, first reflections, and potential echoes.','Sound Visualization & Acoustic Imaging',ARRAY['Geometric acoustics','Ray tracing','Image-source model display','Reflection path diagram','Specular reflection visualization']::text[],ARRAY['Trusting rays at low frequencies where diffraction dominates','Ignoring interference, which the ray model omits','Assuming perfect specular bounces from rough or small surfaces']::text[],ARRAY['Checking first reflections in a control-room design','Aiming loudspeakers for even coverage with ray tracing','Studying echo paths in a large hall']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound ray diagram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7cf9bb5a-25ed-534e-bbac-cf15c74d2993','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7cf9bb5a-25ed-534e-bbac-cf15c74d2993') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7cf9bb5a-25ed-534e-bbac-cf15c74d2993');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fffced8e-8750-53d5-baa2-159a897cccdf','Image-source model display','A visualization based on the image-source method, in which reflections are represented by virtual mirror sources located behind reflecting surfaces, so that each reflected path is drawn as if it came straight from an image source. It shows direct and reflected paths in a room by reflecting the real source across each boundary, giving exact specular reflection paths for simple geometries.','This display shows room echoes using mirror sources. Each wall acts like a mirror for sound. A reflection is drawn as sound from a mirror-image source behind the wall. So a bounced path looks like a straight one. It helps map early reflections in a room.','It turns reflection paths into simple straight lines from virtual sources, making early-reflection structure easy to compute and see for room design.','It underlies room-acoustics prediction and auralization software, and control-room design where first-reflection points on walls must be found.','Sound Visualization & Acoustic Imaging',ARRAY['Image-source method','Reflection path diagram','Early-reflection map','Specular reflection visualization','Sound ray diagram']::text[],ARRAY['Applying it to complex or curved rooms where image counts explode','Assuming it captures diffraction or scattering, which it omits','Confusing image sources with real physical sources']::text[],ARRAY['Finding first-reflection points to place absorbers','Auralising early reflections in a modelled room','Explaining a flutter echo with mirror sources']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Image-source model display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fffced8e-8750-53d5-baa2-159a897cccdf','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fffced8e-8750-53d5-baa2-159a897cccdf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fffced8e-8750-53d5-baa2-159a897cccdf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '18e0d61d-d391-5aa8-b6a0-5c6705d499fa','Reflection path diagram','A visual display showing the direct sound path and the reflected paths from a source to a receiver in a space, typically drawn as lines that bounce off walls, floor, and ceiling. It reveals which surfaces produce reflections, the relative path lengths and thus arrival delays, and where treatment might control problematic reflections.','A reflection path diagram shows how sound gets from a source to a listener. It draws the straight direct path first. Then it draws paths that bounce off surfaces. Longer paths arrive later. It shows which walls cause reflections.','It exposes the paths and timing of reflections reaching a listener, guiding surface treatment and speaker placement to manage early reflections and echoes.','It is used in studio and room design to locate reflection points for absorbers or diffusers and to predict reflection delays at the mix position.','Sound Visualization & Acoustic Imaging',ARRAY['Image-source model display','Early-reflection map','Sound ray diagram','Specular reflection visualization','First reflection']::text[],ARRAY['Considering only first-order bounces and missing later ones','Ignoring floor and ceiling reflections','Treating path length as loudness without accounting for spreading']::text[],ARRAY['Locating side-wall reflection points at the mix seat','Planning ceiling treatment from reflection paths','Explaining comb filtering from a strong reflection']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflection path diagram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '18e0d61d-d391-5aa8-b6a0-5c6705d499fa','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='18e0d61d-d391-5aa8-b6a0-5c6705d499fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='18e0d61d-d391-5aa8-b6a0-5c6705d499fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '92cc5a50-f25b-5564-ba6e-90be1d171814','Early-reflection map','A room-acoustics visualization showing the first, early reflections that arrive shortly after the direct sound, identifying the surfaces responsible and their arrival times and levels. Early reflections, typically within the first tens of milliseconds, strongly affect clarity, imaging, and coloration, so mapping them guides acoustic treatment.','An early-reflection map shows the first echoes in a room. These arrive just after the direct sound. The map marks which surfaces cause them. It also shows when they arrive. These early echoes shape clarity and imaging.','It highlights the reflections that most affect perceived clarity and stereo imaging, so designers can treat the surfaces that matter most first.','It is used in control-room and listening-room design to find and treat first-reflection points and to check the reflection-free zone at the mix position.','Sound Visualization & Acoustic Imaging',ARRAY['Reflection path diagram','Image-source model display','First reflection','Reflection-free zone','Specular reflection visualization']::text[],ARRAY['Confusing early reflections with later reverberation','Over-treating and deadening the room''s early field','Ignoring ceiling and floor early reflections']::text[],ARRAY['Finding first-reflection points for absorber placement','Checking the reflection-free zone at a mixing seat','Diagnosing image smearing from a strong early reflection']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Early-reflection map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '92cc5a50-f25b-5564-ba6e-90be1d171814','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='92cc5a50-f25b-5564-ba6e-90be1d171814') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='92cc5a50-f25b-5564-ba6e-90be1d171814');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a15afca0-aee2-5b21-9742-84d8e77d16ab','Specular reflection visualization','A display of mirror-like, specular sound reflections, where the angle of reflection equals the angle of incidence, drawn as clean reflected rays or paths off smooth, large surfaces. It contrasts with diffuse-reflection visualization; specular models suit surfaces that are large and smooth relative to the wavelength.','This shows sound bouncing like light off a mirror. The angle coming in equals the angle going out. It draws clean reflected paths. It fits big, smooth, hard surfaces. It is the opposite of scattered reflection.','It models the orderly, mirror-like part of reflection, letting designers predict where a smooth surface will send sound and where strong reflections will land.','It is used in ray-tracing and image-source tools for hard-walled spaces and in aiming reflectors or checking mirror points in studios.','Sound Visualization & Acoustic Imaging',ARRAY['Diffuse reflection visualization','Image-source model display','Sound ray diagram','Reflection path diagram','Angle of incidence']::text[],ARRAY['Assuming all surfaces reflect specularly, ignoring scattering','Applying it below frequencies where the surface looks small','Forgetting that real surfaces mix specular and diffuse reflection']::text[],ARRAY['Predicting a hard back-wall reflection in a hall','Aiming a reflector panel over a stage','Finding mirror points on smooth studio walls']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Specular reflection visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a15afca0-aee2-5b21-9742-84d8e77d16ab','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a15afca0-aee2-5b21-9742-84d8e77d16ab') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a15afca0-aee2-5b21-9742-84d8e77d16ab');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bae700c9-57f1-5708-aae3-7a0b3badb7e1','Diffuse reflection visualization','A display of scattered, diffuse sound reflections, where an incident wave striking a rough or irregular surface is redistributed into many directions rather than a single mirror angle. It represents scattering statistically or with many spread rays, contrasting with specular reflection and illustrating how diffusers spread energy in a room.','This shows sound scattering in many directions. A rough surface breaks up a reflection. Instead of one clean bounce, sound spreads out. It is the opposite of a mirror bounce. Diffusers use this to spread sound evenly.','It illustrates how rough surfaces and diffusers spread energy, helping designers balance liveliness and control by scattering rather than absorbing or mirroring sound.','It is used to model and explain diffuser performance and to show how scattering evens out a room sound field in acoustic design tools.','Sound Visualization & Acoustic Imaging',ARRAY['Specular reflection visualization','Diffuser','Scattering coefficient','Reflection path diagram','Diffraction visualization']::text[],ARRAY['Confusing diffusion with absorption, which removes energy','Assuming any bumpy surface diffuses at all frequencies','Treating scattered energy as fully random when some specular part remains']::text[],ARRAY['Showing how a diffuser spreads a reflection','Explaining even reverberation from scattering surfaces','Comparing specular and diffuse treatment of a rear wall']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuse reflection visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bae700c9-57f1-5708-aae3-7a0b3badb7e1','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bae700c9-57f1-5708-aae3-7a0b3badb7e1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bae700c9-57f1-5708-aae3-7a0b3badb7e1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '149509bb-f4c0-5b5d-ba44-bed3f7c44dd5','Diffraction visualization','A display of sound diffraction, the bending and spreading of sound waves around obstacles, edges, and through apertures, showing how energy reaches regions that lie outside a straight geometric path. Diffraction is strongest when obstacle or opening sizes are comparable to the wavelength; visualising it reveals shadow-zone leakage and edge effects that ray models miss.','Diffraction visualization shows sound bending around edges. Sound does not always travel in straight lines. It curves around barriers and through gaps. This lets sound reach hidden spots. The effect is strongest for low sounds with long waves.','It explains why barriers never fully block sound and how low frequencies wrap around objects, informing barrier design and expectations of shadow-zone quiet.','It is used in wave-based simulation and teaching to show barrier performance, edge effects on loudspeakers, and low-frequency leakage around obstacles.','Sound Visualization & Acoustic Imaging',ARRAY['Refraction visualization','Wavefront visualization','Sound barrier','Shadow zone','Interference pattern']::text[],ARRAY['Assuming a barrier makes complete silence behind it','Ignoring diffraction because ray models leave it out','Expecting the same bending at all frequencies']::text[],ARRAY['Showing low bass wrapping around a noise barrier','Explaining edge diffraction from a loudspeaker cabinet','Illustrating sound leaking through a doorway gap']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffraction visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '149509bb-f4c0-5b5d-ba44-bed3f7c44dd5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='149509bb-f4c0-5b5d-ba44-bed3f7c44dd5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='149509bb-f4c0-5b5d-ba44-bed3f7c44dd5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '38e14e25-feaf-5ad5-97c4-109393d8f3a6','Refraction visualization','A display of sound refraction, the bending of sound-wave paths caused by changes in propagation speed, as with temperature gradients, wind gradients, or a change of medium. Because sound speed depends on the temperature and motion of the medium, wavefronts bend toward regions of lower speed; visualising this shows how outdoor sound curves upward or downward with weather.','Refraction visualization shows sound bending as its speed changes. Sound speed depends on air temperature and wind. When speed changes with height, sound paths curve. This can bend sound up or down outdoors. The picture shows those curved paths.','It explains how weather and layered media steer sound over distance, important for outdoor noise, environmental acoustics, and understanding why sound carries differently by day and night.','It is used in outdoor sound-propagation modelling for noise assessment, explaining why sound carries far on cool nights or bends over a temperature inversion.','Sound Visualization & Acoustic Imaging',ARRAY['Diffraction visualization','Sound speed','Temperature gradient','Wavefront visualization','Outdoor sound propagation']::text[],ARRAY['Confusing refraction, a speed change, with diffraction, an edge-bending effect','Ignoring wind gradients, which also refract sound','Assuming sound speed is fixed regardless of temperature']::text[],ARRAY['Explaining why traffic noise carries far on a cold night','Modelling sound bending over a warm ground layer','Showing upward bending on a hot sunny day']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Refraction visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '38e14e25-feaf-5ad5-97c4-109393d8f3a6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='38e14e25-feaf-5ad5-97c4-109393d8f3a6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='38e14e25-feaf-5ad5-97c4-109393d8f3a6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '58212c1f-b7a0-5042-a916-a6c8b9266bdf','Interference pattern','The spatial pattern of alternating reinforcement and cancellation formed when two or more coherent sound waves overlap: where waves arrive in phase they add, giving constructive interference, and where they arrive out of phase they subtract, giving destructive interference. Visualised as a field of maxima and minima, it depends on frequency, path differences, and source spacing.','An interference pattern forms when sound waves overlap. Where crests meet, sound gets louder. Where a crest meets a trough, sound cancels. This makes a pattern of loud and quiet spots. It depends on frequency and spacing.','It explains why combining sources or reflections creates fixed loud and quiet regions, underlying comb filtering, array behaviour, and standing waves.','It appears in loudspeaker array coverage, comb filtering from reflections, and room measurements where position strongly changes level.','Sound Visualization & Acoustic Imaging',ARRAY['Constructive interference','Destructive interference','Comb filtering','Standing-wave visualization','Phase']::text[],ARRAY['Assuming interference needs identical sources rather than coherent ones','Ignoring that the pattern shifts with frequency','Confusing cancellation dips with equipment faults']::text[],ARRAY['Explaining comb filtering from two nearby loudspeakers','Mapping coverage nulls in a stereo setup','Showing cancellation from a wall reflection']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interference pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '58212c1f-b7a0-5042-a916-a6c8b9266bdf','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='58212c1f-b7a0-5042-a916-a6c8b9266bdf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='58212c1f-b7a0-5042-a916-a6c8b9266bdf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2dc4316-feb9-5fd6-a674-9d1d52a75fc8','Standing-wave visualization','A display of a standing wave, the fixed spatial pattern of nodes, or minima, and antinodes, or maxima, that results when waves of the same frequency travel in opposite directions and superpose, as between parallel reflecting boundaries. The pattern does not travel; instead, pressure oscillates in place. Node and antinode positions are set by frequency and boundary geometry.','A standing-wave picture shows a fixed pattern of loud and quiet spots. It forms when waves bounce back and forth and overlap. Some spots stay quiet; these are nodes. Others stay loud; these are antinodes. The pattern sits still instead of moving.','It shows why certain positions in a room or tube are always loud or quiet at a given frequency, explaining room modes and resonances that colour sound.','It is used to explain and locate room modes, bass buildup, and null positions, and to place subwoofers, listeners, or absorbers accordingly.','Sound Visualization & Acoustic Imaging',ARRAY['Node','Antinode','Room-mode map','Resonance','Interference pattern']::text[],ARRAY['Thinking a standing wave travels, when its pattern is fixed','Assuming nodes are quiet for every frequency, not just the mode''s','Confusing pressure nodes with velocity nodes, which differ in position']::text[],ARRAY['Explaining a bass null at one seat in a small room','Demonstrating nodes in a tube or on a string','Placing a sub to avoid a strong room mode']::text[],'intermediate','p(x,t) = 2*P0*cos(kx)*cos(wt)','The standing-wave pressure equals twice the wave amplitude times the cosine of wavenumber times position times the cosine of angular frequency times time.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Standing-wave visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2dc4316-feb9-5fd6-a674-9d1d52a75fc8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2dc4316-feb9-5fd6-a674-9d1d52a75fc8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2dc4316-feb9-5fd6-a674-9d1d52a75fc8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56cfbd5f-6f35-5906-b833-ef1c3a602c9b','Modal pattern','The characteristic spatial pattern of pressure or displacement associated with a single resonance mode of a system, such as an air volume, plate, or membrane, showing the fixed arrangement of nodes and antinodes at that mode natural frequency. Each mode has its own distinct pattern; the total response is a sum of such modal patterns.','A modal pattern is the shape of one resonance. Every resonance has its own layout of loud and quiet regions. The pattern stays fixed at that mode''s frequency. It shows where motion or pressure peaks and where it stalls. Real systems combine many such patterns.','It describes how each resonance distributes energy in space, key to understanding room modes, instrument bodies, and structural vibration.','It is used in modal analysis of rooms, panels, and instruments to see and control where each resonance concentrates energy.','Sound Visualization & Acoustic Imaging',ARRAY['Eigenmode visualization','Room-mode map','Nodal pattern','Resonance','Standing-wave visualization']::text[],ARRAY['Assuming a room has one pattern rather than many overlapping modes','Confusing a mode shape with a travelling wave','Ignoring that patterns change with frequency']::text[],ARRAY['Mapping the pressure shape of a room''s lowest mode','Studying a plate''s vibration mode shapes','Explaining uneven bass from overlapping modes']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56cfbd5f-6f35-5906-b833-ef1c3a602c9b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56cfbd5f-6f35-5906-b833-ef1c3a602c9b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56cfbd5f-6f35-5906-b833-ef1c3a602c9b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9144064b-14d9-554c-b591-5850c01677ce','Room-mode map','A visualization of the spatial pressure distribution of a room resonance, or room mode, showing where pressure is maximal, at antinodes typically at boundaries, and minimal, at nodes, for a given modal frequency. For a rigid-walled rectangular room the modal frequencies follow a standard relation set by room dimensions and integer mode numbers; the map guides placement of sources, listeners, and treatment.','A room-mode map shows the loud and quiet zones of a room resonance. Low rooms ring at certain notes. At each note, pressure piles up in some places and drops in others. The map shows those places. It helps place subs, seats, and traps.','It reveals where a given room mode boosts or cancels bass, guiding low-frequency treatment and the positioning of subwoofers and listeners.','It is used in small-room and studio design to predict bass hot spots and nulls and to plan bass traps and sub placement.','Sound Visualization & Acoustic Imaging',ARRAY['Room mode','Standing-wave visualization','Modal pattern','Bass trap','Node']::text[],ARRAY['Treating each mode alone when several overlap in real rooms','Assuming the map holds for non-rectangular rooms','Ignoring damping, which softens real mode peaks']::text[],ARRAY['Predicting bass buildup in room corners','Choosing a listening position away from a mode null','Planning bass-trap placement at pressure maxima']::text[],'advanced','f = (c/2) * sqrt((l/Lx)^2 + (m/Ly)^2 + (n/Lz)^2)','A rectangular room mode frequency equals half the sound speed times the square root of the summed squares of each mode number divided by its matching room dimension.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room-mode map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9144064b-14d9-554c-b591-5850c01677ce','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9144064b-14d9-554c-b591-5850c01677ce') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9144064b-14d9-554c-b591-5850c01677ce');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '084d5375-2943-58ab-8bdd-1e60df59f456','Node','A point, line, or surface in a standing wave or vibrating system where the oscillating quantity, pressure or displacement, remains minimal or zero. Nodes are fixed in space and alternate with antinodes, the maxima; their positions depend on the mode and boundary conditions. In acoustics, pressure nodes and velocity nodes occur at different locations.','A node is a spot that stays still in a wave. There the motion or pressure is at its lowest. Nodes do not move as the wave rings. They sit between the loud spots, the antinodes. Where a node falls depends on the mode.','It marks the quiet, low-energy locations of a resonance, essential for understanding standing waves, mode shapes, and where to sense or avoid a mode.','It explains dead spots for a room mode, quiet mic positions, and where to touch a string or plate to favour certain modes.','Sound Visualization & Acoustic Imaging',ARRAY['Antinode','Nodal line','Standing-wave visualization','Room-mode map','Modal pattern']::text[],ARRAY['Confusing pressure nodes with velocity nodes, which differ in place','Assuming a node is quiet at every frequency, not just its mode','Thinking nodes move along with the wave']::text[],ARRAY['Finding a bass-null seat at a room mode','Placing a mic at a pressure node to reject a tone','Touching a string at a node to bring out a harmonic']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Node');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '084d5375-2943-58ab-8bdd-1e60df59f456','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='084d5375-2943-58ab-8bdd-1e60df59f456') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='084d5375-2943-58ab-8bdd-1e60df59f456');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0f282bb3-8fdd-5892-b144-13e28cdb1c63','Nodal line','A line on a vibrating surface, such as a plate or membrane, along which the displacement stays essentially zero for a given mode; the two-dimensional analogue of a node. Nodal lines are famously revealed by Chladni figures, where scattered particles collect along the still lines of a driven plate, tracing the mode shape.','A nodal line is a still line on a vibrating plate. Along it the surface barely moves. Sand on a driven plate gathers on these lines. The sand traces the mode''s shape. Chladni figures show this clearly.','It reveals the geometry of a two-dimensional vibration mode, making otherwise invisible plate and membrane modes visible and analysable.','It is used in instrument making, plate tuning such as violin plates, and structural-vibration study to see and adjust mode shapes.','Sound Visualization & Acoustic Imaging',ARRAY['Node','Chladni figure','Nodal pattern','Eigenmode visualization','Modal pattern']::text[],ARRAY['Confusing nodal lines with cracks or surface marks','Assuming one figure shows all modes at once','Forgetting the pattern changes with driving frequency']::text[],ARRAY['Tuning a violin plate by watching Chladni lines','Demonstrating plate modes with sand on a driven plate','Mapping still lines of a loudspeaker cone breakup']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nodal line');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0f282bb3-8fdd-5892-b144-13e28cdb1c63','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0f282bb3-8fdd-5892-b144-13e28cdb1c63') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0f282bb3-8fdd-5892-b144-13e28cdb1c63');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '98880007-2a82-5040-a0cb-8a2256098c49','Nodal pattern','The overall arrangement of nodes, points, lines, or surfaces of minimal motion, that characterises a particular resonance mode of a vibrating system, such as the set of nodal lines on a plate at a given mode. The pattern is unique to each mode and, with the antinodes, defines the mode spatial shape.','A nodal pattern is the full set of still spots in a mode. It links all the nodes for one resonance. On a plate it shows as a set of still lines. Each mode has its own pattern. Together the patterns describe the mode''s shape.','It summarises where a mode is quiet across a whole system, helping identify and compare modes by their distinctive geometry.','It is used in modal analysis and instrument work to identify modes by their node layout and to guide tuning or bracing.','Sound Visualization & Acoustic Imaging',ARRAY['Nodal line','Node','Chladni figure','Modal pattern','Eigenmode visualization']::text[],ARRAY['Mixing patterns from different modes into one','Assuming more nodes always means a higher mode without checking','Ignoring boundary conditions that reshape the pattern']::text[],ARRAY['Identifying a plate mode by its node layout','Comparing nodal patterns across drum-head modes','Guiding brace placement from a panel node pattern']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nodal pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '98880007-2a82-5040-a0cb-8a2256098c49','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='98880007-2a82-5040-a0cb-8a2256098c49') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='98880007-2a82-5040-a0cb-8a2256098c49');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb7ae615-8a23-5d19-94ca-87aad688da18','Eigenmode visualization','A display of a system eigenmodes, its natural resonance modes, each with a fixed spatial shape, the eigenfunction, and a natural frequency, the eigenvalue, showing the mode shapes of an air cavity, room, plate, or structure. Computed analytically or by numerical methods such as finite elements, eigenmode plots show how each natural mode distributes pressure or displacement.','Eigenmode visualization shows a system''s natural resonances. Every object has preferred ways to vibrate. Each way has its own shape and pitch. The picture draws these shapes. It shows where each mode is strong or still.','It exposes the natural modes that govern resonance and coloration, letting engineers predict and control which frequencies a structure or room will emphasise.','It is used in finite-element and boundary-element modal analysis of rooms, cabinets, panels, and instruments to see mode shapes and target problem resonances.','Sound Visualization & Acoustic Imaging',ARRAY['Modal pattern','Room-mode map','Finite-element acoustic visualization','Resonance','Natural frequency']::text[],ARRAY['Confusing an eigenmode, a natural shape, with a forced response','Assuming modes never overlap, when they do in practice','Ignoring damping that broadens real resonances']::text[],ARRAY['Computing room modes with finite-element analysis','Viewing a loudspeaker cabinet panel modes','Studying an instrument body''s natural modes']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Eigenmode visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb7ae615-8a23-5d19-94ca-87aad688da18','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb7ae615-8a23-5d19-94ca-87aad688da18') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb7ae615-8a23-5d19-94ca-87aad688da18');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fe3d2003-6fe9-5861-bbac-0f7aeb156274','Finite-element acoustic visualization','The display of acoustic results computed with the finite-element method, in which a region of air and often the surrounding structure is discretised into a mesh of small elements and the governing acoustic, or Helmholtz, and structural-acoustic equations are solved. Results such as sound pressure, velocity, or structural vibration are visualised as field plots, mode shapes, or frequency responses.','This shows sound results from a finite-element model. The method chops the air into a mesh of tiny cells. It then solves the sound equations on that mesh. The output becomes a coloured field or mode shape. It works well for enclosed spaces at low frequencies.','It lets engineers predict and see sound fields, modes, and structural-acoustic coupling before building hardware, especially where geometry is complex and enclosed.','It is used to model cabin noise, loudspeaker enclosures, mufflers, and room modes, guiding design changes from simulated field and mode plots.','Sound Visualization & Acoustic Imaging',ARRAY['Boundary-element acoustic visualization','Eigenmode visualization','Computational acoustic field map','Helmholtz equation','Finite element method']::text[],ARRAY['Using too coarse a mesh for the frequency, causing errors','Trusting the method at high frequencies where it grows costly','Ignoring boundary-condition accuracy, which drives results']::text[],ARRAY['Simulating cabin noise inside a vehicle','Modelling modes of a small sealed enclosure','Designing a muffler from simulated pressure fields']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Finite-element acoustic visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fe3d2003-6fe9-5861-bbac-0f7aeb156274','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fe3d2003-6fe9-5861-bbac-0f7aeb156274') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fe3d2003-6fe9-5861-bbac-0f7aeb156274');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2f811e9c-a391-5844-96f9-4038732750a5','Boundary-element acoustic visualization','The display of acoustic results from the boundary-element method, which solves the acoustic field by discretising only the boundaries, or surfaces, of a problem rather than the whole volume, using the Helmholtz integral equation. It suits exterior radiation and scattering problems; results are visualised as surface pressures and radiated or scattered fields.','This shows sound results from a boundary-element model. Unlike volume meshing, it meshes only the surfaces. It then finds the sound sent out or scattered from them. The output shows surface pressure and the field around an object. It suits open, radiating problems.','It efficiently predicts exterior radiation and scattering by meshing only surfaces, and visualises how a body radiates or scatters sound into open space.','It is used to model loudspeaker and machine radiation, scattering from objects, and exterior noise, giving surface and far-field plots for design.','Sound Visualization & Acoustic Imaging',ARRAY['Finite-element acoustic visualization','Computational acoustic field map','Helmholtz integral equation','Sound radiation','Scattering']::text[],ARRAY['Using this method for large interior volumes better suited to finite elements','Ignoring irregular-frequency problems in exterior solving','Under-meshing surfaces for the wavelength']::text[],ARRAY['Predicting how a loudspeaker cabinet radiates sound','Modelling scattering from a vehicle body','Computing exterior noise from a machine surface']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary-element acoustic visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2f811e9c-a391-5844-96f9-4038732750a5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2f811e9c-a391-5844-96f9-4038732750a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2f811e9c-a391-5844-96f9-4038732750a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6809cdc3-ece8-57f0-803b-7914f0f10838','Computational acoustic field map','A spatial sound-field map generated by numerical simulation, such as finite elements, boundary elements, finite-difference time-domain, or ray and wave hybrids, rather than by direct measurement, showing predicted pressure, level, or intensity over a region. It lets designers explore sound fields for geometries and conditions that would be hard or costly to measure.','A computational acoustic field map is a simulated sound picture. A computer solves the sound equations for a space. It then draws the predicted field. No microphones are used. It lets you test designs before building them.','It provides predicted field maps for design and analysis, enabling what-if studies and optimisation before any physical prototype exists.','It is used in product, room, and vehicle design to predict noise and coverage, compare options, and guide changes from simulated maps.','Sound Visualization & Acoustic Imaging',ARRAY['Finite-element acoustic visualization','Boundary-element acoustic visualization','Finite-difference time-domain','Acoustic simulation','Pressure-field map']::text[],ARRAY['Trusting simulation without validating against measurement','Using an unsuitable method for the frequency range','Ignoring how boundary and material data limit accuracy']::text[],ARRAY['Predicting coverage in an unbuilt auditorium','Comparing two enclosure designs by simulated fields','Mapping predicted noise around new machinery']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Computational acoustic field map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6809cdc3-ece8-57f0-803b-7914f0f10838','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6809cdc3-ece8-57f0-803b-7914f0f10838') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6809cdc3-ece8-57f0-803b-7914f0f10838');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5eed5185-4647-5824-88ca-64ce778e2463','Far-field acoustic holography','An acoustic-holography approach in which the sound field is reconstructed from measurements taken in the far field of the source, as opposed to nearfield acoustic holography, which measures very close to the source. Because far-field data omit the rapidly decaying evanescent, subwavelength components, spatial resolution is limited by wavelength; the method links to beamforming-type far-field processing.','This rebuilds a sound field from far-off measurements. The mics sit well away from the source. Far-off data miss the fine near-field detail. So the picture is limited by the wavelength. It cannot resolve very small features.','It reconstructs source fields when close access is impossible, accepting wavelength-limited resolution in exchange for practical far-field measurement.','It is used where near-field scanning is impractical, overlapping with beamforming for source characterisation at a distance.','Sound Visualization & Acoustic Imaging',ARRAY['Nearfield acoustic holography','Far-field beamforming','Evanescent wave','Holographic reconstruction','Acoustic hologram']::text[],ARRAY['Expecting sub-wavelength detail that only near-field data provide','Confusing it with near-field holography high resolution','Ignoring the loss of evanescent information']::text[],ARRAY['Characterising a source that cannot be approached closely','Comparing far-field holography with beamforming results','Reconstructing a radiated field from distant measurements']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Far-field acoustic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5eed5185-4647-5824-88ca-64ce778e2463','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5eed5185-4647-5824-88ca-64ce778e2463') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5eed5185-4647-5824-88ca-64ce778e2463');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3cb3dd23-d25f-5ca8-9154-b11fe95fc7c3','Acoustic hologram','A reconstructed representation of a sound field, its amplitude and phase over a surface or volume, obtained by acoustic holography, or, in a related modern sense, a shaped phase and amplitude pattern, often from a passive phase plate, that forms a desired sound-field image. In measurement holography, it captures the complex field from which pressure, velocity, and intensity can be derived.','An acoustic hologram captures a sound field''s full pattern. It records both how strong and how delayed the sound is. From it you can rebuild pressure and motion. Some holograms instead shape sound into a target pattern. Both use strength and timing together.','It stores the complete complex sound field, enabling reconstruction of related quantities or the deliberate shaping of a field into a chosen pattern.','It is used in near-field holography for source analysis and, with phase plates, in ultrasound to sculpt fields for trapping, haptics, or fabrication.','Sound Visualization & Acoustic Imaging',ARRAY['Holographic reconstruction','Nearfield acoustic holography','Back-propagation','Phase','Computational acoustic field map']::text[],ARRAY['Assuming it is a picture rather than amplitude-and-phase data','Ignoring that phase is essential, not optional','Confusing measurement holograms with field-shaping phase plates']::text[],ARRAY['Recording a source''s complex field for holography','Shaping an ultrasound field with a printed phase plate','Deriving intensity from a measured hologram']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic hologram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3cb3dd23-d25f-5ca8-9154-b11fe95fc7c3','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3cb3dd23-d25f-5ca8-9154-b11fe95fc7c3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3cb3dd23-d25f-5ca8-9154-b11fe95fc7c3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e426571f-5797-5f7b-bb90-2c674093b282','Holographic reconstruction','The computational process of recovering a sound field at a surface or plane of interest from acoustic data measured on another surface, by inverting the propagation relationship between the two. In nearfield acoustic holography this reconstructs the field on or near the source, including evanescent components, from a nearby measurement hologram, yielding pressure, velocity, and intensity distributions.','Holographic reconstruction rebuilds a sound field from measured data. Mics record the field on one surface. Math then finds the field on another surface. This often means finding the field right at the source. It gives pressure, motion, and energy flow.','It transforms a measured hologram into useful field quantities at the source, enabling source location, ranking, and detailed near-field analysis.','It is the core step in holography systems used for noise-source identification on machines, panels, and products.','Sound Visualization & Acoustic Imaging',ARRAY['Nearfield acoustic holography','Back-propagation','Acoustic hologram','Equivalent source method','Inverse problem']::text[],ARRAY['Ignoring that reconstruction is an ill-posed inverse problem needing regularisation','Amplifying measurement noise when back-propagating too far','Under-sampling the hologram spatially and aliasing the result']::text[],ARRAY['Reconstructing panel velocity from a nearby mic scan','Finding a machine''s radiating hot spots by holography','Deriving surface intensity from a measured hologram']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Holographic reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e426571f-5797-5f7b-bb90-2c674093b282','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e426571f-5797-5f7b-bb90-2c674093b282') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e426571f-5797-5f7b-bb90-2c674093b282');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a9c5211-4339-5add-b241-6bf9e381a8ae','Back-propagation','In acoustic holography, the process of numerically propagating a measured sound field back toward the source to reconstruct the field at a plane closer to, or on, the source. In planar holography this is done in the spatial-frequency, or wavenumber, domain, where each plane-wave and evanescent component is multiplied by a propagator that depends on the axial distance; it is an ill-posed inverse operation requiring regularisation because evanescent terms are amplified.','Back-propagation traces a sound field back to its source. You measure the field a little away from the source. Math then steps the field backward through space. This rebuilds the field at the source plane. It must be done carefully to avoid blowing up noise.','It recovers the source-plane field from a remote measurement, the key inverse step that gives holography its ability to localise and quantify sources.','It is used inside holography software to reconstruct source-surface pressure, velocity, and intensity from a measured hologram.','Sound Visualization & Acoustic Imaging',ARRAY['Nearfield acoustic holography','Holographic reconstruction','Wavenumber spectrum','Evanescent wave','Regularization']::text[],ARRAY['Back-propagating too far and amplifying evanescent noise','Skipping regularisation of the ill-posed inversion','Ignoring spatial aliasing from coarse mic spacing']::text[],ARRAY['Reconstructing a source plane from a scanned hologram','Regularising a noisy back-propagation to a panel','Recovering surface velocity for intensity mapping']::text[],'advanced','P(k, z0) = P(k, zH) * exp(-j*kz*(zH - z0))','Each wavenumber component of the field at the source plane equals the measured component times a propagator exponential set by the distance stepped back toward the source.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Back-propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a9c5211-4339-5add-b241-6bf9e381a8ae','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a9c5211-4339-5add-b241-6bf9e381a8ae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a9c5211-4339-5add-b241-6bf9e381a8ae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'deb51629-ac3c-55d5-84e5-629fd1c7a223','Equivalent source method','An acoustic-holography and radiation-modelling technique that represents an actual source field by the field of a set of simple virtual, or equivalent, sources, typically monopoles or multipoles, placed inside or behind the real source surface, with strengths fitted so the modelled field matches measurements. Once fitted, the equivalent sources reconstruct pressure, velocity, and intensity anywhere in the field.','This method replaces a real source with simple fake ones. It puts virtual point sources behind the surface. Their strengths are tuned to match the measured sound. Then they can rebuild the field anywhere. It handles odd shapes more easily than flat methods.','It provides a flexible way to reconstruct and predict a source field, handling complex geometries that planar or cylindrical holography cannot, by fitting simple sources to data.','It is used in holography and radiation modelling for irregularly shaped sources, giving field reconstructions and radiated-power estimates.','Sound Visualization & Acoustic Imaging',ARRAY['Nearfield acoustic holography','Holographic reconstruction','Monopole','Boundary-element acoustic visualization','Inverse problem']::text[],ARRAY['Placing equivalent sources poorly, harming the reconstruction','Ignoring regularisation of the fitted inverse problem','Using too few sources to capture the real field']::text[],ARRAY['Reconstructing the field of an irregular machine housing','Modelling radiated power from a complex source','Applying holography where planar geometry does not fit']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Equivalent source method');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'deb51629-ac3c-55d5-84e5-629fd1c7a223','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='deb51629-ac3c-55d5-84e5-629fd1c7a223') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='deb51629-ac3c-55d5-84e5-629fd1c7a223');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1873247-173f-529a-86d6-662aea8ac3b2','Patch acoustic holography','A form of nearfield acoustic holography that reconstructs the sound field over a limited patch of the source using a measurement aperture smaller than the full source, employing special techniques such as data extrapolation or regularised inversion to reduce the errors that a truncated aperture would otherwise cause. It enables local imaging of large sources without measuring the whole surface.','Patch holography images only part of a large source. The mic area is smaller than the source. Normally this small window causes edge errors. Special math reduces those errors. It lets you study one patch at a time.','It makes holography practical for large sources by allowing a small measurement window, using extra processing to control the errors that truncation introduces.','It is used to inspect local regions of big structures, such as vehicle panels or large machines, where scanning the entire surface is impractical.','Sound Visualization & Acoustic Imaging',ARRAY['Nearfield acoustic holography','Holographic reconstruction','Measurement aperture','Regularization','Back-propagation']::text[],ARRAY['Ignoring edge, or truncation, errors from the small aperture','Extending results beyond the reliable patch region','Skipping the regularisation that patch methods rely on']::text[],ARRAY['Imaging one panel of a large vehicle body','Studying a local hot spot on a big machine','Applying holography where full-surface scanning is impossible']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Patch acoustic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1873247-173f-529a-86d6-662aea8ac3b2','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1873247-173f-529a-86d6-662aea8ac3b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1873247-173f-529a-86d6-662aea8ac3b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '091611a7-2afe-57ad-b3b6-b682debcdc16','Planar acoustic holography','The classical form of nearfield acoustic holography in which sound pressure is measured over a plane close to a roughly planar source and the field is reconstructed on parallel planes by transforming to the wavenumber domain, applying a propagator, and transforming back. It efficiently uses spatial Fourier transforms but assumes planar measurement and source geometry.','Planar holography measures sound on a flat grid near a source. It works best when the source is fairly flat too. It uses Fourier math to move the field between planes. This rebuilds the field at the source. It is the classic, most common holography form.','It provides an efficient, well-understood way to reconstruct source-plane fields for flat sources, using fast spatial transforms.','It is used to image flat panels, plates, and machine faces, reconstructing surface velocity and intensity from a planar scan.','Sound Visualization & Acoustic Imaging',ARRAY['Nearfield acoustic holography','Back-propagation','Wavenumber spectrum','Cylindrical acoustic holography','Spherical acoustic holography']::text[],ARRAY['Applying planar geometry to strongly curved sources','Ignoring aperture truncation and spatial aliasing','Measuring too far from the source and losing evanescent detail']::text[],ARRAY['Reconstructing velocity on a flat radiating panel','Imaging a machine face with a planar array','Deriving surface intensity from a planar hologram scan']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Planar acoustic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '091611a7-2afe-57ad-b3b6-b682debcdc16','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='091611a7-2afe-57ad-b3b6-b682debcdc16') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='091611a7-2afe-57ad-b3b6-b682debcdc16');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '801b4b48-af53-5d7d-bcf4-c89e1dfb69b9','Cylindrical acoustic holography','A form of nearfield acoustic holography that uses a cylindrical measurement surface and cylindrical-harmonic, or Fourier-Bessel, expansions to reconstruct the sound field of sources whose geometry suits a cylinder, such as engines, motors, or tyres. Measured pressure on the cylinder is decomposed into cylindrical wave components, propagated, and recombined to reconstruct the field.','This holography wraps the measurement around a cylinder. It suits sources shaped like a tube or drum. Mics sample sound on a cylinder-shaped surface. Special math for round shapes rebuilds the field. It fits engines, motors, and tyres well.','It extends holography to cylindrical sources, matching the measurement geometry to the object so reconstruction is accurate for tube-like radiators.','It is used to image radiation from engines, electric motors, and rotating machinery whose shape fits a cylinder.','Sound Visualization & Acoustic Imaging',ARRAY['Planar acoustic holography','Spherical acoustic holography','Nearfield acoustic holography','Cylindrical harmonics','Back-propagation']::text[],ARRAY['Forcing cylindrical geometry onto flat or spherical sources','Under-sampling around the cylinder and aliasing','Ignoring end effects at the cylinder''s open ends']::text[],ARRAY['Imaging noise radiation from a running engine','Studying an electric motor''s radiating surface','Mapping tyre noise around its circumference']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cylindrical acoustic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '801b4b48-af53-5d7d-bcf4-c89e1dfb69b9','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='801b4b48-af53-5d7d-bcf4-c89e1dfb69b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='801b4b48-af53-5d7d-bcf4-c89e1dfb69b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fd9950a8-f7a1-50c6-abea-aa386175ee93','Spherical acoustic holography','Nearfield acoustic holography performed on a spherical measurement surface using spherical-harmonic expansions to reconstruct the sound field, suited to compact sources that can be surrounded by a sphere. Pressure sampled on the sphere is decomposed into spherical wave functions, propagated radially, and recombined to reconstruct interior or exterior fields.','This holography wraps the measurement around a sphere. It suits small sources you can surround. Mics sample sound on a ball-shaped shell. Math for round shells rebuilds the field. It works both inward and outward from the sphere.','It reconstructs the field of compact sources by matching a spherical measurement geometry, using spherical harmonics for accurate radial propagation.','It is used with spherical microphone arrays to characterise compact sources and sound fields, including for spatial-audio and source-radiation studies.','Sound Visualization & Acoustic Imaging',ARRAY['Spherical harmonics','Spherical microphone array','Planar acoustic holography','Cylindrical acoustic holography','Nearfield acoustic holography']::text[],ARRAY['Applying it to sources too large for the sphere','Under-sampling the sphere and limiting the usable order','Ignoring the frequency limits set by sphere size and mic count']::text[],ARRAY['Characterising a compact source with a spherical array','Capturing a sound field for spatial-audio analysis','Reconstructing radiation from a small loudspeaker']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical acoustic holography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fd9950a8-f7a1-50c6-abea-aa386175ee93','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fd9950a8-f7a1-50c6-abea-aa386175ee93') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fd9950a8-f7a1-50c6-abea-aa386175ee93');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f666347e-f000-5ae8-955b-0e4f72bb3857','Volumetric sound-field reconstruction','The reconstruction of an acoustic field throughout a three-dimensional region, or volume, rather than on a single plane or surface, giving pressure and often velocity or intensity at every point in the volume. It is obtained by combining measured amplitude and phase data with propagation models or holography, yielding a full three-dimensional picture of the field.','This rebuilds sound through a whole three-dimensional space. It gives a value at every point in a volume. It uses recorded strength and timing of the sound. Models then fill in the full space. The result is a complete space-filling field.','It provides a complete spatial picture of a field, letting engineers explore any plane or point within a volume rather than being limited to one surface.','It is used in research and advanced holography to study complex fields in three dimensions, for source analysis, spatial audio, and validation of simulations.','Sound Visualization & Acoustic Imaging',ARRAY['Holographic reconstruction','Nearfield acoustic holography','Pressure-field map','Isosurface of pressure','Sound intensity map']::text[],ARRAY['Assuming dense volume data when only surface data were measured','Ignoring how measurement noise limits three-dimensional accuracy','Treating a reconstructed volume as exact everywhere']::text[],ARRAY['Building a field around a source for full three-dimensional analysis','Slicing a reconstructed volume at any plane of interest','Validating a simulation against a measured space-filling field']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volumetric sound-field reconstruction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f666347e-f000-5ae8-955b-0e4f72bb3857','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f666347e-f000-5ae8-955b-0e4f72bb3857') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f666347e-f000-5ae8-955b-0e4f72bb3857');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fcef45c4-b3ed-5dad-b649-442c9cac9de0','Acoustic field video','An emerging term for a video-like, time-varying visualization of spatial sound intensity across a scene, in which each frame is a spatially grounded map of sound intensity, typically generated with beamforming microphone arrays, so that changing sound activity is shown as moving imagery aligned with the visual scene. It extends still acoustic maps into a temporal sequence.','An acoustic field video shows sound activity as moving video. Each frame maps where sound is strong. A mic array and beamforming build the frames. Playing them shows sound changing over time. It is like a movie of sound across a scene.','It captures how sound sources change and move over time, adding the temporal dimension that single acoustic images lack, for monitoring and analysis.','It is used in research and monitoring to watch sound sources appear, move, and fade, useful for dynamic events, machinery cycles, or scene analysis.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic camera','Sound intensity map','Acoustic beamforming map','Beamforming','Source localization map']::text[],ARRAY['Expecting sharper detail than the array resolution allows','Reading frame colour as calibrated level without scaling','Assuming smooth motion when frame rate or averaging limits it']::text[],ARRAY['Watching noise sources shift during a machine cycle','Monitoring a scene for transient sound events','Reviewing how a source moves across a beamforming view']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic field video');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fcef45c4-b3ed-5dad-b649-442c9cac9de0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fcef45c4-b3ed-5dad-b649-442c9cac9de0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fcef45c4-b3ed-5dad-b649-442c9cac9de0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4affcf19-496b-5463-b7cf-f022e62e538f','Cymatics','Cymatics is the study and display of vibration made visible by driving a physical medium — sand or powder on a plate, a liquid film, or a stretched membrane — at acoustic frequencies so that its standing-wave modes appear as ordered patterns. In its physically grounded sense it is the visualization of resonant modal behavior: the medium organizes along nodal regions of least motion, and the geometry of the pattern is set by the boundary shape, the driving frequency, and the medium''s mechanics. The term is a twentieth-century coinage for phenomena already explained by classical plate, membrane, and surface-wave acoustics.','Cymatics means making sound patterns you can see. You vibrate a plate or liquid with a tone. Sand or water then forms a clear shape. The shape depends on the pitch and the surface. It shows how the surface vibrates.','It turns an invisible vibration into a visible, repeatable pattern, letting people observe resonance, mode shapes, and how frequency and boundary conditions govern a medium''s motion.','Educators and instrument makers use cymatic setups — Chladni plates, tonoscopes, or driven liquid dishes — to demonstrate resonance, compare mode shapes, and show how changing pitch reshapes the pattern.','Sound Visualization & Acoustic Imaging',ARRAY['Chladni figure','Standing-wave pattern','Resonance pattern','Modal sand pattern','Faraday wave']::text[],ARRAY['Treating cymatics as proof of mystical or healing ''frequencies'' rather than ordinary resonance physics','Believing a pattern is a property of the tone alone, ignoring plate shape, size, and boundary conditions','Assuming the coined term names a science separate from established plate and membrane acoustics']::text[],ARRAY['Demonstrating resonance to students with a sand-covered plate','Showing how a rising tone reshapes a driven water film','Comparing mode shapes of different plate geometries']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cymatics');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4affcf19-496b-5463-b7cf-f022e62e538f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4affcf19-496b-5463-b7cf-f022e62e538f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4affcf19-496b-5463-b7cf-f022e62e538f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51d525fa-f0f1-5f01-9147-049f00a75e95','Chladni figure','A Chladni figure is the pattern traced by fine particles that gather along the nodal lines of a vibrating elastic plate. When the plate is excited at one of its resonant frequencies, its surface divides into regions oscillating out of phase, separated by nodal lines of near-zero transverse motion; scattered sand is bounced away from the moving antinodal areas and settles where motion is least, rendering the mode''s nodal geometry visible.','A Chladni figure is a sand pattern on a shaking plate. Play the right tone and the plate vibrates strongly. Sand jumps off the moving parts. It settles on the still lines. Those still lines draw the pattern.','It reveals the nodal-line geometry of a plate''s vibration modes, making the shape of each resonance directly observable.','Instrument builders and acoustics teachers use Chladni figures to map the mode shapes of plates such as violin or guitar tops and to compare tuning between plates.','Sound Visualization & Acoustic Imaging',ARRAY['Chladni plate','Nodal accumulation','Modal sand pattern','Resonance pattern','Standing-wave pattern']::text[],ARRAY['Thinking the sand marks the loudest-moving spots instead of the still nodal lines','Assuming a plate gives one figure, when each resonance gives a different pattern','Overlooking that the support or clamp point changes which modes appear']::text[],ARRAY['Mapping the mode shapes of a violin plate during tuning','Classroom demonstration of plate resonances','Comparing nodal patterns as the drive frequency rises']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chladni figure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51d525fa-f0f1-5f01-9147-049f00a75e95','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51d525fa-f0f1-5f01-9147-049f00a75e95') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51d525fa-f0f1-5f01-9147-049f00a75e95');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6cd34a35-2fdb-5604-9c3b-3e82d9a5d73b','Chladni plate','A Chladni plate is a thin, usually metal, plate — clamped or supported at a point — used to make its flexural vibration modes visible. Driven at a resonant frequency by a bow, a loudspeaker, or a mechanical exciter and dusted with sand or powder, it collects the particles along nodal lines to display the corresponding modal shape. It is the classic apparatus of experimental modal acoustics for plates, and the geometry of its patterns follows Chladni''s law relating modal frequency to the number of nodal lines.','A Chladni plate is a thin metal plate you can vibrate. You hold it at one point and drive it with a tone. Sand on top forms lines. Each tone gives a new pattern. It shows the plate''s vibration modes.','It provides a simple, direct way to excite and display the resonant flexural modes of a plate and to study how frequency and boundary conditions set the pattern.','Used in teaching labs and instrument workshops to find resonances, verify mode shapes, and study how plate thickness, shape, and support affect modal frequencies.','Sound Visualization & Acoustic Imaging',ARRAY['Chladni figure','Modal sand pattern','Resonance pattern','Nodal accumulation','Standing-wave pattern']::text[],ARRAY['Expecting a pattern without exciting an actual resonance of the plate','Forgetting that the support or clamp point suppresses modes that need motion there','Assuming plate material and thickness do not shift the modal frequencies']::text[],ARRAY['Finding plate resonances in a physics teaching lab','Tuning a violin top by reading its mode shapes','Studying how added mass shifts a plate''s modes']::text[],'intermediate','f ∝ (m + 2n)²','For a flat circular plate, the modal frequency is roughly proportional to the square of the quantity (m plus twice n), where m counts diametric nodal lines and n counts circular nodal lines.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Chladni plate');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6cd34a35-2fdb-5604-9c3b-3e82d9a5d73b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6cd34a35-2fdb-5604-9c3b-3e82d9a5d73b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6cd34a35-2fdb-5604-9c3b-3e82d9a5d73b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c7d565bb-e29c-55cc-ab70-1aa1e860548d','Sonorous figure','Sonorous figure is the historical name, dating to Chladni''s own work, for the visible particle patterns formed on a vibrating plate or membrane at resonance. It denotes the same nodal-line figures now called Chladni figures: sand or powder collecting where the surface is nearly motionless while the plate sounds. The phrase reflects the early study of ''sounding figures'' that linked an audible tone to a geometric pattern.','Sonorous figure is an old name for a Chladni pattern. It means the sand shapes on a plate that is making sound. The sand gathers on the still lines. It was the early term for these figures.','It names the historically recognized link between an audible tone from a plate and the geometric nodal pattern that appears at that resonance.','The term appears in historical and scholarly acoustics writing; technicians meet it when reading older texts on plate vibration and instrument acoustics.','Sound Visualization & Acoustic Imaging',ARRAY['Chladni figure','Chladni plate','Nodal accumulation','Modal sand pattern']::text[],ARRAY['Assuming it is a different phenomenon from a Chladni figure rather than the older name for it','Reading ''sonorous'' as loudness rather than the sounding of the plate','Expecting one canonical figure instead of one per resonance']::text[],ARRAY['Reading a historical account of Chladni''s experiments','Comparing old and modern names for plate patterns','Discussing the early history of visible acoustics']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonorous figure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c7d565bb-e29c-55cc-ab70-1aa1e860548d','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c7d565bb-e29c-55cc-ab70-1aa1e860548d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c7d565bb-e29c-55cc-ab70-1aa1e860548d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3279ee54-2e99-51bb-8dcd-981ac0a2ef79','Nodal accumulation','Nodal accumulation is the gathering of scattered particles along the nodal lines or regions of a vibrating surface. Because antinodal areas oscillate with large transverse velocity, they impart energy to grains and eject them, while nodal regions stay nearly still; grains bounced from the moving zones progressively settle where motion is minimal, so they accumulate to trace the mode''s nodes. It is the mechanism that renders Chladni and related patterns visible.','Nodal accumulation is sand piling up on the still lines. The moving parts of the plate throw grains off. The still lines do not. So grains end up on the still lines. That builds the visible pattern.','It is the physical process that converts a vibration mode into a visible pattern, concentrating particles where surface motion is least.','Understanding it helps technicians read Chladni patterns correctly and choose particle size and quantity for a clear mode display.','Sound Visualization & Acoustic Imaging',ARRAY['Chladni figure','Antinode clearing','Modal sand pattern','Standing-wave pattern','Powder-pattern visualization']::text[],ARRAY['Thinking particles gather at the strongest-moving spots rather than at the nodes','Using grains too heavy or coarse to be moved by the vibration','Ignoring that very fine powder can migrate to antinodes, giving inverse patterns']::text[],ARRAY['Explaining why sand forms lines on a Chladni plate','Choosing sand grain size for a clear demonstration','Interpreting an unexpected inverse pattern from fine powder']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nodal accumulation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3279ee54-2e99-51bb-8dcd-981ac0a2ef79','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3279ee54-2e99-51bb-8dcd-981ac0a2ef79') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3279ee54-2e99-51bb-8dcd-981ac0a2ef79');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f3b83f4-6304-50ab-a843-382368f31f5e','Antinode clearing','Antinode clearing is the removal of particles from the antinodal regions of a vibrating surface — the areas of maximum transverse displacement and velocity. At an antinode the surface accelerates strongly, launching resting grains upward and outward so those zones are swept clear; the ejected particles come to rest at the nodes. It is the complement of nodal accumulation, and together they form the visible mode pattern.','Antinode clearing is sand being thrown off the moving parts. Antinodes move the most. They fling grains away. This leaves those areas bare. The bare zones help outline the pattern.','It explains why the high-motion regions of a mode appear empty, defining the pattern''s shape alongside where particles collect.','Recognizing cleared antinodes helps technicians spot where a plate moves most, useful when damping rattles or placing supports and pickups.','Sound Visualization & Acoustic Imaging',ARRAY['Nodal accumulation','Chladni figure','Standing-wave pattern','Resonance pattern','Modal sand pattern']::text[],ARRAY['Reading a cleared area as a dead or damaged spot rather than a high-motion antinode','Assuming coarse and very fine powders clear the same regions','Expecting clearing without reaching a true resonance']::text[],ARRAY['Identifying the high-motion zones of a vibrating plate','Explaining bare patches in a sand figure','Locating where to damp a rattling panel']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Antinode clearing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f3b83f4-6304-50ab-a843-382368f31f5e','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f3b83f4-6304-50ab-a843-382368f31f5e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f3b83f4-6304-50ab-a843-382368f31f5e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ae773d2-fb4a-5c5e-b2c0-0ca4800b947e','Modal sand pattern','A modal sand pattern is the specific sand figure corresponding to one vibration mode of a plate or membrane. Each resonant mode has a distinct spatial distribution of nodes and antinodes; sand driven at that mode''s frequency settles along its nodal set, producing a pattern unique to that mode. Sweeping the drive frequency steps the surface through successive modes, each with its own sand pattern.','A modal sand pattern is the sand shape for one vibration mode. Each mode has its own layout of still lines. Drive that mode and the sand draws it. Change the tone and a new shape appears.','It links a particular resonant mode to a visible signature, letting observers identify and catalog a surface''s modes by their patterns.','Instrument makers use modal sand patterns to tune plates, matching observed figures to target modes on violin, guitar, or cymbal plates.','Sound Visualization & Acoustic Imaging',ARRAY['Chladni figure','Resonance pattern','Standing-wave pattern','Nodal accumulation','Membrane vibration pattern']::text[],ARRAY['Assuming a plate has only one pattern rather than one per mode','Confusing closely spaced modes whose patterns look similar','Ignoring that support and clamping select which modes appear']::text[],ARRAY['Cataloging the first several modes of a test plate','Matching a figure to a target mode during tuning','Distinguishing two nearby resonances by their patterns']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal sand pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ae773d2-fb4a-5c5e-b2c0-0ca4800b947e','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ae773d2-fb4a-5c5e-b2c0-0ca4800b947e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ae773d2-fb4a-5c5e-b2c0-0ca4800b947e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd9bd3ee0-c1ef-5217-8e82-92d4d9e67e45','Membrane vibration pattern','A membrane vibration pattern is the nodal figure of a vibrating stretched membrane, such as a drumhead, made visible with sand or powder or measured optically. A circular membrane''s modes have Bessel-function radial shapes and angular divisions, giving nodal circles and nodal diameters along which particles collect. Unlike a stiff plate, a membrane''s restoring force is tension, so its modal frequencies are inharmonic and follow the membrane wave equation.','A membrane vibration pattern is the shape a drumhead makes when it vibrates. Its still lines form rings and lines across the head. Sand gathers on them. Each mode gives a different set of rings and lines.','It reveals the mode shapes of a membrane, showing where it stays still and where it moves for each resonance.','Drum builders and acousticians use membrane patterns to study head modes, tuning, and how damping or loading shifts a drum''s response.','Sound Visualization & Acoustic Imaging',ARRAY['Modal sand pattern','Chladni figure','Standing-wave pattern','Resonance pattern','Nodal accumulation']::text[],ARRAY['Assuming membrane modes are harmonically spaced like an ideal string','Treating a tension membrane like a stiff plate with the same modes','Forgetting that air loading and the shell shift real drumhead frequencies']::text[],ARRAY['Studying the ring modes of a timpani head','Comparing a drumhead''s modes before and after tuning','Teaching membrane resonance with a powdered drumhead']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Membrane vibration pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd9bd3ee0-c1ef-5217-8e82-92d4d9e67e45','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d9bd3ee0-c1ef-5217-8e82-92d4d9e67e45') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d9bd3ee0-c1ef-5217-8e82-92d4d9e67e45');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27160824-2dda-5b4c-b545-541daf1fd3ed','Resonance pattern','A resonance pattern is the spatial figure a system displays when driven at one of its natural frequencies, where response amplitude peaks and the motion locks into a characteristic mode shape. In pattern visualization it is the arrangement of nodes and antinodes — shown by sand, liquid, or optical means — that appears only at resonance; off resonance the ordered pattern collapses. Its geometry is fixed by the system''s boundaries and the mode excited.','A resonance pattern is the shape a system makes at a natural frequency. At that pitch it vibrates strongly. A clear pattern of still and moving zones appears. Off that pitch, the pattern fades.','It marks and displays a system''s resonances, showing both that a natural frequency is reached and what its mode shape looks like.','Technicians use resonance patterns to locate the natural frequencies of plates, panels, and membranes and to diagnose unwanted resonances in structures and instruments.','Sound Visualization & Acoustic Imaging',ARRAY['Standing-wave pattern','Modal sand pattern','Chladni figure','Membrane vibration pattern','Faraday wave']::text[],ARRAY['Expecting a clear pattern at any frequency, not only at resonances','Confusing the driving frequency with the system''s own natural frequency','Assuming a bigger drive always sharpens the pattern, ignoring damping']::text[],ARRAY['Sweeping a tone to find a panel''s resonances','Confirming a natural frequency by the pattern''s appearance','Diagnosing a buzzing part by its resonant mode']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resonance pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27160824-2dda-5b4c-b545-541daf1fd3ed','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27160824-2dda-5b4c-b545-541daf1fd3ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27160824-2dda-5b4c-b545-541daf1fd3ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c5593a46-6bc8-5309-804e-9e43c9ed15d8','Standing-wave pattern','A standing-wave pattern is the stationary spatial distribution of nodes and antinodes formed when two waves of equal frequency travel in opposite directions and superpose, as with a wave and its reflection in a bounded medium. The pattern does not propagate; nodes of minimum amplitude and antinodes of maximum amplitude stay fixed in space, with adjacent nodes separated by half a wavelength. It underlies Chladni figures, tube and string resonances, and acoustic-levitation nodes.','A standing-wave pattern is a wave that seems to stay in place. It has fixed still points and fixed moving points. The still points are called nodes. Nodes sit half a wavelength apart.','It describes how confined or reflected waves organize into fixed nodes and antinodes, the basis of resonance patterns in strings, tubes, plates, and fields.','Engineers meet standing-wave patterns in room modes, pipe and string resonances, and acoustic levitation, using node spacing to infer wavelength and frequency.','Sound Visualization & Acoustic Imaging',ARRAY['Resonance pattern','Pressure-node visualization','Pressure-antinode visualization','Chladni figure','Faraday wave']::text[],ARRAY['Thinking a standing wave carries energy along like a traveling wave','Measuring node-to-node spacing as a full wavelength instead of half','Assuming standing waves need a fully closed boundary at both ends']::text[],ARRAY['Measuring node spacing to find a tube''s wavelength','Explaining room modes between parallel walls','Locating nodes in an acoustic levitator']::text[],'intermediate','Δx = λ / 2','Neighboring nodes in a standing wave are separated by half a wavelength.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Standing-wave pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c5593a46-6bc8-5309-804e-9e43c9ed15d8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c5593a46-6bc8-5309-804e-9e43c9ed15d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c5593a46-6bc8-5309-804e-9e43c9ed15d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '730b62b3-9c95-5e84-b955-f8143ef7c13b','Faraday wave','A Faraday wave is a standing surface wave that forms on a liquid layer vibrated vertically above a critical acceleration, first reported by Faraday. The pattern responds subharmonically, oscillating at half the driving frequency, and organizes into stripes, squares, or hexagons on the surface. Its wavelength is set by the gravity-capillary dispersion relation evaluated at the subharmonic frequency, making the liquid surface a visible display of a parametric instability.','A Faraday wave is a ripple pattern on a shaken liquid. Vibrate a dish hard enough and the surface forms waves. They can look like stripes or squares. The pattern moves at half the shaking rate.','It shows how vertical vibration can drive a liquid surface into ordered standing-wave patterns through a parametric, subharmonic instability.','Faraday waves appear in liquid cymatics, in pattern-formation and microfluidics research, and as a caution in vibration-sensitive liquid handling.','Sound Visualization & Acoustic Imaging',ARRAY['Standing-wave pattern','Capillary wave pattern','Ripple tank visualization','Liquid-surface sound visualization','Resonance pattern']::text[],ARRAY['Expecting the surface to move at the drive frequency, not its subharmonic half','Assuming any small vibration makes the pattern, ignoring the acceleration threshold','Confusing driven Faraday waves with free ripples from a dropped object']::text[],ARRAY['Showing square and stripe patterns on a vibrated water dish','Studying pattern selection versus drive frequency','Explaining subharmonic response in a physics lab']::text[],'advanced','f_pattern = f_drive / 2;  ω² = (g k + (σ/ρ) k³) tanh(k h)','The surface pattern oscillates at half the driving frequency; the wave''s angular frequency squared relates to wavenumber through gravity, surface tension over density, and the fluid depth.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Faraday wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '730b62b3-9c95-5e84-b955-f8143ef7c13b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='730b62b3-9c95-5e84-b955-f8143ef7c13b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='730b62b3-9c95-5e84-b955-f8143ef7c13b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '723613f0-3ca2-5dad-9993-fe7a1f09c1cb','Ripple tank visualization','Ripple tank visualization is the display of water-surface waves in a shallow transparent tank, illuminated so that wave crests and troughs act as lenses and cast bright and dark bands on a screen below. Used to model general wave behavior, it demonstrates reflection, refraction, diffraction, and interference with controllable sources and barriers. Although the medium is water, the geometry of the patterns illustrates principles that also apply to sound and other waves.','A ripple tank is a shallow tray of water with waves. A light shines through it onto a screen. The waves show up as bright and dark bands. It is used to show how waves bounce, bend, and overlap.','It makes wave behavior visible and controllable, letting learners see reflection, refraction, diffraction, and interference directly.','Physics teaching labs use ripple tanks to demonstrate wave principles that also govern sound, with bars, gaps, and shaped barriers as sources and obstacles.','Sound Visualization & Acoustic Imaging',ARRAY['Capillary wave pattern','Standing-wave pattern','Faraday wave','Liquid-surface sound visualization','Resonance pattern']::text[],ARRAY['Assuming water-wave speed and behavior match sound exactly, ignoring different dispersion','Reading the projected bands as water height rather than a lensing effect','Overlooking that tank depth strongly changes the wave speed']::text[],ARRAY['Demonstrating diffraction through a gap to a class','Showing two-source interference of water waves','Illustrating refraction over a shallow ramp']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ripple tank visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '723613f0-3ca2-5dad-9993-fe7a1f09c1cb','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='723613f0-3ca2-5dad-9993-fe7a1f09c1cb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='723613f0-3ca2-5dad-9993-fe7a1f09c1cb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f61d9964-9853-5edc-b78b-53c6e65e148a','Capillary wave pattern','A capillary wave pattern is the arrangement of short-wavelength surface waves on a liquid for which surface tension, not gravity, is the dominant restoring force. Such waves — typically of millimeter scale — arise on vibrated or disturbed liquid surfaces and follow a dispersion relation in which frequency rises steeply with wavenumber. In sound visualization they form fine ripple textures on driven liquid films and appear within Faraday-wave and cymatic displays.','A capillary wave pattern is a set of tiny ripples on a liquid. They are so small that surface tension pulls them back, not gravity. They form fine textures on a shaken liquid. You see them in cymatic dishes.','It describes the fine, tension-driven ripples that texture a vibrated liquid surface, shaping the detail seen in liquid sound displays.','Capillary waves appear in liquid cymatics, in atomization and spray studies, and in surface-tension measurement by driven-ripple methods.','Sound Visualization & Acoustic Imaging',ARRAY['Faraday wave','Ripple tank visualization','Liquid-surface sound visualization','Standing-wave pattern','Resonance pattern']::text[],ARRAY['Assuming gravity sets the speed of these short ripples, when surface tension dominates','Treating capillary and gravity waves as one regime with the same dispersion','Ignoring how surfactants and contamination change surface tension and the pattern']::text[],ARRAY['Explaining fine ripples on a driven water film','Measuring surface tension from ripple wavelength','Studying spray formation from a vibrated surface']::text[],'advanced','ω² ≈ (σ/ρ) k³','For short surface waves, angular frequency squared is about the surface tension divided by the density, times the wavenumber cubed.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Capillary wave pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f61d9964-9853-5edc-b78b-53c6e65e148a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f61d9964-9853-5edc-b78b-53c6e65e148a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f61d9964-9853-5edc-b78b-53c6e65e148a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0bd4f051-4b97-5534-aec9-e62677617313','Acoustic levitation visualization','Acoustic levitation visualization is the display of small particles or liquid droplets held nearly motionless at the pressure nodes of an intense ultrasonic standing wave. Between an emitter and reflector, or among phased emitters, the acoustic radiation force balances gravity and traps objects at fixed points spaced half a wavelength apart. Seeing the suspended objects makes the standing-wave node structure and the levitation force directly visible.','Acoustic levitation visualization shows objects floating on sound. A strong standing wave holds small beads or drops in the air. They sit at the quiet points of the wave. These points are half a wavelength apart.','It demonstrates the acoustic radiation force and the node structure of a standing wave by holding visible objects at fixed trapping points.','Used in demonstrations and in containerless handling of droplets and samples, where levitated positions reveal node spacing and field strength.','Sound Visualization & Acoustic Imaging',ARRAY['Nodal trapping','Acoustic radiation force visualization','Standing-wave pattern','Pressure-node visualization','Ultrasound field visualization']::text[],ARRAY['Thinking objects float at pressure antinodes rather than near the nodes','Assuming any sound level can levitate, ignoring the very high intensities needed','Believing large, heavy objects levitate as easily as tiny beads or drops']::text[],ARRAY['Suspending water droplets for containerless study','Demonstrating node spacing with levitated beads','Positioning small samples without a holder']::text[],'advanced','d = λ / 2','Stable trapping points sit at the pressure nodes of a standing wave, spaced half a wavelength apart.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic levitation visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0bd4f051-4b97-5534-aec9-e62677617313','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0bd4f051-4b97-5534-aec9-e62677617313') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0bd4f051-4b97-5534-aec9-e62677617313');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3cc4297-1956-52c5-861b-ecbf8d2e8b76','Nodal trapping','Nodal trapping is the confinement of particles or droplets at the nodes of an acoustic standing wave by the acoustic radiation force. For objects small compared with the wavelength and denser than the medium, the time-averaged force pushes them toward the pressure nodes and holds them there against gravity or flow. It is the mechanism behind acoustic levitation and behind particle patterning in acoustofluidic devices.','Nodal trapping means sound holds particles at its quiet points. In a standing wave, small dense particles drift to the nodes. The sound force keeps them there. This traps them in place.','It explains how a standing acoustic field collects and holds particles at fixed points, enabling levitation and particle patterning.','Acoustofluidic chips use nodal trapping to line up cells or beads; levitators use it to suspend droplets for study.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic levitation visualization','Acoustic radiation force visualization','Pressure-node visualization','Standing-wave pattern','Nodal accumulation']::text[],ARRAY['Assuming all particles trap at nodes, when very light or bubble-like ones move to antinodes','Confusing the steady trapping force with the fast back-and-forth of the sound field','Ignoring that particle size relative to wavelength changes the force']::text[],ARRAY['Aligning cells along nodes in an acoustofluidic chip','Holding a droplet steady in a levitator','Patterning beads in a standing-wave channel']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nodal trapping');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3cc4297-1956-52c5-861b-ecbf8d2e8b76','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3cc4297-1956-52c5-861b-ecbf8d2e8b76') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3cc4297-1956-52c5-861b-ecbf8d2e8b76');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9781d7c8-fc37-5f82-ba26-cb410dc9b9b2','Acoustic radiation force visualization','Acoustic radiation force visualization is the display of the steady, time-averaged force that an acoustic field exerts on objects, boundaries, or interfaces. Arising from the nonlinear transfer of momentum in the sound field, this force can push, trap, or deform particles, droplets, and tissue; showing its effect — levitated beads, deflected surfaces, or induced flow — makes an otherwise invisible force apparent. It underlies acoustic levitation, particle manipulation, and elastography.','This shows the push that sound gives to objects. A sound field can press on small things steadily. You see it by watching beads float or a surface bend. That reveals the hidden force.','It reveals the steady force a sound field applies, helping explain levitation, particle handling, and force-based imaging.','Seen in acoustic levitators, in acoustofluidic sorting, and in shear-wave elastography, where a radiation-force push probes tissue stiffness.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic levitation visualization','Nodal trapping','Acoustic streaming visualization','Ultrasound field visualization','Standing-wave pattern']::text[],ARRAY['Confusing the steady radiation force with ordinary sound pressure that averages to zero','Assuming the force always pulls objects toward nodes regardless of their properties','Ignoring that it grows with intensity and depends on the object''s size and density']::text[],ARRAY['Demonstrating a bead pushed to a node','Explaining how elastography nudges tissue','Showing a surface bulged by a focused beam']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic radiation force visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9781d7c8-fc37-5f82-ba26-cb410dc9b9b2','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9781d7c8-fc37-5f82-ba26-cb410dc9b9b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9781d7c8-fc37-5f82-ba26-cb410dc9b9b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '222e111e-35ab-53b7-84f8-5b13ae131b2f','Particle tracing','Particle tracing is the use of small seeded particles to make an invisible motion field — vibration, fluid flow, or acoustic streaming — visible by following the particles'' movement. Tracers are chosen to move faithfully with the field; their tracks, captured by eye or camera, reveal the field''s spatial structure and direction. On vibrating surfaces it produces Chladni-type figures, and in fluids it maps flow and streaming driven by sound.','Particle tracing uses tiny particles to show motion. The particles move with the surface or the flow. You watch or film where they go. Their paths reveal the hidden pattern.','It converts a motion or flow field into visible tracks, letting observers map vibration and flow they cannot see directly.','Used in Chladni demonstrations, in flow visualization, and in acoustic streaming studies where seeded particles trace the induced circulation.','Sound Visualization & Acoustic Imaging',ARRAY['Powder-pattern visualization','Acoustic streaming visualization','Nodal accumulation','Chladni figure','Modal sand pattern']::text[],ARRAY['Using particles too heavy or large to follow the motion faithfully','Assuming a tracer track equals instantaneous velocity when the exposure blurs it','Seeding so densely that the particles disturb the very flow being traced']::text[],ARRAY['Mapping streaming flow with seeded particles','Revealing a plate''s motion with scattered grains','Tracking flow lines around an obstacle']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Particle tracing');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '222e111e-35ab-53b7-84f8-5b13ae131b2f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='222e111e-35ab-53b7-84f8-5b13ae131b2f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='222e111e-35ab-53b7-84f8-5b13ae131b2f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5b64933-33ef-52a4-b797-c4ca8e9f9993','Powder-pattern visualization','Powder-pattern visualization is the general method of dusting a vibrating surface with fine powder or sand to reveal its vibration modes as accumulated-particle figures. Coarser grains gather at nodes to trace nodal lines, while very fine powders can migrate under acoustic streaming toward antinodes, giving inverse patterns. It encompasses Chladni-plate and membrane techniques and is the simplest way to display modal shapes.','Powder-pattern visualization means sprinkling powder on a vibrating surface. The powder moves and forms a pattern. Coarse sand gathers on the still lines. Very fine powder can gather on the moving parts instead.','It provides a low-cost way to display a surface''s vibration modes, with grain size chosen to show nodal or inverse patterns.','Teaching labs and workshops dust plates and panels with sand or lycopodium powder to reveal and compare mode shapes.','Sound Visualization & Acoustic Imaging',ARRAY['Chladni figure','Modal sand pattern','Nodal accumulation','Membrane vibration pattern','Particle tracing']::text[],ARRAY['Assuming all powders gather at the nodes, ignoring fine-powder inverse patterns','Using too much powder, which blurs the pattern','Forgetting that surface texture and static charge affect where powder settles']::text[],ARRAY['Revealing panel modes with a light dusting of sand','Comparing coarse and fine powder patterns','Demonstrating an inverse pattern with lycopodium powder']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Powder-pattern visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5b64933-33ef-52a4-b797-c4ca8e9f9993','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5b64933-33ef-52a4-b797-c4ca8e9f9993') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5b64933-33ef-52a4-b797-c4ca8e9f9993');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ceb84c06-3160-5bd5-8207-5605a8591d55','Liquid-surface sound visualization','Liquid-surface sound visualization is the display of acoustic or vibrational excitation through the motion of a liquid surface — ripples, standing waves, droplet ejection, or crawling patterns on a driven film. Vertical or acoustic driving deforms the surface, and lighting reveals the resulting textures, including Faraday and capillary waves. It is the liquid branch of cymatics, showing frequency- and amplitude-dependent surface patterns.','This means showing sound through a moving liquid surface. Vibration makes ripples, waves, or jumping drops. Light reveals the shapes. The pattern changes with pitch and loudness.','It turns vibration into visible liquid-surface patterns, displaying how a fluid responds to frequency and amplitude.','Used in liquid-cymatics demonstrations, tonoscope-style displays, and studies of driven thin films and droplet behavior.','Sound Visualization & Acoustic Imaging',ARRAY['Faraday wave','Capillary wave pattern','Ripple tank visualization','Standing-wave pattern','Cymatics']::text[],ARRAY['Reading every surface pattern as a direct picture of the sound wave itself','Ignoring the acceleration threshold needed for Faraday patterns','Assuming water depth and dish shape do not affect the result']::text[],ARRAY['Projecting a driven water film for an audience','Showing how a tone changes ripple spacing','Comparing patterns at different drive levels']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Liquid-surface sound visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ceb84c06-3160-5bd5-8207-5605a8591d55','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ceb84c06-3160-5bd5-8207-5605a8591d55') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ceb84c06-3160-5bd5-8207-5605a8591d55');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5a20bfb-c29c-563d-9d80-3dc9aeec88fb','Ferrofluid acoustic visualization','Ferrofluid acoustic visualization is the display of vibration or sound using a magnetic colloidal fluid whose surface can be shaped by a magnetic field. Under a field the ferrofluid forms spiked patterns from the normal-field (Rosensweig) instability, and vertical or acoustic driving adds surface waves, so the combined pattern responds to both the field and the vibration. It is mainly an artistic and demonstration technique rather than a quantitative measurement method.','This uses a magnetic liquid to show vibration. A magnet pulls the liquid into spikes. Sound or shaking then makes the surface ripple. The spiky surface moves with the vibration. It is used mostly for art and demos.','It creates striking visible surface patterns that respond to vibration, combining magnetic shaping with surface-wave motion for display.','Seen in art installations and science demonstrations that pair a ferrofluid pool with music, magnets, and a vibration source.','Sound Visualization & Acoustic Imaging',ARRAY['Liquid-surface sound visualization','Faraday wave','Capillary wave pattern','Cymatics','Standing-wave pattern']::text[],ARRAY['Treating it as a precise acoustic measurement rather than an artistic display','Crediting the magnetic spikes to sound when the field forms them','Assuming the fluid responds only to sound and not mainly to the magnet']::text[],ARRAY['Building a music-reactive ferrofluid art piece','Demonstrating magnetic surface spikes to students','Combining magnets and vibration for a visual show']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ferrofluid acoustic visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5a20bfb-c29c-563d-9d80-3dc9aeec88fb','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5a20bfb-c29c-563d-9d80-3dc9aeec88fb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5a20bfb-c29c-563d-9d80-3dc9aeec88fb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '39309559-8918-5d66-9cf1-c5deff3f2f77','Laser vibrometry visualization','Laser vibrometry visualization is the rendering of surface vibration measured by a laser Doppler vibrometer, which detects the Doppler frequency shift of light reflected from a moving surface to recover its velocity without contact. Scanning the beam over a surface and processing the data yields maps or animations of operating deflection shapes and mode shapes. It provides high-resolution, non-contact visualization of how a structure vibrates.','This shows how a surface vibrates using a laser. The laser light shifts when it hits a moving surface. That shift gives the surface speed. Scanning the beam builds a map of the motion. No sensor touches the object.','It measures and displays surface vibration without contact, mapping mode shapes and motion that added sensors would disturb.','Used to map the vibration of instrument bodies, loudspeaker cones, panels, and machine parts, and to validate structural models.','Sound Visualization & Acoustic Imaging',ARRAY['Holographic interferometry','Electronic speckle pattern interferometry','Modal sand pattern','Resonance pattern','Membrane vibration pattern']::text[],ARRAY['Assuming a single-point reading gives full mode shapes without scanning','Ignoring that a poorly reflecting surface needs treatment for a good signal','Confusing measured surface velocity with displacement without integrating']::text[],ARRAY['Mapping a loudspeaker cone''s motion','Measuring a guitar top''s mode shapes','Validating a finite-element vibration model']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Laser vibrometry visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '39309559-8918-5d66-9cf1-c5deff3f2f77','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='39309559-8918-5d66-9cf1-c5deff3f2f77') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='39309559-8918-5d66-9cf1-c5deff3f2f77');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c48a1135-d0f2-5577-a966-2fd5fc9277eb','Holographic interferometry','Holographic interferometry is an optical technique that compares holographically recorded wavefronts from an object in two states to reveal microscopic surface displacements as interference fringes. For vibration, time-averaged holography records a vibrating surface so that fringe brightness follows the mode''s amplitude distribution, mapping its nodes and antinodes. It measures deformation and vibration to a fraction of the light''s wavelength.','This uses laser holograms to show tiny motion. It compares light from a surface at two moments. Small movements show up as dark and bright fringes. The fringes map how a surface vibrates.','It visualizes very small surface displacements and vibration mode shapes with sub-wavelength sensitivity across a whole field at once.','Used to study the mode shapes of instrument plates, loudspeaker parts, and mechanical components in acoustics and engineering labs.','Sound Visualization & Acoustic Imaging',ARRAY['Electronic speckle pattern interferometry','Laser vibrometry visualization','Interferometric acoustic visualization','Resonance pattern','Modal sand pattern']::text[],ARRAY['Reading the fringe count as absolute motion without the correct interpretation','Ignoring that vibration or air currents blur the delicate fringes','Assuming it needs only ordinary light rather than coherent laser light']::text[],ARRAY['Imaging a violin plate''s vibration modes','Mapping a diaphragm''s deflection under load','Comparing modes at successive resonances']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Holographic interferometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c48a1135-d0f2-5577-a966-2fd5fc9277eb','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c48a1135-d0f2-5577-a966-2fd5fc9277eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c48a1135-d0f2-5577-a966-2fd5fc9277eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '03aacd65-749e-5a67-b59e-b4dd8301e1d8','Electronic speckle pattern interferometry','Electronic speckle pattern interferometry (ESPI) is a video-based interferometric method that images surface displacement and vibration by electronically comparing the laser speckle patterns from an object in different states. Subtracting or correlating camera frames produces fringe patterns that map deformation or, for vibration, the mode-shape amplitude distribution in near real time. It offers whole-field, non-contact vibration visualization without photographic processing.','ESPI uses laser speckle and a camera to show motion. It compares speckle images of a surface. The differences form fringes. The fringes reveal how the surface bends or vibrates. It works in near real time.','It gives fast, whole-field, non-contact maps of surface deformation and vibration mode shapes using a camera instead of film.','Used in acoustics and engineering to visualize the mode shapes of plates, panels, and instrument bodies and to inspect for defects.','Sound Visualization & Acoustic Imaging',ARRAY['Holographic interferometry','Laser vibrometry visualization','Interferometric acoustic visualization','Resonance pattern','Modal sand pattern']::text[],ARRAY['Confusing ESPI speckle fringes with dust or noise in the image','Expecting good fringes without a stable, vibration-isolated setup','Assuming it measures absolute shape rather than the change between two states']::text[],ARRAY['Watching mode shapes update as frequency changes','Inspecting a panel for hidden debonds','Mapping a small speaker''s diaphragm motion']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electronic speckle pattern interferometry');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '03aacd65-749e-5a67-b59e-b4dd8301e1d8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='03aacd65-749e-5a67-b59e-b4dd8301e1d8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='03aacd65-749e-5a67-b59e-b4dd8301e1d8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'efdbf6ad-582d-5fe8-8ceb-b119069b720f','Schlieren imaging','Schlieren imaging is an optical technique that visualizes refractive-index gradients in a transparent medium, which correspond to density — and hence pressure or temperature — variations. Light passing through the test region is refracted by these gradients; a knife-edge placed at the focus blocks part of the deflected light, converting ray deflection into brightness changes in the image. With sufficient speed and sensitivity it reveals shock waves, thermal plumes, jets, and even sound waves in air.','Schlieren imaging shows changes in air density as light and dark. Light bends when it passes through denser or thinner air. A sharp edge at the focus turns that bending into shading. This makes shock waves and even sound visible.','It converts invisible density gradients into visible brightness patterns, letting engineers see flows, heat, and pressure disturbances in clear media.','Used in wind tunnels, ballistics, and acoustics labs to see shock waves, jets, and sound fields, and to study loudspeakers and gas leaks.','Sound Visualization & Acoustic Imaging',ARRAY['Schlieren photography','Shadowgraph imaging','Background-oriented schlieren','Shock-wave visualization','Stroboscopic schlieren']::text[],ARRAY['Confusing schlieren, which senses the first derivative of density, with shadowgraph, which senses the second','Assuming it shows any sound, when only strong or high-frequency fields are visible','Forgetting that the knife-edge orientation sets which gradient direction is seen']::text[],ARRAY['Filming a shock wave around a bullet','Seeing the plume of hot air above a flame','Visualizing an ultrasonic beam in air']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Schlieren imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'efdbf6ad-582d-5fe8-8ceb-b119069b720f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='efdbf6ad-582d-5fe8-8ceb-b119069b720f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='efdbf6ad-582d-5fe8-8ceb-b119069b720f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '68c3396f-2547-5bf7-978a-76f590abb959','Schlieren photography','Schlieren photography is the photographic capture of a schlieren image, recording refractive-index gradients in a transparent medium as brightness variations on film or a sensor. It uses the classic arrangement of a bright source, lenses or mirrors, a knife-edge at the focus, and a camera to freeze density disturbances such as shock waves and thermal flows. It is the still-image form of schlieren visualization.','Schlieren photography takes a still photo of density changes in air. It uses lenses or mirrors, a bright source, and a knife-edge. Bending light forms light and dark areas. The camera records the pattern.','It preserves a schlieren view as a photograph, documenting density disturbances such as shocks, heat plumes, and strong sound fields.','Used in ballistics and aerodynamics to photograph shock waves around projectiles and models, and in acoustics to capture pressure fronts.','Sound Visualization & Acoustic Imaging',ARRAY['Schlieren imaging','Shadowgraph imaging','Stroboscopic schlieren','Shock-wave visualization','Background-oriented schlieren']::text[],ARRAY['Treating image brightness as absolute density rather than its gradient','Using too slow a shutter to freeze fast events like shocks','Misaligning the knife-edge so the sensitivity direction is wrong']::text[],ARRAY['Photographing a supersonic model in a wind tunnel','Capturing the shock around a fired bullet','Recording a hot exhaust plume for study']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Schlieren photography');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '68c3396f-2547-5bf7-978a-76f590abb959','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='68c3396f-2547-5bf7-978a-76f590abb959') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='68c3396f-2547-5bf7-978a-76f590abb959');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1520ca7f-3542-57a6-8392-b91bfd3e67f8','Stroboscopic schlieren','Stroboscopic schlieren is a schlieren method that uses light flashes or camera exposures synchronized to a periodic acoustic or flow phenomenon so that fast, repetitive motion appears frozen or slowed. By flashing at, or slightly off, the driving frequency, a rapidly oscillating sound field — such as an ultrasonic beam — is sampled at a fixed phase, making its otherwise invisible cycle observable. It combines schlieren sensitivity with stroboscopic timing.','Stroboscopic schlieren freezes fast sound waves with timed flashes. The light blinks in step with the sound. Each flash catches the wave at the same point. So the fast wave looks still or slow.','It lets schlieren capture repetitive high-frequency sound fields by sampling them at a fixed phase, freezing motion too fast to see otherwise.','Used to visualize ultrasonic and audible standing-wave fields by strobing at the drive frequency, revealing wavefronts and node structure.','Sound Visualization & Acoustic Imaging',ARRAY['Schlieren imaging','Schlieren photography','Ultrasound field visualization','Shock-wave visualization','Standing-wave pattern']::text[],ARRAY['Flashing at the wrong frequency, which smears rather than freezes the wave','Assuming a single flash captures the whole cycle instead of one phase','Ignoring timing jitter between the flash and the sound, which blurs the image']::text[],ARRAY['Freezing a 28 kHz ultrasonic wave for viewing','Stepping through a wave''s cycle by shifting the flash phase','Showing a standing-wave field to a class']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Stroboscopic schlieren');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1520ca7f-3542-57a6-8392-b91bfd3e67f8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1520ca7f-3542-57a6-8392-b91bfd3e67f8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1520ca7f-3542-57a6-8392-b91bfd3e67f8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4ac28709-0d88-59bb-addd-3cf470e52db5','Background-oriented schlieren','Background-oriented schlieren (BOS) is a technique that infers refractive-index gradients from the apparent distortion of a textured background viewed through a disturbed medium. A camera records the background with and without the flow; digital image correlation measures the pixel displacements, which are proportional to the density gradient integrated along the line of sight. Needing only a patterned backdrop and a camera, it makes density, pressure, and even sound fields measurable without mirrors or a knife-edge.','BOS finds air density changes by watching a patterned background shift. A camera films the pattern with and without the disturbance. Software measures how the dots move. That movement maps the density change.','It recovers density-gradient fields from background distortion, giving schlieren-like results with simple, low-cost equipment and large fields of view.','Used to visualize shock waves, plumes, and sound outdoors or at large scale, including full-scale imaging of shock waves around aircraft against natural backdrops.','Sound Visualization & Acoustic Imaging',ARRAY['Schlieren imaging','Shadowgraph imaging','Shock-wave visualization','Sonic boom visualization','Schlieren photography']::text[],ARRAY['Expecting sharp results without enough background texture for correlation','Treating measured pixel shifts as local density rather than an integral along the path','Ignoring camera or background motion that adds false displacement']::text[],ARRAY['Imaging an aircraft''s shocks against the desert or sun','Mapping a large plume with only a camera and backdrop','Visualizing a shock outdoors where mirrors are impractical']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Background-oriented schlieren');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4ac28709-0d88-59bb-addd-3cf470e52db5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4ac28709-0d88-59bb-addd-3cf470e52db5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4ac28709-0d88-59bb-addd-3cf470e52db5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf312e15-80d6-5315-a91e-5e86ca7bd088','Shadowgraph imaging','Shadowgraph imaging is an optical method that visualizes refractive-index disturbances by the shadows they cast when collimated or diverging light passes through a transparent medium. Unlike schlieren, it uses no knife-edge; brightness variations arise from the second spatial derivative of the refractive index, so it responds most strongly to sharp gradients such as shock fronts. It is simple to set up and well suited to high-speed flow and strong pressure disturbances.','Shadowgraph imaging shows density changes as shadows. Light passes through the air onto a screen. Sharp density changes bend the light and cast shadows. It works best for shock waves. It needs no knife-edge.','It reveals strong density gradients as shadow patterns with a very simple setup, ideal for shock waves and abrupt disturbances.','Used in ballistics and blast studies to see shock fronts, and in teaching to show thermal plumes and strong flows.','Sound Visualization & Acoustic Imaging',ARRAY['Schlieren imaging','Schlieren photography','Shock-wave visualization','Background-oriented schlieren','Sonic boom visualization']::text[],ARRAY['Confusing shadowgraph with schlieren, which needs a knife-edge and senses a different derivative','Expecting it to show weak, smooth gradients that schlieren would reveal','Reading the bright and dark bands as density rather than its curvature']::text[],ARRAY['Imaging a blast shock in a test range','Showing a candle plume on a screen','Capturing a projectile''s bow shock quickly']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shadowgraph imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf312e15-80d6-5315-a91e-5e86ca7bd088','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf312e15-80d6-5315-a91e-5e86ca7bd088') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf312e15-80d6-5315-a91e-5e86ca7bd088');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d9faa84-8098-527b-ab63-96fac8fbd610','Interferometric acoustic visualization','Interferometric acoustic visualization uses optical interferometry to detect the tiny refractive-index or path-length changes that a sound wave produces in a transparent medium. Because acoustic pressure modulates density and thus the optical path, an interferometer converts these changes into fringe shifts that map the sound field''s pressure distribution, often quantitatively. It provides sensitive, non-contact imaging of acoustic and ultrasonic fields in air, water, or solids.','This uses light interference to show sound. Sound squeezes the medium and changes how light travels through it. An interferometer turns that into moving fringes. The fringes map the sound field. Nothing touches the sound.','It measures and maps a sound field by sensing the optical path changes that pressure causes, giving quantitative, non-contact acoustic images.','Used to characterize ultrasonic transducers and fields in water tanks and to image acoustic pressure without a hydrophone disturbing the field.','Sound Visualization & Acoustic Imaging',ARRAY['Holographic interferometry','Acousto-optic visualization','Schlieren imaging','Ultrasound field visualization','Acoustic pressure field scan']::text[],ARRAY['Assuming fringe shifts show surface displacement rather than integrated refractive-index change','Ignoring that vibration and air currents add noise to the fringes','Expecting results without the coherent, stable light an interferometer needs']::text[],ARRAY['Mapping an ultrasonic transducer''s field in water','Imaging a sound field without perturbing it','Calibrating pressure optically against a hydrophone']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Interferometric acoustic visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d9faa84-8098-527b-ab63-96fac8fbd610','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d9faa84-8098-527b-ab63-96fac8fbd610') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d9faa84-8098-527b-ab63-96fac8fbd610');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aac6421a-0925-5a55-878d-f1e8f2d8b405','Photoelastic visualization','Photoelastic visualization reveals stress and elastic waves, including acoustic waves, in transparent solids using the material''s stress-induced birefringence. When such a material is stressed, it splits polarized light into two components whose relative retardation depends on the local stress; viewed between polarizers, this produces colored or dark fringes that map the stress field. For acoustics it makes ultrasonic and elastic wave propagation in solids directly visible.','Photoelastic visualization shows stress in clear solids with polarized light. Stress makes the material bend light in two ways. Between polarizers, this forms colored fringes. The fringes map the stress. It can show sound waves moving in a solid.','It converts internal stress and elastic-wave fields in transparent solids into visible fringe patterns through stress birefringence.','Used to study ultrasonic wave propagation, mode conversion, and stress concentration in transparent models and components.','Sound Visualization & Acoustic Imaging',ARRAY['Interferometric acoustic visualization','Acousto-optic visualization','Shock-wave visualization','Ultrasound field visualization','Standing-wave pattern']::text[],ARRAY['Assuming opaque metals can be imaged this way rather than transparent models','Reading fringe color directly as stress without calibration','Ignoring residual manufacturing stress that adds background fringes']::text[],ARRAY['Watching an ultrasonic pulse cross a glass model','Studying stress at a notch in a clear part','Teaching wave propagation in a transparent bar']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Photoelastic visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aac6421a-0925-5a55-878d-f1e8f2d8b405','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aac6421a-0925-5a55-878d-f1e8f2d8b405') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aac6421a-0925-5a55-878d-f1e8f2d8b405');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f2929038-d042-5c17-a7ef-62b5d1616c2b','Acousto-optic visualization','Acousto-optic visualization exploits the acousto-optic effect, in which a sound wave''s periodic density variation forms a moving phase grating that diffracts light passing through the medium. The diffracted light''s pattern, intensity, or frequency shift reveals the acoustic wave''s wavelength, amplitude, and frequency. It is used to display and probe ultrasonic fields in transparent liquids and solids and underlies devices such as acousto-optic modulators and deflectors.','This shows sound by how it bends light. A sound wave makes layers of dense and thin medium. These act like a grating that splits a light beam. The split light reveals the sound''s wavelength and strength.','It uses light diffracted by a sound wave to reveal and measure the wave''s properties, and to control light in acousto-optic devices.','Used to visualize ultrasonic waves in water and glass, to measure their wavelength, and inside acousto-optic modulators and deflectors.','Sound Visualization & Acoustic Imaging',ARRAY['Interferometric acoustic visualization','Photoelastic visualization','Ultrasound field visualization','Schlieren imaging','Standing-wave pattern']::text[],ARRAY['Confusing the acousto-optic effect with simple shadowing of the beam','Assuming it works in opaque media rather than transparent ones','Ignoring that strong sound gives many diffraction orders, not just one']::text[],ARRAY['Measuring an ultrasonic wavelength from diffraction angles','Displaying a sound beam in a water cell','Modulating a laser with an acousto-optic cell']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acousto-optic visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f2929038-d042-5c17-a7ef-62b5d1616c2b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f2929038-d042-5c17-a7ef-62b5d1616c2b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f2929038-d042-5c17-a7ef-62b5d1616c2b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c4d0d89a-ba4a-5a34-8e17-606898e15665','Acoustic streaming visualization','Acoustic streaming visualization is the display of the steady fluid flow generated by a sound field, driven by the nonlinear absorption and momentum transfer of intense or attenuated sound. Seeded particles, dye, or optical methods reveal the slow circulation set up near boundaries or along a beam. Visualizing it shows a second-order effect that carries mass and heat and influences mixing and cooling.','This shows steady flow caused by sound. Strong sound pushes fluid along, making a slow current. Adding particles or dye reveals the flow. It is a small but real effect of loud sound.','It reveals the steady circulation a sound field drives in a fluid, an effect important for mixing, heat transfer, and microfluidics.','Seen in acoustofluidic devices, ultrasonic cleaning, and thermoacoustic systems, where streaming moves fluid and enhances transport.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic radiation force visualization','Particle tracing','Acoustic cavitation visualization','Ultrasound field visualization','Nodal trapping']::text[],ARRAY['Confusing steady streaming with the fast oscillation of the sound wave','Assuming streaming is negligible at all levels, when intense sound drives strong flow','Overlooking boundary-driven streaming near walls and obstacles']::text[],ARRAY['Revealing streaming near an ultrasonic horn','Studying mixing in an acoustofluidic chip','Explaining fluid drift along a strong beam']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic streaming visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c4d0d89a-ba4a-5a34-8e17-606898e15665','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c4d0d89a-ba4a-5a34-8e17-606898e15665') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c4d0d89a-ba4a-5a34-8e17-606898e15665');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '665eda39-1055-528d-a4b4-966662f7cccc','Shock-wave visualization','Shock-wave visualization is the optical imaging of shock waves — thin fronts across which pressure, density, and temperature rise almost discontinuously as a disturbance travels faster than the local sound speed. Because shocks are steep density gradients, schlieren, shadowgraph, and background-oriented schlieren render them clearly. Visualizing shocks shows their shape, position, and interactions in ballistics, blasts, and supersonic flow.','Shock-wave visualization pictures the sharp fronts made by very fast events. A shock is a sudden jump in air pressure and density. Optical methods like schlieren make it visible. It shows the shock''s shape and path.','It makes shock fronts and their interactions visible, supporting study of supersonic flow, explosions, and impacts.','Used in ballistics ranges, blast testing, and supersonic wind tunnels to see bow shocks, reflections, and shock-shock interactions.','Sound Visualization & Acoustic Imaging',ARRAY['Schlieren imaging','Shadowgraph imaging','Background-oriented schlieren','Mach cone visualization','Sonic boom visualization']::text[],ARRAY['Calling every strong sound a shock, when shocks require supersonic, nonlinear steepening','Assuming a shock has visible thickness at normal scale rather than being very thin','Confusing the shock front with the slower flow behind it']::text[],ARRAY['Imaging the bow shock on a supersonic model','Studying shock reflections in a blast test','Watching two shocks interact in a wind tunnel']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shock-wave visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '665eda39-1055-528d-a4b4-966662f7cccc','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='665eda39-1055-528d-a4b4-966662f7cccc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='665eda39-1055-528d-a4b4-966662f7cccc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '239aa83e-4cad-5189-a979-a2e5abe6cb61','Mach cone visualization','Mach cone visualization images the conical shock envelope that trails a source moving faster than the sound speed in the medium. The individual pressure disturbances pile up along a cone whose half-angle, the Mach angle, decreases as speed increases; its sine equals the ratio of the sound speed to the source speed. Schlieren, shadowgraph, or background-oriented schlieren reveal the cone around projectiles and supersonic aircraft.','This shows the cone-shaped shock behind a supersonic object. When a source beats the speed of sound, its waves stack into a cone. Faster speed makes a narrower cone. Optical methods reveal it.','It displays the shock cone of a supersonic source and, through its angle, relates the pattern to the source''s Mach number.','Used in ballistics and aerodynamics to see the shock cone around bullets and supersonic models and to estimate speed from the Mach angle.','Sound Visualization & Acoustic Imaging',ARRAY['Shock-wave visualization','Sonic boom visualization','Schlieren imaging','Shadowgraph imaging','Background-oriented schlieren']::text[],ARRAY['Confusing the Mach cone with a single sonic-boom event rather than a steady shock envelope','Assuming the cone angle is fixed, when it depends on the Mach number','Thinking the cone appears at or below the speed of sound']::text[],ARRAY['Measuring a bullet''s speed from its Mach angle','Imaging the shock cone on a supersonic model','Explaining why faster flight narrows the cone']::text[],'advanced','sin μ = c / v = 1 / M','The half-angle of the shock cone has a sine equal to the sound speed divided by the source speed, which is one over the Mach number.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mach cone visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '239aa83e-4cad-5189-a979-a2e5abe6cb61','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='239aa83e-4cad-5189-a979-a2e5abe6cb61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='239aa83e-4cad-5189-a979-a2e5abe6cb61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cde2a94a-c4fd-594a-8f6f-1746c31ea9e8','Sonic boom visualization','Sonic boom visualization is the imaging of the shock-wave system generated by an object in sustained supersonic flight, whose pressure signature reaches the ground as the audible boom. Techniques such as background-oriented schlieren, including air-to-air schlieren against a bright backdrop, capture the bow and tail shocks and their spacing. Visualizing them helps relate aircraft shape to boom strength for low-boom design.','Sonic boom visualization pictures the shocks from a supersonic aircraft. These shocks reach the ground as a loud boom. Schlieren-type methods can photograph them in flight. The images show the shock shape and spacing.','It reveals the shock structure behind supersonic aircraft, linking airframe shape to the strength of the boom heard on the ground.','Used in aeronautics research, including air-to-air schlieren of aircraft, to study and reduce sonic-boom loudness in low-boom design.','Sound Visualization & Acoustic Imaging',ARRAY['Shock-wave visualization','Mach cone visualization','Background-oriented schlieren','Schlieren imaging','Shadowgraph imaging']::text[],ARRAY['Thinking the boom happens only when the aircraft breaks the sound barrier, not continuously in supersonic flight','Assuming one shock, when an aircraft makes several bow and tail shocks','Confusing the ground boom with the visible shock pattern aloft']::text[],ARRAY['Photographing an aircraft''s shocks in flight','Studying how airframe shape sets boom strength','Comparing shock spacing between designs']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonic boom visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cde2a94a-c4fd-594a-8f6f-1746c31ea9e8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cde2a94a-c4fd-594a-8f6f-1746c31ea9e8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cde2a94a-c4fd-594a-8f6f-1746c31ea9e8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27c41d63-81d7-55ea-9da0-8a5ba476d792','Ultrasound field visualization','Ultrasound field visualization is the mapping of an ultrasonic pressure field in space, showing beam shape, focus, near- and far-field structure, and standing-wave nodes. It is done optically — by schlieren, interferometry, or acousto-optic methods — or by scanning a hydrophone through the field. The result guides transducer characterization, quality control, and safety, and reveals where acoustic energy concentrates.','This maps where an ultrasound beam goes and how strong it is. You can use light-based methods or a moving sensor. The map shows the beam''s shape and focus. It shows where the sound is strongest.','It characterizes an ultrasonic field''s spatial structure and intensity, essential for transducer design, calibration, and exposure safety.','Used to test medical and industrial transducers, verify focal spots, and check output against exposure limits.','Sound Visualization & Acoustic Imaging',ARRAY['Hydrophone scan map','Acoustic pressure field scan','Schlieren imaging','Interferometric acoustic visualization','Acousto-optic visualization']::text[],ARRAY['UNSAFE: exposing skin or eyes to a focused high-intensity ultrasound beam while aligning it','Assuming a hydrophone does not perturb the very field it measures','Treating a single-plane scan as the full three-dimensional field']::text[],ARRAY['Verifying a therapy transducer''s focal spot','Mapping a diagnostic probe''s beam in a water tank','Checking field output for safety compliance']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasound field visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27c41d63-81d7-55ea-9da0-8a5ba476d792','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27c41d63-81d7-55ea-9da0-8a5ba476d792') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27c41d63-81d7-55ea-9da0-8a5ba476d792');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce158fdd-39b6-5d9e-bc10-6118d7326159','Hydrophone scan map','A hydrophone scan map is a spatial map of acoustic pressure built by moving a calibrated hydrophone, usually on a motorized positioner, through many points in a sound field and recording amplitude and phase at each. Common in water tanks, it yields beam profiles, focal-region maps, and field cross-sections used to characterize ultrasonic transducers. It is a direct, measurement-based alternative to optical field imaging.','A hydrophone scan map shows a sound field measured point by point. A small underwater microphone moves through the water on a stage. It records the pressure at each spot. The points build a map of the beam.','It provides a calibrated, measured picture of a sound field''s pressure distribution for characterizing and verifying transducers.','Used in ultrasound metrology labs to map medical and industrial transducer beams, focal spots, and output for standards compliance.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic pressure field scan','Ultrasound field visualization','Pressure-node visualization','Pressure-antinode visualization','Interferometric acoustic visualization']::text[],ARRAY['Ignoring that a finite-size hydrophone averages over sharp field features','Assuming the hydrophone does not scatter or perturb the field','Scanning too coarsely to resolve a tight focal region']::text[],ARRAY['Profiling a transducer''s beam in a water tank','Mapping a focal spot for a therapy device','Verifying output pressure against a standard']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hydrophone scan map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce158fdd-39b6-5d9e-bc10-6118d7326159','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce158fdd-39b6-5d9e-bc10-6118d7326159') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce158fdd-39b6-5d9e-bc10-6118d7326159');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9ebaa2bc-eb70-5afc-be8f-c4a4d26fbc11','Acoustic pressure field scan','An acoustic pressure field scan is a spatially resolved measurement of sound pressure amplitude, and often phase, across a plane or volume of a field. Acquired by scanning a microphone, hydrophone, or probe array, it produces maps or holograms of the field that reveal sources, beam patterns, and standing-wave structure. It is the basis of techniques such as nearfield acoustic holography.','This is a point-by-point measurement of sound pressure over a region. A probe records the level, and often the timing, at many spots. The data form a map of the field. It shows sources and beam shapes.','It captures the spatial structure of a sound field for source identification, beam mapping, and holographic reconstruction.','Used in nearfield acoustic holography, loudspeaker and transducer testing, and noise-source mapping on machines and vehicles.','Sound Visualization & Acoustic Imaging',ARRAY['Hydrophone scan map','Ultrasound field visualization','Pressure-node visualization','Pressure-antinode visualization','Interferometric acoustic visualization']::text[],ARRAY['Recording only amplitude when phase is needed for holographic reconstruction','Sampling too sparsely and aliasing the spatial pattern','Ignoring room reflections that contaminate the measured field']::text[],ARRAY['Running nearfield holography on a loudspeaker','Mapping noise sources on a running machine','Measuring a probe''s field in a scanning tank']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic pressure field scan');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9ebaa2bc-eb70-5afc-be8f-c4a4d26fbc11','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9ebaa2bc-eb70-5afc-be8f-c4a4d26fbc11') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9ebaa2bc-eb70-5afc-be8f-c4a4d26fbc11');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '857405b2-c4a2-570b-a0d7-1ae92f91d9e4','Pressure-node visualization','Pressure-node visualization is the display of the locations in a standing sound field where the acoustic pressure amplitude is minimal, ideally zero. At a pressure node the pressure cancels while the particle velocity is maximal; such nodes are spaced half a wavelength apart. They are shown by trapped particles, by probe scans, or optically, and mark where objects tend to gather in acoustic levitation.','This shows the quiet points in a standing sound wave. At a pressure node the pressure nearly cancels. There the air moves the most. Nodes sit half a wavelength apart. Levitated objects gather at them.','It locates the pressure minima of a standing wave, revealing the field''s node structure and where particles are trapped.','Used in acoustic levitation, standing-wave tubes, and acoustofluidics to find and use the node positions where objects collect.','Sound Visualization & Acoustic Imaging',ARRAY['Pressure-antinode visualization','Standing-wave pattern','Acoustic levitation visualization','Nodal trapping','Hydrophone scan map']::text[],ARRAY['Confusing a pressure node, where velocity is highest, with a still point of no motion','Measuring node-to-node spacing as a full wavelength instead of half','Assuming the nodes stay fixed if the frequency or geometry drifts']::text[],ARRAY['Locating trapping nodes in a levitator','Finding pressure minima in a standing-wave tube','Aligning particles at nodes in a channel']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-node visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '857405b2-c4a2-570b-a0d7-1ae92f91d9e4','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='857405b2-c4a2-570b-a0d7-1ae92f91d9e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='857405b2-c4a2-570b-a0d7-1ae92f91d9e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7ef8605b-c1e0-5bb8-8970-c7aca2d57af4','Pressure-antinode visualization','Pressure-antinode visualization is the display of the locations in a standing sound field where the acoustic pressure amplitude is maximal. At a pressure antinode the pressure swings hardest while the particle velocity is minimal; antinodes alternate with nodes, each spaced half a wavelength from its neighbor. They are revealed by probe scans, by particle behavior, or optically, marking where pressure-driven effects are strongest.','This shows the loudest points in a standing sound wave. At a pressure antinode the pressure swings the most. There the air barely moves. Antinodes and nodes take turns. Each is half a wavelength apart.','It locates the pressure maxima of a standing wave, showing where pressure-driven effects and forces are strongest.','Used in standing-wave tubes, acoustofluidics, and levitation to place or study samples where the pressure is greatest.','Sound Visualization & Acoustic Imaging',ARRAY['Pressure-node visualization','Standing-wave pattern','Acoustic levitation visualization','Nodal trapping','Hydrophone scan map']::text[],ARRAY['Confusing a pressure antinode, where motion is least, with a point of greatest motion','Assuming antinodes and nodes are a full wavelength apart','Expecting fixed antinodes when the field''s frequency or geometry changes']::text[],ARRAY['Finding pressure maxima in a resonance tube','Placing a sample at an antinode for strong forcing','Mapping antinode spacing to check wavelength']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-antinode visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7ef8605b-c1e0-5bb8-8970-c7aca2d57af4','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7ef8605b-c1e0-5bb8-8970-c7aca2d57af4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7ef8605b-c1e0-5bb8-8970-c7aca2d57af4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4c6515e7-c175-5d47-aac6-585bea898154','Acoustic cavitation visualization','Acoustic cavitation visualization is the imaging of vapor-and-gas bubbles that form, oscillate, and collapse in a liquid driven by intense sound, usually ultrasound. Below its tensile strength the liquid ruptures during rarefaction, nucleating bubbles that pulsate and can implode violently; high-speed photography, shadowgraph, or scattered-light imaging captures the bubble clouds and their dynamics. Visualizing cavitation shows where and how strongly it occurs.','This images bubbles made by strong sound in a liquid. Loud ultrasound can tear tiny bubbles into being. The bubbles grow, shrink, and burst. High-speed cameras or light catch them. It shows where cavitation happens.','It reveals where and how cavitation bubbles form and collapse, important for cleaning, sonochemistry, and avoiding damage.','Used in ultrasonic cleaning, sonochemistry, and medical ultrasound to monitor cavitation and keep it within safe, useful limits.','Sound Visualization & Acoustic Imaging',ARRAY['Sonoluminescence imaging','Acoustic streaming visualization','Ultrasound field visualization','Acoustic radiation force visualization','Shock-wave visualization']::text[],ARRAY['UNSAFE: assuming cavitation is harmless, when collapse can erode surfaces and damage tissue','Confusing gentle stable bubble oscillation with violent inertial collapse','Expecting cavitation at any level rather than above a pressure threshold']::text[],ARRAY['Watching bubble clouds in an ultrasonic cleaner','Monitoring cavitation in a sonochemistry cell','Checking for cavitation near a therapy transducer']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic cavitation visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4c6515e7-c175-5d47-aac6-585bea898154','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4c6515e7-c175-5d47-aac6-585bea898154') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4c6515e7-c175-5d47-aac6-585bea898154');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f04e8d8-a1af-51c7-b9ea-a917180648be','Sonoluminescence imaging','Sonoluminescence imaging is the capture of the faint light emitted when acoustically driven bubbles collapse in a liquid. During intense collapse the bubble contents heat extremely, producing brief flashes of light synchronized to the sound cycle; single-bubble and multi-bubble sonoluminescence are recorded with sensitive detectors or long exposures. Imaging it studies the extreme conditions inside collapsing bubbles.','This captures light made by collapsing bubbles in sound. Strong ultrasound can make a bubble collapse hard. The collapse gives a tiny flash of light. Sensitive cameras record it. It reveals the extreme heat inside the bubble.','It records the light from collapsing bubbles, giving a window into the extreme temperatures and pressures of cavitation collapse.','Used in sonochemistry and physics research to study cavitation energetics and the conditions inside single, trapped, glowing bubbles.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic cavitation visualization','Ultrasound field visualization','Acoustic streaming visualization','Standing-wave pattern','Nodal trapping']::text[],ARRAY['Expecting bright, easily seen light rather than a very faint flash needing a dark room','Confusing the light with ordinary fluorescence or a heating glow','Assuming it occurs without carefully tuned bubble and drive conditions']::text[],ARRAY['Observing a single glowing bubble in a flask','Studying flash timing against the sound cycle','Investigating cavitation energy in sonochemistry']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sonoluminescence imaging');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f04e8d8-a1af-51c7-b9ea-a917180648be','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f04e8d8-a1af-51c7-b9ea-a917180648be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f04e8d8-a1af-51c7-b9ea-a917180648be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '90127bbf-42bd-58c0-8e19-b055b1f1dce4','Speech spectrogram','A time-frequency image of a speech signal produced by the short-time Fourier transform, plotting time on the horizontal axis, frequency on the vertical axis, and short-term spectral energy as brightness or colour. Wideband settings using short analysis windows resolve rapid events and glottal pulses and show formants as dark bands, while narrowband settings using long windows resolve individual harmonics. It is the primary tool for reading formants, fricative noise, plosive bursts, voicing, and prosody.','A speech spectrogram is a picture of speech over time. Time runs left to right, and pitch height runs bottom to top. Darker areas show where the sound has more energy. Wide-band views make speech sounds and formants easy to see. Narrow-band views show the separate harmonics instead. Experts read it to study vowels, hisses, and stops.','It makes the changing frequency content of speech visible so its acoustic structure can be measured and interpreted.','Phoneticians and voice clinicians use it in tools such as Praat to label sounds, measure formants and timing, and study speech.','Sound Visualization & Acoustic Imaging',ARRAY['Short-time Fourier transform','Formant display','Wideband spectrogram','Narrowband spectrogram','Voicing bar','Fricative noise']::text[],ARRAY['Confusing wideband and narrowband settings and misreading formants as harmonics','Assuming darker always means louder without considering the window length','Reading formant frequencies off the axis without careful calibration']::text[],ARRAY['Labelling vowel and consonant boundaries in a recording','Measuring formant frequencies for a phonetic study','Inspecting a voice sample for clinical assessment']::text[],'intermediate','S(t,f) = |X(t,f)|²','The spectrogram value at a given time and frequency is the squared magnitude of the short-time Fourier transform of the signal at that time and frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '90127bbf-42bd-58c0-8e19-b055b1f1dce4','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='90127bbf-42bd-58c0-8e19-b055b1f1dce4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='90127bbf-42bd-58c0-8e19-b055b1f1dce4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '71d15695-b4e3-586a-a3dd-c88665e5f7dc','Formant display','A visualization that shows the formants of speech, the resonant frequency bands of the vocal tract, typically as tracked lines or highlighted bands over a spectrogram or as marked peaks on a short-term spectrum. Formants, numbered F1, F2, F3 upward from low frequency, arise from vocal-tract resonances and define vowel identity and much consonant quality. The display marks their centre frequencies and how they change over time.','A formant display shows the strong resonance bands in speech. The mouth and throat act like a tube that boosts certain pitches. These boosted bands are called formants, named F1, F2, and so on. The display draws them as lines or bright bars. Their positions tell which vowel is being spoken.','It exposes the vocal-tract resonances that distinguish vowels and shape consonants so they can be tracked and measured.','It is used in Praat and similar tools to measure vowel formants for phonetics, accent study, and speech therapy.','Sound Visualization & Acoustic Imaging',ARRAY['Formant','Formant trajectory','Vowel space plot','Speech spectrogram','Linear predictive coding','Vocal tract resonance']::text[],ARRAY['Confusing formants with the harmonics of the fundamental frequency','Trusting tracker output as exact without checking against the spectrogram','Assuming a formant number always maps to a fixed frequency']::text[],ARRAY['Measuring F1 and F2 to identify a vowel','Comparing formants across speakers or accents','Tracking formant change in a therapy session']::text[],'intermediate','F_n = (2n − 1)·c / (4L)','For a uniform tube closed at the glottis and open at the lips, the nth formant frequency equals two n minus one, times the speed of sound, divided by four times the vocal-tract length.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formant display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '71d15695-b4e3-586a-a3dd-c88665e5f7dc','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='71d15695-b4e3-586a-a3dd-c88665e5f7dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='71d15695-b4e3-586a-a3dd-c88665e5f7dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7296fa54-cf7d-5b58-905f-2754770189f2','Formant trajectory','The path traced by one or more formant frequencies as they change over time through an utterance, especially across vowels, diphthongs, and vowel-consonant transitions. Formant trajectories capture the continuous movement of vocal-tract resonances; the direction and rate of F1, F2, and F3 movement encode diphthongs, glides, and coarticulation, and are read from tracked lines on a spectrogram.','A formant trajectory is the moving path of a formant over time. As the mouth changes shape, the formants slide up or down. A single steady vowel holds them nearly fixed. A diphthong or glide makes them sweep between positions. Reading these paths shows how one sound blends into the next.','It represents how vocal-tract resonances move over time, encoding dynamic speech sounds such as diphthongs and consonant transitions.','Phoneticians read formant trajectories to study diphthongs, coarticulation, and transitions in connected speech.','Sound Visualization & Acoustic Imaging',ARRAY['Formant','Formant display','Diphthong','Coarticulation','Speech spectrogram','Formant transition']::text[],ARRAY['Assuming formants stay fixed within a vowel','Confusing a rising trajectory with a change in fundamental frequency','Ignoring tracker errors at consonant boundaries']::text[],ARRAY['Analyzing a diphthong''s F1 and F2 movement','Studying consonant-to-vowel transitions','Comparing coarticulation between speakers']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Formant trajectory');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7296fa54-cf7d-5b58-905f-2754770189f2','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7296fa54-cf7d-5b58-905f-2754770189f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7296fa54-cf7d-5b58-905f-2754770189f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7af5b475-8110-5d70-aaac-492700e71e22','Vowel space plot','A two-dimensional scatter plot that positions vowels by their formant frequencies, conventionally with the first formant on one axis and the second formant on the other, often with axes reversed so the layout mirrors articulatory tongue position. Each vowel token appears as a point, and the area enclosed by the corner vowels defines the vowel space, used to compare speakers, languages, and clinical populations.','A vowel space plot maps vowels using two formant numbers. The first formant relates to how open the mouth is. The second relates to how far forward the tongue sits. Each vowel becomes a dot on the chart. Dots for similar vowels cluster together. The overall shape compares speakers or languages.','It turns formant measurements into a spatial map so vowels can be compared and the working vowel space quantified.','It is used in phonetics and speech pathology to compare vowel systems, accents, and reduced vowel spaces in disordered speech.','Sound Visualization & Acoustic Imaging',ARRAY['Formant','F1–F2 plot','Formant display','Vowel formant','Vowel space area','Speech spectrogram']::text[],ARRAY['Forgetting that axes are often reversed to match articulation','Comparing raw formants across speakers without normalization','Assuming one token represents a speaker''s whole vowel category']::text[],ARRAY['Plotting a speaker''s vowels to compare an accent','Measuring vowel space area in a clinical study','Comparing the vowel systems of two languages']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vowel space plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7af5b475-8110-5d70-aaac-492700e71e22','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7af5b475-8110-5d70-aaac-492700e71e22') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7af5b475-8110-5d70-aaac-492700e71e22');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd922596b-0d6f-5c3b-ada7-980fb026f141','F1–F2 plot','A specific form of vowel space plot that graphs the first formant frequency against the second formant frequency, the two resonances that most strongly determine vowel identity. Points are typically plotted with both axes decreasing from the origin so the arrangement resembles the traditional articulatory vowel quadrilateral. It is the standard visualization for locating and comparing vowels acoustically.','An F1–F2 plot charts a vowel using its two lowest formants. The first formant sits on one axis and the second on the other. Together these two numbers pin down most vowels. The chart is often flipped so it matches a tongue-position diagram. Each vowel then lands in its own region.','It isolates the two formants that carry most vowel information so vowels can be located and compared on one chart.','It is the everyday tool phoneticians use to place vowels and compare productions across speakers.','Sound Visualization & Acoustic Imaging',ARRAY['Vowel space plot','Formant','First formant','Second formant','Vowel quadrilateral','Formant display']::text[],ARRAY['Confusing F1–F2 position with pitch or fundamental frequency','Ignoring axis reversal when reading the chart','Assuming F1 and F2 fully identify every vowel without context']::text[],ARRAY['Placing measured vowels on the vowel quadrilateral','Comparing tense and lax vowels acoustically','Teaching students how formants map to vowels']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='F1–F2 plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd922596b-0d6f-5c3b-ada7-980fb026f141','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d922596b-0d6f-5c3b-ada7-980fb026f141') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d922596b-0d6f-5c3b-ada7-980fb026f141');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ce90ab0b-a47a-5e06-8655-412ba5078447','F0 contour','A curve showing the fundamental frequency (F0) of a voiced signal as it varies over time, where F0 is the rate of vocal-fold vibration and the primary acoustic correlate of perceived pitch. Extracted by pitch-tracking algorithms such as autocorrelation or cepstral methods, the contour is plotted as frequency in hertz or semitones against time and underlies intonation, tone, and melody analysis.','An F0 contour is a line showing voice pitch over time. F0 is how fast the vocal folds vibrate each second. The faster they vibrate, the higher the pitch we hear. A computer tracks this value and draws it as a line. The rises and falls show the melody of speech or song.','It makes the pitch of the voice measurable over time, supporting the study of intonation, tone, and singing.','It is used in Praat and speech tools to study intonation, tone languages, and pitch in voice therapy or singing.','Sound Visualization & Acoustic Imaging',ARRAY['Fundamental frequency','Pitch tracking','Intonation contour','Autocorrelation','Prosody','Voicing']::text[],ARRAY['Confusing fundamental frequency with formants','Trusting octave errors from the pitch tracker as real jumps','Assuming unvoiced sounds have a defined F0']::text[],ARRAY['Tracking intonation in a spoken phrase','Analyzing tone in a tonal language','Monitoring pitch in a singing lesson']::text[],'intermediate','F0 = 1 / T0','The fundamental frequency equals one divided by the period of one vocal-fold vibration cycle.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='F0 contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ce90ab0b-a47a-5e06-8655-412ba5078447','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ce90ab0b-a47a-5e06-8655-412ba5078447') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ce90ab0b-a47a-5e06-8655-412ba5078447');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '795e291e-35fd-517d-b2ae-079bb2fd485d','Intonation contour','The pattern of fundamental-frequency movement across a phrase or sentence, visualized as a pitch curve over time that reflects linguistic intonation: the use of pitch to mark phrasing, questions, statements, focus, and emotion. It is a linguistically interpreted view of the F0 contour, emphasising rises, falls, and boundary tones over the whole utterance rather than instantaneous pitch.','An intonation contour is the tune of a whole sentence. It shows how voice pitch rises and falls as we talk. A rise at the end can mark a question. A fall can mark a finished statement. The shape also carries mood and emphasis.','It shows how pitch is used across an utterance to signal meaning, phrasing, and attitude.','It is used in linguistics and language teaching to study and train question, statement, and emphasis patterns.','Sound Visualization & Acoustic Imaging',ARRAY['F0 contour','Fundamental frequency','Prosody','Boundary tone','Prosodic contour','Pitch accent']::text[],ARRAY['Treating every pitch wiggle as meaningful intonation','Confusing intonation with lexical tone','Ignoring that voiceless gaps break the pitch line']::text[],ARRAY['Comparing question and statement melodies','Teaching intonation to language learners','Analyzing emphasis in a speech recording']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intonation contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '795e291e-35fd-517d-b2ae-079bb2fd485d','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='795e291e-35fd-517d-b2ae-079bb2fd485d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='795e291e-35fd-517d-b2ae-079bb2fd485d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c1bfc48-8b2d-5c2f-bcc7-c6e9a390fdbb','Prosodic contour','A visual representation of the prosody of speech, the suprasegmental patterns of pitch, loudness, duration, and rhythm, usually shown as combined tracks such as fundamental frequency, intensity, and segment timing aligned over time. It generalises the intonation contour by including stress and rhythmic structure, capturing how prosodic features jointly shape phrasing, emphasis, and speech melody.','A prosodic contour shows the rhythm and melody of speech together. Prosody covers pitch, loudness, length, and timing. The display lines up these tracks over time. Together they show stress, phrasing, and flow. It gives a fuller picture than pitch alone.','It brings pitch, loudness, and timing into one view so the overall prosodic shape of speech can be studied.','It is used in prosody research, text-to-speech evaluation, and clinical work on expressive speech.','Sound Visualization & Acoustic Imaging',ARRAY['Prosody','Intonation contour','F0 contour','Intensity contour','Stress','Rhythm']::text[],ARRAY['Reducing prosody to pitch alone and ignoring timing and loudness','Confusing stress with simple loudness','Assuming prosodic marks align exactly with word boundaries']::text[],ARRAY['Studying stress and rhythm in connected speech','Evaluating the naturalness of synthetic speech','Assessing expressive prosody in therapy']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Prosodic contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c1bfc48-8b2d-5c2f-bcc7-c6e9a390fdbb','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c1bfc48-8b2d-5c2f-bcc7-c6e9a390fdbb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c1bfc48-8b2d-5c2f-bcc7-c6e9a390fdbb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd0b9c604-ec74-5f34-8d3f-1aec8962688f','Voice onset time display','A visualization, usually on a waveform aligned to a spectrogram, that shows voice onset time (VOT): the interval between the release burst of a stop consonant and the onset of vocal-fold vibration for a following vowel. VOT distinguishes voicing categories such as voiced, voiceless unaspirated, and voiceless aspirated across languages; the display marks the burst and the first voicing pulse so the interval can be measured in milliseconds.','A voice onset time display shows a key gap in a stop sound. First the mouth releases a burst, as in p or b. Then the vocal folds start buzzing for the vowel. The time between these two events is voice onset time. The display marks both points so you can measure the gap.','It lets the timing between consonant release and voicing be measured, a cue that separates voicing categories across languages.','It is used in phonetics and speech pathology to measure VOT for language study and to assess disordered stop production.','Sound Visualization & Acoustic Imaging',ARRAY['Voice onset time','Plosive burst display','Voicing','Stop consonant','Aspiration','Speech spectrogram']::text[],ARRAY['Confusing the release burst with the start of voicing','Ignoring negative VOT in prevoiced stops','Measuring VOT without aligning the waveform and spectrogram']::text[],ARRAY['Measuring VOT to compare voiced and voiceless stops','Studying aspiration differences across languages','Assessing stop timing in a clinical case']::text[],'advanced','VOT = t_voice − t_release','Voice onset time equals the time of the first voicing pulse minus the time of the consonant release burst.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voice onset time display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd0b9c604-ec74-5f34-8d3f-1aec8962688f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d0b9c604-ec74-5f34-8d3f-1aec8962688f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d0b9c604-ec74-5f34-8d3f-1aec8962688f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ebbf9a4b-7501-5b27-a602-390bef6ce1e9','Voicing bar','A band of low-frequency energy near the bottom of a spectrogram, typically below roughly 300 Hz, that appears during voiced sounds and reflects periodic vocal-fold vibration, that is, the voice fundamental and its lowest harmonics. Its presence or absence during a consonant is a primary cue for whether that consonant is voiced, and it is a standard feature read when interpreting spectrograms.','A voicing bar is a dark stripe low on a spectrogram. It shows up when the vocal folds are vibrating. The stripe sits near the bottom because the voice pitch is low. If the bar is there during a consonant, the consonant is voiced. If it is missing, the consonant is voiceless.','It provides a quick visual cue that vocal-fold vibration is present, marking voiced segments on a spectrogram.','Phoneticians use the voicing bar to judge whether stops and fricatives are voiced when reading spectrograms.','Sound Visualization & Acoustic Imaging',ARRAY['Voicing','Speech spectrogram','Fundamental frequency','Voice onset time display','Voiced consonant','Glottal pulse']::text[],ARRAY['Confusing the voicing bar with the first formant','Assuming its absence always means a voiceless sound rather than weak voicing','Overlooking it when the spectrogram is poorly contrasted']::text[],ARRAY['Deciding if a stop is voiced from a spectrogram','Teaching students to read voicing','Checking voicing in a recorded fricative']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voicing bar');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ebbf9a4b-7501-5b27-a602-390bef6ce1e9','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ebbf9a4b-7501-5b27-a602-390bef6ce1e9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ebbf9a4b-7501-5b27-a602-390bef6ce1e9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cc6e21e0-04f2-566b-b09a-68eb281b3b14','Voiceprint analysis','The examination and comparison of speech spectrograms, historically called voiceprints, to characterise or attempt to identify a speaker from the acoustic patterns of their speech. It relies on visible spectral features such as formants, pitch, and timing; modern forensic phonetics treats purely visual spectrogram matching as unreliable on its own and favours combined acoustic-phonetic and statistical methods, so results must be interpreted with strong caution.','Voiceprint analysis compares speech pictures called spectrograms. The idea is that a person''s speech leaves visible patterns. Analysts look at formants, pitch, and timing to compare voices. By eye alone, this matching is not reliable. Experts warn it should not stand on its own in court.','It aims to describe or compare speakers from visible speech patterns, mainly in forensic and security contexts.','It appears in forensic speech comparison, where it is used cautiously alongside rigorous acoustic and statistical analysis.','Sound Visualization & Acoustic Imaging',ARRAY['Speech spectrogram','Formant','Forensic phonetics','Speaker identification','Fundamental frequency','Spectrographic analysis']::text[],ARRAY['Treating visual voiceprint matching as reliable proof of a speaker''s identity','Assuming a voice is as unique and fixed as a fingerprint','Ignoring how recording quality and channel change the spectrogram']::text[],ARRAY['Comparing two recordings in a forensic case','Explaining the limits of voiceprint evidence','Reviewing spectrograms of a questioned speaker']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Voiceprint analysis');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cc6e21e0-04f2-566b-b09a-68eb281b3b14','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cc6e21e0-04f2-566b-b09a-68eb281b3b14') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cc6e21e0-04f2-566b-b09a-68eb281b3b14');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '74306b04-ec5a-59a4-b294-2f6e1d8f71ee','Sibilance band display','A spectral display that focuses on the high-frequency energy region of sibilant consonants such as /s/, /z/, /ʃ/, and /ʒ/, typically the range from a few kilohertz up to around 10 kHz or above, where turbulent airflow produces intense fricative noise. In production it guides de-essing by showing where sibilant energy peaks; in phonetics it helps distinguish sibilant place of articulation from the shape and centre of gravity of the noise spectrum.','A sibilance band display highlights the hiss in speech. Sounds like s and sh make strong high-pitched noise. The display zooms in on that high band. Engineers use it to find harsh s sounds. Reducing energy there is called de-essing.','It isolates the high-frequency noise of sibilants so it can be measured or tamed.','Audio engineers use it to set de-essers, and phoneticians use it to study sibilant consonants.','Sound Visualization & Acoustic Imaging',ARRAY['Sibilance','De-esser','Fricative noise','Speech spectrogram','Spectral centre of gravity','High-frequency energy']::text[],ARRAY['Confusing sibilant noise with normal vocal harmonics','De-essing too hard and dulling the voice','Assuming all sibilants share the same frequency band']::text[],ARRAY['Setting a de-esser on a vocal track','Studying /s/ versus /ʃ/ in phonetics','Checking harsh sibilance before mastering']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sibilance band display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '74306b04-ec5a-59a4-b294-2f6e1d8f71ee','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='74306b04-ec5a-59a4-b294-2f6e1d8f71ee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='74306b04-ec5a-59a4-b294-2f6e1d8f71ee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '417a49ae-d4ab-571a-a8da-e924b9fb0b69','Plosive burst display','A view, on a waveform and spectrogram, that shows the brief transient release of a plosive (stop) consonant: the burst of noise produced when the oral closure is released and built-up pressure escapes. The burst appears as a short vertical spike with a characteristic spectral shape that varies with place of articulation, and it marks the moment of release used for segmenting stops and measuring voice onset time.','A plosive burst display shows the pop of a stop sound. Sounds like p, t, and k block the air, then release it. That release makes a short burst of noise. On the display it looks like a thin spike. Its shape hints at where in the mouth the stop was made.','It pinpoints the release moment and spectral shape of stop bursts for segmentation and analysis.','It is used to mark stop releases, measure voice onset time, and help identify place of articulation.','Sound Visualization & Acoustic Imaging',ARRAY['Plosive','Stop consonant','Voice onset time display','Speech spectrogram','Transient','Place of articulation']::text[],ARRAY['Confusing the burst with the following vowel onset','Missing weak bursts in unreleased stops','Reading place of articulation from the burst without other cues']::text[],ARRAY['Marking a stop release for VOT measurement','Distinguishing /p/, /t/, and /k/ bursts','Segmenting stops in connected speech']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Plosive burst display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '417a49ae-d4ab-571a-a8da-e924b9fb0b69','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='417a49ae-d4ab-571a-a8da-e924b9fb0b69') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='417a49ae-d4ab-571a-a8da-e924b9fb0b69');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ef8c2a84-686a-5e85-84fe-01573b27d645','Nasal murmur display','A spectrographic view highlighting the nasal murmur, the low-frequency resonant energy radiated through the nose during nasal consonants such as /m/, /n/, and /ŋ/. With the oral tract closed and the velopharyngeal port open, the display shows a strong low-frequency band, often near 250 to 300 Hz, weak higher energy, and characteristic anti-resonances (zeros) that reflect the side-branching of the nasal and oral cavities.','A nasal murmur display shows the hum of nasal sounds. In m or n, the mouth is closed and air flows through the nose. This makes a strong low hum with little high energy. The display shows that low band clearly. Gaps called anti-resonances also appear.','It reveals the low-frequency resonance and anti-resonances that mark nasal consonants on a spectrogram.','It is used to identify nasals, study nasalization, and assess nasal speech in clinical work.','Sound Visualization & Acoustic Imaging',ARRAY['Nasal consonant','Anti-resonance','Nasalization','Speech spectrogram','Formant','Velopharyngeal port']::text[],ARRAY['Confusing the nasal murmur with a voicing bar','Ignoring anti-resonances that weaken higher energy','Assuming all nasals look identical on the spectrogram']::text[],ARRAY['Identifying a nasal consonant on a spectrogram','Studying nasalization of nearby vowels','Assessing hypernasal or hyponasal speech']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Nasal murmur display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ef8c2a84-686a-5e85-84fe-01573b27d645','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ef8c2a84-686a-5e85-84fe-01573b27d645') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ef8c2a84-686a-5e85-84fe-01573b27d645');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f6d246c-ce99-5a55-973d-9c61fd1d9e02','Harmonic-to-noise visualization','A display of the harmonic-to-noise ratio (HNR), the ratio of periodic (harmonic) energy to aperiodic (noise) energy in a voiced signal, usually expressed in decibels and plotted over time. High HNR indicates clear, well-organised vocal-fold vibration, while low HNR indicates breathiness or hoarseness. It is a standard acoustic measure of voice quality computed from autocorrelation or cepstral estimates of periodicity.','This display shows how clean a voice is. A steady voice has strong, regular vibration, called harmonic energy. A rough or breathy voice adds more noise. The harmonic-to-noise ratio compares these two amounts. A high value means a clear voice. A low value means a breathy or hoarse voice.','It quantifies how much of the voice is regular vibration versus noise, giving a measure of voice quality.','Voice clinicians and researchers use HNR in Praat to track hoarseness, breathiness, and therapy progress.','Sound Visualization & Acoustic Imaging',ARRAY['Harmonic-to-noise ratio','Voice quality','Jitter plot','Shimmer plot','Cepstral peak prominence display','Autocorrelation']::text[],ARRAY['Confusing harmonic-to-noise ratio with the signal-to-noise ratio of a recording','Comparing HNR across different pitches or vowels without care','Assuming one HNR value captures all voice quality']::text[],ARRAY['Measuring hoarseness in a clinical voice sample','Tracking voice therapy progress','Comparing voice quality between vowels']::text[],'advanced','HNR = 10·log10(E_harmonic / E_noise) dB','The harmonic-to-noise ratio in decibels equals ten times the base-ten logarithm of the harmonic energy divided by the noise energy.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic-to-noise visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f6d246c-ce99-5a55-973d-9c61fd1d9e02','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f6d246c-ce99-5a55-973d-9c61fd1d9e02') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f6d246c-ce99-5a55-973d-9c61fd1d9e02');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ff83a2ed-ac5e-59ae-ab7c-5e33aa0e9b17','Jitter plot','A visualization of jitter, the short-term, cycle-to-cycle variation in the fundamental period (or frequency) of a voiced signal, often shown as per-cycle period deviations over time or as a summary metric. Jitter reflects instability in vocal-fold vibration and is a standard perturbation measure of voice quality, commonly expressed as local jitter, the mean absolute difference between consecutive periods normalised by the mean period.','A jitter plot shows tiny timing wobble in the voice. Each vibration cycle should last almost the same time. In practice the length changes a little cycle to cycle. Jitter measures that small change in timing. More jitter often sounds rough or unsteady.','It measures the tiny period-to-period timing instability of the voice as a marker of vocal roughness.','It is used in voice clinics with tools such as Praat to assess and track vocal roughness and disorders.','Sound Visualization & Acoustic Imaging',ARRAY['Jitter','Shimmer plot','Fundamental frequency','Voice quality','Perturbation','Harmonic-to-noise visualization']::text[],ARRAY['Comparing jitter across recordings with different pitch-tracking settings','Confusing jitter (timing) with shimmer (amplitude)','Treating a single jitter value as a full diagnosis']::text[],ARRAY['Assessing vocal roughness in a clinic','Tracking jitter before and after therapy','Screening a voice for instability']::text[],'advanced','jitter_local = mean|T_i − T_{i+1}| / mean(T_i)','Local jitter equals the average absolute difference between consecutive vocal periods divided by the average period.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Jitter plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ff83a2ed-ac5e-59ae-ab7c-5e33aa0e9b17','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ff83a2ed-ac5e-59ae-ab7c-5e33aa0e9b17') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ff83a2ed-ac5e-59ae-ab7c-5e33aa0e9b17');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9906b65d-aae0-5276-9a2f-285c9ba91d04','Shimmer plot','A visualization of shimmer, the short-term, cycle-to-cycle variation in the peak amplitude of a voiced signal, shown as per-cycle amplitude deviations over time or as a summary value. Shimmer reflects amplitude instability of vocal-fold vibration and is a standard perturbation measure of voice quality, commonly expressed as local shimmer, the mean absolute difference between consecutive cycle amplitudes normalised by the mean amplitude, often in decibels.','A shimmer plot shows loudness wobble in the voice. Each vibration cycle should reach about the same strength. In practice the strength changes slightly cycle to cycle. Shimmer measures that small change in loudness. More shimmer often sounds breathy or rough.','It measures the tiny cycle-to-cycle amplitude instability of the voice as a marker of vocal quality.','It is used with jitter and HNR in voice clinics to assess breathiness and roughness.','Sound Visualization & Acoustic Imaging',ARRAY['Shimmer','Jitter plot','Voice quality','Amplitude perturbation','Harmonic-to-noise visualization','Fundamental frequency']::text[],ARRAY['Confusing shimmer (amplitude) with jitter (timing)','Comparing shimmer across different recording levels','Assuming shimmer alone identifies a specific disorder']::text[],ARRAY['Assessing breathiness in a voice sample','Combining shimmer with jitter and HNR','Tracking amplitude stability during therapy']::text[],'advanced','shimmer_local = mean|A_i − A_{i+1}| / mean(A_i)','Local shimmer equals the average absolute difference between consecutive cycle amplitudes divided by the average amplitude.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Shimmer plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9906b65d-aae0-5276-9a2f-285c9ba91d04','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9906b65d-aae0-5276-9a2f-285c9ba91d04') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9906b65d-aae0-5276-9a2f-285c9ba91d04');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7634ae2e-582d-5930-b4a7-e7e81a6559d5','Cepstral peak prominence display','A voice-analysis display based on the cepstrum, showing cepstral peak prominence (CPP): the height of the dominant cepstral peak, which corresponds to the signal''s periodicity, above a regression line fitted through the cepstrum at that quefrency. A higher, more prominent peak means stronger harmonic organisation; CPP is a robust acoustic measure of voice quality and dysphonia that, unlike jitter and shimmer, does not require explicit cycle-by-cycle pitch extraction.','This display measures how strongly a voice is periodic. A clear voice has a strong repeating pattern. In the cepstrum, that pattern shows up as one tall peak. Cepstral peak prominence is how far that peak rises above the background. A taller peak means a healthier, clearer voice.','It gauges the strength of voice periodicity without cycle-by-cycle pitch tracking, giving a robust voice-quality measure.','It is widely used clinically to quantify dysphonia and breathiness, including in connected speech.','Sound Visualization & Acoustic Imaging',ARRAY['Cepstrum','Cepstral peak prominence','Voice quality','Harmonic-to-noise visualization','Dysphonia','Quefrency']::text[],ARRAY['Confusing the cepstrum with the spectrum','Assuming CPP needs an accurate pitch track like jitter does','Comparing CPP across different analysis settings without care']::text[],ARRAY['Quantifying dysphonia from a voice sample','Measuring voice quality in connected speech','Tracking CPP over a course of therapy']::text[],'advanced','CPP = C(q_peak) − (a·q_peak + b)','Cepstral peak prominence equals the cepstral peak value minus the value of the least-squares regression line through the cepstrum at the peak''s quefrency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cepstral peak prominence display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7634ae2e-582d-5930-b4a7-e7e81a6559d5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7634ae2e-582d-5930-b4a7-e7e81a6559d5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7634ae2e-582d-5930-b4a7-e7e81a6559d5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb0359fb-eeb7-5b86-a18d-c4098939c705','EQ curve','A graphical plot of an equalizer''s gain in decibels versus frequency, showing how much each part of the audio spectrum is boosted or cut. It represents the equalizer''s magnitude frequency response, combining the individual band filters such as bells, shelves, high-pass and low-pass into one overall curve. The horizontal axis is usually logarithmic frequency and the vertical axis is gain in decibels.','An EQ curve is a line showing how an equalizer changes each frequency. The bottom axis runs from low to high frequencies. The side axis shows boost or cut in decibels. A hump means those frequencies are made louder. A dip means they are made quieter.','It shows at a glance how an equalizer reshapes the balance of frequencies in a signal.','Engineers read and draw EQ curves in every DAW and hardware equalizer to shape tone.','Sound Visualization & Acoustic Imaging',ARRAY['Equalizer','Filter curve','Frequency response','Shelving filter','Parametric equalizer','Gain']::text[],ARRAY['Reading the curve on a linear frequency axis instead of logarithmic','Assuming the drawn curve ignores the phase changes it also causes','Confusing a boost with new content rather than amplified existing content']::text[],ARRAY['Shaping a vocal''s tone in a mix','Cutting a resonant frequency on a drum','Matching two tracks'' tone with EQ']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='EQ curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb0359fb-eeb7-5b86-a18d-c4098939c705','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb0359fb-eeb7-5b86-a18d-c4098939c705') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb0359fb-eeb7-5b86-a18d-c4098939c705');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7f98d57c-3a3a-5340-a6f6-a2aea9df3b36','Filter curve','A plot of a filter''s magnitude response versus frequency, showing how the filter passes, attenuates, or shapes different frequency regions. Common shapes include high-pass, low-pass, band-pass, notch, shelving, bell (peaking), and crossover responses. The curve reveals the cutoff or centre frequency, the slope or roll-off in decibels per octave, and any resonance peak at the cutoff.','A filter curve shows how a filter treats each frequency. Some frequencies pass through freely. Others are turned down or blocked. The curve shows where the filter starts to cut and how steeply. A bump at the corner is called resonance.','It visualizes which frequencies a filter keeps or removes and how sharply it does so.','Engineers use filter curves to set high-pass, low-pass, and notch filters in mixing and system tuning.','Sound Visualization & Acoustic Imaging',ARRAY['Filter','EQ curve','Cutoff frequency','Roll-off','High-pass filter','Resonance']::text[],ARRAY['Confusing the cutoff frequency with the point of full attenuation','Ignoring the filter''s phase shift near cutoff','Assuming a steeper slope is always better']::text[],ARRAY['Setting a high-pass filter to remove rumble','Notching out feedback in a live system','Choosing a filter slope for a crossover']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Filter curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7f98d57c-3a3a-5340-a6f6-a2aea9df3b36','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7f98d57c-3a3a-5340-a6f6-a2aea9df3b36') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7f98d57c-3a3a-5340-a6f6-a2aea9df3b36');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '51eea651-5bda-514f-aded-286d0c6f9088','Crossover response plot','A visualization of the frequency responses of the individual output bands of an audio crossover, showing how the signal is split between drivers such as woofer, midrange, and tweeter, and how their responses overlap around the crossover frequencies. It displays each band''s roll-off slope and the crossover point, and ideally how the bands sum to a flat combined response through the crossover region.','A crossover response plot shows how sound is split between speakers. Low sounds go to the woofer and high sounds to the tweeter. The plot shows where each driver takes over. It also shows how their curves overlap at the handover. Good overlap means the bands add up smoothly.','It shows how a crossover divides the spectrum between drivers and whether their bands combine smoothly.','It is used when designing or tuning loudspeakers and setting crossover points in system processors.','Sound Visualization & Acoustic Imaging',ARRAY['Crossover','Filter curve','Roll-off','Loudspeaker driver','Frequency response','Crossover frequency']::text[],ARRAY['Ignoring how band overlap and phase affect the summed response','UNSAFE: setting a crossover point that sends damaging low frequencies to a tweeter','Assuming steeper slopes always sum better']::text[],ARRAY['Tuning a two-way loudspeaker crossover','Setting crossover points in a system processor','Checking driver overlap in speaker design']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crossover response plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '51eea651-5bda-514f-aded-286d0c6f9088','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='51eea651-5bda-514f-aded-286d0c6f9088') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='51eea651-5bda-514f-aded-286d0c6f9088');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '546130b9-04f2-5007-8661-43861e5c3fcf','Group-delay trace','A plot of group delay versus frequency, where group delay is the negative derivative of a system''s phase response with respect to angular frequency and represents the time delay experienced by the envelope of a narrow band of frequencies. It reveals frequency-dependent time smearing introduced by filters, crossovers, and processing; a flat group delay means all frequencies are delayed equally, while variations indicate phase distortion.','A group-delay trace shows how long each frequency is delayed. Some systems hold back certain frequencies more than others. This plot shows that delay across the spectrum. A flat line means every frequency is delayed the same. Bumps mean some frequencies arrive late, smearing the sound.','It exposes frequency-dependent delay so engineers can spot phase distortion and time smearing.','It is used to evaluate filters, crossovers, and loudspeakers for audible time smearing.','Sound Visualization & Acoustic Imaging',ARRAY['Group delay','Phase response','Filter curve','Phase distortion','Crossover response plot','Linear phase']::text[],ARRAY['Confusing group delay with a single fixed latency','Assuming any group-delay variation is always audible','Ignoring that steep filters add group delay near cutoff']::text[],ARRAY['Checking a crossover for phase distortion','Comparing linear-phase and minimum-phase EQ','Evaluating a loudspeaker''s time behaviour']::text[],'advanced','τ_g(ω) = − dφ(ω)/dω','Group delay at a given frequency equals the negative slope of the phase response with respect to angular frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Group-delay trace');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '546130b9-04f2-5007-8661-43861e5c3fcf','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='546130b9-04f2-5007-8661-43861e5c3fcf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='546130b9-04f2-5007-8661-43861e5c3fcf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '106e6733-3975-5b7c-858e-e08ade9f3d1b','Spectral balance display','A visualization showing how a signal''s energy is distributed across the frequency spectrum, typically as a long-term average spectrum or averaged FFT that reveals the relative levels of low, mid, and high frequencies. It is used to judge overall tonal balance rather than moment-to-moment detail, helping engineers see whether a mix or master is, for example, bass-heavy or bright.','A spectral balance display shows how energy spreads across pitch ranges. It averages the sound over time into one shape. You can see if lows, mids, or highs dominate. A tilt toward the low end looks bass-heavy. A tilt toward the high end looks bright.','It summarises the long-term tonal balance of a signal so overall spectral tilt can be judged.','Mixing and mastering engineers use it to compare a mix''s balance against reference tracks.','Sound Visualization & Acoustic Imaging',ARRAY['Tonal balance curve','Long-term average spectrum','Spectrum analyzer','Spectral tilt','Frequency response','Reference track']::text[],ARRAY['Judging balance from a momentary spectrum instead of an average','Ignoring how genre changes the ideal balance','Chasing a flat spectrum as if it were the goal']::text[],ARRAY['Comparing a mix''s balance to a reference track','Checking spectral tilt during mastering','Spotting a buildup in one frequency range']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral balance display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '106e6733-3975-5b7c-858e-e08ade9f3d1b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='106e6733-3975-5b7c-858e-e08ade9f3d1b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='106e6733-3975-5b7c-858e-e08ade9f3d1b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd136caa3-fe59-5052-b6ab-9d38be7b7bba','Tonal balance curve','A curve representing the target or measured distribution of spectral energy across frequency for a mix or master, often compared against genre-based reference targets to guide tonal decisions. It is a smoothed long-term spectral shape; matching a track''s tonal balance curve to a target helps ensure the low, mid, and high energy sit within norms for a style and translate well across playback systems.','A tonal balance curve shows the overall tone shape of a track. It smooths the spectrum into one broad line. Engineers compare it to a target for the genre. If the low end is too strong, the curve shows it. This helps a mix sound right on many systems.','It guides tonal decisions by comparing a track''s broad spectral shape to reference targets.','Mastering engineers use tonal balance curves in analyzer plug-ins to match genre norms and improve translation.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral balance display','Long-term average spectrum','Mastering','Reference track','Spectral tilt','Frequency response']::text[],ARRAY['Treating a target curve as a strict rule for every song','Matching a curve while ignoring how the mix sounds','Comparing to a target built from a different genre']::text[],ARRAY['Matching a master to a genre target','Checking low-end weight during mastering','Improving translation across playback systems']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonal balance curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd136caa3-fe59-5052-b6ab-9d38be7b7bba','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d136caa3-fe59-5052-b6ab-9d38be7b7bba') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d136caa3-fe59-5052-b6ab-9d38be7b7bba');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '33a1ea2f-16b5-56aa-8b11-c457253e5955','Masking display','A visualization of auditory masking, showing where a louder or spectrally close sound is likely to render another sound inaudible, based on psychoacoustic masking thresholds across frequency and time. It overlays signals or estimates masking thresholds so an engineer can see frequency regions where one track hides another, drawing on the simultaneous (frequency-domain) and temporal (time-domain) masking properties of hearing.','A masking display shows where one sound hides another. A loud sound can cover a softer nearby sound. The display marks those risky regions by frequency. It uses known facts about how hearing works. Engineers use it to see why a part is getting buried.','It reveals where masking may hide one sound behind another so mixes can be made clearer.','It helps engineers find and fix frequency clashes where one instrument buries another.','Sound Visualization & Acoustic Imaging',ARRAY['Auditory masking','Psychoacoustics','Collision map','Frequency-slotting display','Masking threshold','Critical band']::text[],ARRAY['Confusing spectral overlap with actual perceptual masking','Ignoring temporal masking around loud transients','Assuming the display replaces careful listening']::text[],ARRAY['Finding why a guitar buries the vocal','Carving space between the bass and kick','Checking masking before committing a mix']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Masking display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '33a1ea2f-16b5-56aa-8b11-c457253e5955','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='33a1ea2f-16b5-56aa-8b11-c457253e5955') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='33a1ea2f-16b5-56aa-8b11-c457253e5955');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37e042ea-4ada-5d98-a69a-981afba9d2ea','Collision map','A production-oriented visualization that highlights frequency regions where two or more instruments overlap and compete for the same spectral space, indicating potential masking or muddiness. Often shown as overlaid or intersecting spectra, it flags collisions where sources share energy so the engineer can decide where to equalize, pan, or re-arrange to separate them.','A collision map shows where instruments fight for the same frequencies. When two parts share a range, they can clash. The map marks those overlap zones. Engineers then cut one part there to make room. This keeps the mix from sounding muddy.','It flags frequency overlaps between sources so an engineer can separate them in the mix.','It guides EQ and arrangement choices to reduce masking between competing instruments.','Sound Visualization & Acoustic Imaging',ARRAY['Masking display','Frequency-slotting display','Auditory masking','Equalizer','Spectrum analyzer','Frequency overlap']::text[],ARRAY['Treating every overlap as a problem to remove','Cutting both parts and thinning the mix','Relying on the map instead of listening in context']::text[],ARRAY['Spotting a bass and kick clash','Deciding where to EQ competing guitars','Planning an arrangement to avoid overlap']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Collision map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37e042ea-4ada-5d98-a69a-981afba9d2ea','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37e042ea-4ada-5d98-a69a-981afba9d2ea') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37e042ea-4ada-5d98-a69a-981afba9d2ea');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '56c479ba-1f18-5930-a938-48f71db9aa14','Frequency-slotting display','A visualization supporting frequency slotting, the mixing practice of assigning each instrument its own dominant frequency region so sources occupy complementary parts of the spectrum. It shows the spectral footprint of multiple tracks together, helping the engineer carve non-overlapping slots with EQ so each element stays audible without masking the others.','A frequency-slotting display helps give each part its own space. The idea is that instruments should not all crowd one range. The display shows where each track sits in the spectrum. Engineers then place each part in its own slot. This keeps every element clear.','It supports carving complementary frequency slots so instruments do not mask each other.','Engineers use it to plan EQ so bass, guitars, and vocals each own a clear range.','Sound Visualization & Acoustic Imaging',ARRAY['Frequency slotting','Collision map','Masking display','Equalizer','Complementary EQ','Spectrum analyzer']::text[],ARRAY['Slotting so aggressively that instruments sound thin','Ignoring that parts move in frequency over time','Forgetting that level and panning also create separation']::text[],ARRAY['Planning EQ slots for a dense arrangement','Separating two similar synths','Keeping vocals clear over a busy track']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency-slotting display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '56c479ba-1f18-5930-a938-48f71db9aa14','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='56c479ba-1f18-5930-a938-48f71db9aa14') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='56c479ba-1f18-5930-a938-48f71db9aa14');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'dfa9ae6b-eca3-52cb-be3c-45086c5bede8','Harmonic stack display','A visualization of a sound''s harmonic series, showing the fundamental frequency and its overtones stacked at integer multiples of the fundamental. Presented as a set of vertical lines or spectral peaks, it reveals which harmonics are present and their relative strengths, illustrating how the harmonic content shapes timbre for pitched, harmonic sounds.','A harmonic stack display shows the layers inside a pitched note. The lowest tone is the fundamental. Above it sit overtones at whole-number multiples. The display stacks these as a row of lines. Their pattern of strength gives the sound its character.','It shows the harmonic makeup of a pitched sound so its timbre and tuning can be understood.','It is used in synthesis, tuning, and analysis to see which harmonics build a sound''s tone.','Sound Visualization & Acoustic Imaging',ARRAY['Harmonic series','Overtone ladder','Fundamental frequency','Timbre','Spectrum analyzer','Partial']::text[],ARRAY['Confusing harmonics with unrelated inharmonic partials','Assuming every sound has strong harmonics','Mistaking a strong overtone for the fundamental']::text[],ARRAY['Studying a synth patch''s harmonics','Explaining timbre in a lesson','Checking the harmonic content of an instrument']::text[],'intermediate','f_n = n·f0,  n = 1, 2, 3, …','The nth harmonic frequency equals the harmonic number n times the fundamental frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic stack display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'dfa9ae6b-eca3-52cb-be3c-45086c5bede8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='dfa9ae6b-eca3-52cb-be3c-45086c5bede8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='dfa9ae6b-eca3-52cb-be3c-45086c5bede8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '83165c93-6aff-5941-a9bb-10f873003781','Overtone ladder','An educational visualization of the harmonic (overtone) series presented as a ladder of ascending steps, each rung marking a harmonic at an integer multiple of the fundamental frequency. It illustrates how overtones stack above a fundamental and how their spacing relates to musical intervals, making the structure of the harmonic series visible for teaching.','An overtone ladder draws the harmonic series as rungs. The bottom rung is the fundamental tone. Each rung above is a whole-number multiple of it. The rungs get closer together in pitch as they rise. It helps students picture how overtones stack up.','It presents the harmonic series in a simple stepped form to teach how overtones relate to a fundamental.','It is used in music education to explain harmonics, intervals, and timbre.','Sound Visualization & Acoustic Imaging',ARRAY['Harmonic series','Harmonic stack display','Fundamental frequency','Overtone','Musical interval','Partial']::text[],ARRAY['Assuming the rungs are equally spaced in pitch','Confusing overtone number directly with a musical interval','Thinking real instruments follow the ideal ladder exactly']::text[],ARRAY['Teaching the harmonic series to students','Relating overtones to musical intervals','Introducing timbre in a classroom']::text[],'beginner','f_n = n·f0,  n = 1, 2, 3, …','The nth overtone frequency equals the harmonic number n times the fundamental frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Overtone ladder');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '83165c93-6aff-5941-a9bb-10f873003781','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='83165c93-6aff-5941-a9bb-10f873003781') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='83165c93-6aff-5941-a9bb-10f873003781');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42f3ef42-00c0-52fa-8df0-ea1053e0db57','Pitch-class profile','A representation, also called a chroma feature or chromagram, that collapses spectral energy into the twelve pitch classes of the equal-tempered octave by summing the energy of all frequencies that share the same pitch class regardless of octave. Plotted as a twelve-dimensional vector over time, it captures harmonic and melodic content in an octave-invariant way and underpins chord recognition, key detection, and music similarity analysis.','A pitch-class profile sorts sound energy into twelve note names. It ignores which octave a note is in. All the C notes add together, all the C-sharps add together, and so on. The result is twelve values, one per note name. It is widely used to find chords and keys.','It reduces audio to octave-independent pitch-class energy, enabling chord, key, and harmony analysis.','It is a core feature in music software for chord recognition, key detection, and song matching.','Sound Visualization & Acoustic Imaging',ARRAY['Chroma feature','Chromagram','Pitch class','Chord recognition','Key detection','Constant-Q transform']::text[],ARRAY['Confusing pitch class with pitch height, that is, the octave','Assuming it identifies exact notes and octaves','Ignoring that tuning and overtones blur the classes']::text[],ARRAY['Detecting chords in a song','Estimating the musical key','Measuring harmonic similarity between tracks']::text[],'advanced','C(b) = Σ_{k: pc(k)=b} |X(k)|²,  b = 0…11','The chroma value for a pitch class equals the sum of the spectral energy of all frequency bins that map to that pitch class, across every octave.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pitch-class profile');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42f3ef42-00c0-52fa-8df0-ea1053e0db57','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42f3ef42-00c0-52fa-8df0-ea1053e0db57') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42f3ef42-00c0-52fa-8df0-ea1053e0db57');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a91aea7-863d-5fa3-968f-552fe812a382','Piano-roll display','A pitch-versus-time visualization in which notes are drawn as horizontal bars, with vertical position giving pitch, often aligned to a piano keyboard, and bar length giving duration. Common in MIDI sequencers and in transcription and pitch-detection tools, it shows note pitch, timing, duration, and sometimes velocity, providing an editable, score-like view of musical events.','A piano-roll display shows notes as bars on a grid. Height on the grid sets the pitch, like keys on a piano. The length of each bar sets how long the note lasts. Time runs left to right. Musicians use it to see and edit their notes.','It presents musical notes in an editable pitch-and-time grid for viewing, transcription, and editing.','It is the standard MIDI editing view in DAWs and appears in transcription tools.','Sound Visualization & Acoustic Imaging',ARRAY['MIDI','Note event visualization','Pitch detection','Sequencer','Velocity','Transcription']::text[],ARRAY['Confusing MIDI note bars with recorded audio waveforms','Assuming bar height shows loudness rather than pitch','Forgetting that velocity is separate from bar length']::text[],ARRAY['Editing a MIDI melody in a DAW','Viewing notes transcribed from audio','Quantizing note timing']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Piano-roll display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a91aea7-863d-5fa3-968f-552fe812a382','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a91aea7-863d-5fa3-968f-552fe812a382') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a91aea7-863d-5fa3-968f-552fe812a382');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1233e0de-7747-57db-8655-1110cd97907f','Note event visualization','A display of discrete musical note events detected or sequenced from audio or MIDI, showing each note''s onset time, pitch, duration, and often velocity or intensity. Used in transcription, MIDI editing, and music information retrieval, it turns continuous audio or event streams into a symbolic, note-level picture that can be edited or analysed.','A note event visualization shows music as separate notes. Each note has a start time and a pitch. It also has a length and often a strength. The display draws these as marks or bars. This turns sound into a clear list of notes.','It presents music at the level of individual note events for editing and analysis.','It is used in transcription, MIDI editing, and automatic music analysis tools.','Sound Visualization & Acoustic Imaging',ARRAY['Piano-roll display','Onset map','MIDI','Note onset','Transcription','Velocity']::text[],ARRAY['Trusting detected notes without checking against the audio','Confusing a note onset with a note peak','Assuming detection catches every note in dense music']::text[],ARRAY['Reviewing notes from automatic transcription','Editing detected notes in an editor','Analyzing a melody''s note pattern']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Note event visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1233e0de-7747-57db-8655-1110cd97907f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1233e0de-7747-57db-8655-1110cd97907f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1233e0de-7747-57db-8655-1110cd97907f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ca97d8c1-fe58-5ed4-bd03-5a735ecfcf38','Onset map','A visualization of detected note onsets, the moments where new notes or percussive events begin, usually shown as markers or an onset-strength (detection) function aligned to a waveform or spectrogram over time. Onset detection locates sudden increases in energy or spectral change; the map is used for beat tracking, transcription, and rhythmic analysis.','An onset map marks where new notes or hits begin. Each new sound usually starts with a quick jump in energy. The map places a marker at each of these starts. It lines up with the waveform in time. It is used to find beats and rhythm.','It shows where musical events begin so timing, rhythm, and beats can be analysed.','It supports beat tracking, tempo estimation, and transcription in music software.','Sound Visualization & Acoustic Imaging',ARRAY['Note onset','Onset detection function','Beat tracking','Transient','Note event visualization','Tempo curve']::text[],ARRAY['Confusing an onset with a note''s loudest point','Missing soft onsets in legato passages','Treating every energy bump as a real onset']::text[],ARRAY['Finding beats for tempo detection','Aligning transcription to note starts','Analyzing rhythm in a performance']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Onset map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ca97d8c1-fe58-5ed4-bd03-5a735ecfcf38','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ca97d8c1-fe58-5ed4-bd03-5a735ecfcf38') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ca97d8c1-fe58-5ed4-bd03-5a735ecfcf38');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a50cc976-6298-540c-83c0-28f09d6a0f07','Tempo curve','A plot of tempo, in beats per minute, against time, showing how the speed of a piece of music changes over its course. Derived from beat or onset tracking, it reveals expressive timing such as ritardando and accelerando as well as steady sections; the curve captures tempo fluctuation rather than assuming a single fixed tempo.','A tempo curve shows how fast the music goes over time. Speed is measured in beats per minute. The line rises when the music speeds up. It falls when the music slows down. A flat line means a steady tempo.','It reveals how musical tempo changes over time, capturing expressive speeding up and slowing down.','It is used in beat tracking, performance analysis, and aligning audio to a grid.','Sound Visualization & Acoustic Imaging',ARRAY['Tempo','Beat tracking','Onset map','Beats per minute','Ritardando','Rhythm']::text[],ARRAY['Assuming music holds one fixed tempo throughout','Trusting tempo estimates through weak or syncopated beats','Confusing tempo changes with meter changes']::text[],ARRAY['Studying expressive timing in a performance','Tracking tempo drift in a live recording','Aligning audio to a click grid']::text[],'intermediate','tempo (BPM) = 60 / T_beat','The tempo in beats per minute equals sixty divided by the beat period measured in seconds.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tempo curve');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a50cc976-6298-540c-83c0-28f09d6a0f07','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a50cc976-6298-540c-83c0-28f09d6a0f07') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a50cc976-6298-540c-83c0-28f09d6a0f07');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b5f74bbf-7e3d-59e2-8c2f-7e10ebcd7aeb','LUFS trace','A time plot of loudness measured in LUFS (loudness units relative to full scale), following the ITU-R BS.1770 and EBU R128 method of K-weighting the signal, mean-square measuring it, and gating quiet passages. Typically shown as momentary or short-term loudness over time, the trace lets engineers see how perceived loudness evolves and check compliance with loudness targets for broadcast and streaming.','A LUFS trace shows how loud audio feels over time. LUFS is a loudness scale used for broadcast and streaming. The meter follows a standard method that matches human hearing. The line rises and falls with perceived loudness. Engineers use it to hit a loudness target.','It tracks standardised, hearing-weighted loudness over time so content can meet delivery targets.','It is used in broadcast and streaming mastering to meet loudness rules and check level over time.','Sound Visualization & Acoustic Imaging',ARRAY['LUFS','Loudness','True-peak trace','Loudness normalization','K-weighting','Integrated loudness']::text[],ARRAY['Confusing LUFS loudness with sample peak level','Ignoring the gating and averaging behind the number','Chasing momentary values instead of integrated loudness']::text[],ARRAY['Mastering a podcast to a loudness target','Checking a mix against broadcast rules','Comparing loudness across streaming platforms']::text[],'intermediate','L_K = −0.691 + 10·log10( Σ_i G_i · z_i )  LUFS','The K-weighted loudness in LUFS equals minus 0.691 plus ten times the base-ten logarithm of the sum over channels of each channel''s weighting times its mean-square K-weighted level.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='LUFS trace');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b5f74bbf-7e3d-59e2-8c2f-7e10ebcd7aeb','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b5f74bbf-7e3d-59e2-8c2f-7e10ebcd7aeb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b5f74bbf-7e3d-59e2-8c2f-7e10ebcd7aeb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f720a705-961f-55ed-9a5c-abcfb2fd9bae','True-peak trace','A time display of true-peak level, the maximum level of the reconstructed analogue waveform estimated by oversampling the digital signal, expressed in dBTP (decibels true peak). Because inter-sample peaks can exceed the highest sample value, the true-peak trace shows peaks a simple sample-peak meter would miss, and it is used to prevent clipping in downstream converters and codecs as defined in ITU-R BS.1770.','A true-peak trace shows the real peaks between samples. Digital samples are dots, but the true wave curves between them. Those curves can rise above the sample values. The meter estimates them by filling in extra points. This warns of peaks a normal meter would miss.','It reveals the true reconstructed peak level so hidden inter-sample peaks can be caught before they distort.','It is used in mastering and delivery to keep true peaks below limits set for converters and codecs.','Sound Visualization & Acoustic Imaging',ARRAY['True peak','Inter-sample peak display','dBTP','Sample peak','Clipping display','Loudness normalization']::text[],ARRAY['Assuming sample peak equals true peak','Leaving no headroom before lossy encoding','Ignoring true peak because samples never hit full scale']::text[],ARRAY['Setting a true-peak limit before delivery','Checking peaks before lossy encoding','Preventing converter overload on playback']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='True-peak trace');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f720a705-961f-55ed-9a5c-abcfb2fd9bae','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f720a705-961f-55ed-9a5c-abcfb2fd9bae') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f720a705-961f-55ed-9a5c-abcfb2fd9bae');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '13fa6739-26ef-51ba-91e4-6ddeaecd3504','Dynamic range display','A visualization of a signal''s dynamic range, the span between its loud and quiet parts, shown for example as the difference between peak and average (RMS or loudness) levels over time, or as a distribution of levels. It indicates how much level variation a track retains and is used to spot over-compression, where the range between loud and soft has been reduced.','A dynamic range display shows the gap between loud and soft. A lively track keeps big differences in level. A squashed track has little difference left. The display measures and shows this gap. Engineers use it to spot over-compression.','It shows how much loud-to-soft variation a signal keeps, flagging excessive compression or limiting.','It is used in mixing and mastering to judge compression and preserve punch.','Sound Visualization & Acoustic Imaging',ARRAY['Dynamic range','Crest-factor display','Compression','RMS level','Loudness','Peak level']::text[],ARRAY['Confusing dynamic range with signal-to-noise ratio','Assuming a bigger number always sounds better','Ignoring how loudness normalization changes the picture']::text[],ARRAY['Checking a master for over-compression','Comparing the dynamics of two versions','Preserving punch during mastering']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic range display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '13fa6739-26ef-51ba-91e4-6ddeaecd3504','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='13fa6739-26ef-51ba-91e4-6ddeaecd3504') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='13fa6739-26ef-51ba-91e4-6ddeaecd3504');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44c845b2-f6e8-5bee-973f-371858ddb6e6','Crest-factor display','A display of crest factor, the ratio of a signal''s peak level to its RMS (root-mean-square) level, often expressed in decibels and shown over time. A high crest factor indicates sharp transient peaks over a low average level, an untamed, dynamic signal, while a low crest factor indicates a dense, heavily compressed or limited signal whose peaks sit close to its average.','A crest-factor display compares a signal''s peaks to its average. Peaks are the tallest moments of the wave. The average level, called RMS, tracks the general loudness. Crest factor is the gap between them. Big peaks over a low average give a high crest factor.','It quantifies how far peaks rise above the average level, indicating how dynamic or compressed a signal is.','It is used to judge transient content and compression in mixing, mastering, and metering.','Sound Visualization & Acoustic Imaging',ARRAY['Crest factor','RMS level','Peak level','Dynamic range display','Compression','Transient']::text[],ARRAY['Confusing crest factor with dynamic range over a whole song','Assuming a low crest factor is always bad','Comparing crest factor without matching the measurement windows']::text[],ARRAY['Assessing the transient content of a drum bus','Watching crest factor while compressing','Comparing the dynamics of two masters']::text[],'intermediate','CF = V_peak / V_rms   (dB: 20·log10(V_peak / V_rms))','The crest factor equals the peak amplitude divided by the RMS amplitude, and in decibels it is twenty times the base-ten logarithm of that ratio.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crest-factor display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44c845b2-f6e8-5bee-973f-371858ddb6e6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44c845b2-f6e8-5bee-973f-371858ddb6e6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44c845b2-f6e8-5bee-973f-371858ddb6e6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fdd4e621-6c30-5590-93b6-4d2ab931704f','Clipping display','A visualization that flags clipping, the distortion that occurs when a signal exceeds the maximum level a system can represent and its peaks are flattened. It may mark clipped samples on a waveform, light a clip indicator, or highlight where sample or true-peak levels reach or exceed full scale, alerting the engineer to hard-clipped regions that add harmonic distortion.','A clipping display shows where sound has been cut off at the top. When a signal is too loud, the system cannot hold the peaks. The tops of the wave get flattened, which adds harsh distortion. The display marks these spots. It warns the engineer to lower the level.','It alerts the engineer to clipped, distorted regions caused by exceeding the system''s level limit.','It is used while recording, mixing, and mastering to catch and fix overloads.','Sound Visualization & Acoustic Imaging',ARRAY['Clipping','Flat-top waveform','Full scale','True-peak trace','Headroom','Distortion']::text[],ARRAY['UNSAFE: running a power amplifier into sustained clipping, which can overheat and damage loudspeaker drivers','Assuming that if no clip light shows, inter-sample peaks are also safe','Confusing gentle intentional clipping with harsh accidental clipping']::text[],ARRAY['Catching a clipped take while recording','Checking a master for full-scale overs','Diagnosing distortion on a loud mix']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Clipping display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fdd4e621-6c30-5590-93b6-4d2ab931704f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fdd4e621-6c30-5590-93b6-4d2ab931704f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fdd4e621-6c30-5590-93b6-4d2ab931704f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb9a0351-1942-5b99-86f4-6c5dac62ba5e','Flat-top waveform','A waveform whose peaks are visibly flattened into horizontal plateaus, a characteristic sign of hard clipping or heavy limiting where signal peaks have been cut off at a level ceiling. The flat tops indicate that peak information has been lost and replaced by added harmonic distortion; the shape is a quick visual cue of overload or aggressive dynamics processing.','A flat-top waveform has peaks that look sliced off. Normally a wave has rounded peaks. When a signal is clipped hard, those peaks become flat lines. This flat shape means loud detail was lost. It is a quick sign of overload or heavy limiting.','It gives a visual signature that peaks have been clipped or heavily limited, signalling lost detail and distortion.','Engineers spot flat-top waveforms to identify clipped recordings or over-limited masters.','Sound Visualization & Acoustic Imaging',ARRAY['Clipping','Clipping display','Limiting','Hard clipping','Distortion','Waveform']::text[],ARRAY['Assuming flat tops can be fully restored after clipping','Confusing heavy limiting with clean loudness','Mistaking a naturally square wave for clipping']::text[],ARRAY['Spotting a clipped recording by its shape','Judging how hard a master was limited','Explaining clipping to a student']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flat-top waveform');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb9a0351-1942-5b99-86f4-6c5dac62ba5e','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb9a0351-1942-5b99-86f4-6c5dac62ba5e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb9a0351-1942-5b99-86f4-6c5dac62ba5e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '719691be-755d-58a6-9c36-2d0ce315d820','Inter-sample peak display','A visualization of inter-sample peaks, the peaks of the reconstructed analogue waveform that occur between digital sample points and can exceed the highest coded sample value. Estimated by oversampling, as in true-peak metering under ITU-R BS.1770, the display shows these hidden overs so engineers can prevent clipping in digital-to-analogue converters and lossy codecs, which reconstruct the continuous signal.','An inter-sample peak display shows peaks hidden between samples. Digital audio stores only sample points. The smooth wave rebuilt from them can rise higher than any sample. Those hidden highs can cause distortion later. The display estimates and shows them.','It reveals peaks that fall between samples so downstream clipping in converters and codecs can be avoided.','It is used in mastering and delivery, alongside true-peak meters, to leave enough headroom.','Sound Visualization & Acoustic Imaging',ARRAY['Inter-sample peak','True-peak trace','Oversampling','dBTP','Clipping display','Digital-to-analog converter']::text[],ARRAY['Assuming the highest sample equals the true peak','Leaving zero headroom before encoding','Ignoring inter-sample peaks because samples stay below full scale']::text[],ARRAY['Checking hidden peaks before delivery','Setting headroom before lossy encoding','Preventing converter overload on playback']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inter-sample peak display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '719691be-755d-58a6-9c36-2d0ce315d820','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='719691be-755d-58a6-9c36-2d0ce315d820') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='719691be-755d-58a6-9c36-2d0ce315d820');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '918e8293-04a5-51df-a098-3759c09f2bb5','Spectral editing view','An interface that displays audio as a spectrogram and lets the user edit it directly in the time-frequency plane, selecting and attenuating, boosting, or removing energy in specific frequency-and-time regions. Unlike waveform editing, it allows surgical removal of isolated sounds such as a cough, a click, or a tone by treating the spectrogram as an editable canvas, common in restoration and post-production tools.','A spectral editing view lets you edit sound on a spectrogram. It shows sound as a picture of frequency over time. You can select a small patch of that picture. Then you can turn just that patch up or down. This helps remove a single unwanted sound.','It allows precise editing of isolated sounds directly in the time-frequency image rather than on the waveform.','It is used in audio restoration and post to remove coughs, clicks, and stray tones.','Sound Visualization & Acoustic Imaging',ARRAY['Spectrogram','Spectral denoise display','Audio restoration','Short-time Fourier transform','Time-frequency analysis','Noise reduction']::text[],ARRAY['Selecting too wide a region and leaving audible artifacts','Assuming removed energy leaves no trace','Editing the spectrogram without listening to the result']::text[],ARRAY['Removing a cough from a vocal take','Erasing a phone ring from a recording','Cleaning a click out of a music track']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral editing view');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '918e8293-04a5-51df-a098-3759c09f2bb5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='918e8293-04a5-51df-a098-3759c09f2bb5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='918e8293-04a5-51df-a098-3759c09f2bb5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd878a6ac-bf24-5159-b9c9-7d39882f7c49','Spectral denoise display','The interface of a spectral noise-reduction process, showing a captured noise profile, the spectrum of the unwanted background, and the frequency regions being attenuated as the algorithm subtracts or gates noise across the spectrogram. It lets the user set thresholds and see where reduction is applied, balancing noise removal against artifacts in tools used for restoration and dialogue cleanup.','A spectral denoise display shows how background noise is being removed. First it learns the noise from a quiet part. That noise pattern is called a profile. The tool then lowers those noise frequencies across the sound. The display shows where and how much is cut.','It shows the noise profile and the reduction being applied so denoising can be tuned against artifacts.','It is used in restoration and dialogue editing to remove hiss, hum, and steady background noise.','Sound Visualization & Acoustic Imaging',ARRAY['Noise reduction','Noise profile','Spectral editing view','Spectrogram','Audio restoration','Spectral subtraction']::text[],ARRAY['Over-reducing and adding watery or metallic artifacts','Capturing the noise profile from a section that also has signal','Assuming denoising fully restores lost detail']::text[],ARRAY['Removing hiss from a dialogue recording','Cleaning hum from an archive tape','Reducing air-conditioner noise under speech']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral denoise display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd878a6ac-bf24-5159-b9c9-7d39882f7c49','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d878a6ac-bf24-5159-b9c9-7d39882f7c49') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d878a6ac-bf24-5159-b9c9-7d39882f7c49');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e9e8979-863e-59d2-9068-24cffad21e5d','Noise print','A stored spectral profile of a signal''s steady-state noise, captured from a passage that contains only the unwanted noise such as tape hiss, mains hum, air-handling rumble, or vinyl surface noise. A broadband denoiser measures the magnitude spectrum of this segment across many frequency bands and uses it as a per-band threshold template, attenuating bins that sit near the learned noise floor while passing louder program content. The print therefore defines, frequency by frequency, how much energy the process treats as noise.','A noise print is a picture of the background noise in a recording. You take it from a quiet spot that has no music. The tool learns the hiss or hum at each pitch. Then it lowers just that noise and keeps the sound you want.','It gives a denoiser a per-frequency reference of what the noise looks like, so reduction targets the noise spectrum instead of the wanted signal.','A restoration engineer selects a silent region between phrases, captures the noise print, then applies spectral denoising to remove hiss, hum, or ventilation rumble across the whole file.','Sound Visualization & Acoustic Imaging',ARRAY['Spectral subtraction','Broadband denoising','Noise floor','Spectrogram','Tape hiss']::text[],ARRAY['Capturing the print from a region that still contains program signal, which makes the denoiser remove wanted content','Assuming one print fits a whole file when the noise character changes over time','Setting reduction too aggressively and creating watery musical-noise artifacts']::text[],ARRAY['Removing tape hiss from an archival music transfer','Learning ventilation rumble from room tone before dialogue cleanup','Reducing vinyl surface noise between tracks on a reissue']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise print');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e9e8979-863e-59d2-9068-24cffad21e5d','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e9e8979-863e-59d2-9068-24cffad21e5d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e9e8979-863e-59d2-9068-24cffad21e5d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '368084b4-60d3-5244-9e97-51ac491b3891','De-click display','A restoration view that marks transient impulsive defects such as clicks, ticks, and crackle from vinyl, optical film, or digital dropouts on a waveform or spectrogram. Detection flags short, high-slope discontinuities that stand apart from the surrounding signal, and the display overlays markers or highlights on the located impulses so an operator can confirm detections and set sensitivity before interpolation replaces the damaged samples.','This display shows where short clicks and ticks sit in a recording. Clicks are tiny pops, often from vinyl or old film. The view marks each one on top of the sound. You can then check them and let the tool repair them.','It lets an operator see and verify detected impulsive defects, tune detection sensitivity, and avoid false hits before the de-clicker interpolates over them.','Cleaning a vinyl transfer, an engineer watches the de-click display to confirm real clicks are caught while musical transients like snare hits are not falsely flagged.','Sound Visualization & Acoustic Imaging',ARRAY['De-click','Impulse noise','Interpolation','Waveform display','Spectrogram']::text[],ARRAY['Setting sensitivity so high that sharp musical transients are treated as clicks','Trusting markers without listening, so real clicks between markers slip through','Confusing broadband crackle with isolated clicks and choosing the wrong tool']::text[],ARRAY['Removing pops from a 78-rpm disc transfer','Catching digital dropouts that read as clicks in a recovered file','Verifying that snare hits are not flagged as clicks']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='De-click display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '368084b4-60d3-5244-9e97-51ac491b3891','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='368084b4-60d3-5244-9e97-51ac491b3891') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='368084b4-60d3-5244-9e97-51ac491b3891');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd5518936-16e9-5f9e-ba1a-3640fbf71fe4','De-hum display','A spectral visualization that reveals mains-related hum and its harmonic series, that is a fundamental at the power-line frequency of 50 or 60 Hz plus integer-multiple partials, as a comb of narrow horizontal lines on a spectrogram or as peaks on a spectrum. It guides a de-hum process that places narrow notch filters at the fundamental and its harmonics, letting the operator confirm which lines are hum rather than sustained musical tones.','Hum is a low buzzing tone from power wiring. It sits at 50 or 60 hertz plus higher copies. This display shows those tones as a set of thin lines. It helps you notch out the hum without hurting the music.','It exposes the hum fundamental and its harmonics so the operator can target notch filters precisely and avoid removing musical energy at nearby frequencies.','An engineer sees a 60 Hz line and its harmonics on the spectrogram, then enables harmonic notches to strip ground-loop hum from an interview recording.','Sound Visualization & Acoustic Imaging',ARRAY['Mains hum','Harmonic series','Notch filter','Ground loop','Spectrogram']::text[],ARRAY['Notching only the fundamental and leaving audible harmonics behind','Removing a musical note that happens to fall on a hum-harmonic frequency','UNSAFE: chasing hum by defeating the mains earth/ground pin instead of curing the ground loop at its source']::text[],ARRAY['Identifying 50 Hz hum in a field recording made near power lines','Separating a sustained bass note from mains harmonics','Removing lighting-dimmer buzz with a set of harmonic notches']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='De-hum display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd5518936-16e9-5f9e-ba1a-3640fbf71fe4','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d5518936-16e9-5f9e-ba1a-3640fbf71fe4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d5518936-16e9-5f9e-ba1a-3640fbf71fe4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'daa43a4a-973f-548f-a9a7-16e0262ee560','De-reverb spectrogram','A spectrogram view used to assess reverberant smear, the trailing energy that follows each onset as room reflections decay, so a de-reverb process can reduce it. Reverberation appears as horizontal tails extending in time after transient events, and the display shows this reverberant decay relative to the direct sound so an operator can gauge how much late energy is being suppressed and whether the wanted signal is being harmed.','Reverb is the echoey tail after a sound in a room. On a spectrogram it looks like smears after each note. This view shows those tails. It helps you cut the echo while keeping the direct sound.','It visualizes reverberant tails against direct onsets so an operator can judge de-reverb strength and avoid dulling or gating the wanted signal.','Cleaning a boardroom voice recording, an engineer uses the de-reverb spectrogram to see decay tails shrink as suppression is increased.','Sound Visualization & Acoustic Imaging',ARRAY['Reverberation','Dereverberation','Spectrogram','Direct-to-reverberant ratio','Room impulse response']::text[],ARRAY['Over-suppressing until the voice sounds thin, gated, or underwater','Assuming de-reverb removes discrete slap echoes, which need different handling','Confusing steady background-noise tails with reverberant decay']::text[],ARRAY['Reducing room echo on a dialogue recording','Tightening reverb on a distant-miked instrument','Assessing decay before matching two rooms in an edit']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='De-reverb spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'daa43a4a-973f-548f-a9a7-16e0262ee560','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='daa43a4a-973f-548f-a9a7-16e0262ee560') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='daa43a4a-973f-548f-a9a7-16e0262ee560');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '93afcb02-39db-5121-9df9-5225a9cdc7a5','Azimuth error display','A visualization used in tape restoration and stereo alignment that shows the inter-channel time and phase misalignment caused by a playback head whose gap is not perpendicular to tape travel, known as azimuth error. It is commonly rendered as a Lissajous or vectorscope trace, a phase-correlation meter, or an inter-channel delay readout; a tilted or collapsed pattern signals high-frequency loss and a timing offset between the left and right channels.','On tape, the head must line up square with the tape. If it tilts, the two channels drift out of time. This display shows that timing error. A leaning pattern warns you to realign the head.','It reveals inter-channel timing and phase error from head misalignment so an operator can adjust azimuth for maximum high-frequency output and correct stereo phase.','Transferring a stereo tape, an engineer watches a vectorscope while trimming head azimuth until the pattern stands upright and high frequencies peak.','Sound Visualization & Acoustic Imaging',ARRAY['Azimuth','Phase correlation','Lissajous figure','Vectorscope','Inter-channel delay']::text[],ARRAY['Confusing azimuth phase error with a simple channel polarity reversal','Aligning azimuth by level alone and ignoring the phase and timing readout','Assuming a mono-summed check reveals azimuth loss that only shows at high frequencies']::text[],ARRAY['Realigning head azimuth during an analog tape transfer','Diagnosing dull, phasey stereo from a misaligned deck','Checking channel timing before archival digitization']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Azimuth error display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '93afcb02-39db-5121-9df9-5225a9cdc7a5','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='93afcb02-39db-5121-9df9-5225a9cdc7a5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='93afcb02-39db-5121-9df9-5225a9cdc7a5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4dc089b1-0312-5a7d-8146-d820f467d300','Wow-and-flutter display','A visualization of slow and fast pitch modulation in analog playback, where wow is the slow variation below roughly 6 Hz and flutter the faster variation above it, both arising from speed instability in a tape or disc transport. It is shown as a pitch-versus-time curve or as the demodulated speed-error signal derived from a reference tone or from program pitch tracking, exposing periodic and random speed errors for diagnosis or software correction.','Wow and flutter are wobbles in pitch from an uneven transport. Wow is slow and flutter is fast. This display draws the pitch moving up and down over time. It shows how bad the speed error is.','It shows speed-induced pitch instability over time so an engineer can diagnose transport faults or drive a pitch-stabilization correction.','An archivist views a wow-and-flutter trace from a recovered cassette to judge whether software pitch correction can restore a steady musical pitch.','Sound Visualization & Acoustic Imaging',ARRAY['Wow','Flutter','Pitch stability','Capstan','Speed error']::text[],ARRAY['Confusing wow-and-flutter with intentional vibrato in the performance','Judging severity by ear alone rather than by the measured deviation','Treating flutter and wow as one problem when their causes differ']::text[],ARRAY['Assessing a warped record for playback wow','Diagnosing a failing capstan from a flutter trace','Deciding if pitch correction can rescue a wobbly cassette transfer']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wow-and-flutter display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4dc089b1-0312-5a7d-8146-d820f467d300','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4dc089b1-0312-5a7d-8146-d820f467d300') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4dc089b1-0312-5a7d-8146-d820f467d300');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f6adba27-4833-5fa1-9301-8fe40f142618','Spectral fingerprint','A compact, characteristic pattern in a time-frequency representation that identifies a specific source, device, process, or codec, for example the harmonic layout of an instrument, the peak structure a hashing algorithm extracts for recognition, or the tell-tale signature of a particular noise source. It captures the distinctive spectral features that persist across different instances of the same source.','A spectral fingerprint is a sound''s telltale pattern in frequency. Like a real fingerprint, it helps tell one source from another. It can mark an instrument, a device, or a codec. Tools use it to recognize or match audio.','It reduces a sound to a stable set of spectral features so software or an analyst can identify, match, or distinguish sources.','A forensic analyst compares the spectral fingerprint of a hum or device tone across recordings to link them to the same source.','Sound Visualization & Acoustic Imaging',ARRAY['Spectrogram','Audio fingerprint','Spectral peak','Feature extraction','Chromagram']::text[],ARRAY['Assuming a fingerprint is fully unique when different sources can share features','Expecting a fingerprint to survive heavy processing or a codec change','Confusing a perceptual fingerprint with an exact bit-for-bit file hash']::text[],ARRAY['Matching a suspect recording to a known device signature','Identifying an instrument by its harmonic pattern','Spotting a codec by its spectral signature']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral fingerprint');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f6adba27-4833-5fa1-9301-8fe40f142618','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f6adba27-4833-5fa1-9301-8fe40f142618') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f6adba27-4833-5fa1-9301-8fe40f142618');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aefb7b09-6fcc-599d-9082-89fe4120e3b9','Audio fingerprint visualization','A display of the compact features an audio-identification system derives from a recording, commonly time-frequency peak constellations or hashed landmark points laid over a spectrogram, used to match a query clip against a reference database. It shows which robust, perceptually salient points the algorithm keeps and how those points align between two recordings.','Some apps name a song from a short clip. They do it by keeping a few strong points from the sound. This view shows those points on a spectrogram. It also shows how a clip lines up with the original.','It exposes the landmark features used for content identification, helping developers and analysts see why two clips match or fail to match.','A developer inspects the peak constellation of a query against a reference to debug why a noisy clip was or was not recognized.','Sound Visualization & Acoustic Imaging',ARRAY['Audio fingerprinting','Constellation map','Spectral peak','Content identification','Spectrogram']::text[],ARRAY['Confusing a fingerprint match with proof of identical audio files','Assuming matching works on sounds not already in the reference database','Thinking more plotted points always means a stronger match']::text[],ARRAY['Debugging why a noisy clip failed song recognition','Confirming a broadcast used a licensed track','Aligning a short query clip to a reference peak map']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio fingerprint visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aefb7b09-6fcc-599d-9082-89fe4120e3b9','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aefb7b09-6fcc-599d-9082-89fe4120e3b9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aefb7b09-6fcc-599d-9082-89fe4120e3b9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e59664e4-8bbf-5ffa-9351-47936faed17f','Codec artifact visualization','A spectrogram or waveform display that reveals the tell-tale distortions of lossy perceptual coding, such as a sharp low-pass shelf near the codec''s cutoff, short-lived swirling tones or birdies in high bands, pre-echo ahead of transients, and gaps where the encoder discarded masked content. It lets an operator judge that audio has been lossily compressed and roughly at what quality.','Lossy formats like MP3 throw away quiet sound to save space. This leaves marks you can see on a spectrogram. Look for a sharp cut up high and odd swirling tones. The view helps you spot that audio was compressed.','It helps identify prior lossy encoding and its severity, informing mastering, forensic, or quality-control decisions.','A mastering engineer checks a client''s supposed WAV on a spectrogram and sees a 16 kHz shelf, revealing it was upconverted from a low-bitrate MP3.','Sound Visualization & Acoustic Imaging',ARRAY['Lossy compression','Perceptual coding','Pre-echo','Spectrogram','Band-limiting']::text[],ARRAY['Reading any high-frequency rolloff as codec damage rather than natural content','Assuming a WAV container guarantees the audio was never lossily coded','Confusing pre-echo artifacts with room reflections']::text[],ARRAY['Verifying delivery files were not upconverted from MP3','Grading transcoded audio in quality control','Detecting re-encoding in a forensic chain']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Codec artifact visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e59664e4-8bbf-5ffa-9351-47936faed17f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e59664e4-8bbf-5ffa-9351-47936faed17f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e59664e4-8bbf-5ffa-9351-47936faed17f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8bd71eb6-b61d-54e2-8549-6be58eeda973','Band-limiting visualization','A spectrum or spectrogram display showing that a signal''s energy is confined below a defined upper frequency, appearing as an abrupt roll-off or hard shelf above the band edge. It reveals limits set by sample rate and anti-alias filtering, by lossy-codec cutoffs, or by transmission bandwidth, and helps confirm the effective audio bandwidth of a source.','Every recording has a top frequency it can hold. Above that edge, the sound just stops. This display shows that edge as a flat line on a spectrogram. It tells you the real bandwidth of the audio.','It confirms a signal''s effective high-frequency limit so an engineer can judge sample-rate, filtering, or codec provenance.','An engineer sees a hard shelf at 20 kHz and infers a 44.1 kHz source, or a shelf near 16 kHz and suspects a lossy codec.','Sound Visualization & Acoustic Imaging',ARRAY['Bandwidth','Anti-aliasing filter','Nyquist frequency','Low-pass filter','Spectrogram']::text[],ARRAY['Assuming a low cutoff always means poor quality rather than a chosen sample rate','Confusing a gentle natural rolloff with a hard filter edge','Ignoring that some sources are naturally band-limited by the instrument or microphone']::text[],ARRAY['Confirming the true bandwidth of a downloaded file','Checking an anti-alias filter edge on a converter','Spotting telephone-band limiting on a call recording']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Band-limiting visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8bd71eb6-b61d-54e2-8549-6be58eeda973','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8bd71eb6-b61d-54e2-8549-6be58eeda973') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8bd71eb6-b61d-54e2-8549-6be58eeda973');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '90bae188-1c17-5c09-ab64-5ab128c3f95a','Aliasing visualization','A spectral display showing false frequency components produced when content above half the sampling rate is sampled or generated without adequate band-limiting. Energy that exceeds the Nyquist frequency folds back, or mirrors, about it and appears as inharmonic tones that often move opposite to the true pitch. On a spectrogram these mirrored partials reveal aliasing from undersampling, poor sample-rate conversion, or nonlinear processing.','Digital audio must stay below half the sample rate. Sound above that limit folds back to a wrong, lower pitch. This display shows those fake tones. They often slide the wrong way as the real note rises.','It exposes alias products so an engineer can trace them to undersampling, weak anti-alias filtering, or nonlinear plugins and correct the signal chain.','Testing a synth or sample-rate converter, an engineer sweeps a tone and watches mirror images fold down from Nyquist on the analyzer.','Sound Visualization & Acoustic Imaging',ARRAY['Nyquist frequency','Sampling theorem','Anti-aliasing filter','Sample-rate conversion','Foldover']::text[],ARRAY['Confusing alias tones with real harmonics of the source','Assuming a high sample rate alone prevents aliasing inside nonlinear processing','Blaming the analyzer instead of the undersampled signal']::text[],ARRAY['Auditing a soft-synth for foldover on high notes','Checking a cheap sample-rate converter for alias images','Diagnosing harsh digital tones from an overdrive plugin']::text[],'advanced','f_alias = | f - k*f_s |, with integer k chosen so 0 <= f_alias <= f_s/2','An input frequency above half the sample rate mirrors back; the alias frequency equals the input minus the nearest whole-number multiple of the sample rate, taken as a positive value below the Nyquist frequency.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aliasing visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '90bae188-1c17-5c09-ab64-5ab128c3f95a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='90bae188-1c17-5c09-ab64-5ab128c3f95a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='90bae188-1c17-5c09-ab64-5ab128c3f95a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '415ad933-ace1-55ed-a30f-84f84ec26c40','Quantization-noise display','A spectral or waveform view of the low-level error introduced when a signal''s amplitude is rounded to discrete digital levels. Without dither this error correlates with the signal and appears as harmonic distortion and a raised, signal-dependent noise floor; the display shows the quantization products near the least-significant-bit level, useful for evaluating bit depth, truncation, and dither. The ideal signal-to-noise ratio for an N-bit converter is about 6.02N + 1.76 dB.','Digital audio stores levels in fixed steps. Rounding to the nearest step adds a tiny error. This display shows that error as low-level noise or distortion. More bits make the steps smaller and the noise lower.','It reveals quantization error so an engineer can assess bit depth, spot truncation distortion, and confirm that dither is working.','An engineer truncates a 24-bit mix to 16-bit without dither and sees quantization distortion appear on the analyzer at low levels.','Sound Visualization & Acoustic Imaging',ARRAY['Quantization','Dither','Bit depth','Truncation distortion','Signal-to-noise ratio']::text[],ARRAY['Confusing signal-correlated quantization distortion with random noise','Truncating bit depth without dither and adding audible distortion','Assuming quantization noise is inaudible regardless of bit depth or level']::text[],ARRAY['Comparing dithered and truncated 16-bit exports','Evaluating converter performance at low levels','Teaching why bit depth sets the noise floor']::text[],'advanced','SNR ~= 6.02*N + 1.76 dB','For an ideal uniformly quantized signal with dither, the best signal-to-noise ratio in decibels rises by about 6.02 for each added bit, plus a fixed 1.76.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quantization-noise display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '415ad933-ace1-55ed-a30f-84f84ec26c40','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='415ad933-ace1-55ed-a30f-84f84ec26c40') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='415ad933-ace1-55ed-a30f-84f84ec26c40');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e433eb75-0c95-5bfd-9c25-95c43f2757d7','Dither noise visualization','A spectral display of the small random noise deliberately added before requantization to decorrelate quantization error from the signal. Properly applied dither shows as a low, flat, signal-independent noise floor and removes the harmonic distortion that plain truncation produces. The view lets an engineer confirm the dither type and level and see that quantization distortion has been traded for benign, steady noise.','Dither is a faint noise added on purpose before lowering bit depth. It hides the harsh distortion of plain rounding. On a display it looks like a low, steady noise floor. The distortion is gone and only soft noise remains.','It confirms that added dither has replaced signal-dependent quantization distortion with a constant, unobtrusive noise floor.','Exporting a 16-bit master, an engineer compares the analyzer with and without dither to verify the distortion is gone and the noise floor is flat.','Sound Visualization & Acoustic Imaging',ARRAY['Dither','Quantization','Requantization','Bit depth','Noise shaping']::text[],ARRAY['Applying dither more than once across a mastering chain','Adding dither when staying at the same or a higher bit depth','Confusing benign dither noise with a fault in the signal']::text[],ARRAY['Verifying dither on a 24-to-16-bit master','Comparing triangular dither against plain truncation','Teaching why dither trades distortion for soft noise']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dither noise visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e433eb75-0c95-5bfd-9c25-95c43f2757d7','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e433eb75-0c95-5bfd-9c25-95c43f2757d7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e433eb75-0c95-5bfd-9c25-95c43f2757d7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5852740f-d0c0-5656-8ce7-048c46558dd7','Noise-shaped dither display','A spectral view of dither combined with noise shaping, in which the requantization error spectrum is filtered to push energy out of the ear''s most sensitive midrange, around 3 to 4 kHz, and into higher frequencies. The display shows a characteristic rising high-frequency noise contour with a lowered mid-band floor, illustrating that the total noise power is redistributed to reduce perceived loudness rather than removed.','Noise shaping bends the dither noise into a chosen shape. It moves noise away from where ears hear best. On a display the noise dips in the midrange and rises up high. The sound seems quieter even though noise is only moved.','It shows how noise shaping redistributes dither energy into less audible bands, lowering perceived noise at a given bit depth.','Choosing a dither type for a 16-bit master, an engineer views the shaped noise contour to confirm the midrange dip and the rising top end.','Sound Visualization & Acoustic Imaging',ARRAY['Noise shaping','Dither','Requantization','Psychoacoustics','Equal-loudness contour']::text[],ARRAY['Believing noise shaping lowers total noise power rather than moving it','Using aggressive shaping on material meant for further processing','Judging shaped noise by wideband meters instead of by ear and weighting']::text[],ARRAY['Selecting a shaped dither for a final CD master','Comparing flat dither against noise-shaped dither','Explaining why shaped noise measures higher but sounds lower']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Noise-shaped dither display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5852740f-d0c0-5656-8ce7-048c46558dd7','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5852740f-d0c0-5656-8ce7-048c46558dd7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5852740f-d0c0-5656-8ce7-048c46558dd7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7a0378b4-c322-5f12-a244-bed163179f82','SPL map','A spatial visualization of sound pressure level across an area such as seats, a room plan, or a measurement grid, usually rendered as a color-coded heat map in decibels referenced to 20 micropascals. Values may be measured with a meter grid or predicted by acoustic modeling, and are typically shown for a stated frequency band and source condition to reveal loud and quiet zones and overall coverage uniformity.','An SPL map shows how loud sound is at each place. It uses color to mark the level in decibels. Warm colors mean louder spots and cool colors mean quieter ones. It shows where coverage is even or uneven.','It reveals how sound level varies across a space so designers can judge coverage uniformity and find spots that are too loud or too quiet.','A system tech views an SPL map of a venue to confirm the rear seats reach target level without the front rows being too loud.','Sound Visualization & Acoustic Imaging',ARRAY['Sound pressure level','Coverage','Heat map','Decibel','Isobar plot']::text[],ARRAY['Reading a single-frequency map as if it described the full-range level','Ignoring the reference and weighting behind the decibel values','Assuming a predicted map matches the untuned real room']::text[],ARRAY['Checking level uniformity across a stadium bowl','Mapping noise levels on a factory floor','Comparing predicted and measured coverage after tuning']::text[],'beginner','L_p = 20*log10(p / p_0) dB, p_0 = 20 uPa','Sound pressure level in decibels equals twenty times the base-ten logarithm of the measured sound pressure divided by the reference pressure of twenty micropascals.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='SPL map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7a0378b4-c322-5f12-a244-bed163179f82','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7a0378b4-c322-5f12-a244-bed163179f82') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7a0378b4-c322-5f12-a244-bed163179f82');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8fbe08a2-0203-562c-9f94-c37ddf9caa50','Audience coverage plot','A visualization mapping direct-sound level or frequency response from a loudspeaker system across audience positions, showing how evenly the system covers the seats. Rendered as a colored area over a venue plan or section, it typically depicts broadband or banded direct-field level and highlights hot spots, shadowed areas, and the level drop from front to back.','This plot shows how well the speakers cover the seats. Color marks the sound level at each seat area. It shows loud front rows and any weak, shadowed spots. Designers use it to aim and choose speakers.','It shows how uniformly direct sound reaches the audience so designers can select, aim, and position loudspeakers for even coverage.','Designing a theater system, an engineer adjusts loudspeaker angles until the coverage plot shows even level from the first row to the last.','Sound Visualization & Acoustic Imaging',ARRAY['Coverage angle','Direct sound','SPL map','Loudspeaker aiming','Isobar plot']::text[],ARRAY['Judging coverage from one frequency while ignoring high-frequency narrowing','Focusing on level and overlooking response consistency across seats','Assuming direct-field coverage predicts the full reverberant room result']::text[],ARRAY['Aiming delay speakers for even coverage under a balcony','Comparing loudspeaker models for a wide seating fan','Checking front-to-back level drop in a long room']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audience coverage plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8fbe08a2-0203-562c-9f94-c37ddf9caa50','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8fbe08a2-0203-562c-9f94-c37ddf9caa50') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8fbe08a2-0203-562c-9f94-c37ddf9caa50');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '11b73134-77b6-5d16-a4c7-667ad9488948','Direct-field map','A spatial visualization of the direct sound arriving from a source before room reflections, mapping the first-arrival energy or level across positions. Because direct sound falls with distance following the inverse-square law in a free field, the map reveals the reach, aiming, and shadowing of a loudspeaker independent of the room''s reverberant contribution.','Direct sound is the part that reaches you straight from a speaker. It arrives before any echoes off the room. This map shows that direct level at each spot. It drops as you move farther away.','It isolates the direct-sound component so designers can judge aiming, reach, and coverage without the reverberant field clouding the picture.','A tech studies a direct-field map to see how far a horn throws before reflections take over, guiding delay-speaker placement.','Sound Visualization & Acoustic Imaging',ARRAY['Direct sound','Inverse-square law','Reverberant field','Critical distance','Coverage']::text[],ARRAY['Confusing the direct field with the total level a listener hears','Ignoring that beyond critical distance the reverberant field dominates','Assuming direct-field predictions hold in a very live room']::text[],ARRAY['Planning delay speakers beyond a main array','Estimating direct reach in a reverberant hall','Teaching the direct-versus-reverberant balance']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direct-field map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '11b73134-77b6-5d16-a4c7-667ad9488948','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='11b73134-77b6-5d16-a4c7-667ad9488948') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='11b73134-77b6-5d16-a4c7-667ad9488948');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ae35516-ea76-5078-a649-eec0d330ca74','Reverberant-field map','A spatial visualization of the reflected, reverberant sound energy in a room, the diffuse field built from many late reflections, as opposed to the direct sound. In an ideal diffuse field this energy is nearly uniform with position, so the map highlights departures from uniformity, buildup zones, and how the reverberant level compares with the direct field across the space.','In a room, sound bounces off the walls many times. Those late echoes fill the space fairly evenly. This map shows that reverberant energy at each spot. It reveals where reflected sound builds up.','It shows the distribution of reflected energy so designers can judge diffusion, reverberant buildup, and how it competes with direct sound.','An acoustician maps reverberant level in a gym to plan absorption that tames the reflected buildup without deadening the room.','Sound Visualization & Acoustic Imaging',ARRAY['Reverberant field','Diffuse field','Direct field','Critical distance','Reverberation time']::text[],ARRAY['Expecting perfectly uniform reverberant level in a real, non-diffuse room','Confusing reverberant buildup with a direct-sound coverage problem','Assuming more absorption always improves the result everywhere equally']::text[],ARRAY['Planning absorption in a reverberant gymnasium','Assessing diffuse-field uniformity in a test chamber','Comparing reverberant buildup before and after treatment']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverberant-field map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ae35516-ea76-5078-a649-eec0d330ca74','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ae35516-ea76-5078-a649-eec0d330ca74') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ae35516-ea76-5078-a649-eec0d330ca74');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1c74dc29-c2c7-5d43-bf21-94e0b0d41c72','Direct-to-reverberant ratio map','A spatial visualization of the ratio between direct-sound energy and reverberant energy across listener positions, expressed in decibels. Higher ratios near the source indicate clear, intelligible direct sound, while lower ratios beyond the critical distance indicate a room-dominated, less intelligible field. The map ties this balance to clarity and speech intelligibility across a space.','This map compares straight sound to echoey sound at each seat. More direct sound means clearer speech. Far from the source, echoes take over and clarity drops. The map shows where a room stays clear.','It maps the balance that governs clarity and intelligibility, helping designers keep enough direct sound across the whole audience.','A consultant uses a direct-to-reverberant ratio map to place delay loudspeakers where the ratio falls too low for intelligible speech.','Sound Visualization & Acoustic Imaging',ARRAY['Direct-to-reverberant ratio','Critical distance','Clarity','Speech intelligibility','Reverberant field']::text[],ARRAY['Treating the ratio as fixed for a room rather than position-dependent','Ignoring frequency, since the ratio varies across bands','Assuming a good ratio at the mix position holds everywhere']::text[],ARRAY['Deciding where delay speakers restore intelligibility','Comparing rooms for spoken-word suitability','Relating measured clarity to the direct and reverberant balance']::text[],'advanced','DRR = 10*log10(E_direct / E_reverberant) dB','The direct-to-reverberant ratio in decibels equals ten times the base-ten logarithm of the direct-sound energy divided by the reverberant-sound energy.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direct-to-reverberant ratio map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1c74dc29-c2c7-5d43-bf21-94e0b0d41c72','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1c74dc29-c2c7-5d43-bf21-94e0b0d41c72') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1c74dc29-c2c7-5d43-bf21-94e0b0d41c72');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f4dabd5d-97ae-58e7-8f64-e618877e026a','Speech Transmission Index map','A spatial visualization of the Speech Transmission Index, a measure of speech intelligibility running from 0 to 1 that is derived from how much a transmission path reduces the modulation depth of a test signal across octave bands. Mapped across seats, higher values mark intelligible positions and lower values mark problem zones caused by reverberation, background noise, or echoes. The index and its measurement are defined in the IEC 60268-16 standard.','STI rates how clear speech is, from 0 to 1. Higher means easier to understand. This map shows the score at each seat. It marks where noise or echo makes speech hard to follow.','It shows predicted or measured intelligibility across a space so designers can find and fix positions where speech is unclear.','A consultant maps the Speech Transmission Index in a transit hall to verify announcements meet an intelligibility target at every platform position.','Sound Visualization & Acoustic Imaging',ARRAY['Speech Transmission Index','Modulation transfer function','Speech intelligibility','Reverberation time','Signal-to-noise ratio']::text[],ARRAY['Reading the index as loudness rather than intelligibility','Ignoring background noise, which strongly lowers the score','Assuming one good position represents the whole room']::text[],ARRAY['Verifying a paging system meets an intelligibility specification','Mapping the index in a reverberant terminal','Comparing intelligibility before and after acoustic treatment']::text[],'advanced','STI in [0, 1], from the modulation transfer function m(F) across octave bands','The Speech Transmission Index runs from zero to one and is computed by weighting how much a room and its noise reduce the modulation depth of a test signal across octave bands.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Speech Transmission Index map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f4dabd5d-97ae-58e7-8f64-e618877e026a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f4dabd5d-97ae-58e7-8f64-e618877e026a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f4dabd5d-97ae-58e7-8f64-e618877e026a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aef185f4-e8b0-5034-87e3-117055659118','Bass-ratio map','A visualization of bass ratio, an acoustic metric comparing low-frequency to mid-frequency reverberation time, shown by position or across a room. Bass ratio is the sum of reverberation times in the 125 Hz and 250 Hz octave bands divided by the sum in the 500 Hz and 1000 Hz bands; values above one indicate a warmer, bass-rich reverberant character, a quantity used in concert-hall assessment.','Bass ratio compares low-note reverb to mid-note reverb. A value above one means the room sounds warm and full. This map shows that balance in a space. It helps judge if a hall feels warm or thin.','It quantifies and displays low-frequency warmth in a room''s reverberation so designers can assess or tune tonal balance.','A hall consultant checks the bass ratio to confirm the room has enough low-frequency warmth for orchestral music.','Sound Visualization & Acoustic Imaging',ARRAY['Bass ratio','Reverberation time','Warmth','Concert hall acoustics','Frequency-dependent reverberation']::text[],ARRAY['Confusing bass ratio with simple bass level or loudness','Judging warmth from one band instead of the defined ratio','Assuming a high ratio is always desirable regardless of program']::text[],ARRAY['Assessing warmth in a concert-hall design','Comparing halls for orchestral suitability','Diagnosing a thin-sounding room from its reverberation balance']::text[],'advanced','BR = (T_125 + T_250) / (T_500 + T_1000)','Bass ratio equals the sum of the reverberation times in the 125 and 250 hertz octave bands divided by the sum of the reverberation times in the 500 and 1000 hertz bands.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bass-ratio map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aef185f4-e8b0-5034-87e3-117055659118','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aef185f4-e8b0-5034-87e3-117055659118') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aef185f4-e8b0-5034-87e3-117055659118');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c758a941-729b-5c8c-bb4d-9f084e9886f2','Early decay time map','A spatial visualization of early decay time, the reverberation measure derived from the initial 10 dB of the energy decay curve and scaled to an equivalent full 60 dB decay. Because it reflects the earliest, strongest reflections, early decay time correlates with perceived reverberance better than the classic reverberation time, and mapping it reveals how reverberance varies across seats. It is defined in the ISO 3382 series.','Early decay time measures the first part of a sound fading out. It uses the first 10 decibels of decay. This early part is what listeners really hear as reverb. The map shows how it changes from seat to seat.','It maps a measure that tracks perceived reverberance, helping designers judge how live or dead a room feels at each position.','An acoustician compares early decay time across a hall to check that perceived reverberance stays consistent for the audience.','Sound Visualization & Acoustic Imaging',ARRAY['Early decay time','Reverberation time','Energy decay curve','Reverberance','Room impulse response']::text[],ARRAY['Treating early decay time and reverberation time as interchangeable','Extrapolating from a noisy 10 dB range and trusting the result','Assuming early decay time is uniform across a room']::text[],ARRAY['Checking perceived reverberance across concert-hall seats','Comparing early decay time with RT to spot early-reflection effects','Mapping reverberance changes near absorptive surfaces']::text[],'advanced','EDT = 6 * T(0 to -10 dB)','Early decay time is the time for the first ten decibels of decay, multiplied by six to express it as an equivalent sixty-decibel decay time.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Early decay time map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c758a941-729b-5c8c-bb4d-9f084e9886f2','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c758a941-729b-5c8c-bb4d-9f084e9886f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c758a941-729b-5c8c-bb4d-9f084e9886f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e71da687-623f-565e-9d35-0eab7491f6a8','RT map','A spatial or frequency-resolved visualization of reverberation time, the time for the sound energy in a room to decay by 60 dB after the source stops. Values are derived from the energy decay curve of a room impulse response, evaluated per octave or third-octave band, and mapped by position or frequency to show how reverberance varies across a space and spectrum. The measurement is standardized in the ISO 3382 series.','Reverberation time is how long sound takes to fade away. It is measured as a 60-decibel drop after the sound stops. This map shows that time by place or by pitch. It reveals where and when a room rings on.','It displays how reverberation time varies with location and frequency so designers can target treatment and predict a room''s liveness.','An acoustician maps reverberation time by octave band to see that low frequencies ring longer, then plans bass trapping.','Sound Visualization & Acoustic Imaging',ARRAY['Reverberation time','RT60','Energy decay curve','Sabine equation','Early decay time']::text[],ARRAY['Quoting one reverberation number and ignoring its strong frequency dependence','Confusing measured reverberation time with perceived reverberance, which early decay time tracks better','Assuming Sabine estimates hold in non-diffuse or very absorptive rooms']::text[],ARRAY['Mapping reverberation by band before choosing absorption','Documenting a hall against a target reverberation curve','Diagnosing a boomy room from long low-frequency reverberation']::text[],'intermediate','RT60 = 0.161 * V / A (V in m^3, A in m^2 sabins)','By the Sabine equation, reverberation time in seconds is about 0.161 times the room volume in cubic meters divided by the total absorption in square-meter sabins.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='RT map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e71da687-623f-565e-9d35-0eab7491f6a8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e71da687-623f-565e-9d35-0eab7491f6a8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e71da687-623f-565e-9d35-0eab7491f6a8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5561b433-d2f5-5653-a5ab-f91246c442f0','Impulse-response heat map','A visualization of a measured room or system impulse response rendered as a color map, most often a spectrogram-style time-frequency plot or a grid across measurement positions. It shows how energy arrives and decays over time and frequency, including the direct sound, discrete reflections, and reverberant decay, so an analyst can read arrival times, decay slopes, and spectral coloration from a single image.','An impulse response captures how a room answers a quick sound. This heat map shows that answer with color. Time runs one way and frequency the other. You can see the first sound, the echoes, and the fade.','It turns a room or system impulse response into a readable image of arrivals and decay, supporting alignment, treatment, and analysis.','A tuner reads an impulse-response heat map to spot a strong reflection and its delay, then treats the surface causing it.','Sound Visualization & Acoustic Imaging',ARRAY['Impulse response','Spectrogram','Reflection','Energy decay curve','Reverberation time']::text[],ARRAY['Confusing measurement noise tails with real reflections','Ignoring windowing choices that change how the plot looks','Reading absolute color as level without checking the scale']::text[],ARRAY['Locating a problem reflection during room tuning','Comparing before-and-after treatment responses','Teaching how direct sound, reflections, and decay appear']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulse-response heat map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5561b433-d2f5-5653-a5ab-f91246c442f0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5561b433-d2f5-5653-a5ab-f91246c442f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5561b433-d2f5-5653-a5ab-f91246c442f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '677ffa50-cdce-53b9-83eb-13bab58fa8db','Comb-filter visualization','A display of the periodic peaks and notches in a frequency response that occur when a signal sums with a delayed copy of itself, as from a reflection or two mismatched sources. The notches fall at odd multiples of half the inverse delay and repeat at a spacing equal to the inverse of the delay, producing the regularly spaced dips that give the comb its name. The plot exposes this pattern versus frequency.','When a sound meets a slightly delayed copy, some pitches add and others cancel. This makes a row of evenly spaced dips in the response. The display shows that comb-like pattern. Wider spacing between dips means a shorter delay.','It reveals comb filtering from reflections or source overlap so an engineer can find the delay and fix the timing or geometry.','A tech sees comb notches when two speakers overlap, reads the notch spacing, and adjusts delay to align the arrivals.','Sound Visualization & Acoustic Imaging',ARRAY['Comb filtering','Reflection','Path-length difference','Phase interference','Frequency response']::text[],ARRAY['Trying to fix comb-filter notches with EQ instead of timing or placement','Confusing comb notches with a single resonance or filter dip','Ignoring that the notch spacing reveals the delay time']::text[],ARRAY['Diagnosing hollow sound from two overlapping speakers','Spotting a floor-bounce reflection at a microphone','Aligning delay between mains and front fills']::text[],'intermediate','notches at f_n = (2n-1)/(2*dt); spacing df = 1/dt','For a delay of dt seconds, cancellation notches fall at odd multiples of one over twice the delay, and neighboring notches are spaced by one divided by the delay.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Comb-filter visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '677ffa50-cdce-53b9-83eb-13bab58fa8db','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='677ffa50-cdce-53b9-83eb-13bab58fa8db') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='677ffa50-cdce-53b9-83eb-13bab58fa8db');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ec3b3c2f-590a-5217-a7a4-7e62a0820eaa','Lobing pattern','A visualization of the spatial interference lobes produced when two or more sources or drivers radiate the same frequencies and their outputs combine with position-dependent phase. Constructive addition forms lobes of higher level and destructive cancellation forms nulls between them; the pattern shifts with frequency and geometry, and the display reveals how coverage and response vary with angle and position.','When two speakers play the same sound, their waves meet. In some directions they add and get louder. In others they cancel and drop out. This pattern of loud lobes and quiet nulls is what the display shows.','It shows how multiple sources interfere in space so designers can predict uneven coverage and reduce destructive lobing.','A designer views the lobing pattern of stacked cabinets to see nulls sweeping the audience and adjusts spacing or splay.','Sound Visualization & Acoustic Imaging',ARRAY['Interference','Lobe','Null','Comb filtering','Loudspeaker array']::text[],ARRAY['Assuming two sources always sum to more level everywhere','Ignoring how lobes and nulls move with frequency','Confusing interference lobing with a single speaker''s own polar pattern']::text[],ARRAY['Predicting nulls from stacked subwoofers','Explaining uneven coverage from two spaced mains','Setting driver spacing to control lobing']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Lobing pattern');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ec3b3c2f-590a-5217-a7a4-7e62a0820eaa','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ec3b3c2f-590a-5217-a7a4-7e62a0820eaa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ec3b3c2f-590a-5217-a7a4-7e62a0820eaa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a6e769dd-c271-5809-84e5-2b15e454bad6','Polar response plot','A plot of a transducer''s sensitivity or output level as a function of angle around it, usually drawn on polar, that is circular, axes for a given frequency or band. For microphones it shows the pickup pattern such as omnidirectional, cardioid, or figure-eight; for loudspeakers and instruments it shows radiated directivity. The distance from the center at each angle represents relative level, revealing directional behavior.','A polar plot shows how a mic or speaker responds by direction. Angle runs around a circle. How far the line sits from the center shows the level there. It reveals which way a device hears or throws sound.','It compactly shows directionality versus angle so engineers can choose and aim microphones and loudspeakers for a task.','An engineer reads a microphone''s polar plot to pick a cardioid that rejects a monitor placed at its rear null.','Sound Visualization & Acoustic Imaging',ARRAY['Directivity','Polar pattern','Cardioid','Off-axis response','Isobar plot']::text[],ARRAY['Assuming the polar pattern is the same at every frequency','Reading the plot as coverage distance rather than relative level','Ignoring that patterns narrow at high frequencies']::text[],ARRAY['Choosing a mic pattern to reject a stage monitor','Comparing loudspeaker directivity for a room','Explaining why a cardioid rejects sound from behind']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Polar response plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a6e769dd-c271-5809-84e5-2b15e454bad6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a6e769dd-c271-5809-84e5-2b15e454bad6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a6e769dd-c271-5809-84e5-2b15e454bad6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34ef2429-3fa4-5983-9754-00eba3e2cd56','Isobar plot','A loudspeaker directivity visualization that draws contour lines connecting angles of equal level relative to on-axis, typically overlaid on angle-versus-frequency axes or on a polar plot. Each isobar, for example the -6 dB contour, marks the edge of a coverage zone, so the plot compactly summarizes how a loudspeaker''s coverage angle changes with frequency.','An isobar plot draws lines that link points of equal loudness around a speaker. Each line marks a coverage edge, like the -6 decibel limit. It shows how the covered angle changes with pitch. Designers use it to aim speakers.','It summarizes how coverage angle varies with frequency so designers can predict and match loudspeaker coverage to a room.','A consultant compares isobar plots to choose a loudspeaker whose -6 dB coverage stays constant across the vocal range.','Sound Visualization & Acoustic Imaging',ARRAY['Directivity','Coverage angle','Polar response plot','Beamwidth','Off-axis response']::text[],ARRAY['Confusing an equal-level contour with an absolute SPL value','Assuming the -6 dB edge is the only usable coverage','Ignoring vertical directivity when only horizontal isobars are shown']::text[],ARRAY['Selecting a loudspeaker for a consistent coverage angle','Comparing horn directivity across frequency','Documenting coverage in a system design report']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Isobar plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34ef2429-3fa4-5983-9754-00eba3e2cd56','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34ef2429-3fa4-5983-9754-00eba3e2cd56') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34ef2429-3fa4-5983-9754-00eba3e2cd56');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '046fe164-7888-5636-bcf1-239ec97522fc','Beamwidth plot','A graph of a loudspeaker''s coverage angle versus frequency, where beamwidth at each frequency is the angular span between the points at which output falls to a stated level below on-axis, commonly -6 dB. A flat curve indicates constant directivity, while narrowing at high frequencies or widening at low frequencies reveals frequency-dependent coverage.','Beamwidth is the angle a speaker covers at each pitch. This plot draws that angle against frequency. A flat line means steady coverage. A line that narrows up high means the sound beams forward.','It shows how a loudspeaker''s coverage angle changes with frequency so designers can predict even or uneven tonal coverage across seats.','An engineer checks a beamwidth plot to confirm a speaker holds its coverage angle through the vocal range before specifying it.','Sound Visualization & Acoustic Imaging',ARRAY['Beamwidth','Directivity','Coverage angle','Constant directivity','Isobar plot']::text[],ARRAY['Assuming coverage angle is fixed across all frequencies','Ignoring the reference level that defines the beamwidth edge','Confusing horizontal and vertical beamwidth']::text[],ARRAY['Selecting a constant-directivity horn','Explaining why high frequencies beam on-axis','Comparing coverage consistency between speakers']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Beamwidth plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '046fe164-7888-5636-bcf1-239ec97522fc','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='046fe164-7888-5636-bcf1-239ec97522fc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='046fe164-7888-5636-bcf1-239ec97522fc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c11f3115-a286-5746-97ff-301fcc7cddfb','Off-axis response plot','A frequency-response curve measured at one or more angles away from a transducer''s front axis, shown alongside the on-axis response. It reveals how tonal balance changes off to the side or above and below, since most sources lose high frequencies off-axis. The set of off-axis curves characterizes directivity and predicts how a source sounds away from its aim.','A speaker or mic usually sounds different off to the side. This plot shows the response at angles away from the front. It usually loses highs as the angle grows. It predicts how the sound changes off-center.','It shows how frequency balance changes with angle so engineers can predict tonal consistency for listeners off the main axis.','An engineer studies off-axis curves to judge how a speaker will sound for seats outside its direct aim.','Sound Visualization & Acoustic Imaging',ARRAY['Off-axis response','On-axis response','Directivity','Polar response plot','High-frequency rolloff']::text[],ARRAY['Specifying a speaker on its on-axis curve alone','Assuming off-axis loss is only about level, not tone','Ignoring off-axis response when spacing microphones']::text[],ARRAY['Predicting tone for wide seating','Choosing a mic with smooth off-axis response for a choir','Explaining dull sound for off-center listeners']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Off-axis response plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c11f3115-a286-5746-97ff-301fcc7cddfb','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c11f3115-a286-5746-97ff-301fcc7cddfb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c11f3115-a286-5746-97ff-301fcc7cddfb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd106e21a-b0d5-5d0f-90a4-08601336cfd6','Horizontal polar map','A directivity visualization plotting a loudspeaker''s relative level across horizontal, that is left-to-right, angle versus frequency, usually as a color-coded map built from measured data. It shows how horizontal coverage widens or narrows with frequency, revealing beaming, coverage width, and off-axis coloration in the horizontal plane.','This map shows a speaker''s side-to-side coverage. One axis is the horizontal angle. The other is frequency. Color shows the level, so you see where highs beam and lows spread.','It shows horizontal directivity across frequency so designers can match a loudspeaker''s side-to-side coverage to a room''s width.','A designer reads a horizontal polar map to confirm a speaker covers a wide seating fan without beaming at high frequencies.','Sound Visualization & Acoustic Imaging',ARRAY['Directivity','Polar response plot','Horizontal coverage','Beamwidth','Isobar plot']::text[],ARRAY['Assuming horizontal behavior also describes vertical coverage','Reading color as absolute level instead of relative to on-axis','Ignoring the high-frequency narrowing shown in the map']::text[],ARRAY['Matching horizontal coverage to a wide room','Comparing two speakers'' horizontal directivity','Explaining side-seat tonal loss']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Horizontal polar map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd106e21a-b0d5-5d0f-90a4-08601336cfd6','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d106e21a-b0d5-5d0f-90a4-08601336cfd6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d106e21a-b0d5-5d0f-90a4-08601336cfd6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ab579f6-0ca6-5903-874f-30255a6964a7','Vertical polar map','A directivity visualization plotting a loudspeaker''s relative level across vertical, that is up-and-down, angle versus frequency, typically as a color-coded map. It reveals vertical coverage, beaming, and the lobing behavior important for line arrays, where vertical directivity controls how energy is distributed from the front to the back of an audience.','This map shows a speaker''s up-and-down coverage. One axis is the vertical angle. The other is frequency. Color shows the level, so you see how sound aims from front to back rows.','It shows vertical directivity across frequency so designers can control front-to-back coverage and manage array lobing.','An engineer studies a vertical polar map of a line array to see how splay angles steer energy toward the rear seats.','Sound Visualization & Acoustic Imaging',ARRAY['Directivity','Line array','Vertical coverage','Lobing pattern','Beamwidth']::text[],ARRAY['Overlooking vertical lobing that horizontal data hides','Assuming vertical coverage is symmetrical about the axis','Ignoring how array splay reshapes the vertical pattern']::text[],ARRAY['Setting line-array splay for front-to-back coverage','Diagnosing thin sound at certain row depths','Comparing vertical directivity of array modules']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Vertical polar map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ab579f6-0ca6-5903-874f-30255a6964a7','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ab579f6-0ca6-5903-874f-30255a6964a7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ab579f6-0ca6-5903-874f-30255a6964a7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9a455bdd-7f85-5197-a552-3d2731a95819','Balloon data','A measurement dataset describing a source''s three-dimensional directivity, that is its radiated level as a function of azimuth and elevation, usually per frequency band. Named for the balloon-like 3D surface it forms when plotted, it is commonly stored in standardized loudspeaker-directivity formats such as GLL or the Common Loudspeaker Format and read by acoustic-modeling software to predict coverage in a room.','Balloon data records how a speaker radiates in every direction. It stores the level at many angles for each band. Plotted in 3D it looks like a lumpy balloon. Modeling software uses it to predict room coverage.','It provides the full 3D directivity a modeling program needs to predict how a loudspeaker covers a space.','A designer imports a manufacturer''s balloon data into modeling software to simulate a system''s coverage before installation.','Sound Visualization & Acoustic Imaging',ARRAY['Directivity','GLL','Common Loudspeaker Format','Acoustic modeling','Polar response plot']::text[],ARRAY['Assuming coarse angular resolution captures narrow high-frequency lobes','Using balloon data measured under conditions unlike the real install','Confusing a directivity dataset with a full loudspeaker model that includes limiting']::text[],ARRAY['Importing loudspeaker directivity into modeling software for prediction','Comparing manufacturer directivity datasets','Building an array model from module balloon data']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Balloon data');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9a455bdd-7f85-5197-a552-3d2731a95819','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9a455bdd-7f85-5197-a552-3d2731a95819') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9a455bdd-7f85-5197-a552-3d2731a95819');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0e217bb6-01b7-5f71-a337-c636b849aa92','EASE map','A coverage or acoustic-parameter prediction map generated in electroacoustic room-modeling software of the EASE type, which computes results over an audience area from loudspeaker directivity data and room geometry. Such maps display predicted quantities such as direct sound pressure level, total level, speech transmission index, clarity, or arrival time as color across the mapped surfaces, supporting system design before installation.','EASE is software that models sound in a planned room. It uses speaker data and the room shape. It draws maps of predicted level or clarity over the seats. Designers use these maps before building the system.','It lets designers predict and visualize coverage and acoustic parameters in software so problems are solved before any hardware is installed.','A consultant produces prediction maps of direct level and speech intelligibility to validate a paging design against its targets.','Sound Visualization & Acoustic Imaging',ARRAY['Acoustic modeling','Balloon data','SPL map','Speech Transmission Index','Coverage']::text[],ARRAY['Trusting predictions built from an inaccurate room or absorption model','Confusing a predicted map with verified measured results','Ignoring that the input directivity resolution limits accuracy']::text[],ARRAY['Predicting intelligibility for a stadium bowl','Validating coverage before a permanent install','Comparing loudspeaker options in a modeled room']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='EASE map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0e217bb6-01b7-5f71-a337-c636b849aa92','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0e217bb6-01b7-5f71-a337-c636b849aa92') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0e217bb6-01b7-5f71-a337-c636b849aa92');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1b4db0b9-f57f-5f5c-8278-2517fc924fc1','Array coverage prediction','A simulated visualization of the sound coverage a loudspeaker array will produce over an audience area, computed from each element''s directivity, position, aim, and signal processing. It displays predicted level and its uniformity, often per frequency band, so a designer can evaluate front-to-back and side-to-side consistency and refine the array before deployment.','This prediction shows how an array of speakers will cover the seats. Software combines each speaker''s aim and output. It draws the expected level across the audience. Designers tune the array until coverage looks even.','It forecasts array coverage so designers can optimize element count, angles, and processing for even level before the show.','A system engineer runs an array coverage prediction to set line-array splay angles that keep level even from front to rear.','Sound Visualization & Acoustic Imaging',ARRAY['Line array','Coverage','SPL map','Line-array splay','Acoustic modeling']::text[],ARRAY['Assuming a prediction replaces on-site measurement and tuning','Modeling one frequency and ignoring band-dependent coverage','Neglecting real room reflections not captured by a free-field model']::text[],ARRAY['Designing line-array splay for a theater','Comparing array sizes for a festival stage','Presenting predicted coverage to a client']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Array coverage prediction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1b4db0b9-f57f-5f5c-8278-2517fc924fc1','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1b4db0b9-f57f-5f5c-8278-2517fc924fc1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1b4db0b9-f57f-5f5c-8278-2517fc924fc1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb12af4a-16c9-5b6f-93ec-d2054a669303','Line-array splay visualization','A display of the inter-cabinet splay angles set between elements of a vertical line array, together with the coverage those angles are predicted to produce. Tighter splay at the top focuses energy to distant seats and wider splay at the bottom spreads it to near seats; the visualization links the mechanical angle settings to the resulting vertical coverage.','A line array is a stack of speakers with hinges. The angle between boxes is the splay. This view shows those angles and the coverage they make. Tighter top angles reach far seats and wider bottom angles cover near seats.','It connects the array''s mechanical splay angles to predicted vertical coverage so designers can shape front-to-back level.','Rigging a line array, a tech sets each hinge to the splay angles the visualization specifies for even coverage.','Sound Visualization & Acoustic Imaging',ARRAY['Line array','Splay angle','Vertical coverage','Array coverage prediction','Rigging']::text[],ARRAY['Using equal splay angles throughout instead of progressive angles','Ignoring how splay interacts with array length and throw distance','UNSAFE: exceeding the manufacturer''s rated inter-cabinet splay or load limits when rigging the array']::text[],ARRAY['Setting progressive splay for a raked auditorium','Matching splay to a modeled coverage target','Adjusting splay to cover a deep balcony']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Line-array splay visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb12af4a-16c9-5b6f-93ec-d2054a669303','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb12af4a-16c9-5b6f-93ec-d2054a669303') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb12af4a-16c9-5b6f-93ec-d2054a669303');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8aae1dce-ca55-59b9-8938-1e7c6f0fee9f','Subwoofer array prediction','A modeled visualization of the low-frequency coverage produced by a group of subwoofers, showing how their outputs sum and cancel across an area because of spacing, delay, and polarity. Rendered as an SPL map for a low-frequency band, it reveals directional control patterns such as broadside, cardioid, or end-fire, along with the uneven level and power-alley effects that sub arrays create.','Subwoofers placed together interact strongly. Their low sound adds in some spots and cancels in others. This prediction maps that low-frequency coverage. It shows patterns like a loud center alley or a directional sub array.','It forecasts how a subwoofer array''s spacing, delay, and polarity shape low-frequency coverage so designers can steer bass and reduce dead spots.','A designer predicts a subwoofer array to avoid a narrow power alley and keep bass even across the audience.','Sound Visualization & Acoustic Imaging',ARRAY['Subwoofer array','Cardioid subwoofer','End-fire array','Power alley','Low-frequency coverage']::text[],ARRAY['Placing subs by ear without predicting their interaction','Ignoring how delay and polarity steer the pattern','Assuming free-field predictions hold near strong room boundaries']::text[],ARRAY['Steering bass away from a stage with a cardioid sub array','Avoiding a power alley across a dance floor','Comparing broadside and gradient sub layouts']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Subwoofer array prediction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8aae1dce-ca55-59b9-8938-1e7c6f0fee9f','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8aae1dce-ca55-59b9-8938-1e7c6f0fee9f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8aae1dce-ca55-59b9-8938-1e7c6f0fee9f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ffcdea37-f8a9-556d-af77-e9572cbc6783','Cardioid subwoofer map','A visualization of the directional low-frequency coverage of a cardioid subwoofer arrangement, in which spacing, delay, and polarity are set so outputs sum in front of and cancel behind the array. The map, typically an SPL contour for a low band, shows the forward lobe and the rear null, quantifying how much low-frequency energy is kept off the stage.','A cardioid sub setup aims bass forward and cancels it behind. This map shows that pattern. A strong lobe points at the crowd and a null sits behind. It helps keep low sound off the stage.','It shows the forward-focused, rear-cancelling coverage of a cardioid sub array so designers can verify stage rejection and audience level.','A tech maps a cardioid sub array to confirm the rear null reduces bass on stage for the musicians.','Sound Visualization & Acoustic Imaging',ARRAY['Cardioid subwoofer','Subwoofer array prediction','Rear rejection','Polarity','End-fire array']::text[],ARRAY['Expecting a perfect rear null across all low frequencies','Getting delay or polarity wrong and losing the cardioid pattern','Assuming room boundaries do not disturb the intended null']::text[],ARRAY['Reducing stage bass for a live band','Keeping low frequencies off a nearby residence','Verifying rear rejection after setting sub delays']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cardioid subwoofer map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ffcdea37-f8a9-556d-af77-e9572cbc6783','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ffcdea37-f8a9-556d-af77-e9572cbc6783') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ffcdea37-f8a9-556d-af77-e9572cbc6783');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '457ee1b6-f89b-5ab6-8184-4e36663add35','End-fire array map','A visualization of the coverage from an end-fire subwoofer array, in which units are spaced along the firing axis and progressively delayed so their outputs sum forward and cancel to the rear. The map, an SPL contour for a low band, shows strong forward directivity and rear attenuation, illustrating how the physical spacing and matching delays steer low-frequency energy.','An end-fire array lines up subs front to back. Each one is delayed to match the sound travel time. The bass adds going forward and cancels going backward. This map shows that forward-aimed pattern.','It shows the forward-directional coverage of a delayed, in-line sub array so designers can confirm rear cancellation and aim bass at the audience.','A tech spaces and delays subs for an end-fire array, then checks the map to confirm strong forward output and rear rejection.','Sound Visualization & Acoustic Imaging',ARRAY['End-fire array','Subwoofer array prediction','Cardioid subwoofer','Delay','Low-frequency directivity']::text[],ARRAY['Setting the delay to the wrong value for the chosen spacing','Expecting broadband rejection from a geometry tuned to one band','Confusing an end-fire array with a delayed cardioid gradient array']::text[],ARRAY['Aiming festival subs forward with an end-fire array','Reducing bass behind the stage','Tuning spacing and delay for forward directivity']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='End-fire array map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '457ee1b6-f89b-5ab6-8184-4e36663add35','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='457ee1b6-f89b-5ab6-8184-4e36663add35') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='457ee1b6-f89b-5ab6-8184-4e36663add35');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f74af9e3-c760-5783-8189-ffb5ff61e3be','Gradient array map','A gradient array map is a visualization of the directional radiation or coverage produced by a low-frequency gradient loudspeaker array—an arrangement combining pressure and pressure-gradient behaviour, as in cardioid or end-fire subwoofer configurations. The map depicts predicted level or directivity around the array, usually at low frequencies, showing where energy is reinforced and where it is attenuated to the sides or rear.','A gradient array is a group of subwoofers set up to aim low sound one way. A gradient array map shows where that low energy goes. It marks where the bass is strong and where it is cut. Engineers use it to keep bass off the stage. It works mainly at low frequencies.','It shows how a directional low-frequency array steers bass energy, helping engineers cut level where it is unwanted, such as on stage or offsite.','System engineers use gradient array maps in prediction software when designing cardioid or end-fire subwoofer arrays for concerts.','Sound Visualization & Acoustic Imaging',ARRAY['Cardioid subwoofer array','End-fire array','Directivity','Coverage map','Low-frequency control']::text[],ARRAY['Confusing a pressure-gradient loudspeaker array with a pressure-gradient microphone','Expecting the predicted rear rejection to hold at every frequency','Ignoring how element spacing and delay set the pattern']::text[],ARRAY['Designing a cardioid sub array to protect the stage','Predicting bass spill toward neighbours','Tuning end-fire sub spacing in software']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Gradient array map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f74af9e3-c760-5783-8189-ffb5ff61e3be','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f74af9e3-c760-5783-8189-ffb5ff61e3be') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f74af9e3-c760-5783-8189-ffb5ff61e3be');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e9aa3bcf-ca05-5463-8e42-da1ed904662a','Pressure-zone map','A pressure-zone map is a spatial visualization of the sound pressure distribution within a bounded space, showing regions of high and low pressure. It is commonly derived from modal or numerical simulation at low frequencies, where standing waves create pressure antinodes (maxima) and nodes (minima). The map reveals where a room mode concentrates or cancels energy across a plane or volume.','A pressure-zone map shows where sound pressure is high or low in a space. At low frequencies, room modes create loud spots and quiet spots. The map paints these zones across the room. It helps show why bass changes from seat to seat. It is not the same as a boundary microphone.','It reveals the spatial pattern of standing-wave pressure, guiding placement of listeners, sources, and low-frequency treatment.','Acousticians use pressure-zone maps from room-mode simulation to place subwoofers and seats away from severe peaks and nulls.','Sound Visualization & Acoustic Imaging',ARRAY['Room mode','Standing wave','Node','Antinode','Modal analysis']::text[],ARRAY['Confusing a pressure-zone map with a pressure-zone (boundary) microphone','Assuming the pattern is the same at every frequency','Reading a single plane as the whole three-dimensional field']::text[],ARRAY['Placing subwoofers to smooth the low end','Choosing the mixing position in a control room','Explaining a boomy note from a room mode']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-zone map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e9aa3bcf-ca05-5463-8e42-da1ed904662a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e9aa3bcf-ca05-5463-8e42-da1ed904662a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e9aa3bcf-ca05-5463-8e42-da1ed904662a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3101759f-a109-512c-8233-e41b775a6e7b','Null map','A null map is a visualization that identifies the spatial locations where a sound field reaches a local minimum due to destructive interference or cancellation. Nulls arise from the interaction of multiple sources, boundary reflections, or array steering. The map highlights these dips in level so coverage gaps and cancellation zones can be seen and addressed.','A null is a spot where sound cancels and gets very quiet. A null map shows where these quiet spots fall. They come from waves meeting and cancelling. The map helps you spot coverage holes. Then you can move a speaker or a listener.','It exposes cancellation zones in a coverage pattern, so designers can avoid seating listeners in dead spots or steer nulls onto unwanted areas.','Engineers read null maps in prediction software to keep interference dips off the audience and onto reflective walls instead.','Sound Visualization & Acoustic Imaging',ARRAY['Destructive interference','Comb filtering','Coverage map','Array interaction','Cancellation']::text[],ARRAY['Assuming null positions stay fixed across frequency','Confusing a true null with a simple level drop from distance','Ignoring how source spacing moves nulls']::text[],ARRAY['Steering array nulls toward a rear wall','Diagnosing a dead seat between two speakers','Predicting cancellation from two subwoofers']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Null map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3101759f-a109-512c-8233-e41b775a6e7b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3101759f-a109-512c-8233-e41b775a6e7b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3101759f-a109-512c-8233-e41b775a6e7b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb39daab-86b1-57f7-ae83-54f48d4b123b','Hot spot map','A hot spot map is a visualization that highlights localized regions of elevated sound pressure level within a coverage area or room, where level exceeds surrounding areas or a target value. Hot spots may result from source proximity, focusing reflections off concave surfaces, or constructive interference. The map flags these areas for level control or acoustic treatment.','A hot spot is a place where sound is much louder than nearby areas. A hot spot map shows where these loud areas fall. They can come from being close to a speaker or from focused reflections. The map helps you find and fix them. That keeps levels more even for the audience.','It locates areas of excess level so coverage can be evened out and listeners are not exposed to unexpectedly loud spots.','Designers use hot spot maps to catch focusing from curved surfaces or front-row overexposure before an event.','Sound Visualization & Acoustic Imaging',ARRAY['Coverage uniformity plot','Sound focusing','Constructive interference','SPL distribution','Concave reflector']::text[],ARRAY['UNSAFE: Ignoring audience hot spots that push exposure toward unsafe levels','Assuming hot spots come only from proximity, not from focusing','Reading one frequency''s map as the whole picture']::text[],ARRAY['Finding a focus point under a domed ceiling','Checking front-row levels at a concert','Evening out coverage across a seating stand']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hot spot map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb39daab-86b1-57f7-ae83-54f48d4b123b','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb39daab-86b1-57f7-ae83-54f48d4b123b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb39daab-86b1-57f7-ae83-54f48d4b123b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '73442bf2-e1a7-5ea3-823a-9ce930865c54','Coverage uniformity plot','A coverage uniformity plot is a visualization of how consistently sound level—and sometimes spectral balance or intelligibility—is distributed across a defined audience area. It typically maps sound pressure level as colour or contour over the seating, revealing the spread between the loudest and quietest positions. Uniform coverage shows small variation; poor coverage shows large gradients or patchiness.','A coverage uniformity plot shows how even the sound level is across the seats. It uses colours or contours over the audience area. Small changes in colour mean even coverage. Big changes mean some seats are much louder than others. Designers aim for a small spread.','It quantifies how evenly a system covers the audience, a key design goal so every seat hears a similar level and balance.','System designers judge coverage uniformity plots in prediction tools to choose splay angles and speaker counts for even seating coverage.','Sound Visualization & Acoustic Imaging',ARRAY['Coverage angle','SPL distribution','Seat-to-seat variance map','Line array','Directivity']::text[],ARRAY['Judging uniformity at one frequency instead of across the band','Confusing overall loudness with even coverage','Ignoring spectral balance while chasing level uniformity']::text[],ARRAY['Setting line-array splay for even coverage','Comparing two designs for level spread','Checking balcony versus floor coverage']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Coverage uniformity plot');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '73442bf2-e1a7-5ea3-823a-9ce930865c54','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='73442bf2-e1a7-5ea3-823a-9ce930865c54') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='73442bf2-e1a7-5ea3-823a-9ce930865c54');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bf182458-f5d9-55d8-ac15-07ff12060df8','Seat-to-seat variance map','A seat-to-seat variance map is a venue prediction or measurement display that shows how sound level, spectral balance, or intelligibility differs from one seating position to the next across an audience. It visualizes local variation rather than the average, exposing places where neighbouring seats experience markedly different sound, often from interference, reflections, or coverage edges.','This map shows how sound changes from one seat to the next. Two seats side by side can sound different. The map paints those differences across the audience. Big changes point to interference or coverage edges. Designers use it to smooth out the experience.','It highlights local seat-to-seat differences that averages hide, guiding fixes so nearby listeners get more consistent sound.','Engineers use seat-to-seat variance maps to catch spots where comb filtering or coverage overlap makes adjacent seats sound different.','Sound Visualization & Acoustic Imaging',ARRAY['Coverage uniformity plot','Comb filtering','Intelligibility','SPL distribution','Array interaction']::text[],ARRAY['Trusting an average level while ignoring seat-to-seat swings','Assuming the variance is the same across frequency','Blaming the source when room reflections cause the spread']::text[],ARRAY['Finding patchy intelligibility under a balcony','Comparing adjacent seats near array overlap','Reporting coverage quality to a client']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seat-to-seat variance map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bf182458-f5d9-55d8-ac15-07ff12060df8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bf182458-f5d9-55d8-ac15-07ff12060df8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bf182458-f5d9-55d8-ac15-07ff12060df8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '40706d7c-0f18-5d81-a450-f1a0cdf8644a','Reflection order visualization','Reflection order visualization is a diagram or simulation output that distinguishes sound reflections by their order—first-order reflections that bounce once before reaching the receiver, second-order that bounce twice, and so on. Often built with the image-source method or ray tracing, it shows each reflection''s path, arrival time, and strength, clarifying how early reflections build up in a room.','Sound in a room bounces off surfaces before reaching you. A first-order reflection bounces once. A second-order one bounces twice, and so on. This visualization draws those paths by order. It shows when and how strongly each reflection arrives. That helps explain the early room sound.','It separates reflections by how many bounces they take, helping acousticians target the surfaces that cause the strongest early reflections.','Acousticians use reflection order views from image-source or ray-tracing models to place absorption or diffusion on surfaces causing problem early reflections.','Sound Visualization & Acoustic Imaging',ARRAY['Image-source method','Ray tracing','Early reflections','Room acoustic ray cloud','Impulse response']::text[],ARRAY['Assuming only first-order reflections matter','Confusing reflection order with a ranking by arrival level','Ignoring that higher orders blend into reverberation']::text[],ARRAY['Finding first-reflection points in a control room','Placing diffusers from a reflection model','Explaining early-reflection build-up to students']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reflection order visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '40706d7c-0f18-5d81-a450-f1a0cdf8644a','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='40706d7c-0f18-5d81-a450-f1a0cdf8644a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='40706d7c-0f18-5d81-a450-f1a0cdf8644a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fcf29cf6-7423-5dfa-875c-4c599bf6ba80','Auralization visual interface','An auralization visual interface is the graphical environment of an acoustic simulation that lets a user position sources and listeners in a modeled space and audition the auralized result—the simulated sound at a chosen location. It links the visual room model and its computed acoustic response to audible playback, so that changing a position updates both the picture and the rendered sound.','Auralization means turning an acoustic model into sound you can hear. Its visual interface is the on-screen room you work in. You place a source and a listener in the model. Then you hear how that spot would sound. Moving the listener updates the view and the sound.','It connects a visual room model to audible simulation, letting designers and clients hear predicted acoustics before anything is built.','Consultants use auralization interfaces to demo how a hall will sound from different seats during design reviews with clients.','Sound Visualization & Acoustic Imaging',ARRAY['Auralization','Room acoustic simulation','Impulse response','Binaural rendering','Ray tracing']::text[],ARRAY['Treating an auralization as an exact recording of the finished room','Ignoring how model detail and material data limit accuracy','Forgetting that the headphones or playback system colour the result']::text[],ARRAY['Demoing seat choices to a concert-hall client','Comparing two treatment options by ear','Teaching how materials change a room''s sound']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Auralization visual interface');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fcf29cf6-7423-5dfa-875c-4c599bf6ba80','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fcf29cf6-7423-5dfa-875c-4c599bf6ba80') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fcf29cf6-7423-5dfa-875c-4c599bf6ba80');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '09e4be13-4cff-5562-b00e-f61984823f71','Room acoustic ray cloud','A room acoustic ray cloud is a visualization from ray-tracing simulation that displays the many sound rays emitted from a source as they travel and reflect within a modeled room, forming a dense cloud of paths. It conveys how energy distributes in space and time, showing which regions receive strong direct and reflected energy and how rays scatter off surfaces.','Ray tracing models sound as many rays leaving a source. A ray cloud shows all those rays inside the room model. You see them spread out and bounce off surfaces. Dense areas get more sound energy. It gives a quick picture of how sound fills the space.','It gives an intuitive picture of how sound energy spreads and reflects in a room, complementing the numeric results of a simulation.','Acousticians view ray clouds to spot strong reflection paths and uneven energy before refining a room design.','Sound Visualization & Acoustic Imaging',ARRAY['Ray tracing','Reflection order visualization','Image-source method','Room acoustic simulation','Sound energy distribution']::text[],ARRAY['Treating the rays as real sound rather than a computational model','Assuming ray tracing captures low-frequency wave effects well','Reading ray density as an exact level']::text[],ARRAY['Spotting a strong reflection path in a model','Checking energy spread in an arena design','Teaching how ray tracing approximates sound']::text[],'advanced',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Room acoustic ray cloud');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '09e4be13-4cff-5562-b00e-f61984823f71','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='09e4be13-4cff-5562-b00e-f61984823f71') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='09e4be13-4cff-5562-b00e-f61984823f71');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '85ebcd83-d0e7-538e-af47-e7256484c512','Spectral decay map','A spectral decay map is a visualization of how the decay of sound varies with frequency, showing decay level or rate along both frequency and time axes. Related to the cumulative spectral decay or waterfall display, it reveals frequencies that ring on longer than others—whether from room modes, resonances, or a loudspeaker''s stored energy. It exposes frequency-dependent decay that a single reverberation figure would hide.','Sound does not always fade at the same rate at every pitch. A spectral decay map shows decay across both frequency and time. Frequencies that ring on longer stand out clearly. This can reveal room modes or a speaker resonance. A single decay number would hide these details.','It shows frequency-dependent decay, helping locate resonances and ringing that a broadband reverberation time cannot reveal.','Engineers read spectral decay or waterfall plots to find ringing room modes or a resonant loudspeaker before treating them.','Sound Visualization & Acoustic Imaging',ARRAY['Cumulative spectral decay','Waterfall plot','Reverberation time','Room mode','Resonance']::text[],ARRAY['Confusing a spectral decay map with a plain spectrum snapshot','Reading the earliest slice as if windowing did not affect it','Assuming one decay time fits all frequencies']::text[],ARRAY['Finding a ringing mode in a small studio','Checking a loudspeaker for stored-energy resonances','Comparing decay before and after treatment']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral decay map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '85ebcd83-d0e7-538e-af47-e7256484c512','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='85ebcd83-d0e7-538e-af47-e7256484c512') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='85ebcd83-d0e7-538e-af47-e7256484c512');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f1ce3fba-c226-5381-9597-4215b7a0d85b','Bioacoustic spectrogram','A spectrogram computed from recordings of animal sound, displaying acoustic energy as a function of time on the horizontal axis, frequency on the vertical axis, and amplitude as color or brightness, used to analyze the structure of vocalizations such as bird song, whale calls, insect stridulation, and bat echolocation. It is produced by a short-time Fourier transform of the signal, and its time-frequency resolution is set by the analysis window length. Bioacousticians choose window and overlap settings suited to the temporal and spectral scale of a species'' signals.','A spectrogram is a picture of sound. This kind shows sounds made by animals. Time runs left to right. Pitch runs bottom to top. Bright spots show the loud parts. It reveals the shape of a bird song or whale call.','It turns an animal sound into a visual pattern so its frequency, timing, and structure can be measured and compared across individuals, species, and recordings.','Researchers open field recordings in software such as Raven or Audacity to view bioacoustic spectrograms, measure call frequencies and durations, and label species in long-term monitoring datasets.','Bioacoustics & Ecoacoustics',ARRAY['Spectrogram','Short-time Fourier transform','Call contour','Ultrasonic spectrogram','Passive acoustic monitoring']::text[],ARRAY['Reading a spectrogram as a photo of the sound rather than an estimate whose detail depends on window settings','Forgetting that a long window sharpens frequency but blurs timing, while a short window does the reverse','Assuming color always means calibrated loudness when it usually shows relative energy only']::text[],ARRAY['Measuring the frequency range of a bird song from a field recording','Comparing whale call structure between two populations','Labeling species in a long-term acoustic monitoring archive']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bioacoustic spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f1ce3fba-c226-5381-9597-4215b7a0d85b','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f1ce3fba-c226-5381-9597-4215b7a0d85b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f1ce3fba-c226-5381-9597-4215b7a0d85b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '42c46d31-634e-5260-821e-2d9cbd02545d','Call contour','The trace of the dominant or fundamental frequency of an animal vocalization as it changes over the duration of the call, extracted from a spectrogram and plotted as a frequency-versus-time curve. The contour captures the shape of frequency modulation, whether rising, falling, or arched, and its slope, inflection points, and bandwidth serve as standard acoustic features for classifying calls and distinguishing species or individuals.','A call contour is a line that tracks a call''s pitch over time. It follows the strongest pitch from start to end. The line may rise, fall, or curve. Its shape helps tell one call or species from another.','It reduces a complex call to a simple pitch-over-time shape so researchers can quantify frequency modulation and compare the melodic pattern of calls.','Analysts trace call contours in bioacoustic software to classify bat, bird, or dolphin calls, feeding contour features such as slope and bandwidth into automatic classifiers.','Bioacoustics & Ecoacoustics',ARRAY['Bioacoustic spectrogram','Fundamental frequency','Frequency modulation','Whistle contour','Feature extraction']::text[],ARRAY['Confusing the contour of the fundamental with a harmonic overtone lying above it','Assuming the loudest spectrogram band is always the fundamental frequency','Treating a noisy or gapped contour as a real feature rather than a tracking error']::text[],ARRAY['Classifying dolphin whistles by the shape of their frequency contour','Separating two bat species by call slope','Measuring frequency modulation in a bird song phrase']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Call contour');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '42c46d31-634e-5260-821e-2d9cbd02545d','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='42c46d31-634e-5260-821e-2d9cbd02545d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='42c46d31-634e-5260-821e-2d9cbd02545d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '466c4b3d-8cd4-566e-b657-35b0732c3bf7','Echolocation spectrogram','A spectrogram of the biosonar pulses emitted by echolocating animals such as bats and toothed whales, displaying the brief, often frequency-modulated clicks or chirps in time and frequency. It typically shows steep downward or upward frequency sweeps, harmonics, and very short inter-pulse intervals. Because the pulses are short and often ultrasonic, a short analysis window and a high sample rate are required to resolve their fine time structure.','Some animals find things by listening to echoes. Bats and dolphins do this. This spectrogram shows their fast clicks and chirps. The sounds often sweep from high to low pitch. Short windows are needed to see their quick shape.','It reveals the fine time-frequency structure of biosonar signals so researchers can study how animals shape pulses to detect and locate prey.','Bat researchers record with ultrasonic detectors and view echolocation spectrograms to identify species from call shape and to study foraging behavior.','Bioacoustics & Ecoacoustics',ARRAY['Ultrasonic spectrogram','Bioacoustic spectrogram','Biosonar','Frequency-modulated sweep','Click train']::text[],ARRAY['Using too long an analysis window, which smears short pulses and hides their sweep','Sampling below the Nyquist rate for ultrasonic calls, which aliases or loses them','Confusing echolocation pulses with communication calls in the same recording']::text[],ARRAY['Identifying a bat species from the shape of its echolocation sweep','Studying how a dolphin adjusts clicks as it closes on prey','Counting pulse rate during a bat''s approach to a target']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Echolocation spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '466c4b3d-8cd4-566e-b657-35b0732c3bf7','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='466c4b3d-8cd4-566e-b657-35b0732c3bf7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='466c4b3d-8cd4-566e-b657-35b0732c3bf7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30b215d4-b833-5175-b1bd-b1db5db6019d','Ultrasonic spectrogram','A spectrogram displaying acoustic energy at frequencies above the upper limit of human hearing, conventionally above about 20 kilohertz, which requires a high sample rate and an ultrasonic-capable microphone. It is widely used to visualize bat echolocation and social calls, rodent vocalizations, and insect signals. The frequency axis extends well beyond the audible range, and time-frequency resolution again depends on the analysis window.','Some sounds are too high for people to hear. These are called ultrasound. This spectrogram shows those very high sounds. It needs a special microphone and a fast recorder. Bats, mice, and some insects make such sounds.','It makes inaudible high-frequency signals visible and measurable so researchers can study animals whose calls lie above the human hearing range.','Field teams deploy ultrasonic recorders to capture bat and rodent calls, then view ultrasonic spectrograms to identify species and behaviors that are otherwise silent to the ear.','Bioacoustics & Ecoacoustics',ARRAY['Echolocation spectrogram','Bioacoustic spectrogram','Sample rate','Nyquist frequency','Ultrasound']::text[],ARRAY['Recording at a sample rate too low to capture the ultrasonic band','Assuming a standard audio microphone captures ultrasound, when most roll off well below it','Forgetting that air absorbs high frequencies quickly, which shortens detection range']::text[],ARRAY['Surveying bat activity along a hedgerow at night','Studying ultrasonic courtship calls of mice in a lab','Detecting insect signals above the audible range']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasonic spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30b215d4-b833-5175-b1bd-b1db5db6019d','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30b215d4-b833-5175-b1bd-b1db5db6019d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30b215d4-b833-5175-b1bd-b1db5db6019d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c848e935-a1b5-5c09-992b-f24cbc0223c8','Seismic-acoustic spectrogram','A time-frequency display of low-frequency ground-borne or coupled ground-and-air vibrations, produced from seismometer or geophone data and sometimes paired infrasound sensors, used to visualize events such as earthquakes, volcanic tremor, or the seismic components of animal signals. Energy is typically concentrated at very low frequencies, so long analysis windows and low sample rates are used. The display helps separate overlapping geophysical and biological sources.','The ground itself can carry low vibrations. Special sensors pick these up. This spectrogram shows those slow, deep signals. It is used for quakes, volcanoes, and some animal signals. Elephants, for example, send low rumbles through the ground.','It visualizes very low-frequency vibrations traveling through the ground so analysts can detect and classify geophysical events or ground-coupled animal signals.','Volcano observatories and animal researchers view seismic-acoustic spectrograms from geophones to track tremor, quakes, or elephant rumbles felt through the ground.','Bioacoustics & Ecoacoustics',ARRAY['Infrasound spectrogram','Spectrogram','Geophone','Seismic tremor','Substrate-borne vibration']::text[],ARRAY['Confusing ground-borne seismic signals with airborne sound recorded at the same time','Using a high sample rate suited to audio when the energy sits only at very low frequencies','Ignoring sensor coupling to the ground, which strongly affects the recorded signal']::text[],ARRAY['Tracking volcanic tremor before an eruption','Studying seismic elephant communication through the ground','Separating a quake from cultural noise in a monitoring record']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Seismic-acoustic spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c848e935-a1b5-5c09-992b-f24cbc0223c8','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c848e935-a1b5-5c09-992b-f24cbc0223c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c848e935-a1b5-5c09-992b-f24cbc0223c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eca3cee2-7b4b-5271-99af-60fbe96bdbe5','Infrasound spectrogram','A spectrogram of sound below the nominal lower limit of human hearing, conventionally below about 20 hertz, produced from infrasound microphones or microbarometers. It is used to visualize signals from sources such as volcanoes, severe weather, ocean-wave microbaroms, large explosions, and low-frequency animal calls from elephants, whales, or cassowaries. Because the frequencies are so low, very long analysis windows and extended recording times are needed.','Some sounds are too low for people to hear. These are called infrasound. This spectrogram shows those very deep sounds. Volcanoes, storms, and big animals can make them. Long recordings are needed to see slow signals.','It makes very low-frequency sound visible so analysts can detect and study natural events and animal calls that lie below the human hearing range.','Monitoring networks view infrasound spectrograms to detect distant explosions or volcanic activity, and bioacousticians use them to study elephant and whale calls.','Bioacoustics & Ecoacoustics',ARRAY['Seismic-acoustic spectrogram','Spectrogram','Infrasound','Microbarom','Low-frequency call']::text[],ARRAY['Using short analysis windows that cannot resolve sub-20-hertz energy','Confusing wind noise on the sensor with true infrasonic signals','Assuming microphones built for audio can capture infrasound, when most cannot']::text[],ARRAY['Detecting a distant volcanic eruption from its infrasound','Studying long-range elephant calls below the hearing range','Monitoring severe storms that radiate infrasound']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infrasound spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eca3cee2-7b4b-5271-99af-60fbe96bdbe5','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eca3cee2-7b4b-5271-99af-60fbe96bdbe5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eca3cee2-7b4b-5271-99af-60fbe96bdbe5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'edb6de1e-99e3-5521-9963-5450247425a9','Acoustic event display','A visual interface that marks detected sound events on a time axis or over a spectrogram, drawing boxes, regions, or markers around segments an algorithm or annotator has identified as discrete events, such as a bird call, a gunshot, or a vehicle pass. It overlays detection results on the underlying audio representation so the timing, frequency extent, and label of each event can be reviewed and verified.','Sound recordings often hold many separate events. An acoustic event display marks each one it finds. It draws boxes or marks on a spectrogram or timeline. Each mark shows when an event happened and what it was. People use it to check the results.','It presents automatic or manual detections in context so an analyst can quickly see, verify, and correct which sounds were found and when.','In sound event detection tools, analysts review acoustic event displays to confirm flagged bird calls or gunshots and to correct false alarms before reporting.','Bioacoustics & Ecoacoustics',ARRAY['Sound event detection','Sound event timeline','Bioacoustic spectrogram','Annotation','Acoustic event']::text[],ARRAY['Trusting every marked event without checking for false detections','Assuming missing marks mean silence rather than missed detections','Confusing the display with the detector, since the display only shows the detector''s output']::text[],ARRAY['Verifying automatic bird-call detections in a monitoring project','Reviewing flagged gunshots in a wildlife protection recording','Correcting event boundaries during dataset annotation']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic event display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'edb6de1e-99e3-5521-9963-5450247425a9','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='edb6de1e-99e3-5521-9963-5450247425a9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='edb6de1e-99e3-5521-9963-5450247425a9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e4a353b7-58d2-5c90-b90d-ee85ab5491fa','Sound event localization and detection','A combined task, often abbreviated SELD, in which a system both detects the class and temporal activity of sound events and estimates their spatial direction of arrival, typically from multichannel or ambisonic audio. Widely studied through the DCASE challenge series, its output is commonly displayed as event labels along a timeline together with azimuth and elevation trajectories, uniting sound event detection with direction-of-arrival estimation into a single spatial-temporal description of a scene.','This task finds what sounds happen and where they come from. It works from recordings made with several microphones. It labels each sound and its direction. The result shows both the event and its angle over time. It joins detection with direction finding.','It answers both what sound occurred and from which direction, giving a spatial and temporal map of the sound sources in a scene.','Researchers train SELD models on ambisonic recordings and plot event labels with azimuth and elevation tracks to analyze scenes for robotics, monitoring, and smart devices.','Bioacoustics & Ecoacoustics',ARRAY['Sound event detection','Direction of arrival','Ambisonics','Acoustic scene map','Spatial audio heat map']::text[],ARRAY['Treating detection and localization as separate when this task couples them','Assuming a single microphone can give direction, when multichannel input is required','Confusing direction of arrival with distance, which the task usually does not give']::text[],ARRAY['Mapping which animal calls come from which direction in a forest array','Giving a robot awareness of nearby sound sources','Analyzing an urban scene for both event type and direction']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound event localization and detection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e4a353b7-58d2-5c90-b90d-ee85ab5491fa','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e4a353b7-58d2-5c90-b90d-ee85ab5491fa') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e4a353b7-58d2-5c90-b90d-ee85ab5491fa');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '54ddf470-f934-5181-b71d-1c747a6ca9e3','Audio embedding projection','A two- or three-dimensional visualization of high-dimensional audio feature vectors, called embeddings, produced by a machine-learning model, obtained by applying a dimensionality-reduction method such as principal component analysis, t-SNE, or UMAP to project each audio clip to a point in a low-dimensional space. Clips with similar learned features fall near one another, so clusters, outliers, and class structure in the embedding space become visible.','A model turns each sound into a long list of numbers. These lists are hard to view directly. An embedding projection shrinks them to two or three dimensions. Each sound becomes a dot on a map. Similar sounds sit close together.','It makes a model''s learned audio representation visible so researchers can inspect clustering, class separation, and outliers in a dataset.','Machine-learning engineers plot audio embedding projections to check whether a model groups species or sound classes sensibly and to spot mislabeled or unusual clips.','Bioacoustics & Ecoacoustics',ARRAY['Audio embedding','t-SNE audio map','UMAP audio embedding','Latent-space audio map','Dimensionality reduction']::text[],ARRAY['Reading distances between far-apart clusters as meaningful when methods like t-SNE distort them','Assuming the axes carry physical units, when projected axes are usually abstract','Forgetting that different random seeds or settings change the layout']::text[],ARRAY['Checking whether a bird-sound model separates species in feature space','Finding mislabeled clips that fall in the wrong cluster','Comparing embeddings from two models on the same dataset']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio embedding projection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '54ddf470-f934-5181-b71d-1c747a6ca9e3','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='54ddf470-f934-5181-b71d-1c747a6ca9e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='54ddf470-f934-5181-b71d-1c747a6ca9e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6aed09f4-73c4-5259-88e2-eedbdcb49c2d','t-SNE audio map','An audio embedding projection produced specifically with t-distributed stochastic neighbor embedding, a nonlinear dimensionality-reduction technique that models pairwise similarities between high-dimensional audio feature vectors as probabilities and arranges points in two dimensions to preserve local neighborhood structure. It excels at revealing local clusters of similar sounds but does not faithfully preserve global distances or relative cluster sizes.','This map places sounds as dots in two dimensions. It uses a method called t-SNE. The method keeps similar sounds close together. It is good at showing small groups. But the gaps between far groups can mislead you.','It exposes local cluster structure in a set of audio features, helping reveal groups of similar sounds within a dataset.','Analysts use t-SNE audio maps to visualize clusters of bird calls or music clips and to explore how a model groups similar sounds.','Bioacoustics & Ecoacoustics',ARRAY['Audio embedding projection','UMAP audio embedding','Dimensionality reduction','Latent-space audio map','Cluster analysis']::text[],ARRAY['Interpreting the distance between separate clusters as meaningful','Reading cluster sizes as real, since t-SNE does not preserve them','Using a single perplexity setting and assuming the layout is unique']::text[],ARRAY['Exploring clusters of animal calls in a feature set','Checking class separation in a sound classifier','Spotting outlier recordings far from any group']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='t-SNE audio map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6aed09f4-73c4-5259-88e2-eedbdcb49c2d','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6aed09f4-73c4-5259-88e2-eedbdcb49c2d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6aed09f4-73c4-5259-88e2-eedbdcb49c2d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34e97142-8d2d-56ac-9563-594607e9a7f9','UMAP audio embedding','An audio embedding projection produced with Uniform Manifold Approximation and Projection, a manifold-learning technique that builds a fuzzy topological representation of high-dimensional audio features and optimizes a low-dimensional layout to preserve local structure and, better than t-SNE, some global structure. It is often faster than t-SNE and is widely used to cluster and browse large bioacoustic and audio datasets.','This map also turns sounds into dots in two dimensions. It uses a method called UMAP. Like t-SNE, it keeps similar sounds close. It often keeps the big picture better. It also runs fast on large sets.','It reduces high-dimensional audio features to a viewable map, preserving local groupings and some large-scale structure for exploring datasets.','Bioacousticians use UMAP audio embeddings to browse thousands of clips, form clusters of call types, and guide semi-automatic labeling.','Bioacoustics & Ecoacoustics',ARRAY['Audio embedding projection','t-SNE audio map','Dimensionality reduction','Latent-space audio map','Manifold learning']::text[],ARRAY['Assuming UMAP distances are fully metric, when only some global structure is kept','Treating UMAP settings as neutral, when neighbor count and minimum distance reshape the map','Reading tiny gaps between clusters as strong class boundaries']::text[],ARRAY['Clustering a large archive of frog calls for review','Guiding active labeling from grouped clips','Comparing call repertoires across sites']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='UMAP audio embedding');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34e97142-8d2d-56ac-9563-594607e9a7f9','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34e97142-8d2d-56ac-9563-594607e9a7f9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34e97142-8d2d-56ac-9563-594607e9a7f9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '14db95c5-a571-5688-98f3-93aab6f091c5','Latent-space audio map','A visualization of the internal, learned representation, called the latent space, that a neural network assigns to audio, typically shown by projecting the latent vectors of many clips into two or three dimensions. Unlike a raw feature map, it reflects the compressed representation an autoencoder, embedding model, or generative model has learned. Nearby points share features the model deems similar, and the geometry can expose how the model organizes sound.','A neural network builds its own inner code for sound. This hidden code is called the latent space. A latent-space map shows that code as points. Sounds the model finds alike land near each other. It shows how the model organizes sound.','It reveals how a model internally represents and organizes audio, exposing structure, similarity, and gaps in its learned latent space.','Researchers plot latent-space audio maps from autoencoders or embedding models to interpret what a model has learned and to sample or interpolate between sounds.','Bioacoustics & Ecoacoustics',ARRAY['Audio embedding projection','Latent space','Autoencoder','t-SNE audio map','UMAP audio embedding']::text[],ARRAY['Assuming latent dimensions match human sound features, when they are learned rather than designed','Treating a projected latent map as the true high-dimensional space','Expecting smooth, meaningful interpolation everywhere in the latent space']::text[],ARRAY['Interpreting what an autoencoder learned about bird song','Interpolating between two sounds in a generative model','Finding gaps where a model represents no data']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Latent-space audio map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '14db95c5-a571-5688-98f3-93aab6f091c5','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='14db95c5-a571-5688-98f3-93aab6f091c5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='14db95c5-a571-5688-98f3-93aab6f091c5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7be43daa-506e-5361-81f0-adf305f6034f','Feature map','In a convolutional neural network, the two-dimensional array of activations produced when one learned filter is convolved across its input, so that each layer yields a stack of feature maps that each highlight where a particular pattern occurs. For audio, feature maps computed over a spectrogram input show where time-frequency patterns such as onsets or harmonic bands are detected. More generally the term also covers any visualized array of derived acoustic features.','A neural network scans its input with small filters. Each filter looks for one pattern. Its output is a grid called a feature map. Bright spots show where that pattern was found. A layer makes many such maps at once.','It shows where in the input a given learned filter responds, revealing which patterns a network layer extracts from the sound.','When debugging an audio network, engineers visualize feature maps over a spectrogram to see which time-frequency patterns the early and deep layers respond to.','Bioacoustics & Ecoacoustics',ARRAY['Convolutional neural network','Activation map','Spectrogram','Convolution filter','Saliency map']::text[],ARRAY['Confusing one feature map, a single filter''s output, with the whole layer''s stack of maps','Assuming feature maps are directly interpretable, when deep ones are often abstract','Mixing up a feature map with the input spectrogram it was computed from']::text[],ARRAY['Inspecting what an audio network''s first layer detects','Comparing shallow versus deep feature maps in a classifier','Debugging why a model misses a certain call type']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Feature map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7be43daa-506e-5361-81f0-adf305f6034f','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7be43daa-506e-5361-81f0-adf305f6034f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7be43daa-506e-5361-81f0-adf305f6034f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b00bcc48-cd74-5824-95be-79aa0ede568e','Saliency map','A visualization that highlights which parts of an input most influenced a model''s output, classically computed as the magnitude of the gradient of the class score with respect to each input value. For audio, a saliency map is overlaid on the input spectrogram to show which time-frequency regions most affected the prediction, giving a fine-grained, input-level explanation of the decision.','A saliency map shows what the model paid attention to. It marks the input parts that mattered most. For sound, it highlights spots on the spectrogram. Bright spots are the ones that changed the answer. It helps explain a model''s choice.','It attributes a model''s decision to specific input regions, helping explain and debug why a network made a particular prediction.','To check an audio classifier, engineers compute saliency maps over spectrograms to confirm the model uses the actual call and not background noise.','Bioacoustics & Ecoacoustics',ARRAY['Grad-CAM spectrogram','Class activation map','Attention map','Feature map','Model interpretability']::text[],ARRAY['Treating a saliency map as proof of reasoning rather than a rough attribution','Assuming raw gradient saliency is stable, when it can be noisy and fragile','Confusing saliency, which is input attribution, with attention, which is internal weighting']::text[],ARRAY['Checking that a bird classifier focuses on the call, not the noise','Debugging a model that keys on a background artifact','Explaining a single prediction to a domain expert']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Saliency map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b00bcc48-cd74-5824-95be-79aa0ede568e','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b00bcc48-cd74-5824-95be-79aa0ede568e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b00bcc48-cd74-5824-95be-79aa0ede568e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f8d5657-2b64-5d58-ac6d-9a4ab57d2445','Attention map','A visualization of the attention weights inside a neural network, especially a transformer or attention-based audio model, showing how strongly the model links each output position to each input position. Displayed over a spectrogram or token sequence, it reveals which time-frequency regions or frames the model weighted most heavily when forming a representation or prediction, offering a window into the model''s internal focus.','Some models weigh each input part when they decide. These weights are called attention. An attention map draws those weights. It shows which parts of the sound the model leaned on. Strong links show up as bright areas.','It exposes the internal weighting a model gives to different input parts, helping show where an attention-based network focuses.','Researchers plot attention maps from transformer audio models over spectrograms to see which frames or bands drive a classification or transcription.','Bioacoustics & Ecoacoustics',ARRAY['Saliency map','Class activation map','Transformer','Self-attention','Feature map']::text[],ARRAY['Reading attention weights as a full causal explanation of the output','Confusing attention, an internal weighting, with saliency, an input gradient','Assuming one attention head tells the whole story, when models use many']::text[],ARRAY['Inspecting which frames a speech model attends to','Comparing attention across heads in an audio transformer','Explaining where a model focuses in a long recording']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attention map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f8d5657-2b64-5d58-ac6d-9a4ab57d2445','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f8d5657-2b64-5d58-ac6d-9a4ab57d2445') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f8d5657-2b64-5d58-ac6d-9a4ab57d2445');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e7609d16-0a4c-5fd1-b547-a6e28cac6543','Activation map','A visualization of the activations, or outputs, of the units in a neural-network layer in response to a given input, showing the spatial pattern of response for a single channel or the aggregate response across a layer. For an audio network operating on a spectrogram, an activation map indicates where and how strongly units fired for time-frequency structure. The term overlaps with feature map but emphasizes the response to a specific input.','A neural network''s units switch on for some inputs. Their output strength is called activation. An activation map shows this response as a grid. Bright areas mark where units fired hard. It shows how the network reacts to one sound.','It reveals how strongly and where a layer''s units respond to a given input, helping interpret what the network reacts to.','Engineers view activation maps from an audio network to see which internal units respond to a specific call and how activity changes with depth.','Bioacoustics & Ecoacoustics',ARRAY['Feature map','Class activation map','Saliency map','Convolutional neural network','Model interpretability']::text[],ARRAY['Using activation map and feature map as if identical, without noting the input-response emphasis','Assuming strong activation always means importance for the final class','Reading deep activations literally when they are highly abstract']::text[],ARRAY['Seeing which units respond to a specific animal call','Tracking how activations change from shallow to deep layers','Debugging a dead or saturated layer']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Activation map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e7609d16-0a4c-5fd1-b547-a6e28cac6543','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e7609d16-0a4c-5fd1-b547-a6e28cac6543') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e7609d16-0a4c-5fd1-b547-a6e28cac6543');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3fb49640-cf41-5bfc-81df-75247417406e','Class activation map','A class-discriminative visualization, abbreviated CAM, that highlights the image or spectrogram regions a convolutional network used to predict a specific class, produced by taking a weighted sum of the final convolutional feature maps using the trained class weights that follow a global average pooling layer. The resulting map, upsampled to the input size, localizes the evidence for a class. It requires a specific global-average-pooling architecture, a constraint that Grad-CAM later generalized.','A class activation map shows where a model saw a class. It works on the last layer of a network. It blends the feature maps using the class weights. The result marks the regions that led to the label. It needs a certain network design.','It localizes the evidence a network used for a particular class, turning a whole-input prediction into a region-level explanation.','With a global-average-pooling network, engineers compute class activation maps over spectrograms to see which call regions drove a species prediction.','Bioacoustics & Ecoacoustics',ARRAY['Grad-CAM spectrogram','Activation map','Global average pooling','Saliency map','Convolutional neural network']::text[],ARRAY['Assuming CAM works on any architecture, when it needs global average pooling before the classifier','Confusing CAM with Grad-CAM, which removes that architectural constraint','Reading the coarse map as pixel-precise when it is upsampled from a small grid']::text[],ARRAY['Localizing the call region behind a species label','Checking that a model relies on signal, not noise, for its class','Teaching interpretability on a simple pooling network']::text[],'advanced','M_c(x,y) = sum_k [ w_k^c * f_k(x,y) ]','The class activation map for class c at a spatial location equals the sum, over the feature-map channels k, of the class weight for channel k and class c multiplied by the activation of channel k at that location.','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class activation map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3fb49640-cf41-5bfc-81df-75247417406e','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3fb49640-cf41-5bfc-81df-75247417406e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3fb49640-cf41-5bfc-81df-75247417406e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a12db1b6-4efc-54e1-b337-80251706b810','Grad-CAM spectrogram','A gradient-weighted class activation mapping visualization applied to an audio spectrogram, highlighting the time-frequency regions most responsible for a network''s class prediction. Grad-CAM weights each final convolutional feature map by the global-average-pooled gradient of the class score with respect to that map, sums the weighted maps, and applies a rectified linear unit. Unlike the original CAM it works on almost any convolutional architecture without retraining.','This is a heat overlay on a sound picture. It shows what a model used to pick a class. It weighs each feature map by its gradient. Then it adds them and keeps the positive parts. Warm colors mark the key time and pitch regions.','It explains which spectrogram regions drove a class decision, generalizing CAM to work on most convolutional networks without changing their design.','To audit an audio network, engineers overlay a Grad-CAM heatmap on the spectrogram to confirm the model focuses on the target call.','Bioacoustics & Ecoacoustics',ARRAY['Class activation map','Saliency map','Bioacoustic spectrogram','Convolutional neural network','Model interpretability']::text[],ARRAY['Treating the coarse heatmap as pixel-accurate localization','Forgetting that the rectified linear unit keeps only evidence for the class, not against it','Assuming a sharp map means the model is correct, when it only shows focus']::text[],ARRAY['Auditing whether a bird network focuses on the call','Finding that a model keys on a recording artifact','Comparing focus across two competing models']::text[],'advanced','L^c = ReLU( sum_k [ a_k^c * A^k ] ),  a_k^c = (1/Z) * sum_i sum_j ( dy^c / dA_ij^k )','The Grad-CAM map for class c is the rectified linear unit of a weighted sum of feature maps A over channels k. Each weight is the average, over all spatial locations, of the gradient of the class score for class c with respect to that feature map.','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Grad-CAM spectrogram');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a12db1b6-4efc-54e1-b337-80251706b810','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a12db1b6-4efc-54e1-b337-80251706b810') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a12db1b6-4efc-54e1-b337-80251706b810');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7438f73b-62ac-5ad0-b5c2-62acace284cb','Audio feature image','The general practice of arranging audio-derived features into a two-dimensional array treated as an image so it can be fed to computer-vision or convolutional models. Beyond the plain spectrogram, this includes representations such as mel-spectrograms, chromagrams, cepstral-coefficient images, scalograms, and rhythm or modulation features rendered as pixel grids. The audio problem is thereby recast as an image-recognition problem.','Sound can be turned into a flat grid of features. That grid is treated like a picture. A spectrogram is one example. Others show pitch classes or rhythm. Image models can then read the sound.','It reframes audio as an image so powerful image-based neural networks can be applied to sound tasks.','Engineers convert clips into mel-spectrogram or cepstral-coefficient images and feed them to convolutional networks for tasks like species or scene classification.','Bioacoustics & Ecoacoustics',ARRAY['Bioacoustic spectrogram','Mel-spectrogram','Feature map','Convolutional neural network','Scalogram']::text[],ARRAY['Assuming any feature image works equally well, when the choice strongly affects results','Treating the axes as ordinary image pixels, when time and frequency carry real meaning','Forgetting that scaling and normalization of the feature image change model behavior']::text[],ARRAY['Feeding mel-spectrogram images to a bird classifier','Comparing cepstral images against spectrograms as network inputs','Turning rhythm features into images for genre tagging']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audio feature image');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7438f73b-62ac-5ad0-b5c2-62acace284cb','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7438f73b-62ac-5ad0-b5c2-62acace284cb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7438f73b-62ac-5ad0-b5c2-62acace284cb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2aa29427-3415-5038-876a-b4ad4fd8b5c7','Acoustic scene map','A visualization that summarizes the sound sources present in an environment and, often, their spatial arrangement, produced from acoustic scene analysis or sound event localization. It may depict which source types are active and where they lie relative to a microphone array, giving an overview of the whole auditory scene rather than a single event. Usage ranges from labeled spatial layouts to activity summaries over an area.','A scene holds many sounds at once. An acoustic scene map sums them up. It shows which sources are active and where. It gives an overview of the whole scene. It comes from analyzing many sounds together.','It provides a high-level picture of what sound sources fill an environment and roughly where they are, supporting scene understanding.','In smart devices or robotics, engineers build acoustic scene maps from array recordings to show the layout of talkers, machines, or animals in a space.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic scene analysis','Sound event localization and detection','Spatial audio heat map','Acoustic occupancy map','Direction of arrival']::text[],ARRAY['Confusing a scene map, which is a many-source overview, with a single event display','Assuming exact positions when many maps give only direction or rough zones','Treating the map as complete when quiet or masked sources may be missing']::text[],ARRAY['Summarizing the sound sources in a busy room for a smart speaker','Giving a robot an overview of nearby sound sources','Mapping which habitats hold which animal sounds']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic scene map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2aa29427-3415-5038-876a-b4ad4fd8b5c7','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2aa29427-3415-5038-876a-b4ad4fd8b5c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2aa29427-3415-5038-876a-b4ad4fd8b5c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '32aeb2ab-1cb1-56d2-b3c5-ae1efa0979fe','Sound event timeline','A visualization that plots detected sound events along a time axis, showing each event''s onset, offset, and class label, often as horizontal bars or a piano-roll layout with one row per class. It summarizes the temporal activity of sound classes across a recording, making overlapping and recurring events easy to see and review, and it is a standard output of sound event detection systems.','A sound event timeline lists events along time. Each event shows its start and end. Rows or bars stand for each sound type. Overlaps and repeats are easy to see. It sums up a whole recording at a glance.','It shows when each type of sound occurs across a recording, giving a compact temporal summary of detection results.','In sound event detection tools, analysts read a sound event timeline to review which classes were active when and to spot patterns over hours of audio.','Bioacoustics & Ecoacoustics',ARRAY['Sound event detection','Acoustic event display','Bioacoustic spectrogram','Annotation','Sound event localization and detection']::text[],ARRAY['Reading a timeline as exact when detection boundaries carry error','Assuming empty rows mean silence rather than missed detections','Ignoring overlapping events stacked in the same time span']::text[],ARRAY['Reviewing which species called through a dawn chorus','Summarizing machine sounds across a factory shift','Spotting recurring events over a night of monitoring']::text[],'beginner',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound event timeline');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '32aeb2ab-1cb1-56d2-b3c5-ae1efa0979fe','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='32aeb2ab-1cb1-56d2-b3c5-ae1efa0979fe') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='32aeb2ab-1cb1-56d2-b3c5-ae1efa0979fe');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a5b7c60-0ec6-5b1e-aea2-e829c5faa198','Acoustic occupancy map','A spatial map indicating where sound sources are active or likely present, derived from acoustic data. In ecology it draws on passive acoustic monitoring and occupancy modeling to estimate the probability that a species is present across survey sites, correcting for imperfect detection. In acoustic sensing and robotics it can mark grid cells where sound activity or sources are detected. In both senses it converts detections into a spatial picture of presence.','An occupancy map shows where sounds are likely present. It turns many detections into a map of places. Each spot shows if a source is active or likely there. In ecology it estimates where a species lives. It builds a picture of presence across an area.','It turns acoustic detections into a spatial estimate of where sources or species are present, supporting monitoring and mapping.','Ecologists combine recorder-array detections with occupancy models to map where a species is likely present across a landscape.','Bioacoustics & Ecoacoustics',ARRAY['Passive acoustic monitoring','Occupancy model','Acoustic scene map','Spatial audio heat map','Sound event detection']::text[],ARRAY['Reading absence of detections as true absence rather than possible non-detection','Ignoring detection probability, which occupancy models exist to correct','Confusing where a sound was detected with where its source truly is']::text[],ARRAY['Mapping likely presence of a frog species across wetland sites','Showing grid cells with active sound sources for a robot','Guiding survey effort toward under-sampled areas']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic occupancy map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a5b7c60-0ec6-5b1e-aea2-e829c5faa198','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a5b7c60-0ec6-5b1e-aea2-e829c5faa198') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a5b7c60-0ec6-5b1e-aea2-e829c5faa198');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f16b9f49-e34b-525b-b280-505828263adf','Spatial audio heat map','A color-coded visualization of acoustic energy or source likelihood across directions or physical locations, in which warmer colors mark stronger sound or higher source probability. Produced by beamforming, an acoustic camera, or direction-of-arrival estimation, it overlays the sound-energy distribution on an angular grid or on a photograph of the scene, showing where sound is coming from.','A heat map paints sound energy with color. Warm colors mark strong sound. It shows the direction or place a sound comes from. It may lie over a photo of the scene. It reveals where the loudest sources are.','It shows how sound energy is distributed across directions or locations, helping locate and rank sound sources in a scene.','Acoustic-camera operators overlay a spatial audio heat map on a video frame to find a rattle in a car or a leak in a pipe.','Bioacoustics & Ecoacoustics',ARRAY['Beamforming','Acoustic camera','Direction of arrival','Ambisonic energy map','Acoustic scene map']::text[],ARRAY['Reading a hot spot as the exact source when resolution is limited by array size and frequency','Ignoring side lobes that create false hot spots','Assuming color is a calibrated level when it often shows relative energy']::text[],ARRAY['Finding a squeak in a car with an acoustic camera','Locating a noisy component on a machine','Showing where the loudest sources sit in a room']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spatial audio heat map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f16b9f49-e34b-525b-b280-505828263adf','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f16b9f49-e34b-525b-b280-505828263adf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f16b9f49-e34b-525b-b280-505828263adf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fb8165e0-7760-59fb-afb0-756f926cf024','Ambisonic energy map','A directional visualization of sound energy computed from an ambisonic, or spherical-harmonic, recording, showing how acoustic energy or intensity is distributed over directions on a sphere. From the B-format or higher-order components, an energy or intensity vector is derived for each time-frequency bin and mapped onto a spherical or planar direction grid, revealing the dominant directions of arrival in the sound field.','An ambisonic recording catches sound from all sides. An energy map shows where that sound comes from. It turns the recording into energy over a sphere. Bright areas mark strong directions. It reveals the main sources around the microphone.','It converts an ambisonic recording into a directional energy picture, showing which directions carry the most sound.','Spatial-audio engineers compute ambisonic energy maps from B-format recordings to analyze room acoustics or to find sources for virtual reality and 360-degree video.','Bioacoustics & Ecoacoustics',ARRAY['Ambisonics','B-format visualizer','Spatial audio heat map','Direction of arrival','Spherical harmonic display']::text[],ARRAY['Assuming first-order ambisonics gives sharp direction, when its spatial resolution is limited','Confusing an energy direction with a clean single-source position in reverberant rooms','Ignoring that higher order is needed for finer directional detail']::text[],ARRAY['Analyzing source directions in a 360-degree video recording','Studying reflections in a room from a B-format capture','Finding dominant sound directions for virtual reality audio']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambisonic energy map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fb8165e0-7760-59fb-afb0-756f926cf024','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fb8165e0-7760-59fb-afb0-756f926cf024') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fb8165e0-7760-59fb-afb0-756f926cf024');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '629bda16-4cf2-5504-9f76-0ca714eae3ca','Spherical harmonic display','A visualization of the spatial components of a sound field expressed in the spherical-harmonic basis, the mathematical functions used to describe directional patterns and to define the channel format of ambisonic audio. It may show the individual harmonic patterns, with their positive and negative lobes over a sphere, or the per-order energy of a decomposed field, illustrating how directional information is distributed across harmonic orders and degrees.','Sound around a point can be split into simple shape patterns. These patterns are called spherical harmonics. This display draws those shapes on a sphere. It can also show how much energy each pattern holds. It shows how direction is built from simple parts.','It illustrates how a sound field is decomposed into spherical-harmonic components, clarifying the basis behind ambisonic spatial audio.','Spatial-audio developers use spherical harmonic displays to teach and debug ambisonic encoding and to see which orders carry a field''s directional energy.','Bioacoustics & Ecoacoustics',ARRAY['Spherical harmonics','Ambisonics','B-format visualizer','Ambisonic energy map','Higher-order ambisonics']::text[],ARRAY['Confusing the harmonic basis patterns with the actual sound sources','Assuming low orders capture fine direction, when higher orders are needed','Mixing up harmonic degree and order when reading the display']::text[],ARRAY['Teaching how ambisonics encodes direction','Debugging an ambisonic encoder''s channel order','Showing the per-order energy of a recorded field']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical harmonic display');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '629bda16-4cf2-5504-9f76-0ca714eae3ca','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='629bda16-4cf2-5504-9f76-0ca714eae3ca') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='629bda16-4cf2-5504-9f76-0ca714eae3ca');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e3e75e0c-beab-56f3-a9f5-f86bc7b73475','B-format visualizer','A tool that displays the components of first-order ambisonic B-format audio, namely the omnidirectional pressure channel W and the three figure-of-eight velocity channels X, Y, and Z, or a directional picture derived from them. It may show per-channel waveforms and levels or compute an intensity and direction vector to indicate where sound is arriving from, giving insight into a B-format recording''s spatial content.','B-format is a four-channel way to store surround sound. One channel is the overall level. Three others point front-back, left-right, and up-down. A B-format visualizer shows these channels. It can also show the direction sound comes from.','It exposes the channels and directional content of a B-format recording, helping engineers check and understand ambisonic captures.','Ambisonic engineers use a B-format visualizer to verify channel order and polarity and to see source directions in a recording before mixing.','Bioacoustics & Ecoacoustics',ARRAY['Ambisonics','B-format','Ambisonic energy map','Spherical harmonic display','Direction of arrival']::text[],ARRAY['Mixing up channel ordering and normalization conventions such as FuMa and ambiX','Reversing a velocity channel''s polarity, which flips the mapped direction','Assuming first-order B-format resolves closely spaced sources sharply']::text[],ARRAY['Checking B-format channel order before a virtual reality mix','Finding a polarity error in an ambisonic recording','Seeing source directions in a 360-degree capture']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='B-format visualizer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e3e75e0c-beab-56f3-a9f5-f86bc7b73475','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e3e75e0c-beab-56f3-a9f5-f86bc7b73475') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e3e75e0c-beab-56f3-a9f5-f86bc7b73475');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2f6800d-c27d-58b6-948c-690e8287c218','Directionality map','A visualization showing the direction from which sound energy arrives at a microphone or array, mapping estimated direction-of-arrival or energy over azimuth and, often, elevation. Built from beamforming, intensity analysis, or ambisonic processing, it indicates the bearings of dominant sources. It is closely related to a spatial audio heat map but focuses specifically on angle rather than physical location.','A directionality map shows where sound comes from. It marks the angles of the main sources. It is built from array or ambisonic data. Bright areas point to strong directions. It focuses on angle, not exact place.','It reveals the bearings of sound sources around a sensor, helping identify from which directions sound arrives.','Engineers use directionality maps from microphone arrays to point cameras at talkers or to steer beams toward a source.','Bioacoustics & Ecoacoustics',ARRAY['Direction of arrival','Spatial audio heat map','Beamforming','Ambisonic energy map','Sound event localization and detection']::text[],ARRAY['Confusing direction, which is angle only, with full localization that also includes distance','Trusting a single bearing in a reverberant room with many reflections','Ignoring front-back confusion that some array geometries cause']::text[],ARRAY['Steering a camera toward the active talker','Finding the bearing of a machine noise','Tracking a moving source''s angle over time']::text[],'intermediate',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Directionality map');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2f6800d-c27d-58b6-948c-690e8287c218','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2f6800d-c27d-58b6-948c-690e8287c218') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2f6800d-c27d-58b6-948c-690e8287c218');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bdab39f9-c625-5d0b-94c5-b12a12daa317','Acoustic intensity video','A time-varying visualization of acoustic intensity, the vector product of sound pressure and particle velocity that gives the direction and magnitude of sound-energy flow, rendered as successive frames so a changing sound field can be watched over time. Often overlaid on a scene from an acoustic camera or an intensity-probe array, it animates how energy and source activity move through space.','Sound carries energy that flows in a direction. This flow is called acoustic intensity. This video shows that flow frame by frame. It plays like a movie over a scene. You can watch sound sources turn on and move.','It shows how sound-energy flow and source activity change over time and space, animating a moving or intermittent sound field.','Acoustic-camera users record intensity video to watch a rattle come and go or to see how noise moves across a machine during operation.','Bioacoustics & Ecoacoustics',ARRAY['Sound intensity','Acoustic camera','Spatial audio heat map','Beamforming','Particle velocity']::text[],ARRAY['Confusing sound intensity, which is energy flow, with sound pressure alone','Reading frame hot spots as exact sources despite limited resolution','Ignoring reflections that make energy flow look like a false source']::text[],ARRAY['Watching an intermittent rattle appear in a car cabin','Seeing noise move across a running machine','Studying how a source radiates over time']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic intensity video');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bdab39f9-c625-5d0b-94c5-b12a12daa317','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bdab39f9-c625-5d0b-94c5-b12a12daa317') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bdab39f9-c625-5d0b-94c5-b12a12daa317');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2ed59858-db33-541f-82d4-f2cf4bba8879','Multimodal acoustic visualization','A visualization that combines acoustic data with one or more other modalities, such as camera images, video, depth or lidar, robot sensor data, or model outputs, to present sound in context. Examples include overlaying a sound-energy heat map on a video frame, fusing acoustic detections with visual object tracks, or pairing spectrograms with synchronized imagery. The aim is a richer, cross-referenced picture than sound alone provides.','Some displays mix sound data with other kinds of data. They may add camera images or video. They may add robot or depth sensors. This is multimodal acoustic visualization. It shows sound together with what else is happening.','It places acoustic information in the context of other sensor data, giving a fuller, cross-referenced view of a scene than sound alone.','Engineers overlay acoustic heat maps on video or fuse sound detections with camera tracking in robotics, surveillance, and augmented-reality systems.','Bioacoustics & Ecoacoustics',ARRAY['Acoustic camera','Spatial audio heat map','Sensor fusion','Sound event localization and detection','Acoustic scene map']::text[],ARRAY['Assuming the sound and image are aligned without careful spatial and time calibration','Letting the visual layer hide errors in the underlying acoustic estimate','Treating fused data as more certain than its weakest sensor']::text[],ARRAY['Overlaying a noise heat map on a machine''s video','Fusing sound and vision for a robot''s awareness','Pairing spectrograms with video in a wildlife study']::text[],'advanced',NULL,NULL,'bf6dba82-ae3e-4f97-a565-0d22c5f80fd7' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Multimodal acoustic visualization');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2ed59858-db33-541f-82d4-f2cf4bba8879','bf6dba82-ae3e-4f97-a565-0d22c5f80fd7',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2ed59858-db33-541f-82d4-f2cf4bba8879') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2ed59858-db33-541f-82d4-f2cf4bba8879');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cd8a8941-f54e-50dc-9791-47c10b7de80d','Root mean square pressure','The square root of the time-averaged square of the instantaneous sound pressure over a stated interval. Because acoustic energy and intensity are proportional to the mean square pressure, the rms value, rather than the peak or instantaneous value, is the pressure amplitude used to characterise steady-state sound and to compute sound pressure level. For a pure sinusoid the rms pressure equals the peak pressure divided by the square root of two.','This is a kind of average of the changing sound pressure. It squares the pressure, takes the mean, then takes the square root. It gives one steady number for a sound that keeps changing. Meters use it to report sound level.','It reduces a rapidly varying pressure waveform to a single amplitude that tracks the energy content of the sound, providing the pressure value on which sound pressure level and most steady-state acoustic measurements are based.','Sound level meters and analysers compute rms pressure over a time window before converting it to a level in decibels; technicians rely on it when reading steady levels, calibrating microphones, or comparing noise sources.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sound pressure','Sound pressure level','Peak pressure','Crest factor','Mean square pressure']::text[],ARRAY['Confusing rms pressure with peak pressure, which differ by the crest factor','Assuming the peak-to-rms ratio is always the square root of two, which holds only for sinusoids','Forgetting that the rms value depends on the averaging time chosen for non-steady signals']::text[],ARRAY['Reading a steady noise level on a sound level meter','Calibrating a measurement microphone with a known rms tone','Comparing the rms pressure of two machines at a fixed distance']::text[],'intermediate','p_rms = √( (1/T) ∫₀ᵀ p²(t) dt );  sinusoid: p_rms = p̂ / √2','Root-mean-square pressure equals the square root of the pressure squared and averaged over the time interval; for a sine wave it is the peak pressure divided by the square root of two.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Root mean square pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cd8a8941-f54e-50dc-9791-47c10b7de80d','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cd8a8941-f54e-50dc-9791-47c10b7de80d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cd8a8941-f54e-50dc-9791-47c10b7de80d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ede10c19-1b43-5a70-ad54-8412d21a42c0','Sound energy level','A logarithmic measure of sound energy, defined as ten times the base-ten logarithm of the ratio of a given sound energy to a reference sound energy. The internationally standardised reference sound energy is one picojoule, equal to ten to the power minus twelve joules. It expresses a quantity of acoustic energy, such as the energy delivered by a transient event, on a decibel scale, and is distinct from sound exposure level, which is based on time-integrated squared pressure.','This puts a sound''s total energy on a decibel scale. It compares that energy to a fixed tiny value. The value is one trillionth of a joule. More energy gives a higher level.','It lets an amount of acoustic energy be reported in decibels against a fixed reference, so energy from events or sources can be compared on the same logarithmic scale used for other acoustic levels.','It appears in acoustics standards and laboratory reports where the energy of transient or accumulated sound is quantified, complementing power-based and pressure-based levels in room and source characterisation.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sound energy','Sound exposure level','Sound power level','Reference quantity','Decibel']::text[],ARRAY['Confusing sound energy level with sound exposure level or sound power level','Using the wrong reference energy instead of one picojoule','Treating it as a pressure quantity and applying the twenty-times-log rule']::text[],ARRAY['Reporting the acoustic energy of a transient event in decibels','Comparing accumulated sound energy between two measurements','Documenting energy-based descriptors in an acoustics test report']::text[],'intermediate','L_E = 10·log₁₀(E / E₀) dB,  E₀ = 1 pJ = 10⁻¹² J','Sound energy level equals ten times the base-ten logarithm of the sound energy divided by the reference energy of one picojoule.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound energy level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ede10c19-1b43-5a70-ad54-8412d21a42c0','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ede10c19-1b43-5a70-ad54-8412d21a42c0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ede10c19-1b43-5a70-ad54-8412d21a42c0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b255bba9-61d1-5e85-b266-5cd701e8875f','Volume velocity','The volumetric flow rate of fluid produced by a vibrating surface or through an opening, equal to the integral of the normal component of particle velocity over the area of interest; for a small piston or aperture with uniform velocity it is the product of surface area and particle velocity. Expressed in cubic metres per second, it characterises the source strength of a simple acoustic source and links particle motion to acoustic impedance in ports, horns, ducts, and loudspeaker systems.','This is how much air a source pushes each second. It multiplies the moving area by how fast it moves. A big cone moving fast shifts more air. It sets how strong a simple sound source is.','It quantifies how much fluid a source displaces per unit time, serving as the source-strength variable that, together with acoustic impedance, determines the pressure a source radiates.','Loudspeaker and enclosure designers use volume velocity when modelling port and cone output; it underlies lumped-element analysis of Helmholtz resonators, horns, and duct networks.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Particle velocity','Acoustic impedance','Source strength','Acoustic inertance','Sound power']::text[],ARRAY['Confusing volume velocity in cubic metres per second with particle velocity in metres per second','Ignoring the area term and treating cone speed alone as output','Assuming uniform velocity across a large radiating surface']::text[],ARRAY['Modelling the air output of a loudspeaker port','Analysing a Helmholtz resonator as a lumped element','Estimating the source strength of a small vibrating panel']::text[],'advanced','U = ∫_S u·dS;  uniform velocity: U = S·u  (m³/s)','Volume velocity is the particle velocity integrated over the radiating area; for uniform motion it is the area times the particle velocity.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Volume velocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b255bba9-61d1-5e85-b266-5cd701e8875f','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b255bba9-61d1-5e85-b266-5cd701e8875f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b255bba9-61d1-5e85-b266-5cd701e8875f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '63cd7738-6d0c-5beb-9617-2ee6fa11d039','Acoustic power flow','The transport of acoustic energy per unit time through a region or across a surface, given by the integral of the sound intensity, the time-averaged product of pressure and particle velocity, over that surface. Because intensity is a vector, acoustic power flow has direction, describing how sound energy is carried away from a source or through a boundary; its net value through a closed surface equals the radiated sound power.','This is how sound energy moves through space each second. It follows the direction the energy travels. Adding it up over a surface gives the power passing through. Around a source, that total is its radiated power.','It describes the directional movement of acoustic energy, allowing the power radiated by a source or crossing a boundary to be found by integrating intensity over a surface.','Sound intensity mapping and sound power measurements rely on it: technicians scan an intensity probe over a surface to find where and how strongly energy flows from a machine.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sound intensity','Sound power','Sound power level','Acoustic flux','Particle velocity']::text[],ARRAY['Confusing power flow, a directional transport, with the scalar sound power through a closed surface','Ignoring the direction of intensity when summing contributions','Assuming pressure alone gives power flow without particle velocity']::text[],ARRAY['Scanning an intensity probe to locate energy leaks in a panel','Determining the sound power of a machine in a noisy room','Mapping how energy radiates from a loudspeaker cabinet']::text[],'intermediate','W = ∮_S I·dS,   I = ⟨p·u⟩','Acoustic power flow through a surface equals the sound intensity, the time-averaged product of pressure and particle velocity, integrated over that surface.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic power flow');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '63cd7738-6d0c-5beb-9617-2ee6fa11d039','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='63cd7738-6d0c-5beb-9617-2ee6fa11d039') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='63cd7738-6d0c-5beb-9617-2ee6fa11d039');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53dd0e42-2ca4-5ff0-9c00-efd5eeffef88','Acoustic flux','The rate at which sound energy flows through a specified area, equal to the sound intensity integrated over that area; when the area is a closed surface surrounding a source, the acoustic flux equals the source''s sound power. The term treats sound energy transport as a flux quantity, with intensity acting as the corresponding flux density, or flow per unit area. It is expressed in watts.','This is the sound energy flowing through an area each second. Intensity is the flow for each square metre. Adding intensity over the whole area gives the flux. Around a source it equals that source''s power.','It expresses sound energy transport as a flux, letting the energy crossing an area, or the power leaving a source, be obtained by integrating intensity over area.','The concept underlies sound power determination by intensity scanning and energy-based room acoustics, where the energy crossing measurement surfaces is summed.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sound intensity','Sound energy flux','Sound power','Acoustic power flow','Reference intensity']::text[],ARRAY['Confusing acoustic flux, a power in watts, with intensity, a flux density in watts per square metre','Mixing energy flux with volume flux, which is the volume velocity','Forgetting the area over which intensity is integrated']::text[],ARRAY['Summing intensity over a surface to get radiated power','Energy-based analysis of sound crossing a room boundary','Relating measured intensity to a source''s total output']::text[],'intermediate','Φ = ∫_S I·dS  (W);  closed surface: Φ = W_source','Acoustic flux is the sound intensity integrated over an area; over a closed surface around a source it equals the source''s sound power.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic flux');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53dd0e42-2ca4-5ff0-9c00-efd5eeffef88','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53dd0e42-2ca4-5ff0-9c00-efd5eeffef88') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53dd0e42-2ca4-5ff0-9c00-efd5eeffef88');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1967f7e5-e84c-50e4-b80c-e6464dbaada4','Acoustic inertance','The acoustic analogue of mass, quantifying the pressure difference required to produce a given rate of change of volume velocity in a body of fluid that moves without appreciable compression, such as the air in a short duct, port, or neck. For a tube of effective length and cross-sectional area it equals the fluid density times the effective length divided by the area, with units of kilograms per metre to the fourth power, equivalently pascal-seconds squared per cubic metre. Its acoustic impedance is proportional to frequency, dominating a system''s behaviour above resonance.','This is the sound version of mass. Air in a tube or port acts heavy and resists speeding up. A longer, narrower tube gives more inertance. It helps set the tuning of ports and resonators.','It represents the inertia of a moving plug of air in lumped-element acoustic models, pairing with acoustic compliance to set the resonance of ports, necks, and Helmholtz systems.','Loudspeaker designers use it to tune bass-reflex ports and passive radiators; it also models the necks of Helmholtz absorbers and the air in ducts and mufflers.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Acoustic compliance','Acoustic impedance','Helmholtz resonator','Volume velocity','Acoustic mass']::text[],ARRAY['Using the physical port length instead of the effective length that includes end corrections','Confusing acoustic inertance with acoustic resistance or compliance','Assuming inertance is independent of the port cross-sectional area']::text[],ARRAY['Tuning a bass-reflex loudspeaker port to a target frequency','Designing the neck of a Helmholtz absorber','Modelling the air mass in a duct or muffler element']::text[],'advanced','M_a = ρ·l_eff / S  (kg·m⁻⁴);  Z_a = jωM_a','Acoustic inertance equals air density times the effective length of the air plug divided by its cross-sectional area; its impedance rises with frequency.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic inertance');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1967f7e5-e84c-50e4-b80c-e6464dbaada4','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1967f7e5-e84c-50e4-b80c-e6464dbaada4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1967f7e5-e84c-50e4-b80c-e6464dbaada4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f57342a-4ece-528c-b4ec-dc605dc4a4c7','Wave','A wave is a disturbance that travels through a medium or field, transporting energy and momentum without any net transport of the medium itself. In acoustics a sound wave is a mechanical disturbance in which particles of the medium oscillate about their rest positions and hand energy to neighbouring regions. Waves are described by quantities such as frequency, wavelength, speed, amplitude, and phase.','A wave is a moving disturbance that carries energy. It passes through a material such as air or water. The material itself does not travel along with it. Each part just wiggles and pushes the next part. Sound is a wave that moves through the air.','The wave concept lets us describe how sound and other signals move energy through space and time, forming the basis for nearly every acoustic measurement and calculation.','Technicians treat sound as a wave when predicting coverage, aligning loudspeakers in time, and interpreting measurements such as frequency response and phase.','Sound Visualization & Acoustic Imaging',ARRAY['Mechanical wave','Sound wave','Frequency','Wavelength','Amplitude','Propagation']::text[],ARRAY['Thinking the medium travels with the wave rather than oscillating in place','Confusing a wave''s energy with the small motion of individual particles','Assuming every wave needs a medium, which is untrue for electromagnetic waves']::text[],ARRAY['Explaining why sound needs air to cross a room','Describing how a loudspeaker launches energy into a hall','Introducing frequency and wavelength in a training class']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f57342a-4ece-528c-b4ec-dc605dc4a4c7','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f57342a-4ece-528c-b4ec-dc605dc4a4c7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f57342a-4ece-528c-b4ec-dc605dc4a4c7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4b21517f-ce50-5368-8ba6-1594b26fa6d0','Mechanical wave','A mechanical wave is a wave that propagates only through a material medium—gas, liquid, or solid—by the interaction of neighbouring particles through elastic restoring forces. Unlike an electromagnetic wave it cannot travel through a vacuum. Sound is a mechanical wave; in fluids it is longitudinal, while solids also support transverse and other wave types.','A mechanical wave needs a material to travel through. That material can be a gas, a liquid, or a solid. The particles push and pull on their neighbours. This passes the wave along. Sound is a mechanical wave, so it cannot cross empty space.','It distinguishes sound and vibration from waves like light, explaining why sound requires a medium and why its speed depends on the medium''s properties.','Understanding sound as a mechanical wave helps technicians reason about why sound speed changes with temperature and why vibration travels through structures.','Sound Visualization & Acoustic Imaging',ARRAY['Wave','Longitudinal wave','Sound wave','Medium','Elasticity','Wave speed']::text[],ARRAY['Believing sound can travel through a vacuum','Confusing mechanical waves with electromagnetic waves such as radio','Assuming the medium moves bodily along with the wave']::text[],ARRAY['Explaining why there is no sound in outer space','Discussing structure-borne vibration through a stage floor','Teaching why sound speed rises in warm air']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mechanical wave');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4b21517f-ce50-5368-8ba6-1594b26fa6d0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4b21517f-ce50-5368-8ba6-1594b26fa6d0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4b21517f-ce50-5368-8ba6-1594b26fa6d0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5db59e49-bd91-5170-9e0f-71ee36e5d1c8','Wave speed','Wave speed is the rate at which a wave''s disturbance, or a point of constant phase, advances through a medium. For a periodic wave it equals the product of frequency and wavelength, v = fλ, so in a fixed medium a higher frequency corresponds to a proportionally shorter wavelength. For sound, wave speed is set by the medium''s elasticity and density and, in air, rises with temperature.','Wave speed is how fast a wave moves through a material. For sound in air it is about 343 metres per second at room temperature. Speed equals frequency times wavelength. So a higher pitch has a shorter wavelength. Warm air makes sound travel a little faster.','It links frequency and wavelength, letting engineers convert between the two and predict how far sound travels in a given time.','Technicians use wave speed to compute delay times, align loudspeakers, and estimate wavelengths when planning coverage and treating room modes.','Sound Visualization & Acoustic Imaging',ARRAY['Wavelength','Frequency','Speed of sound','Propagation','Wave']::text[],ARRAY['Thinking louder sounds travel faster than quiet ones','Believing higher-frequency sound travels faster through air','Forgetting that the speed of sound changes with temperature']::text[],ARRAY['Calculating the wavelength of a 100 Hz tone','Setting delay for a speaker tower from the speed of sound','Explaining a modal frequency from room dimensions']::text[],'beginner','v = f·λ','Wave speed equals frequency multiplied by wavelength.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Wave speed');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5db59e49-bd91-5170-9e0f-71ee36e5d1c8','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5db59e49-bd91-5170-9e0f-71ee36e5d1c8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5db59e49-bd91-5170-9e0f-71ee36e5d1c8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4b8798dc-77a8-5d87-b287-26e16506cec0','Propagation','Propagation is the process by which a wave travels outward from its source through a medium or field. It covers how the wavefront advances and spreads and how it interacts with boundaries and inhomogeneities through reflection, refraction, diffraction, absorption, and scattering. The manner of propagation determines how level, timing, and spectral content change with distance and environment.','Propagation means the way a wave travels out from its source. Sound spreads through the air and gets weaker with distance. Along the way it can bounce, bend, or be soaked up. These effects change how loud and clear it is. Studying propagation tells us what reaches the listener.','It describes how sound moves from source to listener, underpinning predictions of level loss, arrival time, and how obstacles and surfaces reshape sound.','Sound designers weigh propagation when placing loudspeakers, predicting outdoor level loss, and diagnosing why distant seats sound different from near ones.','Sound Visualization & Acoustic Imaging',ARRAY['Propagation direction','Wavefront','Attenuation','Reflection','Diffraction','Refraction']::text[],ARRAY['Assuming sound level drops the same way indoors and outdoors','Ignoring reflection and diffraction when predicting coverage','Treating propagation as instant over large distances']::text[],ARRAY['Predicting level loss across an open field','Explaining why a barrier casts a sound shadow','Diagnosing comb filtering from reflected paths']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Propagation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4b8798dc-77a8-5d87-b287-26e16506cec0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4b8798dc-77a8-5d87-b287-26e16506cec0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4b8798dc-77a8-5d87-b287-26e16506cec0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f292713-6c5e-526d-a7f2-3ec7212ba8d0','Propagation direction','Propagation direction is the direction in which a wave''s energy advances, normal to the wavefront for a simple travelling wave and commonly represented by a wave vector or a ray. In a free field the sound intensity vector points in this direction, which sets the arrival angle at a receiver and governs how multiple sources sum in space.','Propagation direction is the way a wave''s energy is heading. For a simple wave it points straight out from the wavefront. You can picture it as an arrow or a ray. It tells you the angle that sound arrives from. This matters when several sources overlap.','It specifies where sound energy is heading, which is essential for aiming loudspeakers, understanding arrival angles, and analysing how sources combine.','Engineers think about propagation direction when aiming array elements, steering low-frequency arrays, and reading intensity or direction-of-arrival measurements.','Sound Visualization & Acoustic Imaging',ARRAY['Wavefront','Wave vector','Ray','Propagation','Sound intensity','Direction of arrival']::text[],ARRAY['Confusing the direction a particle moves with the direction the wave travels','Assuming a single fixed direction inside a reverberant room','Ignoring direction when summing overlapping sources']::text[],ARRAY['Aiming a line array at the back of a room','Steering a cardioid subwoofer array','Reading the direction from a sound intensity probe']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Propagation direction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f292713-6c5e-526d-a7f2-3ec7212ba8d0','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f292713-6c5e-526d-a7f2-3ec7212ba8d0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f292713-6c5e-526d-a7f2-3ec7212ba8d0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67f452a8-3331-55ee-9b42-4e67f986845d','Phase difference','Phase difference is the difference in phase angle between two periodic waves of the same frequency, expressed in degrees or radians. It corresponds to a time offset Δt relative to the period T, with Δφ = 360°·(Δt/T), or to a path-length difference relative to wavelength. Phase difference governs how waves combine: near 0° they reinforce, and near 180° they tend to cancel.','Phase difference tells how far two waves are shifted from each other. It is measured in degrees. A full cycle is 360 degrees. When two equal waves line up, they add and get louder. When they are half a cycle apart, they cancel out.','It quantifies the timing offset between signals, explaining constructive and destructive interference, comb filtering, and the result of summing sources.','Technicians read phase difference when aligning subwoofers with tops, checking polarity, and diagnosing cancellations between microphones or loudspeakers.','Sound Visualization & Acoustic Imaging',ARRAY['Phase','Phase relationship','In phase','Out of phase','Comb filtering','Interference']::text[],ARRAY['Confusing phase difference with polarity inversion','Assuming 180-degree cancellation is perfect at every frequency','Forgetting phase difference depends on frequency for a fixed time offset']::text[],ARRAY['Aligning a subwoofer to the main speakers','Explaining comb filtering from two open microphones','Timing two arrivals in a measurement']::text[],'intermediate','Δφ = 360°·(Δt / T)','Phase difference in degrees equals 360 times the time offset divided by the period.','0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67f452a8-3331-55ee-9b42-4e67f986845d','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67f452a8-3331-55ee-9b42-4e67f986845d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67f452a8-3331-55ee-9b42-4e67f986845d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '284cd8c7-5832-5819-a604-39baeebf419d','Phase relationship','Phase relationship is the general description of how the phases of two or more periodic signals compare over time—whether they are in phase, out of phase, or offset by some intermediate angle, and whether that offset is fixed or drifting. For signals of the same frequency it is a constant phase difference; for differing frequencies it changes continuously.','A phase relationship describes how the timing of two signals compares. They may line up, be opposite, or sit somewhere between. If they share a frequency, the offset stays fixed. If not, the offset keeps changing. This shapes how the signals add together.','It frames how signals combine over time, which is central to interference, stereo imaging, and the summation of loudspeakers and microphones.','Engineers assess phase relationships when combining mic signals, blending speaker outputs, and reading phase traces in analysis software.','Sound Visualization & Acoustic Imaging',ARRAY['Phase','Phase difference','In phase','Out of phase','Coherence','Interference']::text[],ARRAY['Assuming two sources with the same signal are always in phase at the listener','Treating polarity and phase as identical','Ignoring that a phase relationship varies with frequency']::text[],ARRAY['Blending a close and a distant microphone','Checking speaker summation at a crossover','Reading a phase trace during system tuning']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Phase relationship');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '284cd8c7-5832-5819-a604-39baeebf419d','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='284cd8c7-5832-5819-a604-39baeebf419d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='284cd8c7-5832-5819-a604-39baeebf419d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7c8dea71-40e3-5f3f-b44b-e19c15e7965e','In phase','Two periodic signals are in phase when their corresponding cycle points—such as peaks and zero crossings—occur at the same instants, giving a phase difference of 0° or a whole number of cycles. Equal-amplitude in-phase signals of the same frequency add constructively, producing a summed amplitude up to twice that of either alone.','Two waves are in phase when their cycles line up in time. Their peaks happen together and their dips happen together. When equal waves are in phase, they add up. The result is louder than either wave alone. The phase difference is zero degrees.','It names the condition for maximum constructive addition, which technicians aim for when summing sources that should reinforce.','Getting subwoofers in phase with the main speakers at the crossover maximizes level and avoids a dip in the response.','Sound Visualization & Acoustic Imaging',ARRAY['Out of phase','Phase difference','Constructive interference','Polarity','Phase']::text[],ARRAY['Confusing being in phase with having correct polarity','Assuming two speakers are in phase everywhere in a room','Thinking in-phase signals always double the level regardless of amplitude']::text[],ARRAY['Tuning a subwoofer to add with the tops','Verifying two drivers sum at the crossover','Explaining constructive addition in class']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='In phase');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7c8dea71-40e3-5f3f-b44b-e19c15e7965e','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7c8dea71-40e3-5f3f-b44b-e19c15e7965e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7c8dea71-40e3-5f3f-b44b-e19c15e7965e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '53467167-faa3-5adf-8065-2a7cf2c581bc','Out of phase','Two periodic signals are out of phase when their cycles do not coincide, having a nonzero phase difference; the term most often denotes the 180° case, where one signal''s peaks align with the other''s troughs. Equal-amplitude signals 180° out of phase cancel when summed. Loosely, the phrase can describe any intermediate offset as well.','Two waves are out of phase when their cycles do not line up. Often this means they are half a cycle apart. Then one wave''s peak meets the other''s dip. Equal waves like this cancel and get quieter. The phrase can also mean any offset that is not zero.','It names the condition that leads to partial or full cancellation, which technicians must find and fix, or sometimes exploit deliberately.','A wiring polarity error can leave stereo speakers out of phase, thinning the bass and blurring the centre image.','Sound Visualization & Acoustic Imaging',ARRAY['In phase','Phase difference','Destructive interference','Polarity','Cancellation']::text[],ARRAY['Confusing being out of phase with a reversed polarity connection','Assuming cancellation is total at every frequency','Believing out of phase always means exactly 180 degrees']::text[],ARRAY['Diagnosing weak bass from a miswired speaker','Explaining a hollow sound from two microphones','Showing cancellation between opposed sources']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Out of phase');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '53467167-faa3-5adf-8065-2a7cf2c581bc','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='53467167-faa3-5adf-8065-2a7cf2c581bc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='53467167-faa3-5adf-8065-2a7cf2c581bc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '782f95b6-e997-51ea-99a7-5c5f732313a1','Crest','The crest of a wave is the point of maximum positive displacement or pressure within a cycle—the highest peak above the equilibrium value. In a sound pressure waveform it corresponds to the instant of greatest compression. For a symmetric wave the vertical distance from equilibrium to the crest equals the amplitude.','A crest is the highest point of a wave in each cycle. It is the top of the peak above the middle line. In a sound wave it is the moment of greatest push on the air. The distance from the middle to the crest is the amplitude.','It gives a clear reference point on a waveform for describing amplitude, timing, and how the peaks of different waves line up.','On a waveform display, spotting crests helps with editing, measuring peak level, and comparing the timing of two signals.','Sound Visualization & Acoustic Imaging',ARRAY['Trough','Amplitude','Peak','Waveform','Compression']::text[],ARRAY['Confusing the crest height with the peak-to-peak height','Assuming every waveform has a single clear crest','Mixing up the crest (a level) with the wave''s period (a time)']::text[],ARRAY['Reading peaks on a DAW waveform','Teaching amplitude with a sine drawing','Lining up transients between two tracks']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Crest');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '782f95b6-e997-51ea-99a7-5c5f732313a1','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='782f95b6-e997-51ea-99a7-5c5f732313a1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='782f95b6-e997-51ea-99a7-5c5f732313a1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '739c8ef4-ea0c-5193-b74d-8815325bddc2','Trough','The trough of a wave is the point of maximum negative displacement or pressure within a cycle—the lowest dip below the equilibrium value. In a sound pressure waveform it corresponds to the instant of greatest rarefaction. A trough and the neighbouring crest are separated by half a period.','A trough is the lowest point of a wave in each cycle. It is the bottom of the dip below the middle line. In a sound wave it is the moment of greatest pull on the air. A trough sits half a cycle away from a crest.','It marks the negative extreme of a cycle, giving a reference for amplitude, polarity, and the spacing between wave features.','Recognising troughs on a waveform aids editing at zero crossings, judging polarity, and measuring peak-to-peak values.','Sound Visualization & Acoustic Imaging',ARRAY['Crest','Amplitude','Rarefaction','Waveform','Zero crossing']::text[],ARRAY['Confusing a trough with a zero crossing','Assuming the trough depth differs from the crest height for a symmetric wave','Mixing up rarefaction with compression']::text[],ARRAY['Finding zero crossings for a clean edit','Explaining rarefaction in a pressure wave','Measuring peak-to-peak on a scope']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Trough');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '739c8ef4-ea0c-5193-b74d-8815325bddc2','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='739c8ef4-ea0c-5193-b74d-8815325bddc2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='739c8ef4-ea0c-5193-b74d-8815325bddc2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bcc59982-2334-5775-9f15-09d3723493b7','Rise time','Rise time is the time taken for a signal or sound level to increase from a low reference to a high reference, conventionally from 10% to 90% of the final amplitude for a step-like change. A short rise time indicates a fast transient rich in high-frequency content, while a long rise time indicates a gradual onset. It characterizes how quickly attacks and onsets develop.','Rise time is how long a signal takes to climb from low to high. It is often measured from 10 percent up to 90 percent. A short rise time means a sharp, fast attack. A long rise time means a slow build-up. Fast attacks carry more high-frequency energy.','It quantifies how fast an onset develops, linking the time domain to high-frequency content and to how punchy a sound feels.','Engineers consider rise time when setting compressor attack, capturing drum transients, and choosing measurement windows for fast events.','Sound Visualization & Acoustic Imaging',ARRAY['Transient','Attack','Onset','Impulsive sound','Envelope']::text[],ARRAY['Confusing rise time with the total duration of a sound','Ignoring that very short rise times demand wide bandwidth','Assuming rise time and decay time are always equal']::text[],ARRAY['Setting a compressor to catch drum hits','Measuring the onset of a snare transient','Choosing an analyzer window for clicks']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rise time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bcc59982-2334-5775-9f15-09d3723493b7','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bcc59982-2334-5775-9f15-09d3723493b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bcc59982-2334-5775-9f15-09d3723493b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0d98bb85-8f86-5128-a1ee-8fb778b08885','Steady-state sound','Steady-state sound is sound whose statistical or spectral properties stay essentially constant over the observation interval, once any initial onset transient has settled. Its level and spectrum do not change appreciably with time, so a single spectrum or level meaningfully represents the signal. Sustained tones and continuous machinery noise approximate steady-state conditions.','A steady-state sound stays about the same over time. Its level and tone do not change much once it settles. A held organ note is close to steady state. So is the steady hum of a fan. One reading can describe the whole sound.','It identifies signals stable enough to be described by a single spectrum or level, which simplifies measurement and analysis.','Steady-state assumptions let technicians measure noise levels, room response with pink noise, and machine tones with a simple averaged reading.','Sound Visualization & Acoustic Imaging',ARRAY['Continuous sound','Transient','Sustain','Root mean square','Spectrum']::text[],ARRAY['Treating a sound with a strong onset as steady state too early','Assuming real signals are perfectly steady','Confusing steady state with simply being loud']::text[],ARRAY['Measuring fan noise with an averaged level','Analyzing a sustained synth tone','Running pink noise to read room response']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Steady-state sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0d98bb85-8f86-5128-a1ee-8fb778b08885','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0d98bb85-8f86-5128-a1ee-8fb778b08885') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0d98bb85-8f86-5128-a1ee-8fb778b08885');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5867cfaa-7fe4-5012-a155-ca93759e4635','Impulsive sound','Impulsive sound is a brief, high-level acoustic event with a rapid onset and short duration, such as a hammer strike, gunshot, or handclap. It has a fast rise time and broad frequency content, and its peak level can greatly exceed its time-averaged level. Impulsive sounds are used to excite systems for impulse-response measurement and are treated specially in noise-exposure assessment.','An impulsive sound is a short, sharp burst. Examples are a clap, a hammer hit, or a gunshot. It starts fast and dies away quickly. Its peak can be far above its average level. Sudden loud bursts like these can be extra harmful to hearing.','It labels sharp transient events that need peak-based handling in measurement and in judging hearing risk.','Impulsive sounds like a balloon pop or a starter pistol are used to capture a room''s impulse response and reverberation.','Sound Visualization & Acoustic Imaging',ARRAY['Transient','Impulse response','Rise time','Peak level','Continuous sound']::text[],ARRAY['UNSAFE: Judging the hazard of an impulsive sound by its average level instead of its peak','Assuming a slow meter reading captures the true peak','Confusing impulsive sound with merely loud continuous sound']::text[],ARRAY['Popping a balloon to measure a room impulse response','Assessing the peak level from a gunshot','Capturing a handclap for reverb analysis']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impulsive sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5867cfaa-7fe4-5012-a155-ca93759e4635','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5867cfaa-7fe4-5012-a155-ca93759e4635') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5867cfaa-7fe4-5012-a155-ca93759e4635');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '583728ae-aaa3-5611-8aaa-3cb3df670da9','Continuous sound','Continuous sound is sound that persists without interruption over the period of interest, as opposed to impulsive or intermittent sound. It may be steady or fluctuating in level, but it remains present throughout. Continuous noise sources such as ventilation or traffic are characterized by time-averaged levels over a stated interval.','A continuous sound keeps going without stopping. It stays present the whole time you listen. It may be steady or it may rise and fall. Traffic hum and air conditioning are examples. We describe it with an average level over time.','It classifies sounds that are present throughout an interval, guiding whether averaged or event-based measures apply.','Continuous background noise is measured with time-averaged levels when assessing HVAC noise or setting a venue''s noise floor.','Sound Visualization & Acoustic Imaging',ARRAY['Steady-state sound','Intermittent sound','Impulsive sound','Background noise','Equivalent level']::text[],ARRAY['Confusing continuous with steady, though a continuous sound can fluctuate','Using a single peak to describe a long continuous noise','Assuming continuous always means unchanging']::text[],ARRAY['Measuring HVAC noise in an empty hall','Rating traffic noise over an hour','Setting a room''s noise floor target']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Continuous sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '583728ae-aaa3-5611-8aaa-3cb3df670da9','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='583728ae-aaa3-5611-8aaa-3cb3df670da9') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='583728ae-aaa3-5611-8aaa-3cb3df670da9');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a12a54c6-3fb5-5e0c-a329-e74f3929e8ed','Intermittent sound','Intermittent sound is sound that is present for periods separated by intervals of relative quiet, repeatedly starting and stopping over the observation time. Its level pattern alternates between audible events and gaps. Assessment often combines time-averaged levels with statistics that account for the on and off periods.','An intermittent sound starts and stops again and again. There are quiet gaps between the bursts. A passing train or a cycling pump is intermittent. We measure it over time to capture both the on and off parts. Averages alone can miss the pattern.','It describes on-and-off sounds whose gaps matter, so measurement must span enough time to capture the pattern.','Intermittent noise, such as a compressor cycling on and off, is logged over time so both loud and quiet phases are captured.','Sound Visualization & Acoustic Imaging',ARRAY['Continuous sound','Impulsive sound','Time history','Equivalent level','Duty cycle']::text[],ARRAY['Measuring only during a loud burst and missing the gaps','Confusing intermittent sound with impulsive events','Using too short a window to capture the pattern']::text[],ARRAY['Logging a pump that cycles on and off','Rating noise from passing trains','Capturing an alarm that repeats']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intermittent sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a12a54c6-3fb5-5e0c-a329-e74f3929e8ed','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a12a54c6-3fb5-5e0c-a329-e74f3929e8ed') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a12a54c6-3fb5-5e0c-a329-e74f3929e8ed');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ee739f88-2bf2-5492-bd46-d3a571ad078e','Periodic sound','Periodic sound is sound whose waveform repeats at regular time intervals, so a single period defines the entire pattern. Its repetition rate is the fundamental frequency, and its spectrum consists of discrete harmonics at integer multiples of that frequency. Sustained musical tones from pitched instruments are approximately periodic.','A periodic sound repeats the same shape over and over. Each repeat takes the same amount of time. That repeat rate sets the pitch we hear. Its tone is built from a fundamental plus harmonics. A held note on a flute is close to periodic.','It links a repeating waveform to a clear pitch and a harmonic spectrum, underpinning how we hear tone and analyze pitched sounds.','Recognising periodic signals guides pitch detection, tuning, and reading the harmonic lines that a pitched instrument shows on a spectrum.','Sound Visualization & Acoustic Imaging',ARRAY['Aperiodic sound','Fundamental frequency','Harmonic','Period','Waveform']::text[],ARRAY['Assuming real instrument tones are perfectly periodic','Confusing period (a time) with frequency (a rate)','Expecting noise to show clear harmonics']::text[],ARRAY['Tuning an instrument by its pitch','Reading harmonic lines on a spectrum','Explaining why a tone has a clear pitch']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Periodic sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ee739f88-2bf2-5492-bd46-d3a571ad078e','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ee739f88-2bf2-5492-bd46-d3a571ad078e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ee739f88-2bf2-5492-bd46-d3a571ad078e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a9522cc0-4486-52e4-9450-69e3e0c15016','Aperiodic sound','Aperiodic sound is sound whose waveform does not repeat at a fixed interval, so it has no single well-defined period or pitch. Its spectrum tends to be continuous or irregular rather than a set of evenly spaced harmonics. Noise, many percussion sounds, and consonant-like transients are aperiodic.','An aperiodic sound does not repeat on a fixed cycle. Because of that it has no clear single pitch. Its spectrum spreads out instead of showing neat harmonics. A cymbal crash and a burst of noise are aperiodic. So are many hissing speech sounds.','It names sounds without a stable pitch, guiding how we analyze noise and percussive content differently from tones.','Treating a snare or hi-hat as aperiodic shapes how engineers EQ, gate, and analyze its broad, non-harmonic spectrum.','Sound Visualization & Acoustic Imaging',ARRAY['Periodic sound','Noise','Transient','Broadband','Spectrum']::text[],ARRAY['Expecting a clear pitch from an aperiodic sound','Looking for evenly spaced harmonics in noise','Confusing aperiodic with simply quiet']::text[],ARRAY['EQing a noisy cymbal','Analyzing a burst of broadband noise','Explaining why a snare has no clear note']::text[],'beginner',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Aperiodic sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a9522cc0-4486-52e4-9450-69e3e0c15016','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a9522cc0-4486-52e4-9450-69e3e0c15016') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a9522cc0-4486-52e4-9450-69e3e0c15016');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c0a8319f-8db3-5f8e-b267-0376ea9ed352','Random sound','Random sound is sound whose instantaneous waveform cannot be predicted exactly and is described statistically rather than by a fixed function of time. Examples include thermal and acoustic noise; a common idealization is white or pink noise with a defined power spectral density. Random signals are characterized by averages, variance, and spectra rather than by an exact waveform.','A random sound cannot be predicted moment to moment. You never know the next exact value in advance. Instead we describe it with averages and its spectrum. White noise and pink noise are common examples. Its detailed shape is different every time.','It frames signals that must be handled with statistics, the basis for using noise in testing and for describing background hiss.','Random noise like pink noise is used to measure room and system response, since its statistics stay stable even though the waveform does not.','Sound Visualization & Acoustic Imaging',ARRAY['Deterministic sound','White noise','Pink noise','Power spectral density','Stochastic']::text[],ARRAY['Expecting two captures of random noise to look identical','Assuming random means it has no useful spectrum','Confusing random noise with distortion']::text[],ARRAY['Using pink noise to tune a system','Describing a room''s background hiss','Averaging noise to get a stable spectrum']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Random sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c0a8319f-8db3-5f8e-b267-0376ea9ed352','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c0a8319f-8db3-5f8e-b267-0376ea9ed352') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c0a8319f-8db3-5f8e-b267-0376ea9ed352');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2fbdb928-8d05-56d5-a8a2-f0125a6be199','Deterministic sound','Deterministic sound is sound that can be described exactly by a mathematical function of time or by a fixed set of components, so its future values follow from its rule. Pure tones, sums of sinusoids, and repeatable synthesized signals are deterministic. It contrasts with random sound, whose waveform is inherently statistical.','A deterministic sound follows a fixed rule over time. If you know the rule, you can predict every value. A pure tone is a simple example. A repeatable synth signal is another. It is the opposite of random noise.','It labels predictable, repeatable signals, which make ideal test stimuli because they can be reproduced and compared exactly.','Deterministic test tones and swept sines drive repeatable measurements of frequency response, distortion, and system behaviour.','Sound Visualization & Acoustic Imaging',ARRAY['Random sound','Sine wave','Test tone','Swept sine','Periodic sound']::text[],ARRAY['Assuming any repeating-looking sound is fully deterministic','Confusing deterministic with merely periodic','Expecting real signals to be free of added noise']::text[],ARRAY['Running a swept sine for a response measurement','Using a 1 kHz tone to set levels','Comparing repeated captures of the same test signal']::text[],'intermediate',NULL,NULL,'0c5fa38e-c585-429a-ae4a-298a1d47ffb5' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Deterministic sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2fbdb928-8d05-56d5-a8a2-f0125a6be199','0c5fa38e-c585-429a-ae4a-298a1d47ffb5',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2fbdb928-8d05-56d5-a8a2-f0125a6be199') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2fbdb928-8d05-56d5-a8a2-f0125a6be199');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd8a71242-aafd-51c6-bee6-9bb1bbd60128','Decibel','A dimensionless unit, equal to one-tenth of a bel, that expresses the logarithmic ratio of two quantities. For power-like quantities the level in decibels is ten times the base-ten logarithm of the ratio; for field or root-power quantities such as sound pressure or voltage it is twenty times that logarithm, because those quantities are squared to obtain power. A decibel value is meaningful only with respect to a stated reference quantity.','A decibel compares two values using a logarithm. It squeezes a huge range into small numbers. For power you use ten times the log. For pressure or voltage you use twenty times. It always needs a reference to compare against.','It compresses very wide ranges of acoustic and electrical quantities into a manageable logarithmic scale that also matches the way people perceive changes in level.','Engineers read gain, loss, signal-to-noise ratio, and sound level in decibels on consoles, meters, and analysers, and add or subtract them instead of multiplying ratios.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Bel','Sound pressure level','Reference quantity','Level difference','Logarithm']::text[],ARRAY['Using the ten-times-log rule for pressure or voltage instead of the twenty-times-log rule','Quoting a decibel value without stating the reference','Adding decibel levels arithmetically as if summing energy directly']::text[],ARRAY['Reading gain and headroom on a mixing console','Expressing a signal-to-noise ratio in decibels','Comparing two sound levels on a meter']::text[],'beginner','L = 10·log₁₀(P/P₀) dB (power);  L = 20·log₁₀(F/F₀) dB (field)','A level in decibels is ten times the base-ten logarithm of a power ratio, or twenty times the logarithm of a field-quantity ratio such as pressure or voltage.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decibel');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd8a71242-aafd-51c6-bee6-9bb1bbd60128','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d8a71242-aafd-51c6-bee6-9bb1bbd60128') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d8a71242-aafd-51c6-bee6-9bb1bbd60128');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '101ea28c-9cca-5d96-a7d5-e432e3945e64','Reference quantity','The fixed, agreed value placed in the denominator of a ratio when a physical quantity is expressed as a level in decibels. Choosing a reference quantity fixes the zero of the level scale and makes decibel values comparable; examples include twenty micropascals for sound pressure in air, one picowatt for sound power, and one picowatt per square metre for sound intensity. Without a stated reference a decibel level has no absolute meaning.','A reference quantity is the fixed value a level is compared to. It sets where zero decibels sits. For sound pressure in air it is twenty micropascals. Every decibel level needs one to make sense.','It anchors a decibel scale to a defined physical value, so that levels measured by different people and instruments mean the same thing.','Technicians rely on standard references, such as decibels relative to twenty micropascals for sound pressure, to know what a reading actually represents and to compare measurements across systems.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Reference pressure','Reference power','Reference intensity','Decibel','Absolute level']::text[],ARRAY['Comparing decibel figures that use different references','Assuming zero decibels means no sound rather than the reference value','Omitting the reference when reporting a level']::text[],ARRAY['Stating a sound pressure level relative to twenty micropascals','Choosing a voltage reference for a line-level measurement','Documenting the reference used in a noise report']::text[],'beginner','L = 10·log₁₀(Q/Q₀);  Q₀ = reference quantity','A level equals ten times the logarithm of the quantity divided by its reference quantity, so the reference quantity is the fixed value the measurement is compared with.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference quantity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '101ea28c-9cca-5d96-a7d5-e432e3945e64','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='101ea28c-9cca-5d96-a7d5-e432e3945e64') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='101ea28c-9cca-5d96-a7d5-e432e3945e64');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '26636a70-fe7b-5f22-9ddc-99d5ac5f45b1','Reference pressure','The standard sound pressure used as the denominator when computing sound pressure level. In air the reference is twenty micropascals, that is two times ten to the power minus five pascals, chosen to approximate the threshold of human hearing at one kilohertz; for underwater acoustics the reference is one micropascal. Sound pressure level is twenty times the base-ten logarithm of the rms sound pressure divided by this reference.','This is the fixed pressure that sound levels compare to. In air it is twenty micropascals. That value is near the quietest sound people can hear. Underwater a different value, one micropascal, is used.','It fixes the zero of the sound-pressure-level scale, so a measured pressure can be turned into a decibel level that everyone interprets the same way.','Every sound pressure level reading on a meter is referenced to twenty micropascals; technicians must note when underwater or other references apply, to avoid large errors.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sound pressure level','Reference quantity','Root mean square pressure','Threshold of hearing','Decibel']::text[],ARRAY['Comparing airborne sound pressure levels to underwater levels without noting the twenty-micropascal versus one-micropascal difference','Using twenty micropascals as the reference for underwater sound','Thinking zero decibels means total silence rather than the reference pressure']::text[],ARRAY['Setting up a sound level meter that reads relative to twenty micropascals','Interpreting a hydrophone level referenced to one micropascal','Explaining why zero decibels is still audible for some listeners']::text[],'beginner','p₀ = 20 µPa = 2×10⁻⁵ Pa (air);  1 µPa (water)','The reference pressure is twenty micropascals in air and one micropascal in water, used as the denominator in the sound pressure level calculation.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '26636a70-fe7b-5f22-9ddc-99d5ac5f45b1','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='26636a70-fe7b-5f22-9ddc-99d5ac5f45b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='26636a70-fe7b-5f22-9ddc-99d5ac5f45b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '95f72edf-a9c3-5324-be2d-844f8000c620','Reference intensity','The standard sound intensity used as the denominator when computing sound intensity level, equal to one picowatt per square metre, that is ten to the power minus twelve watts per square metre. This value is chosen so that, for a plane progressive wave in air under reference conditions, the sound intensity level and the sound pressure level referenced to twenty micropascals are numerically almost equal.','This is the fixed intensity that intensity levels compare to. It equals one trillionth of a watt per square metre. It is picked so intensity level and pressure level nearly match in air. That makes the two scales line up.','It sets the zero of the sound-intensity-level scale and is chosen to keep intensity level close to sound pressure level for a plane wave in air.','Sound intensity analysers reference measured intensity to one picowatt per square metre; the near-equality with sound pressure level lets technicians sanity-check intensity readings against pressure readings.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sound intensity','Sound intensity level','Reference pressure','Reference power','Reference quantity']::text[],ARRAY['Confusing the intensity reference of one picowatt per square metre with the power reference of one picowatt','Assuming intensity level always equals pressure level exactly','Using a watt value instead of watts per square metre']::text[],ARRAY['Configuring a sound intensity analyser','Comparing intensity level to sound pressure level for a plane wave','Documenting references in an intensity-based sound power test']::text[],'intermediate','I₀ = 1 pW/m² = 10⁻¹² W/m²','The reference intensity is one picowatt per square metre, the fixed value used as the denominator in the sound intensity level calculation.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference intensity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '95f72edf-a9c3-5324-be2d-844f8000c620','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='95f72edf-a9c3-5324-be2d-844f8000c620') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='95f72edf-a9c3-5324-be2d-844f8000c620');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3bd93a7a-401a-52e8-b5e3-554352920419','Reference power','The standard sound power used as the denominator when computing sound power level, equal to one picowatt, that is ten to the power minus twelve watts. Sound power level is ten times the base-ten logarithm of a source''s radiated acoustic power divided by this reference, giving a level that characterises the source independently of the room or the distance.','This is the fixed power that power levels compare to. It equals one trillionth of a watt. Sound power level uses ten times the log of power over this value. It describes a source on its own.','It fixes the zero of the sound-power-level scale, so the total acoustic power a source radiates can be expressed in decibels independently of the listening position.','Manufacturers rate machinery and appliances by sound power level referenced to one picowatt; this lets buyers compare sources without regard to test-room acoustics.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sound power','Sound power level','Reference intensity','Reference quantity','Decibel']::text[],ARRAY['Confusing sound power level with sound pressure level, which depends on distance','Using the intensity reference instead of one picowatt','Applying the twenty-times-log rule to a power quantity']::text[],ARRAY['Reading a manufacturer''s sound power rating for a fan','Comparing appliance noise emissions by power level','Reporting laboratory sound power referenced to one picowatt']::text[],'intermediate','P₀ = 1 pW = 10⁻¹² W;  L_W = 10·log₁₀(P/P₀)','The reference power is one picowatt, the fixed value used as the denominator when sound power is expressed as a level in decibels.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reference power');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3bd93a7a-401a-52e8-b5e3-554352920419','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3bd93a7a-401a-52e8-b5e3-554352920419') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3bd93a7a-401a-52e8-b5e3-554352920419');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1f5cd2b0-ab99-5dbf-b4dc-2389a0d989e4','Absolute level','A level expressed relative to a fixed, internationally agreed reference quantity, so that the numerical value corresponds to a definite physical magnitude. Sound pressure level relative to twenty micropascals, and electrical levels relative to a defined reference voltage, are absolute levels because their references are defined constants. Absolute levels can be compared directly between measurements without further information about the signal.','An absolute level compares a value to a fixed standard reference. So the number means a set physical amount. Sound pressure level is one example. You can compare absolute levels directly.','It ties a decibel reading to a defined physical reference, so that the value alone conveys an actual magnitude and is comparable across systems.','Technicians use absolute levels when a reading must mean a specific pressure or voltage, such as in calibration and compliance measurements.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Relative level','Reference quantity','Sound pressure level','Decibel','Reference pressure']::text[],ARRAY['Treating a relative decibel figure as if it were absolute','Omitting the reference so the absolute meaning is lost','Mixing absolute and relative decibel values in one calculation']::text[],ARRAY['Calibrating a system to a target sound pressure level','Setting a console output to a defined voltage level','Verifying a level against a compliance limit']::text[],'intermediate','L = 20·log₁₀(x/x₀),  x₀ a fixed standard reference','An absolute level is the logarithmic ratio of a quantity to a fixed, internationally defined reference, so the number represents a definite physical magnitude.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Absolute level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1f5cd2b0-ab99-5dbf-b4dc-2389a0d989e4','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1f5cd2b0-ab99-5dbf-b4dc-2389a0d989e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1f5cd2b0-ab99-5dbf-b4dc-2389a0d989e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '87a3dd3f-1aa2-5786-83dc-57b163a81cee','Relative level','A level expressed with respect to a chosen or arbitrary reference within a signal or system rather than a fixed physical constant, so it conveys a change or ratio rather than an absolute magnitude. Examples include a level in decibels relative to a peak value, relative to a nominal alignment level, or the difference between two measured levels. Relative levels describe how much larger or smaller one value is than another.','A relative level compares a value to another value you choose. It shows a change, not a fixed amount. An example is decibels below a peak. It tells you how much louder or quieter something is.','It quantifies differences and ratios within a system, letting engineers describe gain, cut, and headroom without tying the number to an absolute physical reference.','Fader gains, equaliser boosts and cuts, and decibels-below-peak readings are relative levels used constantly when balancing a mix or setting headroom.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Absolute level','Level difference','Decibel','Reference quantity','Gain']::text[],ARRAY['Assuming a relative decibel value corresponds to a fixed sound pressure','Forgetting which value was used as the reference','Comparing relative levels that use different references']::text[],ARRAY['Reading a fader set to minus six decibels relative to unity','Expressing a peak as decibels below full scale','Describing an equaliser cut in decibels']::text[],'intermediate','ΔL = 20·log₁₀(x/x_ref),  x_ref chosen, not fixed','A relative level is the logarithmic ratio of a quantity to a chosen reference value, expressing a difference rather than an absolute magnitude.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Relative level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '87a3dd3f-1aa2-5786-83dc-57b163a81cee','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='87a3dd3f-1aa2-5786-83dc-57b163a81cee') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='87a3dd3f-1aa2-5786-83dc-57b163a81cee');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf3c62e1-8007-576c-a7df-0899c2aaf9b2','Level difference','The arithmetic difference between two levels expressed in decibels, equal to ten times the base-ten logarithm of the ratio of the two underlying power quantities. Because subtracting levels corresponds to dividing the original quantities, a level difference expresses how many times larger one quantity is than another. In building acoustics it also names the difference in sound pressure level between a source room and a receiving room.','A level difference is one level minus another, in decibels. Subtracting decibels is like dividing the raw values. So it shows a ratio between them. In building acoustics it compares two rooms.','It expresses the ratio between two quantities as a single decibel figure, which is why gains, losses, and sound insulation are all stated as level differences.','It describes insertion loss, gain, and the sound insulation between rooms; technicians read it directly by subtracting one decibel value from another.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Decibel','Attenuation','Relative level','Sound reduction index','Sound insulation']::text[],ARRAY['Adding levels when the underlying quantities should be summed as energy','Confusing a level difference with a ratio of the levels themselves','Ignoring background noise when measuring a room-to-room difference']::text[],ARRAY['Measuring the sound insulation between two rooms','Finding the insertion loss of a filter in decibels','Comparing two channel levels by subtraction']::text[],'beginner','ΔL = L₁ − L₂ = 10·log₁₀(P₁/P₂) dB','A level difference is one level minus another, equal to ten times the logarithm of the ratio of the two underlying power quantities.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Level difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf3c62e1-8007-576c-a7df-0899c2aaf9b2','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf3c62e1-8007-576c-a7df-0899c2aaf9b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf3c62e1-8007-576c-a7df-0899c2aaf9b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '661bbc19-2087-5c49-95af-e3060e280229','Attenuation','The reduction in the magnitude of a signal or acoustic quantity as it passes through a medium, device, or distance, expressed in decibels as ten times the base-ten logarithm of the input-to-output power ratio, or twenty times the logarithm of the input-to-output field ratio. Attenuation is the opposite of gain and is always a loss; it may arise from absorption, spreading, filtering, or deliberate padding.','Attenuation is a drop in signal or sound level. It is the opposite of gain. It happens through distance, materials, or a device. You measure how much is lost in decibels.','It quantifies how much a signal or sound is reduced, whether unwanted, such as cable loss or air absorption, or deliberate, such as a pad protecting an input.','Technicians insert pads and attenuators to prevent overload, and account for cable, distance, and material attenuation when planning gain structure and coverage.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Gain','Insertion loss','Pad','Level difference','Decibel']::text[],ARRAY['Confusing attenuation with distortion or noise rather than a level reduction','Using the ten-times-log rule on voltage quantities that need the twenty-times-log rule','Assuming a pad changes tone rather than only reducing level']::text[],ARRAY['Adding a pad to tame a hot microphone signal','Accounting for cable loss over a long run','Estimating the level drop from a barrier or absorber']::text[],'beginner','A = 10·log₁₀(P_in/P_out) = 20·log₁₀(V_in/V_out) dB','Attenuation in decibels is ten times the logarithm of the input-to-output power ratio, or twenty times the logarithm of the input-to-output voltage ratio.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Attenuation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '661bbc19-2087-5c49-95af-e3060e280229','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='661bbc19-2087-5c49-95af-e3060e280229') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='661bbc19-2087-5c49-95af-e3060e280229');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8f49076c-9483-54b2-bd66-445046e1e466','L95','A statistical, or percentile, sound level equal to the A-weighted sound pressure level that is exceeded for ninety-five percent of the measurement period. Because the level falls below it for only five percent of the time, L95 represents the quieter, steadier part of a fluctuating noise climate and is widely used as an estimate of the underlying background level.','L95 is the level passed for ninety-five percent of the time. The sound drops below it only five percent of the time. So it marks the steady, quiet part of the noise. People use it for background level.','It captures the near-continuous floor of a fluctuating sound, giving a repeatable descriptor of background noise that is little affected by brief loud events.','Environmental-noise consultants report L95 as the background level in planning work and in assessments of industrial or entertainment noise.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Background level','Percentile level','L90','Residual level','Equivalent continuous sound level']::text[],ARRAY['Confusing L95, exceeded ninety-five percent of the time, with L5, exceeded only five percent of the time','Treating L95 as an average rather than a percentile','Assuming it captures loud transient events']::text[],ARRAY['Estimating the background level for a noise-impact assessment','Characterising a quiet rural night-time climate','Comparing background before and after a new source starts']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='L95');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8f49076c-9483-54b2-bd66-445046e1e466','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8f49076c-9483-54b2-bd66-445046e1e466') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8f49076c-9483-54b2-bd66-445046e1e466');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '248d0c13-2e78-570b-82f9-d89567d09826','Background level','The sound pressure level present at a location in the absence of the specific source under investigation, representing the underlying noise against which that source is judged. In practice it is often estimated by a low percentile level such as L90 or L95, which reflects the steadier, quieter portion of the environment. A meaningful measurement of a source requires its level to stand clearly above the background.','Background level is the sound without the source you care about. It is the noise that is always there. It is often measured as L90 or L95. A source must rise above it to be measured well.','It establishes the baseline noise a source must be separated from, so that measurements of the source are not contaminated by everything else present.','Before measuring a machine or venue, technicians record the background level to apply corrections and confirm the source is high enough above it to measure reliably.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Residual level','Ambient level','L90','L95','Signal-to-noise ratio']::text[],ARRAY['Confusing background level with the total ambient level that includes the source','Failing to measure the background before switching on the source','Ignoring the background when the source is only a few decibels above it']::text[],ARRAY['Recording background noise before a machine test','Applying a background correction to a source measurement','Assessing whether a source is audible above the background']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Background level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '248d0c13-2e78-570b-82f9-d89567d09826','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='248d0c13-2e78-570b-82f9-d89567d09826') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='248d0c13-2e78-570b-82f9-d89567d09826');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f281692e-2425-55b7-97a7-35e51b7d76eb','Residual level','The sound pressure level that remains at a position when the specific sound under assessment is removed, as defined in environmental-noise standards. It is the ambient sound minus the particular source of interest, and serves as the baseline against which that source''s contribution and any character corrections are evaluated. It is closely related to, but defined more strictly than, the everyday notion of background noise.','Residual level is what is left when the target source stops. It is the rest of the sound at that spot. Noise standards use it as a strict baseline. The source is judged against it.','It provides the standardised baseline used to isolate a specific source''s contribution to the total sound at a location.','In environmental-noise assessments, technicians measure the residual sound with the source switched off to separate it from the specific sound level.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Ambient level','Background level','Specific sound level','Environmental noise','L90']::text[],ARRAY['Confusing residual sound with ambient sound, which includes the source','Measuring the residual while the source is still contributing','Treating residual and background as identical without regard to the standard''s definitions']::text[],ARRAY['Measuring residual sound with an industrial source switched off','Separating a specific source in an environmental-noise assessment','Establishing a baseline for a planning noise condition']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Residual level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f281692e-2425-55b7-97a7-35e51b7d76eb','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f281692e-2425-55b7-97a7-35e51b7d76eb') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f281692e-2425-55b7-97a7-35e51b7d76eb');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e2c82f62-c31f-5581-8f01-df1a6228a466','Ambient level','The total sound pressure level at a location arising from all sources near and far, including the specific source under assessment. In environmental-noise terminology the ambient sound is the all-encompassing sound in a given situation; removing the specific source of interest from it leaves the residual sound. It is normally measured with A-weighting as an equivalent continuous level over a stated period.','Ambient level is all the sound at a place at once. It includes every source, near and far. Take away the source you study and the residual is left. It is usually an A-weighted average.','It describes the complete sound environment, providing the total against which specific sources and residual sound are compared.','Technicians log the ambient level with a meter to characterise a site''s overall noise climate for planning, monitoring, or design.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Residual level','Background level','Specific sound level','Equivalent continuous sound level','Environmental noise']::text[],ARRAY['Confusing ambient sound, from all sources, with residual sound, which has the source removed','Assuming ambient equals background, which is only its quieter part','Using too short a period to represent a varying environment']::text[],ARRAY['Characterising the overall noise climate of a site','Logging ambient levels over a twenty-four-hour period','Comparing ambient sound before and after a development']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambient level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e2c82f62-c31f-5581-8f01-df1a6228a466','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e2c82f62-c31f-5581-8f01-df1a6228a466') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e2c82f62-c31f-5581-8f01-df1a6228a466');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eef4e572-175c-5036-a130-1ee73cc7eca6','Normalized level','A measured level adjusted to a standard reference condition so that results from different rooms or setups can be compared. In building acoustics the normalized level difference corrects the raw difference between two rooms for the receiving room''s sound absorption, referring it to a reference equivalent absorption area of ten square metres. Normalization removes the influence of a particular measurement environment from the reported figure.','A normalized level is adjusted to a standard condition. This removes the effect of the test room. In buildings it corrects for how much the room absorbs sound. Then different rooms can be compared fairly.','It strips out the effect of a specific test environment, such as a room''s absorption, so measured levels can be compared on a common basis.','Building acousticians report normalized level differences for facades and partitions, so ratings do not depend on the furnishing or absorption of the receiving room.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Standardized level','Level difference','Equivalent absorption area','Sound insulation','Reference quantity']::text[],ARRAY['Confusing normalization to absorption with standardization to reverberation time','Using the wrong reference absorption area','Comparing raw and normalized differences as if they were equivalent']::text[],ARRAY['Reporting facade sound insulation to a common absorption','Comparing partition tests done in different rooms','Correcting a level difference for receiving-room absorption']::text[],'intermediate','D_n = D − 10·log₁₀(A/A₀) dB,  A₀ = 10 m²','The normalized level difference is the measured level difference corrected by ten times the logarithm of the receiving room''s absorption divided by a reference of ten square metres.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Normalized level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eef4e572-175c-5036-a130-1ee73cc7eca6','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eef4e572-175c-5036-a130-1ee73cc7eca6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eef4e572-175c-5036-a130-1ee73cc7eca6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9f74144f-553f-5dcb-a48c-f655b8abd650','Standardized level','A measured level corrected according to a defined standard procedure so that reported values are consistent between measurements. In building acoustics the standardized level difference refers the raw difference between two rooms to a reference reverberation time of half a second, correcting for the receiving room''s reverberation instead of its absorption. It expresses room-to-room performance under a fixed, agreed reference condition.','A standardized level is fixed to a set standard state. In buildings it uses a set echo time. That time is half a second. This lets us compare results from different rooms.','It refers a measurement to a defined standard condition, such as a reference reverberation time, so ratings are reproducible and comparable across sites.','Field tests of dwellings report the standardized level difference, so that sound insulation ratings reflect the partition rather than the receiving room''s reverberation.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Normalized level','Level difference','Reverberation time','Sound insulation','Reference quantity']::text[],ARRAY['Confusing standardization to reverberation time with normalization to absorption','Using a reference reverberation time other than the specified value','Reporting the uncorrected level difference as standardized']::text[],ARRAY['Field-testing sound insulation between dwellings','Reporting the standardized level difference for a party wall','Comparing standardized differences across projects']::text[],'intermediate','D_nT = D + 10·log₁₀(T/T₀) dB,  T₀ = 0.5 s','The standardized level difference is the measured level difference corrected by ten times the logarithm of the receiving room''s reverberation time divided by a reference of half a second.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Standardized level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9f74144f-553f-5dcb-a48c-f655b8abd650','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9f74144f-553f-5dcb-a48c-f655b8abd650') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9f74144f-553f-5dcb-a48c-f655b8abd650');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a080b12e-699e-5934-962c-346fe92094cf','Day-evening-night level','A composite environmental-noise indicator that combines A-weighted equivalent continuous sound levels for the day, evening, and night periods into a single long-term value, applying a five-decibel penalty to the evening period and a ten-decibel penalty to the night period to reflect greater sensitivity at those times. The three period levels are energy-averaged over their respective twelve-, four-, and eight-hour durations. It is a primary indicator for strategic noise mapping in environmental-noise policy.','This blends day, evening, and night noise into one number. Evening noise gets a five decibel penalty. Night noise gets a ten decibel penalty. The penalties reflect that noise bothers people more then.','It summarises a whole day''s noise exposure in one figure while weighting evening and night more heavily, supporting fair comparison and mapping of long-term community noise.','It drives strategic noise maps and action plans for roads, railways, and airports, and appears in planning limits for long-term community noise exposure.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Night level','Equivalent continuous sound level','Environmental noise','A-weighting','Day level']::text[],ARRAY['Forgetting the five-decibel evening and ten-decibel night penalties','Weighting the periods equally instead of by twelve, four, and eight hours','Treating it as a simple arithmetic average of the three levels']::text[],ARRAY['Producing a strategic noise map for a motorway','Assessing airport noise against a day-evening-night limit','Comparing long-term community exposure between sites']::text[],'advanced','L_den = 10·log₁₀[ (1/24)(12·10^(L_day/10) + 4·10^((L_eve+5)/10) + 8·10^((L_night+10)/10)) ]','The day-evening-night level energy-averages the day, evening, and night levels over twelve, four, and eight hours, adding five decibels to the evening and ten decibels to the night before combining them.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Day-evening-night level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a080b12e-699e-5934-962c-346fe92094cf','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a080b12e-699e-5934-962c-346fe92094cf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a080b12e-699e-5934-962c-346fe92094cf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4fbc3545-e7ea-59e8-8b7a-35dee0881e8c','Night level','The A-weighted equivalent continuous sound level determined over the night period, typically the eight hours from twenty-three hundred to oh seven hundred, and, for strategic assessment, averaged over a year. It is used on its own to assess sleep disturbance and night-time annoyance, and also forms the most heavily penalised term of the day-evening-night level. National definitions of the exact night period may vary within the framework of the governing standard.','Night level is the average noise over the night hours. The night is often eleven at night to seven in the morning. It is used to judge sleep disturbance. It is also the most penalized part of the combined day-evening-night level.','It isolates night-time noise exposure so that sleep disturbance and night annoyance can be assessed and limited separately from daytime noise.','Regulators set night-level limits for transport and industrial noise; acousticians measure or model it to check compliance and predict sleep-disturbance risk.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Day-evening-night level','Equivalent continuous sound level','Environmental noise','A-weighting','Background level']::text[],ARRAY['Assuming a fixed night period when national definitions differ','Confusing the single-year average with a single night''s measurement','Ignoring the ten-decibel night penalty when it feeds into the day-evening-night level']::text[],ARRAY['Assessing sleep disturbance near a railway','Checking night-time noise against a regulatory limit','Providing the night term for a day-evening-night calculation']::text[],'intermediate','L_night = 10·log₁₀[ (1/T_n) ∫ p²(t)/p₀² dt ],  T_n ≈ 8 h','Night level is the A-weighted equivalent continuous level over the roughly eight-hour night period, energy-averaging the squared pressure relative to the reference pressure.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Night level');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4fbc3545-e7ea-59e8-8b7a-35dee0881e8c','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4fbc3545-e7ea-59e8-8b7a-35dee0881e8c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4fbc3545-e7ea-59e8-8b7a-35dee0881e8c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f9cac56c-e518-548f-9228-bef02dbb7ab3','C-weighting','A standardised frequency weighting for sound level meters that is much flatter than A-weighting, with nominal minus-three-decibel points near thirty-one and a half hertz and eight kilohertz and only a slight roll-off between them. Defined in the sound-level-meter standard, it approximates the ear''s response at high sound levels and passes far more low-frequency energy than A-weighting. It is specified for peak sound level measurements and is widely used to assess low-frequency and high-level noise.','C-weighting is a filter used in sound meters. It is much flatter than A-weighting. It lets low bass through almost unchanged. It is used for loud sounds and for peak levels.','It shapes the meter''s frequency response to match hearing at high levels and to retain low-frequency content, so loud and bass-heavy noise is measured meaningfully.','Technicians use C-weighting for peak exposure and for checking low-frequency noise; the difference between C-weighted and A-weighted levels flags bass-heavy sources.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['A-weighting','Z-weighting','Frequency weighting','Peak sound level','Sound level meter']::text[],ARRAY['Assuming C-weighting is completely flat rather than gently rolled off at the extremes','Using A-weighting where peak measurements require C-weighting','Ignoring the C-minus-A difference as a low-frequency indicator']::text[],ARRAY['Measuring peak sound level at a concert','Checking low-frequency noise from a plant room','Comparing C-weighted and A-weighted levels to spot bass-heavy noise']::text[],'intermediate','C(f) = 20·log₁₀[ f₄²f² / ((f²+f₁²)(f²+f₄²)) ] + 0.06 dB;  f₁=20.6, f₄=12194 Hz','C-weighting applies low-frequency and high-frequency poles at about twenty-point-six and twelve thousand one hundred ninety-four hertz, normalised to zero decibels at one kilohertz with a small offset.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='C-weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f9cac56c-e518-548f-9228-bef02dbb7ab3','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f9cac56c-e518-548f-9228-bef02dbb7ab3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f9cac56c-e518-548f-9228-bef02dbb7ab3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd14d928f-a5d8-5cb9-9be9-f0aea711552f','Linear weighting','An older or informal designation for a flat, essentially unweighted frequency response in a sound level meter, in which all frequencies within the instrument''s range are passed with equal gain. It was often labelled Lin or Flat on instruments before the response was formally standardised; the current standardised equivalent is Z-weighting, a zero frequency weighting with a defined flat response and tolerance band.','Linear weighting means the meter treats all frequencies the same. No band is boosted or cut. Older meters labelled this Lin or Flat. Today the standard flat setting is called Z-weighting.','It provides an unshaped measurement that reflects the true spectral content of a signal, without the hearing-based emphasis of A-weighting or C-weighting.','Engineers select a flat or Z-weighting when they need the actual spectrum, such as measuring a source for analysis rather than judging the human response.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Z-weighting','Flat response','Frequency weighting','C-weighting','Unweighted level']::text[],ARRAY['Assuming linear weighting is identical across all instruments before standardization','Confusing linear frequency weighting with linear time averaging','Expecting linear-weighted levels to match A-weighted readings']::text[],ARRAY['Selecting a flat response to capture a true spectrum','Comparing an old Lin setting to modern Z-weighting','Measuring an unweighted level for octave-band analysis']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linear weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd14d928f-a5d8-5cb9-9be9-f0aea711552f','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d14d928f-a5d8-5cb9-9be9-f0aea711552f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d14d928f-a5d8-5cb9-9be9-f0aea711552f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'caf4f2b8-9736-53bf-b334-f7eeda63f666','Flat response','A frequency response in which output magnitude is essentially constant across the frequency range of interest, so no band is emphasised or attenuated relative to another. Applied to a measurement chain it means the instrument neither boosts nor cuts any frequency, capturing the signal''s true spectral balance; applied to equipment such as microphones or amplifiers it indicates uniform gain within a stated tolerance over a specified band.','Flat response means all frequencies come through evenly. No part of the spectrum is boosted or cut. A flat microphone captures sound as it is. It is judged within a stated tolerance.','It ensures a device or measurement path reproduces or reports the input spectrum faithfully, which is the baseline for accurate measurement and neutral reproduction.','Measurement microphones and reference monitors are chosen for flat response; technicians verify it with swept-sine or noise tests against a tolerance window.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Frequency response','Linear weighting','Z-weighting','Bandwidth','Tolerance']::text[],ARRAY['Treating any smooth response as perfectly flat regardless of tolerance','Ignoring the frequency band over which flatness is specified','Assuming a flat electrical response guarantees flat acoustic output in a room']::text[],ARRAY['Selecting a flat measurement microphone','Verifying a monitor''s response against a tolerance band','Checking a signal chain for coloration']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Flat response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'caf4f2b8-9736-53bf-b334-f7eeda63f666','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='caf4f2b8-9736-53bf-b334-f7eeda63f666') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='caf4f2b8-9736-53bf-b334-f7eeda63f666');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c19dda17-93fb-53af-b1da-9ca23309e277','Time weighting','The exponential time averaging applied by a sound level meter to a signal''s squared, frequency-weighted pressure, characterised by a standard time constant. The standardised settings are Fast, with a time constant of one hundred twenty-five milliseconds, and Slow, with a time constant of one second; a legacy Impulse setting uses a fast thirty-five-millisecond rise and a slow decay. A shorter time constant follows rapid fluctuations more closely, while a longer one produces a steadier, more readable display.','Time weighting sets how fast the meter reacts. Fast uses a one hundred twenty-five millisecond time constant. Slow uses a one second time constant. Fast follows quick changes; Slow gives a steadier reading.','It smooths the fluctuating signal so the display is readable, letting the user trade responsiveness to transients against steadiness of the reading.','Technicians pick Fast to catch short events and Slow for a stable level; the choice must be stated because it changes the reading of varying noise.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Fast time weighting','Slow time weighting','Impulse time weighting','Detector response','Equivalent continuous sound level']::text[],ARRAY['Confusing time weighting with frequency weighting','Comparing Fast and Slow readings as if they were interchangeable','Assuming time weighting affects the equivalent continuous level, which uses linear averaging']::text[],ARRAY['Using Slow to read a steady machine level','Using Fast to capture fluctuating traffic noise','Recording the time weighting alongside a reported level']::text[],'intermediate','p_τ²(t) = (1/τ) ∫_{−∞}^{t} p²(ξ)·e^{−(t−ξ)/τ} dξ;  Fast τ=0.125 s, Slow τ=1 s','Time weighting exponentially averages the squared pressure with a time constant, one hundred twenty-five milliseconds for Fast and one second for Slow.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Time weighting');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c19dda17-93fb-53af-b1da-9ca23309e277','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c19dda17-93fb-53af-b1da-9ca23309e277') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c19dda17-93fb-53af-b1da-9ca23309e277');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c595bff3-a290-5ff6-941a-154eb3d1bb08','Averaging time','The total duration over which a measurement is averaged, most importantly the integration period of an equivalent continuous sound level. The equivalent continuous level energy-averages the squared, frequency-weighted pressure over this time, so the averaging time must be stated with the result. It differs from exponential time weighting: the averaging time is a fixed window giving equal weight to all instants, whereas time weighting applies a continuously decaying exponential.','Averaging time is how long a measurement is averaged over. The equivalent level uses it as a fixed window. All the time in the window counts equally. The result depends on it, so it must be stated.','It defines the window for energy averaging, determining how far brief events are diluted into a longer-term equivalent level.','Choosing an averaging time, from minutes for a spot check to hours for exposure, sets what an equivalent level represents; technicians match it to the assessment period.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Equivalent continuous sound level','Time weighting','Integration time','Logging interval','Measurement period']::text[],ARRAY['Confusing averaging time, with equal weighting, with exponential time weighting','Reporting an equivalent continuous level without stating its averaging time','Using too short a window to represent a varying source']::text[],ARRAY['Setting a fifteen-minute equivalent level for an environmental spot check','Averaging over a full shift for exposure','Choosing an integration period for a noise survey']::text[],'intermediate','L_eq,T = 10·log₁₀[ (1/T) ∫₀ᵀ p²(t)/p₀² dt ] dB','The equivalent continuous level averages the squared pressure over the averaging time, relative to the reference pressure, then converts to decibels.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Averaging time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c595bff3-a290-5ff6-941a-154eb3d1bb08','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c595bff3-a290-5ff6-941a-154eb3d1bb08') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c595bff3-a290-5ff6-941a-154eb3d1bb08');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '27ea27a9-c5c5-561e-a15d-9105dff50c61','Sampling interval','The time between successive individual samples or readings taken by a measuring instrument, equal to the reciprocal of the sampling rate. In a sound level meter or data logger it sets how finely the fluctuating level is captured before further processing or storage. A shorter sampling interval resolves faster changes but produces more data.','The sampling interval is the time between one sample and the next. It is one divided by the sample rate. A shorter interval catches faster changes. It also makes more data to handle.','It determines the time resolution of the captured data, fixing how quickly changes in level can be tracked.','Setting the sampling interval on a logger balances time resolution against storage; too coarse an interval misses short events.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sampling rate','Logging interval','Time resolution','Averaging time','Data logger']::text[],ARRAY['Confusing the sampling interval with the logging interval for stored records','Choosing an interval too coarse to catch short events','Assuming a fine interval improves the accuracy of a steady level']::text[],ARRAY['Configuring a noise logger''s sample timing','Resolving fast level changes in a survey','Balancing data volume against time detail']::text[],'beginner','Δt = 1 / f_s','The sampling interval equals one divided by the sampling rate.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sampling interval');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '27ea27a9-c5c5-561e-a15d-9105dff50c61','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='27ea27a9-c5c5-561e-a15d-9105dff50c61') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='27ea27a9-c5c5-561e-a15d-9105dff50c61');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2a3715e-2fc0-5dda-85f3-ab4f883ee00e','Logging interval','The time spacing between successive measurement records that an instrument stores to memory, such as one stored equivalent level every second, minute, or fifteen minutes. Each logged value usually summarises the sound over that interval, for example an equivalent level with a maximum and a percentile set, so the logging interval sets the time resolution of the saved history rather than of the underlying measurement.','The logging interval is the gap between saved records. A meter might store one value each minute. Each stored value sums up that period. It sets how detailed the saved history is.','It controls the resolution and size of the stored measurement history, letting the user trade detail against memory and analysis effort.','Unattended noise loggers store an equivalent level and percentiles per logging interval; consultants pick it to match the assessment while keeping data manageable.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Sampling interval','Averaging time','Equivalent continuous sound level','Data logger','Time history']::text[],ARRAY['Confusing the logging interval with the sampling interval of raw data','Choosing an interval that hides short but important events','Assuming each logged value is an instantaneous sample rather than a summary']::text[],ARRAY['Setting fifteen-minute logging for a week-long survey','Storing per-second equivalent levels for a detailed event study','Matching the logging interval to a regulatory reporting period']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Logging interval');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2a3715e-2fc0-5dda-85f3-ab4f883ee00e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2a3715e-2fc0-5dda-85f3-ab4f883ee00e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2a3715e-2fc0-5dda-85f3-ab4f883ee00e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '683d4bb4-173b-5f56-b1cf-ca50a05a3915','Detector response','The way a sound level meter''s detector converts a fluctuating, frequency-weighted signal into the value it displays, characterised by the detection law and its dynamics. Standard meters use a true root-mean-square detector so the reading reflects signal energy, combined with a chosen exponential time weighting; a separate peak detector captures the highest instantaneous value. The detector response therefore determines whether the display tracks energy, peaks, or a smoothed average.','The detector response is how the meter turns a changing signal into a number. Most meters use a true RMS detector for energy. A peak detector catches the highest instant. The setting decides what the display shows.','It defines how the instrument reduces a varying signal to a reading, ensuring the displayed value corresponds to a defined measure such as root-mean-square energy or peak.','Choosing a root-mean-square detector with Fast or Slow, versus a peak detector, decides whether a meter reports energy-based levels or worst-case peaks for exposure checks.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Root mean square','Peak sound level','Time weighting','Crest factor','Sound level meter']::text[],ARRAY['Confusing a true root-mean-square reading with a peak reading','Assuming all meters use the same detection law','Ignoring crest factor when a signal is highly impulsive']::text[],ARRAY['Selecting root-mean-square versus peak detection for an exposure check','Measuring impulsive noise where the peak matters','Verifying that a meter uses a true root-mean-square detector']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Detector response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '683d4bb4-173b-5f56-b1cf-ca50a05a3915','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='683d4bb4-173b-5f56-b1cf-ca50a05a3915') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='683d4bb4-173b-5f56-b1cf-ca50a05a3915');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '45e710ba-0ac7-5f14-bec3-cb4cf4d0feb8','Overload indication','A warning provided by a sound level meter when the input signal exceeds the upper limit of the instrument''s valid operating range, so that the affected reading may be inaccurate. The standard requires an overload indicator that responds to the instantaneous signal and flags any measurement during which an overload occurred, allowing invalid data to be identified and rejected.','Overload indication warns that the sound was too loud to measure. The input went above the meter''s top limit. The reading may then be wrong. The warning lets you reject that data.','It alerts the user that a measurement exceeded the meter''s linear range, so that unreliable results can be discarded rather than trusted.','When metering loud transient events, technicians watch for the overload flag and repeat measurements on a higher range if it appears.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Under-range indication','Measurement range','Peak sound level','Linearity range','Dynamic range of meter']::text[],ARRAY['Ignoring an overload flag and reporting the invalid reading','Assuming an overload affects only the instant, not the whole measurement','Not switching to a higher range after repeated overloads']::text[],ARRAY['Metering loud impulsive noise near machinery','Rejecting a measurement flagged as overloaded','Choosing a higher range after an overload warning']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Overload indication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '45e710ba-0ac7-5f14-bec3-cb4cf4d0feb8','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='45e710ba-0ac7-5f14-bec3-cb4cf4d0feb8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='45e710ba-0ac7-5f14-bec3-cb4cf4d0feb8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '43592e60-b59f-52e2-a44f-18f200d6453b','Under-range indication','A warning that the input signal is too low for the sound level meter to measure reliably, because it approaches the instrument''s inherent noise floor. Near this limit the meter''s own electrical and thermal noise contributes significantly to the reading, so measured levels are no longer valid. The indicator lets the user recognise and discard measurements taken below the usable range.','Under-range indication warns that the sound was too quiet to measure. The signal is near the meter''s own noise. The reading then includes that noise. The warning tells you to reject it.','It signals that the measured level is corrupted by the instrument''s noise floor, so too-quiet measurements are not mistaken for valid data.','Measuring very quiet environments, technicians heed the under-range flag and switch to a more sensitive range or instrument.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Overload indication','Noise floor','Measurement range','Dynamic range of meter','Linearity range']::text[],ARRAY['Trusting a reading dominated by the meter''s own noise','Confusing under-range with a genuinely low ambient level','Failing to switch to a more sensitive range']::text[],ARRAY['Measuring a very quiet studio or chamber','Rejecting readings near the meter''s noise floor','Selecting a sensitive range for low-level work']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Under-range indication');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '43592e60-b59f-52e2-a44f-18f200d6453b','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='43592e60-b59f-52e2-a44f-18f200d6453b') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='43592e60-b59f-52e2-a44f-18f200d6453b');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cf51ffb8-ed61-5c16-81d5-24dd28ed8e0f','Dynamic range of meter','The span, in decibels, between the lowest level a sound level meter can measure reliably, set by its noise floor, and the highest level before overload, on a given range or overall. A wide dynamic range lets the instrument capture both quiet backgrounds and loud peaks without changing range. It is distinct from, though related to, the linearity range over which readings remain accurate.','The dynamic range is the gap between the quietest and loudest a meter can measure. The bottom is set by the meter''s own noise. The top is set by overload. A wide range covers soft and loud sounds.','It states how wide a level span the meter can handle at once, determining whether quiet and loud sounds can be measured without switching ranges.','Choosing a meter with adequate dynamic range avoids range changes during events with both quiet passages and loud peaks, such as concerts or vehicle pass-by tests.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Measurement range','Linearity range','Noise floor','Overload indication','Under-range indication']::text[],ARRAY['Confusing dynamic range with the full measurement range across all ranges','Ignoring the noise floor that sets the lower limit','Assuming full accuracy across the entire dynamic range']::text[],ARRAY['Selecting a meter for events with wide level swings','Avoiding range changes during a concert measurement','Comparing instruments by their single-range dynamic range']::text[],'intermediate','DR = L_max − L_min (dB)','The meter''s dynamic range in decibels is the highest measurable level before overload minus the lowest level set by the noise floor.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Dynamic range of meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cf51ffb8-ed61-5c16-81d5-24dd28ed8e0f','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cf51ffb8-ed61-5c16-81d5-24dd28ed8e0f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cf51ffb8-ed61-5c16-81d5-24dd28ed8e0f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '72a9cae4-56ef-5a66-818b-aefaa015249f','Measurement range','The span of sound levels, from a stated lower limit to an upper limit, over which a sound level meter is specified to operate for a given weighting and range setting. It is defined by the manufacturer in accordance with the instrument standard and marks the levels, between the under-range and overload limits, within which readings are considered valid. Instruments often provide several selectable ranges to cover a wider total span.','The measurement range is the band of levels a meter can read. It runs from a lowest to a highest level. Below or above it, readings are not valid. Many meters offer several ranges to switch between.','It tells the user the levels over which the instrument gives valid readings, so the correct range can be chosen for the sound being measured.','Technicians select a range that brackets the expected levels, keeping the signal above under-range and below overload for valid data.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Linearity range','Dynamic range of meter','Overload indication','Under-range indication','Sound level meter']::text[],ARRAY['Confusing a single range with the meter''s total span across all ranges','Measuring outside the specified range and trusting the result','Not selecting the range appropriate to the expected level']::text[],ARRAY['Choosing a range that brackets the expected levels','Reading the specified range from a datasheet','Switching range when levels drift out of bounds']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement range');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '72a9cae4-56ef-5a66-818b-aefaa015249f','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='72a9cae4-56ef-5a66-818b-aefaa015249f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='72a9cae4-56ef-5a66-818b-aefaa015249f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '226038a9-34bd-5ad2-b896-6aaa3c114715','Linearity range','The span of levels over which a sound level meter''s indicated reading changes in exact proportion to the input, within specified tolerances, as verified by level-linearity testing in the instrument standard. Across this range a given change in input level produces an equal change in the displayed level; outside it, near the noise floor or near overload, the reading departs from proportionality. The linearity range is a tested performance limit, not merely a nominal span.','The linearity range is where the meter reads in proportion to the input. A ten decibel rise in sound gives a ten decibel rise on the display. Near its noise floor or overload it stops tracking. Tests confirm this range.','It defines where the instrument''s readings stay proportional to the input, guaranteeing that level differences are reported accurately.','Calibration labs test level linearity to certify the range where a meter is accurate; users keep signals within it for trustworthy differences.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Measurement range','Dynamic range of meter','Level linearity','Overload indication','Traceable calibration']::text[],ARRAY['Confusing the linearity range with the broader measurement range','Assuming proportionality holds right up to overload','Overlooking linearity error near the noise floor']::text[],ARRAY['Certifying a meter''s level linearity in a lab','Keeping signals within the linear span for accurate differences','Interpreting linearity test results on a calibration certificate']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Linearity range');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '226038a9-34bd-5ad2-b896-6aaa3c114715','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='226038a9-34bd-5ad2-b896-6aaa3c114715') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='226038a9-34bd-5ad2-b896-6aaa3c114715');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5bf12a79-b206-52f8-a56e-5bc1e6fa3a53','Class 1 sound level meter','A precision-grade sound level meter meeting the tighter tolerance limits and wider frequency range of the highest performance class in the instrument standard. Class 1 instruments have smaller permitted errors across frequency and are specified over a broader frequency range than Class 2, making them suitable for precise laboratory and regulatory measurements. The class designates conformance to a tolerance grade, not a single fixed accuracy figure at every point.','A Class 1 meter is a precision instrument. It must meet tight error limits. It works accurately over a wide frequency range. It is used for lab work and legal measurements.','It provides the accuracy and frequency coverage needed where measurements must be defensible, such as regulatory enforcement and laboratory testing.','Consultants use Class 1 meters and matching Class 1 calibrators for enforcement, environmental assessments, and any work requiring the highest confidence.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Class 2 sound level meter','Traceable calibration','Frequency weighting','Tolerance','Sound level meter']::text[],ARRAY['Assuming Class 1 means error-free rather than tighter tolerances','Pairing a Class 1 meter with a lower-class calibrator','Using Class 2 where a standard or regulator requires Class 1']::text[],ARRAY['Performing a regulatory enforcement measurement','Laboratory testing of product noise','Selecting an instrument class to meet a standard''s requirement']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class 1 sound level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5bf12a79-b206-52f8-a56e-5bc1e6fa3a53','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5bf12a79-b206-52f8-a56e-5bc1e6fa3a53') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5bf12a79-b206-52f8-a56e-5bc1e6fa3a53');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '163f8f2e-5e66-5091-b7a3-4329bed409b1','Class 2 sound level meter','A general-purpose sound level meter meeting the wider tolerance limits and somewhat narrower frequency range of the lower performance class in the instrument standard. Class 2 instruments are accepted for many occupational and general noise measurements where the tighter performance of Class 1 is not required. Their larger permitted errors, particularly at the frequency extremes, must be considered when a standard or regulation specifies a class.','A Class 2 meter is a general-purpose instrument. Its error limits are wider than Class 1. It suits everyday noise checks. Some rules still require the tighter Class 1.','It offers adequate accuracy for routine and occupational noise measurement at lower cost than Class 1, where regulations permit its use.','Class 2 meters are common for workplace noise surveys and general assessments; the user must confirm a Class 2 instrument is acceptable for the task.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Class 1 sound level meter','Traceable calibration','Frequency weighting','Tolerance','Sound level meter']::text[],ARRAY['Using a Class 2 meter where the standard demands Class 1','Ignoring the larger Class 2 errors at high and low frequencies','Assuming Class 2 and Class 1 give identical readings']::text[],ARRAY['Conducting a workplace noise survey','General environmental spot checks','Confirming Class 2 is acceptable for a given regulation']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Class 2 sound level meter');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '163f8f2e-5e66-5091-b7a3-4329bed409b1','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='163f8f2e-5e66-5091-b7a3-4329bed409b1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='163f8f2e-5e66-5091-b7a3-4329bed409b1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9d910aba-af37-5a8d-958f-0d1df853d641','Traceable calibration','A calibration whose result is linked, through an unbroken chain of documented comparisons each with a stated uncertainty, to recognised national or international measurement standards, ultimately the base units of the International System. For acoustic instruments this means the reference calibrator or microphone is certified against higher-order standards held by a national metrology institute. Traceability underpins the validity and comparability of measurements and is required for defensible or regulatory work.','Traceable calibration links a meter to national standards. It uses a chain of checks with known error. Each step ties back to official base standards. This makes readings trustworthy and easy to compare.','It establishes confidence that an instrument''s readings are correct and comparable, by tying its calibration to the recognised standards that define the units.','Labs calibrate sound level meters and calibrators against traceable references and issue certificates; users perform field calibration checks between laboratory calibrations.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Calibration','Measurement uncertainty','Acoustic calibrator','National metrology institute','Class 1 sound level meter']::text[],ARRAY['Assuming a field check with a calibrator replaces periodic traceable laboratory calibration','Overlooking the stated uncertainty in each step of the chain','Treating an expired calibration certificate as still valid']::text[],ARRAY['Sending a meter for annual traceable calibration','Performing a daily field calibration check','Providing calibration certificates for a legal measurement']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Traceable calibration');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9d910aba-af37-5a8d-958f-0d1df853d641','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9d910aba-af37-5a8d-958f-0d1df853d641') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9d910aba-af37-5a8d-958f-0d1df853d641');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4caec28c-56f4-5da9-9e62-3ee2963218d1','Hertz','The SI unit of frequency, equal to one cycle, or one complete oscillation, per second. In acoustics it expresses how many times per second a periodic pressure disturbance repeats, and it is the standard unit for the frequency of sound waves and audio signals. One hertz equals one reciprocal second.','Hertz is the unit for frequency. One hertz means one cycle each second. A 100 hertz tone repeats 100 times a second. Higher hertz values sound higher in pitch.','It gives a standard, universal way to state how fast a sound or signal oscillates, so pitch, tuning, and filter settings can be specified and compared.','Technicians read hertz on tuners, analyzers, and equalizers, setting crossover points, filter frequencies, and oscillator tones by their value in hertz.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Frequency','Kilohertz','Period','Cycle','Pitch']::text[],ARRAY['Confusing hertz, a rate, with the period, its reciprocal in seconds','Assuming higher hertz means louder rather than higher pitched','Writing hertz for angular frequency, which is stated in radians per second']::text[],ARRAY['Setting an oscillator to 1000 hertz for testing','Reading a spectrum analyzer''s frequency axis','Tuning an instrument to a 440 hertz reference']::text[],'beginner','f = 1/T;  1 Hz = 1 s⁻¹','Frequency in hertz equals one divided by the period in seconds; one hertz is one cycle per second.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Hertz');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4caec28c-56f4-5da9-9e62-3ee2963218d1','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4caec28c-56f4-5da9-9e62-3ee2963218d1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4caec28c-56f4-5da9-9e62-3ee2963218d1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c1d571a4-7032-576a-8b0e-225529a72e51','Kilohertz','A decimal multiple of the hertz equal to one thousand hertz. It is the customary unit for stating audio and acoustic frequencies in the upper part of the hearing range, and for sample and radio rates, where values in plain hertz would be inconveniently large.','One kilohertz is one thousand hertz. It is written kHz. A 2 kHz tone is 2000 cycles each second. It is used for higher pitched sounds.','It keeps frequency values short and readable in the thousands-of-hertz region, easing work with treble content, sample rates, and filter settings.','Engineers speak of a 3 kHz presence boost or a 44.1 kHz sample rate, using kilohertz on analyzers, equalizers, and converter specifications.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Hertz','Frequency','Megahertz','Sample rate','Treble']::text[],ARRAY['Confusing kilohertz with kilobits or kilobytes per second','Writing an uppercase K instead of the correct lowercase k for kilo','Treating 1 kHz as 100 hertz instead of 1000 hertz']::text[],ARRAY['Setting a sample rate of 48 kHz','Boosting presence near 3 kHz on a vocal','Reading the treble region of a spectrum display']::text[],'beginner','1 kHz = 10³ Hz = 1000 Hz','One kilohertz equals one thousand hertz, or ten to the third power hertz.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Kilohertz');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c1d571a4-7032-576a-8b0e-225529a72e51','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c1d571a4-7032-576a-8b0e-225529a72e51') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c1d571a4-7032-576a-8b0e-225529a72e51');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '69a057bb-2239-515b-a238-259f8c731b00','Harmonic','A frequency component of a periodic signal located at an integer multiple of the fundamental frequency. The fundamental is the first harmonic; the component at twice that frequency is the second harmonic, and so on. Harmonics arise from the Fourier decomposition of any periodic waveform and, with the fundamental, define its timbre.','A harmonic is part of a musical tone. Its frequency is a whole-number multiple of the lowest tone. If the base is 100 hertz, harmonics fall at 200, 300, and 400 hertz. They shape how the sound feels.','Harmonics explain why instruments and voices at the same pitch sound different, and they underlie tuning, additive synthesis, and distortion analysis.','Technicians see harmonics as evenly spaced peaks on an analyzer and track them when measuring distortion or shaping tone with equalization.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Fundamental frequency','Partial','Overtone','Harmonic series','Total harmonic distortion']::text[],ARRAY['Confusing the second harmonic with the first overtone in numbering','Assuming all partials of a real instrument are harmonic','Treating harmonics as unrelated tones rather than multiples of the fundamental']::text[],ARRAY['Reading harmonic peaks on a spectrum analyzer','Measuring total harmonic distortion of an amplifier','Identifying the fundamental among its harmonics']::text[],'intermediate','fₙ = n·f₀,  n = 1, 2, 3, …','The nth harmonic frequency equals n times the fundamental frequency, for whole numbers n.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Harmonic');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '69a057bb-2239-515b-a238-259f8c731b00','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='69a057bb-2239-515b-a238-259f8c731b00') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='69a057bb-2239-515b-a238-259f8c731b00');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'fbbb4cfe-d0a2-5885-878c-af8f13f2d949','Partial','Any individual sinusoidal frequency component present in a complex tone, whether or not its frequency is an integer multiple of the fundamental. The term is neutral: harmonic partials fall on the harmonic series, while inharmonic partials do not. A complex tone is the sum of its partials, each with its own frequency, amplitude, and phase.','A partial is one single frequency inside a fuller sound. A complex sound is many partials added together. Some partials line up as harmonics. Others sit off the harmonic series.','The idea lets us describe any sound, tuned or untuned, as a set of pure tones, which is the basis of spectral analysis and synthesis.','In additive synthesis and analyzer work, technicians treat each peak as a partial with a frequency, level, and phase to rebuild or study a sound.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Harmonic','Overtone','Inharmonic partial','Spectral content','Fundamental frequency']::text[],ARRAY['Using partial and harmonic as if they always mean the same thing','Assuming every partial is tuned to the fundamental','Forgetting that the fundamental is itself a partial']::text[],ARRAY['Analyzing a bell''s partials on a spectrogram','Building a tone in an additive synthesizer','Separating tuned and untuned partials in a sound']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Partial');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'fbbb4cfe-d0a2-5885-878c-af8f13f2d949','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='fbbb4cfe-d0a2-5885-878c-af8f13f2d949') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='fbbb4cfe-d0a2-5885-878c-af8f13f2d949');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c98a31ea-a95c-59fe-8d6a-34e71fb6a1b3','Inharmonic partial','A partial whose frequency does not coincide with an integer multiple of the fundamental, so it lies off the harmonic series. Inharmonic partials are typical of percussion, bells, and stiff strings, where dispersion and complex mode shapes place resonances at non-integer ratios. Their presence gives such sounds an ambiguous or bell-like pitch.','An inharmonic partial is a frequency that does not fit the harmonic pattern. Its pitch is not a whole-number multiple of the base tone. Bells and drums are full of them. This makes their pitch feel less clear.','It explains why some sources have a vague or metallic pitch, informing how we analyze, tune, and synthesize percussion and struck instruments.','When measuring cymbals, bells, or piano strings, technicians see partials that do not fall on neat multiples and account for this in tuning and synthesis.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Partial','Harmonic','Inharmonicity','Overtone','Spectral content']::text[],ARRAY['Expecting all struck instruments to have harmonic partials','Confusing inharmonicity with simply being detuned','Assuming inharmonic partials have no defined pitch at all']::text[],ARRAY['Analyzing bell partials that fall off the harmonic series','Modeling piano string stiffness in synthesis','Explaining a cymbal''s unclear pitch']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Inharmonic partial');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c98a31ea-a95c-59fe-8d6a-34e71fb6a1b3','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c98a31ea-a95c-59fe-8d6a-34e71fb6a1b3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c98a31ea-a95c-59fe-8d6a-34e71fb6a1b3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '86dc1328-283b-55bb-872c-96f224429740','Spectral content','The set of frequency components present in a signal, together with their amplitudes and, in a full description, their phases. It is what a Fourier transform reveals: how a sound''s energy is distributed across frequency. Spectral content determines timbre and is displayed as a spectrum or spectrogram.','Spectral content is the mix of frequencies in a sound. It shows which pitches are present and how strong each is. A tool called a spectrum shows this. It is why a flute and a guitar sound different.','Describing a sound by its spectral content lets engineers judge tone, spot problems, and shape sound with filters and equalizers.','On a real-time analyzer, technicians read spectral content to find harsh bands, resonances, or missing energy before adjusting equalization.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Spectrum','Frequency response','Partial','Timbre','Fourier transform']::text[],ARRAY['Confusing spectral content with loudness alone','Reading a single snapshot as if the spectrum never changes','Ignoring phase when it matters to the result']::text[],ARRAY['Checking the spectral content of a mix on an analyzer','Finding a resonant peak in a room','Comparing the tone of two microphones']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spectral content');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '86dc1328-283b-55bb-872c-96f224429740','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='86dc1328-283b-55bb-872c-96f224429740') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='86dc1328-283b-55bb-872c-96f224429740');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '22d783f8-5e37-550c-ae10-5179d5b37e2e','Narrowband','Describing a signal, filter, or analysis whose energy or passband occupies a small range of frequencies relative to its centre frequency. In spectral analysis, narrowband refers to constant, fine absolute bandwidth, such as a fixed-width FFT bin, that resolves closely spaced tones. A narrowband signal is dominated by a small span of frequencies.','Narrowband means a small span of frequencies. A narrowband filter passes only a thin slice. Narrowband analysis can tell close tones apart. It zooms in on a small part of the spectrum.','Narrowband analysis and filtering isolate individual tones and resonances that coarse, wide bands would blur together.','Engineers switch an analyzer to narrowband FFT to separate a hum''s harmonics or to pin down a single feedback frequency.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Broadband','Resolution bandwidth','Bandwidth','Fast Fourier transform','Fractional-octave band']::text[],ARRAY['Confusing narrowband constant bandwidth with fractional-octave bands','Assuming narrowband always means low frequency','Expecting narrowband analysis to update as fast as broadband']::text[],ARRAY['Using narrowband FFT to find a hum frequency','Isolating one feedback tone','Separating closely spaced harmonics']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Narrowband');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '22d783f8-5e37-550c-ae10-5179d5b37e2e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='22d783f8-5e37-550c-ae10-5179d5b37e2e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='22d783f8-5e37-550c-ae10-5179d5b37e2e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'ae06c82c-30f3-5e0d-9572-451e359c60d4','Broadband','Describing a signal, source, or process whose energy is spread over a wide, continuous range of frequencies rather than concentrated at discrete tones. Broadband noise such as white or pink noise contains all frequencies within a band; a broadband measurement sums energy across the whole range instead of resolving individual components.','Broadband means a wide range of frequencies at once. Broadband noise has energy spread everywhere. A broadband level adds up the whole range. Hiss and rushing water are broadband.','Broadband signals and measures describe overall energy and are used to test systems evenly across the spectrum.','Technicians play broadband pink noise to check a sound system''s response, or read a broadband sound level to summarize total noise.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Narrowband','Pink noise','White noise','Bandwidth','Frequency range']::text[],ARRAY['Confusing a broadband level with a single-frequency reading','Assuming broadband noise looks flat in every analyzer view','Treating broadband and full-range as identical in every context']::text[],ARRAY['Playing broadband pink noise to tune a room','Reading a broadband noise level','Testing a loudspeaker across its whole range']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Broadband');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'ae06c82c-30f3-5e0d-9572-451e359c60d4','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='ae06c82c-30f3-5e0d-9572-451e359c60d4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='ae06c82c-30f3-5e0d-9572-451e359c60d4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'cdcc7d44-2431-5b96-a0b9-7f164ff96dcd','Fractional-octave band','A frequency band whose width is a fixed fraction of an octave, defined by upper and lower band-edge frequencies in a constant ratio. For a one-over-N-octave band the ratio of upper to lower edge is two raised to the one-over-N power, giving constant-percentage (proportional) bandwidth. Standardized octave and fractional-octave filters, such as one-first, one-third, and one-twelfth octave, are specified for acoustic analysis.','A fractional-octave band is a slice of the spectrum. Its width is a set part of an octave. One-third octave is a common choice. The bands get wider as frequency rises.','Fractional-octave bands give a frequency resolution that follows how we hear, with proportional widths, making them standard for acoustic and audio spectra.','Real-time analyzers show one-third or one-twelfth octave bars, which technicians use to equalize systems and measure room and product noise.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['One-third octave band','Octave band','Constant-percentage bandwidth','Real-time analyzer','Resolution bandwidth']::text[],ARRAY['Confusing constant-percentage bands with constant-width narrowband bins','Assuming all bands have equal absolute width in hertz','Mixing base-two and base-ten band-edge definitions without noting it']::text[],ARRAY['Choosing one-third octave bands on an analyzer','Comparing octave and fractional-octave resolution','Measuring product noise in standard bands']::text[],'intermediate','f_upper / f_lower = 2^(1/N)   (1/N-octave)','For a one-over-N octave band, the upper edge divided by the lower edge equals two to the power one over N.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fractional-octave band');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'cdcc7d44-2431-5b96-a0b9-7f164ff96dcd','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='cdcc7d44-2431-5b96-a0b9-7f164ff96dcd') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='cdcc7d44-2431-5b96-a0b9-7f164ff96dcd');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'bb6e83e2-339e-5d07-bca1-d3dc61d87f4d','One-third octave band','A fractional-octave band one third of an octave wide, the most common proportional bandwidth in acoustic measurement. Its band edges lie in a ratio of two to the one-third power, about 1.26, giving a bandwidth near twenty-three percent of the centre frequency. Standard centre frequencies and filter tolerances are defined for these bands, with three bands per octave across the audio range.','A one-third octave band covers one third of an octave. Three of them make one full octave. Each band is about a quarter as wide as its centre pitch. It is the usual choice for room and noise work.','One-third octave bands balance frequency detail and readability, matching hearing well enough to be the workhorse resolution for acoustics.','Graphic equalizers and real-time analyzers use one-third octave bands; technicians read them to flatten rooms and to log environmental and product noise.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Fractional-octave band','Octave band','Graphic equalizer','Real-time analyzer','Constant-percentage bandwidth']::text[],ARRAY['Stating the band is exactly 1.26 times wide instead of about 23 percent bandwidth','Confusing rounded centre labels with the exact centre frequencies','Treating one-third octave bars as fine enough to find single tones']::text[],ARRAY['Tuning a room with a one-third octave equalizer','Logging noise in standard one-third octave bands','Reading a real-time analyzer in thirds of an octave']::text[],'intermediate','f_upper/f_lower = 2^(1/3) ≈ 1.26;  BW ≈ 0.23·f_c','Band edges sit in a ratio of two to the one-third power, near 1.26, so bandwidth is about twenty-three percent of the centre frequency.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='One-third octave band');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'bb6e83e2-339e-5d07-bca1-d3dc61d87f4d','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='bb6e83e2-339e-5d07-bca1-d3dc61d87f4d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='bb6e83e2-339e-5d07-bca1-d3dc61d87f4d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2d50000c-a5b1-5a01-9537-765335b0bd68','Resolution bandwidth','The effective width in frequency over which a spectrum analyzer integrates energy into one displayed point, setting the finest spacing at which two tones can be told apart. In an FFT analyzer the bin spacing equals the sample rate divided by the block length, equivalently the reciprocal of the window duration, and the effective width also depends on the window''s shape.','Resolution bandwidth is how finely an analyzer splits frequency. A small value tells close tones apart. It gets smaller as the measured time gets longer. It sets the detail of the spectrum.','It defines the trade-off between frequency detail and time or speed, telling the user how close two tones can be and still be seen apart.','Choosing a longer FFT block narrows the resolution bandwidth so technicians can separate a hum''s harmonics, at the cost of slower updates.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Fast Fourier transform','Window function','Narrowband','Bin','Bandwidth']::text[],ARRAY['Confusing bin spacing with the wider effective noise bandwidth of the window','Expecting fine resolution and fast time response at the same time','Ignoring the window shape''s effect on true resolution']::text[],ARRAY['Lengthening an FFT to resolve close tones','Setting resolution bandwidth on a spectrum analyzer','Trading time response for frequency detail']::text[],'advanced','Δf = f_s / N = 1/T   (FFT bin spacing)','The FFT bin spacing equals the sample rate divided by the block length, which is one divided by the window duration.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Resolution bandwidth');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2d50000c-a5b1-5a01-9537-765335b0bd68','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2d50000c-a5b1-5a01-9537-765335b0bd68') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2d50000c-a5b1-5a01-9537-765335b0bd68');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a2f4f3ef-79d1-593d-9f7a-a8a0129ef033','Frequency range','The span between the lowest and highest frequencies that a device, signal, or measurement covers, usually stated as a pair of limits in hertz. For equipment the limits are commonly the points at which the response falls by a stated amount, such as three decibels. The nominal audio range of human hearing is about twenty hertz to twenty kilohertz.','Frequency range is the span from the lowest to the highest frequency. It is given as two numbers in hertz. Human hearing runs about 20 to 20000 hertz. Gear lists a range to show what it can handle.','Stating a frequency range summarizes at a glance what a system can capture or reproduce, aiding selection and comparison.','Technicians match a microphone''s or loudspeaker''s frequency range to the job and check that a system covers the needed low and high limits.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Bandwidth','Frequency response','Hertz','Audio band','Broadband']::text[],ARRAY['Confusing frequency range with a flat frequency response','Ignoring the decibel limits that define the stated endpoints','Assuming a wider range always means better sound']::text[],ARRAY['Checking a loudspeaker''s frequency range for a venue','Comparing microphone frequency ranges','Confirming a system reaches low bass']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Frequency range');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a2f4f3ef-79d1-593d-9f7a-a8a0129ef033','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a2f4f3ef-79d1-593d-9f7a-a8a0129ef033') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a2f4f3ef-79d1-593d-9f7a-a8a0129ef033');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8d3c819a-ce23-59db-8071-b4f06d717696','Complex response','A description of a system''s response that specifies both magnitude and phase as functions of frequency, expressed as a complex-valued frequency response or transfer function. It captures not only how much each frequency is passed but also the phase shift or time delay applied, information a magnitude-only curve omits. The complex response is what dual-channel transfer-function measurement recovers.','Complex response gives both size and timing at each frequency. It shows how much a system passes and how much it shifts phase. A plain size curve leaves the timing out. Both parts matter for how a system behaves.','It fully characterizes a linear system, so magnitude, phase, and delay can all be checked, aligned, and corrected.','Transfer-function tools show magnitude and phase together; technicians use the complex response to time-align loudspeakers and set delays.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Frequency response','Transfer function','Phase response','Magnitude response','Group delay']::text[],ARRAY['Judging a system by magnitude while ignoring phase','Assuming a flat magnitude means no phase shift','Forgetting that phase wraps and needs unwrapping to read delay']::text[],ARRAY['Time-aligning subwoofers with a transfer-function tool','Reading magnitude and phase together','Setting delay from measured phase']::text[],'advanced','H(f) = |H(f)|·e^{jφ(f)}','The complex response at each frequency has a magnitude and a phase angle, written as magnitude times e to the j times phase.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Complex response');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8d3c819a-ce23-59db-8071-b4f06d717696','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8d3c819a-ce23-59db-8071-b4f06d717696') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8d3c819a-ce23-59db-8071-b4f06d717696');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'e642c50d-8e96-5fc0-bc75-80f5964d013c','Medium','The material substance through which a sound wave travels, supplying the mass and elasticity needed to carry the wave. Sound is a mechanical wave and cannot propagate without a medium; it moves as compressions and rarefactions of the medium''s particles. Gases, liquids, and solids all act as media, each with a characteristic sound speed and impedance.','A medium is the material that sound moves through. It can be air, water, or solid matter. Sound needs a medium and cannot travel in a vacuum. The medium''s makeup sets how fast sound goes.','The medium is what actually carries acoustic energy; its properties fix the speed, impedance, and loss that shape every sound path.','Technicians consider the medium when sound crosses air, walls, or water, since each changes speed, level, and coupling.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Propagation','Speed of sound','Acoustic impedance','Elasticity','Density']::text[],ARRAY['Believing sound can travel through a vacuum','Assuming the medium moves bodily with the wave rather than oscillating in place','Ignoring that sound speed changes with the medium']::text[],ARRAY['Explaining why space has no sound','Tracing sound from air into a wall','Comparing sound speed in air and water']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Medium');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'e642c50d-8e96-5fc0-bc75-80f5964d013c','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='e642c50d-8e96-5fc0-bc75-80f5964d013c') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='e642c50d-8e96-5fc0-bc75-80f5964d013c');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a7372d41-9541-5ee1-8eb5-aa1dd9bcaa67','Ground-borne sound','Acoustic energy that travels as vibration through the ground or a building structure and is reradiated as audible sound inside a receiving space. Typically generated by railways, road traffic, or machinery, it propagates through soil and structural elements as elastic waves, then sets surfaces such as floors and walls vibrating, which radiate low-frequency noise into rooms.','Ground-borne sound travels as shaking through the earth or a building. A train or machine sends vibration into the ground. That vibration reaches a building and shakes its surfaces. Those surfaces then radiate a low rumble indoors.','Naming this path separates structure-carried vibration from airborne sound, guiding how it is measured and controlled at source, path, or receiver.','Acousticians assess ground-borne sound near rail lines and use isolation, such as floating floors or resilient mounts, to reduce it.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Structure-borne sound','Vibration isolation','Source-path-receiver model','Airborne sound','Reradiation']::text[],ARRAY['Confusing ground-borne sound with airborne noise that leaks in','Trying to block it with absorption meant for airborne sound','Ignoring low-frequency rumble because broadband levels look modest']::text[],ARRAY['Assessing train rumble in a nearby building','Designing a floating floor to cut vibration','Tracing machinery hum through a structure']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ground-borne sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a7372d41-9541-5ee1-8eb5-aa1dd9bcaa67','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a7372d41-9541-5ee1-8eb5-aa1dd9bcaa67') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a7372d41-9541-5ee1-8eb5-aa1dd9bcaa67');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4e6e5086-1a2f-5b96-acab-1f6fd68d7bda','Fluid-borne sound','Sound that propagates through a fluid medium, that is a gas or a liquid, as longitudinal pressure waves. Because fluids support compression but not shear, fluid-borne sound consists only of longitudinal waves, unlike solids, which also carry shear and bending waves. The term is common in describing noise carried within pipes, ducts, and hydraulic or water systems.','Fluid-borne sound moves through a gas or a liquid. It travels as pressure waves that push and pull. Fluids carry only this push-pull kind of wave. Pipes and ducts often carry fluid-borne sound.','The term distinguishes sound carried inside a fluid from structure-borne and airborne paths, which matters for pipe, duct, and underwater noise.','Engineers trace fluid-borne noise in hydraulic lines and water pipes, adding silencers or flexible sections to break the path.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Structure-borne sound','Airborne sound','Longitudinal wave','Medium','Acoustic impedance']::text[],ARRAY['Assuming fluids carry shear waves like solids','Confusing fluid-borne noise in a pipe with airborne noise around it','Overlooking coupling between fluid-borne and structure-borne paths']::text[],ARRAY['Tracing noise in a hydraulic line','Fitting a silencer to a duct','Studying underwater sound in a tank']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fluid-borne sound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4e6e5086-1a2f-5b96-acab-1f6fd68d7bda','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4e6e5086-1a2f-5b96-acab-1f6fd68d7bda') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4e6e5086-1a2f-5b96-acab-1f6fd68d7bda');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f28904db-f818-5812-ab5f-40581d917e96','Sound velocity','The speed at which a sound wave propagates through a medium, set by the medium''s elasticity and density. In an ideal gas it depends on temperature through the ratio of specific heats, the gas constant, and molar mass; in air at twenty degrees Celsius it is about three hundred forty-three metres per second. Strictly, velocity implies direction, so speed of sound is the more exact name for the scalar value.','Sound velocity is how fast sound travels through a material. In air near room temperature it is about 343 metres per second. It is faster in water and in solids. It rises as air gets warmer.','Knowing the sound speed lets engineers relate frequency to wavelength and predict delays, distances, and phase over a path.','Technicians use the speed of sound to set loudspeaker delay times and to work out wavelengths for spacing and alignment.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Speed of sound','Wavelength','Medium','Temperature','Acoustic impedance']::text[],ARRAY['Treating the speed of sound as fixed regardless of temperature','Assuming sound is slower in water than in air','Confusing the wave''s speed with the particle velocity of the medium']::text[],ARRAY['Setting delay time from the speed of sound','Finding a wavelength at a given frequency','Correcting delay for stage temperature']::text[],'intermediate','c = √(γRT/M);  air ≈ 343 m/s at 20 °C','In an ideal gas the sound speed equals the square root of the ratio of specific heats times the gas constant times absolute temperature, divided by the molar mass.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Sound velocity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f28904db-f818-5812-ab5f-40581d917e96','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f28904db-f818-5812-ab5f-40581d917e96') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f28904db-f818-5812-ab5f-40581d917e96');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '68fd545f-4c16-593b-ad57-634bdb3d8e65','Elasticity','The property of a medium by which it resists deformation and returns to its original shape after a distorting force is removed, supplying the restoring force that sustains a sound wave. Together with inertia, represented by density, elasticity governs the speed of sound: a stiffer medium propagates sound faster. It is quantified by an elastic modulus appropriate to the deformation, such as the bulk modulus for fluids.','Elasticity is a material''s springiness. It pulls the material back to shape after a push. This restoring pull lets sound waves keep moving. Stiffer materials carry sound faster.','Elasticity provides the restoring force in the mass-and-spring behaviour of a medium, without which a mechanical wave could not travel.','Understanding elasticity helps technicians see why sound is faster in steel than in air and why the choice of medium changes wave speed.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Bulk modulus','Density','Speed of sound','Compressibility','Medium']::text[],ARRAY['Confusing elasticity with how far a material stretches rather than its stiffness','Assuming denser materials always carry sound faster','Ignoring elasticity''s role alongside density in setting wave speed']::text[],ARRAY['Explaining fast sound in steel','Comparing the stiffness of two media','Relating an elastic modulus to wave speed']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Elasticity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '68fd545f-4c16-593b-ad57-634bdb3d8e65','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='68fd545f-4c16-593b-ad57-634bdb3d8e65') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='68fd545f-4c16-593b-ad57-634bdb3d8e65');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '28566293-4733-55f5-8239-74a960e1d42a','Bulk modulus','A measure of a substance''s resistance to uniform compression, defined as the ratio of an applied pressure change to the resulting fractional decrease in volume. It has units of pressure and is the relevant elastic constant for sound in fluids: the sound speed equals the square root of the bulk modulus divided by density. For gases the adiabatic bulk modulus, larger than the isothermal one, applies to sound.','Bulk modulus tells how hard a material is to squeeze. A high value means it barely compresses. It sets how fast sound travels in a fluid. Water has a much higher value than air.','It quantifies the stiffness of a fluid to compression, giving the elastic term that, with density, fixes the speed of sound.','Acousticians use bulk modulus and density to compute sound speed and impedance in water and other fluids.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Compressibility','Elasticity','Density','Speed of sound','Adiabatic compression']::text[],ARRAY['Using the isothermal bulk modulus for sound instead of the adiabatic one','Confusing the bulk modulus with density''s role in wave speed','Assuming a stiffer fluid must also be denser']::text[],ARRAY['Computing sound speed in water','Comparing the compressibility of fluids','Finding the acoustic impedance of a liquid']::text[],'advanced','K = -V(dP/dV);  c = √(K/ρ)','Bulk modulus is minus volume times the change in pressure per change in volume; sound speed equals the square root of bulk modulus over density.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Bulk modulus');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '28566293-4733-55f5-8239-74a960e1d42a','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='28566293-4733-55f5-8239-74a960e1d42a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='28566293-4733-55f5-8239-74a960e1d42a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'eed1246b-17e9-5d5b-867e-bf32f2016bf3','Compressibility','The fractional change in volume of a medium per unit change in applied pressure, the reciprocal of the bulk modulus. A highly compressible medium such as air changes volume readily under pressure, whereas water is nearly incompressible. Compressibility, together with density, determines the speed of sound, since a more compressible medium generally propagates sound more slowly.','Compressibility is how easily a material can be squeezed. Air squeezes a lot. Water hardly squeezes at all. Softer materials often carry sound more slowly.','It expresses a medium''s yield to pressure, the inverse of its stiffness, and feeds directly into sound speed and acoustic impedance.','Engineers weigh compressibility when comparing how sound travels in air, water, and hydraulic fluids.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Bulk modulus','Elasticity','Density','Speed of sound','Medium']::text[],ARRAY['Confusing compressibility with density','Assuming a more compressible medium carries sound faster','Forgetting that compressibility is the inverse of the bulk modulus']::text[],ARRAY['Comparing the compressibility of air and water','Explaining slow sound in a gas','Relating compressibility to bulk modulus']::text[],'advanced','β = 1/K = -(1/V)(dV/dP)','Compressibility equals one over the bulk modulus, that is minus one over volume times the change in volume per change in pressure.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Compressibility');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'eed1246b-17e9-5d5b-867e-bf32f2016bf3','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='eed1246b-17e9-5d5b-867e-bf32f2016bf3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='eed1246b-17e9-5d5b-867e-bf32f2016bf3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '7bac9a58-bd4f-53fe-b1da-137119406099','Adiabatic compression','Compression of a gas that occurs without heat exchange with its surroundings, so the work done raises the gas temperature. Sound in air is an adiabatic process because the compressions and rarefactions happen too quickly for heat to flow between adjacent regions. This is why the adiabatic, not the isothermal, relation governs the pressure-volume behaviour and the speed of sound in gases.','Adiabatic compression squeezes a gas with no heat escaping. The trapped energy makes the gas warmer. Sound squeezes air this fast. This choice gives the right sound speed in air.','Recognizing sound as adiabatic corrects the pressure-density relation, yielding the observed speed of sound rather than a lower, wrong value.','It underlies why the speed of sound in air includes the ratio of specific heats, a factor built into acoustic calculations.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Adiabatic process','Bulk modulus','Specific heat ratio','Speed of sound','Compressibility']::text[],ARRAY['Assuming sound compression is isothermal at constant temperature','Leaving the specific heat ratio out of the sound speed','Thinking heat has time to flow during an acoustic cycle']::text[],ARRAY['Explaining why sound speed uses the specific heat ratio','Correcting an isothermal speed estimate','Relating compression heating to sound']::text[],'advanced','P·Vᵞ = constant   (γ = c_p/c_v)','In adiabatic compression, pressure times volume raised to the specific heat ratio stays constant, where gamma is the ratio of specific heats.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Adiabatic compression');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '7bac9a58-bd4f-53fe-b1da-137119406099','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='7bac9a58-bd4f-53fe-b1da-137119406099') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='7bac9a58-bd4f-53fe-b1da-137119406099');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'd7000f49-e26a-504b-be63-a38079afc2e7','Ambient pressure','The steady, background pressure of the medium surrounding a sound field, about which the acoustic pressure fluctuates. In air this is normally atmospheric pressure, close to one hundred one thousand three hundred twenty-five pascals at sea level. Sound pressure is the small fluctuation superimposed on this much larger ambient value.','Ambient pressure is the steady pressure of the air around us. At sea level it is about 101325 pascals. Sound is a tiny ripple on top of it. The ripple is far smaller than this background.','It sets the baseline on which acoustic pressure rides, and its value affects density and therefore sound speed and level.','Technicians remember that microphones sense the small sound pressure riding on a large ambient pressure, and that altitude changes the ambient value.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Static pressure','Sound pressure','Atmospheric pressure','Medium','Density']::text[],ARRAY['Confusing the tiny sound pressure with the large ambient pressure','Assuming ambient pressure is the same at all altitudes','Ignoring ambient pressure''s effect on air density']::text[],ARRAY['Explaining sound pressure riding on atmospheric pressure','Noting altitude effects on microphones','Relating ambient pressure to air density']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ambient pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'd7000f49-e26a-504b-be63-a38079afc2e7','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='d7000f49-e26a-504b-be63-a38079afc2e7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='d7000f49-e26a-504b-be63-a38079afc2e7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8b9b4e96-ddb6-54da-8aed-1545118a1b97','Static pressure','The non-acoustic, equilibrium pressure of a medium in the absence of, or averaged over, any sound wave; in the atmosphere it is the local barometric pressure. It is the pressure on which the alternating acoustic pressure is superimposed, and by convention it is the mean about which sound pressure varies with a zero time average.','Static pressure is the medium''s steady pressure with no sound added. In air it is the barometer reading. Sound pressure swings above and below it. On average the sound part is zero.','It defines the reference equilibrium from which sound pressure is measured as a departure, and it relates to the medium''s density.','In measurement, static pressure is what a barometer reads, and corrections for it are applied when calibrating microphones.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Ambient pressure','Sound pressure','Atmospheric pressure','Barometric pressure','Medium']::text[],ARRAY['Confusing static pressure with the fluctuating sound pressure','Assuming static pressure never affects acoustic measurements','Mixing static pressure up with dynamic flow pressure']::text[],ARRAY['Reading barometric static pressure','Correcting a microphone calibration for pressure','Separating static and sound pressure']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Static pressure');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8b9b4e96-ddb6-54da-8aed-1545118a1b97','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8b9b4e96-ddb6-54da-8aed-1545118a1b97') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8b9b4e96-ddb6-54da-8aed-1545118a1b97');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b0cf89b1-a14d-511c-ac71-5f4015bd3299','Temperature','A measure of the thermal state of a medium that, for gases, directly sets the speed of sound: sound speed rises with the square root of absolute temperature. In air the speed increases by roughly zero point six metres per second for each degree Celsius. Temperature gradients in air also bend sound paths through refraction.','Temperature is how hot or cold the medium is. Warmer air lets sound travel faster. The speed rises about 0.6 metres per second per degree. Layers of warm and cool air can bend sound.','Because it controls sound speed and refraction, temperature must be known to predict delays, wavelengths, and the bending of outdoor sound.','Technicians correct loudspeaker delay for stage temperature and expect outdoor sound to bend when air layers differ in temperature.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Speed of sound','Refraction','Medium','Humidity','Sound velocity']::text[],ARRAY['Assuming temperature has no effect on the speed of sound','Using a fixed sound speed for outdoor delay in changing weather','Confusing temperature effects with humidity effects on speed']::text[],ARRAY['Correcting delay for a hot stage','Predicting sound bending on a cool evening','Finding sound speed at a given temperature']::text[],'beginner','c ≈ 331.3·√(1 + t/273.15) m/s   (t in °C)','The speed of sound in air equals about 331.3 metres per second times the square root of one plus the Celsius temperature divided by 273.15.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Temperature');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b0cf89b1-a14d-511c-ac71-5f4015bd3299','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b0cf89b1-a14d-511c-ac71-5f4015bd3299') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b0cf89b1-a14d-511c-ac71-5f4015bd3299');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f7e3bd38-3e93-5e14-b0ed-ff7c0832b3f6','Humidity','The amount of water vapour present in air, usually expressed as relative humidity, which strongly influences the atmospheric absorption of sound, especially at high frequencies. High-frequency absorption is greatest at low-to-moderate humidity and lessens as humidity rises; humidity also has a small effect on air density and sound speed. Standard methods relate absorption to temperature, humidity, and pressure.','Humidity is how much water vapour is in the air. It changes how much high sound is soaked up over distance. Dry air can absorb treble more than you might expect. It has only a tiny effect on sound speed.','Humidity sets high-frequency air absorption, so it must be accounted for when predicting how far treble carries outdoors.','For outdoor and long-throw systems, technicians expect high-frequency loss to change with humidity and temperature over distance.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Molecular absorption','Atmospheric absorption','Temperature','Air absorption','Medium']::text[],ARRAY['Assuming humid air always absorbs more high frequencies','Ignoring air absorption over long outdoor distances','Confusing humidity''s large absorption effect with a large speed effect']::text[],ARRAY['Predicting treble loss outdoors','Adjusting expectations for a humid venue','Estimating long-throw high-frequency roll-off']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Humidity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f7e3bd38-3e93-5e14-b0ed-ff7c0832b3f6','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f7e3bd38-3e93-5e14-b0ed-ff7c0832b3f6') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f7e3bd38-3e93-5e14-b0ed-ff7c0832b3f6');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '1dea17be-6f00-5cf4-a8ed-848870b3b64f','Molecular absorption','The dominant mechanism of atmospheric sound absorption at audio frequencies, arising from thermal relaxation of oxygen and nitrogen molecules whose internal energy states lag the passing pressure wave. This relaxation converts acoustic energy to heat, with a frequency- and humidity-dependent loss that grows strongly with frequency. It exceeds classical viscous and thermal losses across most of the audible range in air.','Molecular absorption is how air soaks up sound as heat. Air molecules take in energy and release it late. This drains the wave, mostly at high frequencies. It depends on humidity and temperature.','It explains why distant sound loses its highs, and it is the main term in predicting outdoor high-frequency attenuation.','Sound designers for large outdoor sites expect molecular absorption to soften highs with distance and plan coverage accordingly.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Atmospheric absorption','Humidity','Viscous loss','Thermal loss','Relaxation']::text[],ARRAY['Attributing all air absorption to viscosity rather than molecular relaxation','Ignoring molecular absorption at short distances, where it is small','Assuming it stays constant as humidity changes']::text[],ARRAY['Explaining lost highs across a stadium','Modeling outdoor sound over distance','Comparing absorption at different humidities']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Molecular absorption');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '1dea17be-6f00-5cf4-a8ed-848870b3b64f','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='1dea17be-6f00-5cf4-a8ed-848870b3b64f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='1dea17be-6f00-5cf4-a8ed-848870b3b64f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '3b510fd4-261c-56fb-be68-a7c49034ca84','Viscous loss','Attenuation of sound caused by the internal friction, or viscosity, of the medium, as adjacent layers of fluid in relative motion dissipate acoustic energy into heat. It is one component of classical absorption and increases with the square of frequency. In free air viscous loss is small compared with molecular relaxation, but it becomes important in narrow channels and porous absorbers, where boundary friction is large.','Viscous loss is sound energy lost to friction inside the medium. Moving layers rub and turn sound into heat. It grows quickly with frequency. It matters most in tiny gaps and porous foams.','It accounts for part of how a medium and its boundaries drain sound energy, key to how porous absorbers and small ducts damp sound.','The mechanism explains why porous absorbers and narrow slots absorb sound, guiding acoustic treatment design.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Thermal loss','Molecular absorption','Classical absorption','Porous absorber','Viscosity']::text[],ARRAY['Confusing viscous loss with thermal loss','Ignoring viscous loss inside porous absorbers','Assuming it dominates free-air absorption in the audio range']::text[],ARRAY['Explaining absorption in porous foam','Modeling loss in a narrow slot','Separating viscous and thermal damping']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Viscous loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '3b510fd4-261c-56fb-be68-a7c49034ca84','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='3b510fd4-261c-56fb-be68-a7c49034ca84') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='3b510fd4-261c-56fb-be68-a7c49034ca84');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f3cd307e-28aa-5a33-be61-ee17b2fe79ff','Thermal loss','Attenuation of sound arising from heat conduction between the warmer compressions and cooler rarefactions of the wave, which lets the process depart slightly from perfectly adiabatic and dissipates acoustic energy as heat. Together with viscous loss it forms classical absorption and rises with the square of frequency. It is significant at boundaries and within porous materials, where heat exchange with solid surfaces is enhanced.','Thermal loss is sound energy lost to heat flow inside the wave. Squeezed spots are warmer and heat leaks to cooler spots. This small leak drains the sound. It grows with frequency and near surfaces.','It captures the heat-conduction share of a medium''s absorption, contributing with viscosity to how porous and bounded systems damp sound.','It helps explain absorption in porous materials and narrow gaps, informing the design of acoustic treatment.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Viscous loss','Molecular absorption','Classical absorption','Adiabatic compression','Porous absorber']::text[],ARRAY['Confusing thermal loss with viscous loss','Assuming sound in air is perfectly adiabatic with no heat conduction','Overlooking thermal loss at material boundaries']::text[],ARRAY['Explaining damping in porous absorbers','Modeling boundary losses in a tube','Separating thermal and viscous absorption']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Thermal loss');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f3cd307e-28aa-5a33-be61-ee17b2fe79ff','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f3cd307e-28aa-5a33-be61-ee17b2fe79ff') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f3cd307e-28aa-5a33-be61-ee17b2fe79ff');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b4734af0-ef9f-5766-b512-1d12ba5fa251','Spherical spreading','The geometric decrease of sound intensity as a wave radiates outward from a point source into free space, spreading its power over the surface of an expanding sphere. Because that surface area grows with the square of distance, intensity falls as one over distance squared, and the sound pressure level drops by about six decibels for each doubling of distance in the far field.','Spherical spreading is how sound thins out from a small source. The energy covers a growing ball of space. Each time the distance doubles, the level drops about 6 decibels. This happens before any absorption.','It predicts the basic loss of level with distance from a point source, the starting point for outdoor and free-field level estimates.','Technicians apply the six-decibel-per-doubling rule to estimate how loud a point source will be at a listener''s distance.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Inverse-square law','Cylindrical spreading','Point source','Free field','Sound intensity']::text[],ARRAY['Applying six decibels per doubling to line sources','Confusing spreading loss with absorption loss','Using the free-field rule inside a reverberant room']::text[],ARRAY['Estimating level loss from a point source','Predicting outdoor level with distance','Comparing point and line source falloff']::text[],'intermediate','I ∝ 1/r²;  ΔL ≈ -6 dB per distance doubling','Intensity falls as one over distance squared, so the level drops about six decibels each time the distance doubles.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Spherical spreading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b4734af0-ef9f-5766-b512-1d12ba5fa251','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b4734af0-ef9f-5766-b512-1d12ba5fa251') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b4734af0-ef9f-5766-b512-1d12ba5fa251');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '01814e8b-a938-58f5-9753-a7f840a17f7a','Cylindrical spreading','The geometric decrease of sound intensity as a wave radiates outward from an ideal line source, spreading over the curved surface of an expanding cylinder. Because that area grows in direct proportion to distance, intensity falls as one over distance, and the sound pressure level drops by about three decibels for each doubling of distance, a slower loss than spherical spreading.','Cylindrical spreading is how sound thins from a long line source. The energy wraps a growing cylinder, not a ball. Each time the distance doubles, the level drops about 3 decibels. That is slower than a point source.','It describes the gentler distance loss of line sources, which underlies the reach of line arrays and long noise sources.','The three-decibel-per-doubling behaviour helps explain why line arrays and lines of traffic carry farther than point sources.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Spherical spreading','Line source','Line array','Inverse-square law','Sound intensity']::text[],ARRAY['Using three decibels per doubling for a point source','Assuming a real line source behaves ideally at all distances','Expecting cylindrical spreading in the far field of a short source']::text[],ARRAY['Explaining line-array throw','Estimating traffic-line noise falloff','Comparing line and point source distance loss']::text[],'intermediate','I ∝ 1/r;  ΔL ≈ -3 dB per distance doubling','Intensity falls as one over distance, so the level drops about three decibels each time the distance doubles.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Cylindrical spreading');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '01814e8b-a938-58f5-9753-a7f840a17f7a','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='01814e8b-a938-58f5-9753-a7f840a17f7a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='01814e8b-a938-58f5-9753-a7f840a17f7a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '9571a261-062a-5bea-8ba4-3d982fa8e839','Source-path-receiver model','A conceptual framework for noise control that treats any noise problem as three linked elements: the source that generates sound, the path along which it travels, and the receiver that perceives it. Control measures can be applied at any of the three, and the model guides where intervention is most effective, whether by quieting the source, interrupting the path, or protecting the receiver.','This model splits a noise problem into three parts. There is a source, a path, and a receiver. You can cut noise at any of the three. It helps you pick the best place to act.','It organizes noise control by making clear the three points where sound can be reduced, so effort goes where it works best.','Acousticians use it to plan treatment: quiet the machine, block or absorb the path, or fit hearing protection at the receiver.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Noise control','Ground-borne sound','Transmission path','Sound isolation','Receiver']::text[],ARRAY['Treating the path only and ignoring source and receiver options','Assuming receiver protection is always the cheapest fix','Forgetting there can be several parallel paths']::text[],ARRAY['Planning noise control for a machine','Choosing between source, path, and receiver fixes','Fitting hearing protection at the receiver']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source-path-receiver model');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '9571a261-062a-5bea-8ba4-3d982fa8e839','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='9571a261-062a-5bea-8ba4-3d982fa8e839') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='9571a261-062a-5bea-8ba4-3d982fa8e839');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0a746af8-0f13-5b71-8bf5-ad1b6d458713','Impedance boundary','A surface or interface characterised by its specific acoustic impedance, the complex ratio of sound pressure to the normal particle velocity at the boundary. This impedance governs how an incident wave is split into reflected and absorbed or transmitted parts; the pressure reflection coefficient follows from the mismatch between the boundary impedance and the characteristic impedance of the adjoining medium. When the boundary impedance equals the medium''s characteristic impedance the boundary is matched and produces no reflection, whereas a large mismatch yields strong reflection.','An impedance boundary is a surface described by its acoustic impedance. Impedance links sound pressure to how fast the surface moves. It decides how much sound bounces back. A close match to the air reflects very little.','It provides the physical basis for predicting reflection, absorption, and transmission at any surface, tying material behaviour to how strongly sound returns to the room.','Acousticians use boundary impedance, or its normalised form, to model absorbers, walls, and porous panels in room-acoustics and duct calculations, and to predict absorption from measured impedance.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Specific acoustic impedance','Reflection coefficient','Absorption coefficient','Characteristic impedance','Rigid boundary']::text[],ARRAY['Confusing the specific acoustic impedance of the boundary with the characteristic impedance of the medium','Assuming a boundary reflects everything unless it is soft, ignoring impedance matching','Treating boundary impedance as purely real when it is generally complex and frequency dependent']::text[],ARRAY['Modelling a porous absorber from its surface impedance','Predicting a wall reflection in a room-acoustics simulation','Designing a duct liner using normalised impedance']::text[],'advanced','R = (Z − ρc)/(Z + ρc)','The pressure reflection coefficient equals the boundary impedance minus the medium''s characteristic impedance, divided by their sum.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Impedance boundary');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0a746af8-0f13-5b71-8bf5-ad1b6d458713','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0a746af8-0f13-5b71-8bf5-ad1b6d458713') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0a746af8-0f13-5b71-8bf5-ad1b6d458713');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '439f4ae3-c620-551a-8037-ea02e22b52c1','Rigid boundary','An idealised boundary that does not move under the incident sound pressure, so the normal component of particle velocity at the surface is zero. Its specific acoustic impedance is effectively infinite compared with the medium, giving a pressure reflection coefficient of plus one: the reflected wave returns in phase with the incident wave and the surface is a pressure antinode. It is the standard hard-wall assumption for massive, non-porous, highly reflective surfaces.','A rigid boundary is a surface that does not move when sound hits it. Almost all the sound bounces straight back. The reflected wave stays in phase with the incoming wave. Pressure is highest right at the surface.','It gives a simple limiting case for a perfectly reflecting hard wall, used as a reference boundary condition in acoustic theory and modelling.','Technicians treat thick concrete, tile, or masonry as near-rigid when estimating reflections, room modes, and low-frequency build-up in a space.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Pressure-release boundary','Impedance boundary','Reflection coefficient','Standing wave','Room mode']::text[],ARRAY['Assuming any hard surface is perfectly rigid at all frequencies','Confusing a rigid boundary (velocity node) with a pressure-release boundary (pressure node)','Forgetting that a rigid boundary doubles the pressure at the surface']::text[],ARRAY['Modelling a concrete wall as a hard reflector','Predicting a pressure antinode at a solid boundary','Setting a hard-wall condition in a room-mode calculation']::text[],'intermediate','R = +1  (normal velocity u_n = 0 at surface)','The pressure reflection coefficient is plus one and the normal particle velocity at the surface is zero.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rigid boundary');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '439f4ae3-c620-551a-8037-ea02e22b52c1','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='439f4ae3-c620-551a-8037-ea02e22b52c1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='439f4ae3-c620-551a-8037-ea02e22b52c1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '943cf275-ad8c-5a3d-a522-105232335411','Pressure-release boundary','An idealised boundary at which the sound pressure is forced to zero, so it acts as a pressure node and its specific acoustic impedance approaches zero. The pressure reflection coefficient is minus one, meaning the reflected wave is inverted relative to the incident wave while the particle velocity is maximised at the surface. This soft boundary is the counterpart of the rigid boundary and appears most often in underwater acoustics, at a water surface seen from below, and in theoretical analysis.','A pressure-release boundary forces the sound pressure to zero at the surface. The reflected wave is flipped upside down. Motion of the air or water is largest there. It is the opposite of a rigid wall.','It provides the limiting soft boundary condition, needed to model interfaces such as a water surface and to complete reflection theory alongside the rigid case.','Underwater acousticians treat the sea surface as pressure-release when predicting reflections and interference for sonar and hydrophone work.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Rigid boundary','Impedance boundary','Reflection coefficient','Pressure node','Phase inversion']::text[],ARRAY['Expecting pressure-release behaviour from ordinary room walls, which are closer to rigid','Forgetting that the reflected wave is phase-inverted','Confusing a pressure node with a velocity node']::text[],ARRAY['Modelling the sea surface in sonar prediction','Explaining phase inversion at a soft boundary','Setting a pressure-zero condition in a waveguide problem']::text[],'intermediate','R = −1  (pressure p = 0 at surface)','The pressure reflection coefficient is minus one and the sound pressure at the surface is zero.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pressure-release boundary');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '943cf275-ad8c-5a3d-a522-105232335411','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='943cf275-ad8c-5a3d-a522-105232335411') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='943cf275-ad8c-5a3d-a522-105232335411');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '708c7f4e-bd85-51c6-9f59-482e1bfbe4f2','Boundary layer','The thin region of fluid immediately adjacent to a solid surface in which viscous drag and heat conduction significantly affect an acoustic wave. Within it the tangential particle velocity falls to zero at the wall (the viscous boundary layer) and temperature fluctuations are conducted into the surface (the thermal boundary layer). Its characteristic thickness scales with the square root of kinematic viscosity divided by angular frequency, so it is thicker at low frequencies; the associated losses dominate absorption in narrow tubes, slits, and porous materials.','The boundary layer is a thin layer of air right next to a surface. Here friction and heat loss drain sound energy. The layer is thicker at low frequencies. These losses matter most in narrow tubes and pores.','It explains the viscous and thermal energy losses that occur at surfaces, which underlie absorption in porous materials, narrow gaps, and small resonators.','Designers of microperforated panels, porous absorbers, and small ports rely on boundary-layer losses to predict how much sound energy is dissipated.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Viscous loss','Thermal conduction','Porous absorber','Microperforated panel','Acoustic impedance']::text[],ARRAY['Ignoring boundary-layer losses when modelling narrow tubes or slits','Assuming the layer thickness is fixed rather than frequency dependent','Confusing the acoustic boundary layer with the aerodynamic boundary layer of steady flow']::text[],ARRAY['Predicting loss in a microperforated absorber','Estimating damping in a narrow resonator neck','Modelling attenuation in a small tube or port']::text[],'advanced','δ_v ≈ √(2μ/(ρω)) = √(2ν/ω)','The viscous boundary-layer thickness is about the square root of twice the kinematic viscosity divided by the angular frequency.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Boundary layer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '708c7f4e-bd85-51c6-9f59-482e1bfbe4f2','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='708c7f4e-bd85-51c6-9f59-482e1bfbe4f2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='708c7f4e-bd85-51c6-9f59-482e1bfbe4f2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b30d05bd-6ed0-59d8-8e0e-d701aebc5808','Quarter-wave resonator','A tube or cavity, closed at one end and open at the other, that resonates when its length equals an odd number of quarter wavelengths of the sound. At the closed end the pressure is maximum (a velocity node) and at the open end the pressure is near zero (a pressure node), so the fundamental occurs when the length is one quarter wavelength. Resonances therefore fall at odd harmonics only, and such resonators are used to absorb or reinforce specific frequencies.','A quarter-wave resonator is a tube closed at one end and open at the other. It resonates when its length is a quarter of the wavelength. Only odd harmonics ring. It can boost or soak up one target frequency.','It provides a tuned resonance at a chosen frequency, used to absorb a narrow band of noise or to reinforce a note in an instrument or duct.','Acousticians fit quarter-wave tubes to ducts and rooms to attenuate a specific low-frequency tone, and the same physics governs closed organ pipes.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Helmholtz resonator','Standing wave','Resonant frequency','Room mode','Half-wave resonator']::text[],ARRAY['Assuming a quarter-wave tube produces all harmonics rather than odd ones only','Ignoring the end correction that lengthens the effective tube','Confusing a quarter-wave tube (one open end) with a half-wave tube']::text[],ARRAY['Tuning a quarter-wave tube to cancel a duct resonance','Explaining why a closed organ pipe sounds an octave lower','Designing a narrow-band bass absorber']::text[],'intermediate','f_n = (2n−1)·c/(4L),  n = 1, 2, 3, …','The resonant frequencies equal odd multiples of the speed of sound divided by four times the tube length.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Quarter-wave resonator');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b30d05bd-6ed0-59d8-8e0e-d701aebc5808','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b30d05bd-6ed0-59d8-8e0e-d701aebc5808') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b30d05bd-6ed0-59d8-8e0e-d701aebc5808');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2a5b3d90-4f9c-5fa5-bb76-590b80b0db13','Acoustic barrier','A solid obstacle placed between a source and receiver to reduce sound transmission by blocking the direct path and forcing sound to diffract over or around its edges. Its effectiveness, the insertion loss, grows with the path-length difference between the diffracted and direct paths relative to wavelength, so barriers work best at high frequencies and for receivers deep in the shadow zone. A practical barrier must also be massive enough that direct transmission through it is negligible compared with diffraction over the top.','An acoustic barrier is a solid wall set between a noise source and a listener. It blocks the straight path so sound must bend over the top. This works best for high notes. Low bass bends around it easily.','It lowers received noise by lengthening the sound''s path and placing the listener in an acoustic shadow, without needing to absorb much energy.','Highway noise walls, equipment enclosures, and stage screens use barrier diffraction to cut noise at nearby receivers.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Diffraction','Insertion loss','Sound shadow','Transmission loss','Fresnel number']::text[],ARRAY['Expecting a barrier to block low frequencies as well as high ones','Ignoring flanking paths and diffraction over the edges','UNSAFE: relying on an under-designed barrier as the sole hearing-protection control in high-noise areas']::text[],ARRAY['Designing a highway noise wall','Screening a noisy generator on a work site','Placing a stage screen to protect nearby ears']::text[],'intermediate','N = 2δ/λ   (δ = path-length difference)','The Fresnel number equals twice the path-length difference between the diffracted and direct paths, divided by the wavelength.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Acoustic barrier');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2a5b3d90-4f9c-5fa5-bb76-590b80b0db13','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2a5b3d90-4f9c-5fa5-bb76-590b80b0db13') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2a5b3d90-4f9c-5fa5-bb76-590b80b0db13');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0ae47e67-4772-57ea-93cb-087ea144d3ec','Path-length difference','The difference in distance travelled by two sound waves reaching the same point by different routes, such as a direct and a reflected path, or the outputs of two spaced sources. This spatial difference corresponds to a time delay equal to the difference divided by the speed of sound, and to a phase difference of two pi times the difference divided by the wavelength. When the difference is an integer number of wavelengths the waves add constructively; when it is an odd number of half wavelengths they cancel.','Path-length difference is how much farther one sound travels than another to the same spot. It sets the time delay between them. It also sets their phase difference. Equal-wavelength gaps add up; half-wavelength gaps cancel.','It quantifies why interference, comb filtering, and reflection cancellations occur, linking geometry directly to constructive and destructive addition.','Sound engineers compute path-length differences to predict comb filtering from reflections and to time-align spaced loudspeakers.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Phase difference','Comb filtering','Constructive interference','Destructive interference','Time delay']::text[],ARRAY['Confusing path-length difference with absolute distance from the source','Forgetting that its effect depends on frequency through the wavelength','Assuming one fixed distance always cancels, ignoring which frequencies reinforce']::text[],ARRAY['Predicting comb filtering from a floor reflection','Time-aligning two subwoofers','Explaining cancellation between a spaced microphone pair']::text[],'intermediate','Δφ = 2π·Δr/λ ;  Δt = Δr/c','The phase difference equals two pi times the path-length difference over the wavelength, and the time delay equals the difference divided by the speed of sound.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Path-length difference');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0ae47e67-4772-57ea-93cb-087ea144d3ec','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0ae47e67-4772-57ea-93cb-087ea144d3ec') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0ae47e67-4772-57ea-93cb-087ea144d3ec');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '03e9f2b9-2cd7-5f29-911e-c0a4efd1553f','Mode','A characteristic pattern of vibration or standing wave in which every part of a bounded system oscillates at a single natural frequency with a fixed spatial shape of nodes and antinodes. Each such normal mode is set by the system''s geometry and boundary conditions, and any free vibration of the system can be expressed as a weighted sum of its modes. In acoustics the term covers standing waves on strings and membranes, in air columns, and in rooms.','A mode is one natural pattern in which a system vibrates. Every part moves at the same frequency. The pattern of still points and peaks stays fixed. Any vibration is a mix of these modes.','It provides the basic building block for describing resonance, so complex vibrations are understood as combinations of simple, independent modes.','Recognising modes helps technicians explain room resonances, instrument overtones, and loudspeaker cone break-up.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Normal mode','Modal frequency','Resonance','Standing wave','Room mode']::text[],ARRAY['Thinking a system has only one mode rather than many','Confusing a mode (a spatial pattern) with a single frequency alone','Assuming modes always sit at simple integer frequency ratios']::text[],ARRAY['Identifying a room resonance as a specific mode','Explaining an instrument''s overtone as a higher mode','Diagnosing cone break-up in a driver']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Mode');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '03e9f2b9-2cd7-5f29-911e-c0a4efd1553f','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='03e9f2b9-2cd7-5f29-911e-c0a4efd1553f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='03e9f2b9-2cd7-5f29-911e-c0a4efd1553f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5d8426a6-b881-5595-839b-bb117d758031','Modal frequency','The natural frequency at which a particular mode of a system resonates, set by the system''s geometry, boundary conditions, and wave speed. For a rectangular room with rigid walls the axial, tangential, and oblique modal frequencies equal half the speed of sound times the square root of the summed squares of each integer mode number divided by its corresponding room dimension. Modal frequencies are densely packed at high frequencies but sparse and individually audible at low frequencies.','A modal frequency is the pitch at which one mode resonates. Room size and shape set these frequencies. Low modes are few and far apart. They cause uneven bass in small rooms.','It tells acousticians exactly where a room or structure will resonate, which is essential for predicting low-frequency response and colouration.','Studio designers calculate room modal frequencies to place bass traps, monitors, and the listening position for smoother low-frequency response.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Room mode','Mode','Axial mode','Standing wave','Resonant frequency']::text[],ARRAY['Considering only axial modes and ignoring tangential and oblique modes','Assuming modal frequencies depend on wall material rather than mainly on dimensions','Treating dense high-frequency modes as individually audible']::text[],ARRAY['Calculating the axial modes of a control room','Placing bass traps at modal pressure maxima','Choosing room dimensions to spread modes evenly']::text[],'advanced','f = (c/2)·√[(n_x/L_x)² + (n_y/L_y)² + (n_z/L_z)²]','The modal frequency equals half the speed of sound times the square root of the sum of each mode number divided by its room dimension, squared.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modal frequency');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5d8426a6-b881-5595-839b-bb117d758031','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5d8426a6-b881-5595-839b-bb117d758031') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5d8426a6-b881-5595-839b-bb117d758031');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8355fc5b-b988-5caf-ae54-8750f66e18ef','Damping coefficient','A parameter quantifying the rate at which a vibrating or resonating system loses energy to friction, radiation, or other dissipation. In the equation of motion of a damped oscillator it is the coefficient of the velocity term; larger values mean faster amplitude decay and broader, less sharply tuned resonances. It is related to the quality factor, the loss factor, and the decay constant, and it determines whether a system is under-, critically, or over-damped.','The damping coefficient measures how fast a vibration loses energy. A high value makes the sound die away quickly. It also widens the resonance peak. It sets how sharply a system rings.','It sets how quickly resonances decay and how sharp they are, controlling ringing, resonance bandwidth, and the stability of vibrating systems.','Engineers adjust damping in loudspeaker suspensions, panels, and isolation mounts to control resonance and unwanted ringing.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Damping','Quality factor','Decay constant','Loss factor','Critical damping']::text[],ARRAY['Confusing the damping coefficient with the dimensionless damping ratio','Assuming more damping is always better, ignoring over-damping','Equating damping only with added absorbers and forgetting internal material losses']::text[],ARRAY['Tuning loudspeaker suspension damping','Reducing panel resonance in an enclosure','Setting damping in a vibration isolator']::text[],'advanced','m·x″ + R·x′ + s·x = 0 ;  δ = R/(2m)','In a mass, resistance, and stiffness oscillator the damping term is the velocity coefficient, and the amplitude decay rate equals that resistance divided by twice the mass.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Damping coefficient');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8355fc5b-b988-5caf-ae54-8750f66e18ef','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8355fc5b-b988-5caf-ae54-8750f66e18ef') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8355fc5b-b988-5caf-ae54-8750f66e18ef');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c330656c-91a0-582f-b6b6-3c025ef90bd1','Decay constant','The rate parameter describing how the amplitude or energy of a freely decaying oscillation or sound field falls off exponentially with time. If sound pressure decays as an exponential, the decay constant is the reciprocal of the time for the amplitude to fall to one over e of its initial value. In room acoustics it links directly to reverberation time, since a sixty-decibel decay corresponds to a fixed multiple of the decay constant.','The decay constant sets how fast a sound dies away. A big value means a quick fade. It is the reverse of the decay time. In rooms it fixes the reverberation time.','It provides a compact single-number measure of decay rate, connecting modal ringing, damping, and reverberation time in one quantity.','Acousticians derive reverberation time from the measured decay constant of a room''s sound-level decay curve.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Reverberation time','Damping coefficient','Time constant','Reverberant decay','Quality factor']::text[],ARRAY['Confusing the amplitude decay constant with the energy decay rate, which is twice as fast','Mixing up the decay constant with its reciprocal, the time constant','Assuming decay is linear in amplitude rather than exponential']::text[],ARRAY['Fitting a decay constant to a room decay curve','Relating modal ringing to its decay constant','Deriving reverberation time from a measured decay']::text[],'advanced','p(t) = p₀·e^(−δt) ;  T₆₀ ≈ 6.91/δ','Sound pressure falls exponentially at the decay constant, and the sixty-decibel reverberation time is about six point nine one divided by that constant.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Decay constant');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c330656c-91a0-582f-b6b6-3c025ef90bd1','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c330656c-91a0-582f-b6b6-3c025ef90bd1') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c330656c-91a0-582f-b6b6-3c025ef90bd1');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '4b2c735e-c667-593a-9310-6962dc9a857f','Ring time','The interval over which a resonant system or narrow filter keeps sounding after its driving signal stops, as stored energy decays. It is longest for high-Q, lightly damped resonances and short for well-damped ones, and it is inversely related to the resonance bandwidth. In practice ring time is often quoted as the time for the decaying tone to fall by a set amount, and it underlies audible ringing in rooms, filters, and mechanical resonators.','Ring time is how long a resonance keeps sounding after the signal stops. Sharp, lightly damped resonances ring the longest. Well-damped ones fade fast. A narrow filter has a long ring.','It describes the audible persistence of resonances, warning where filters or rooms will smear transients and blur sound.','Engineers watch ring time when using high-Q equaliser filters or when a room mode makes a bass note hang on.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Quality factor','Decay constant','Resonance','Reverberant decay','Damping']::text[],ARRAY['Assuming a narrow, high-Q filter has no time cost, ignoring its long ring','Confusing ring time with the reverberation time of the whole room','Thinking heavier damping lengthens rather than shortens the ring']::text[],ARRAY['Hearing a high-Q equaliser boost ring on a transient','Diagnosing a bass note that hangs on a room mode','Comparing a resonant filter''s ring to its bandwidth']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ring time');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '4b2c735e-c667-593a-9310-6962dc9a857f','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='4b2c735e-c667-593a-9310-6962dc9a857f') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='4b2c735e-c667-593a-9310-6962dc9a857f');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '912d8e7c-eee4-531a-94f9-80a65a0bc01e','Reverberant decay','The gradual decrease of sound-energy density in an enclosure after the source stops, produced by repeated reflections that lose energy at the boundaries and in the air. In a diffuse field this decay is approximately exponential, appearing as a straight line on a decibel-versus-time plot whose slope defines the reverberation time. The early portion may deviate from a single slope because of distinct early reflections or non-diffuse conditions.','Reverberant decay is how the leftover sound in a room fades after the source stops. Each reflection loses a little energy. On a decibel graph the fade looks like a straight slope. That slope gives the reverberation time.','It is the physical process measured by reverberation time and decay-curve analysis, describing how quickly a room clears of sound.','Acousticians record a room''s reverberant decay to measure reverberation time and judge speech clarity.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Reverberation time','Decay curve','Reverberant field','Sabine equation','Decay constant']::text[],ARRAY['Assuming the decay is always one straight line rather than sometimes multi-sloped','Confusing reverberant decay with early reflections','Measuring decay in a field that is not yet diffuse']::text[],ARRAY['Recording a decay curve to find reverberation time','Spotting a double-slope decay in a coupled room','Assessing clarity from the shape of the decay']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Reverberant decay');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '912d8e7c-eee4-531a-94f9-80a65a0bc01e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='912d8e7c-eee4-531a-94f9-80a65a0bc01e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='912d8e7c-eee4-531a-94f9-80a65a0bc01e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a435a791-1f38-5fa3-9370-026028e808dc','Late reflection','A reflection that arrives well after the direct sound, typically more than roughly eighty milliseconds later, having undergone several bounces so that individual reflections merge into the diffuse reverberant tail. Late reflections arrive from many directions with high density and, unlike early reflections, are generally not perceived as separate events. They build reverberance and, when strong relative to the direct sound, can reduce speech clarity.','A late reflection reaches you well after the direct sound. It has bounced many times first. These reflections blur together into the reverb tail. Too many can make speech hard to follow.','It identifies the part of a room''s response that builds reverberance and can blur speech, separating it from useful early energy.','Room designers control late reflections with absorption and diffusion to protect speech intelligibility in halls and studios.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Early reflection','Reverberation','Reverberant field','Initial time delay gap','Clarity']::text[],ARRAY['Treating all reflections as harmful, ignoring the benefit of early energy','Confusing late reflections with distinct echoes','Assuming one fixed millisecond cut-off applies to every kind of programme']::text[],ARRAY['Adding absorption to tame a reverberant tail','Improving speech clarity in a lecture hall','Balancing early and late energy in a concert hall']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Late reflection');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a435a791-1f38-5fa3-9370-026028e808dc','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a435a791-1f38-5fa3-9370-026028e808dc') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a435a791-1f38-5fa3-9370-026028e808dc');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aa9b512b-ba34-5c85-9885-79ffd8a0171e','Initial time delay gap','The time interval between the arrival of the direct sound at a listener and the arrival of the first significant reflection, usually a strong early reflection from a nearby surface. Introduced in concert-hall acoustics as a measure of perceived intimacy, a short gap makes a space feel small and enveloping while a long gap makes it feel large. It is read from a room impulse response as the delay before the first prominent reflection.','The initial time delay gap is the pause between the direct sound and the first strong reflection. A short gap makes a room feel small and intimate. A long gap makes it feel large. It is read from the room''s impulse response.','It gives a single measure of perceived intimacy and apparent room size, helping link a hall''s geometry to how close the sound feels.','Hall designers use the initial time delay gap to judge intimacy and to position reflectors that create a desirable first reflection.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Early reflection','Direct sound','Impulse response','Late reflection','Reverberation time']::text[],ARRAY['Confusing the initial time delay gap with reverberation time','Measuring to a late reflection instead of the first strong one','Assuming a longer gap is always better']::text[],ARRAY['Reading the gap from a hall impulse response','Positioning a reflector to shorten the gap','Comparing intimacy between two seats']::text[],'intermediate','ITDG = (r₁ − r₀)/c','The initial time delay gap equals the first reflection''s path length minus the direct path length, divided by the speed of sound.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Initial time delay gap');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aa9b512b-ba34-5c85-9885-79ffd8a0171e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aa9b512b-ba34-5c85-9885-79ffd8a0171e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aa9b512b-ba34-5c85-9885-79ffd8a0171e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '408b161b-e6e6-505a-8531-c54c9589f27e','Direct field','The region near a sound source where the direct, unreflected sound dominates over the reverberant sound, so the sound pressure level falls by about six decibels for each doubling of distance as in free space. Its extent depends on the source directivity and the room''s absorption, and it ends near the critical distance, where direct and reverberant energy are equal. Within the direct field a listener hears mainly the source, with little influence from the room.','The direct field is the area close to a source where straight-line sound wins. Here the level drops about six decibels each time you double the distance. The room adds little. It ends at the critical distance.','It marks the zone where a source is heard clearly with minimal room effect, guiding microphone and listener placement.','Engineers place close microphones and near-field monitors within the direct field to minimise room colouration.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Reverberant field','Critical distance','Free field','Inverse-square law','Source directivity']::text[],ARRAY['Assuming the direct field extends throughout the room','Ignoring source directivity, which changes its size','Confusing the direct field with the free field of an anechoic space']::text[],ARRAY['Placing a close microphone within the direct field','Using near-field monitors to beat room acoustics','Estimating where direct sound stops dominating']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Direct field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '408b161b-e6e6-505a-8531-c54c9589f27e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='408b161b-e6e6-505a-8531-c54c9589f27e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='408b161b-e6e6-505a-8531-c54c9589f27e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c23be18a-61cf-5be3-b257-75bcacae4235','Free field','An idealised sound field in a homogeneous medium free of boundaries and reflections, so sound from a point source spreads uniformly and its pressure obeys the inverse-square law, falling six decibels per doubling of distance. It is the reference condition for many acoustic measurements and is approximated inside an anechoic chamber. Only the direct sound is present, with no reverberant contribution.','A free field is sound spreading out with no reflections at all. The level drops six decibels each time the distance doubles. Only the direct sound exists. An anechoic room comes close.','It provides the clean reference condition for measuring source output, directivity, and microphone response without room effects.','Loudspeaker and microphone measurements are made in anechoic, free-field conditions so the room does not corrupt the result.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Anechoic chamber','Inverse-square law','Direct field','Diffuse field','Sound power']::text[],ARRAY['Believing an ordinary quiet room is a free field','Forgetting that the inverse-square law needs the free-field condition','Confusing free-field with diffuse-field microphone calibration']::text[],ARRAY['Measuring a loudspeaker in an anechoic chamber','Calibrating a microphone for free-field response','Predicting outdoor level with the inverse-square law']::text[],'intermediate','L_p = L_W − 20·log₁₀(r) − 11 dB   (point source, r in metres)','For a point source in free space the sound pressure level equals the sound power level minus twenty times the log of distance in metres, minus about eleven decibels.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Free field');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c23be18a-61cf-5be3-b257-75bcacae4235','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c23be18a-61cf-5be3-b257-75bcacae4235') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c23be18a-61cf-5be3-b257-75bcacae4235');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5270c62a-e969-540e-a2a3-c5b815826ed5','Diffuseness','The degree to which a sound field is uniform in energy and arrives equally from all directions, the ideal being a perfectly diffuse field with constant energy density and random, isotropic incidence. High diffuseness means reflections are dense and evenly distributed in direction, which underlies the assumptions of statistical room acoustics and reverberation-time theory. It can be quantified by direction-of-arrival uniformity or by an energy-based measure derived from the sound intensity and energy density of the field.','Diffuseness is how evenly sound comes from every direction. In a very even field the energy is the same all over. Sound reaches you from all sides at once. A perfect field is what reverb theory assumes.','It underpins statistical room acoustics, since even sound distribution is the assumption behind reverberation-time formulas and diffuse-field measurements.','Acousticians add diffusers and check diffuseness when validating reverberation-chamber measurements and hall acoustics.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Diffuse field','Reverberant field','Diffuser','Sound intensity','Reverberation time']::text[],ARRAY['Assuming any reverberant room is fully diffuse','Confusing diffuseness with loudness or reverberation time','Ignoring low-frequency non-diffuseness in small rooms']::text[],ARRAY['Validating a reverberation chamber''s diffuse field','Adding diffusers to even out a room','Assessing the directional uniformity of reflections']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Diffuseness');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5270c62a-e969-540e-a2a3-c5b815826ed5','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5270c62a-e969-540e-a2a3-c5b815826ed5') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5270c62a-e969-540e-a2a3-c5b815826ed5');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '63a64f5d-4378-5d55-94d8-0d45c31b24b7','Source strength','A measure of how strongly a sound source emits, defined most precisely for a simple (monopole) source as its volume velocity: the product of the vibrating surface area and its normal velocity amplitude, equal to the rate at which the source displaces the surrounding medium. Source strength sets the amplitude of the radiated pressure field and, together with frequency and radiation conditions, the radiated sound power. It is the fundamental quantity describing the output of an idealised acoustic source.','Source strength tells how strongly a source pushes out sound. For a simple source it is the amount of air it moves per second. That equals its area times its speed. It sets how loudly the source radiates.','It provides the basic input quantity for radiation calculations, linking a source''s physical motion to the pressure and power it produces.','Loudspeaker and transducer designers use volume velocity as source strength to predict low-frequency output and radiated power.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Volume velocity','Monopole','Sound power','Radiation','Source directivity']::text[],ARRAY['Confusing source strength (volume velocity) with the sound pressure at a point','Ignoring that radiated power also depends on frequency and loading','Assuming cone area alone gives output without cone velocity']::text[],ARRAY['Estimating a subwoofer''s low-frequency output from cone area and excursion','Modelling a small source as a monopole','Comparing the source strength of two drivers']::text[],'advanced','Q = S·u   (volume velocity)','The source strength, or volume velocity, equals the vibrating surface area times its normal velocity amplitude.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source strength');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '63a64f5d-4378-5d55-94d8-0d45c31b24b7','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='63a64f5d-4378-5d55-94d8-0d45c31b24b7') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='63a64f5d-4378-5d55-94d8-0d45c31b24b7');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '0b4edd52-58ef-5c24-90b2-3b78ca8148e4','Source directivity','The way a sound source radiates unevenly with direction, concentrating more energy along some angles than others. It is described by a directivity pattern, by the directivity factor comparing on-axis intensity to that of an omnidirectional source of equal power, and by the directivity index, its decibel form. Directivity generally increases with frequency as the source grows large compared with the wavelength, so real sources beam at high frequencies.','Source directivity is how a source aims its sound. Some directions get more energy than others. Sources beam more at high frequencies. Low notes spread out in all directions.','It describes how a source''s output is distributed in space, which is essential for aiming loudspeakers and predicting coverage.','Sound designers use loudspeaker directivity data to aim boxes, choose horns, and predict how evenly an audience is covered.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Directivity factor','Directivity index','Polar pattern','Beamwidth','Radiation']::text[],ARRAY['Assuming a source radiates equally in all directions at all frequencies','Confusing the directivity factor with the directivity index','Ignoring that directivity rises with frequency']::text[],ARRAY['Aiming a line array for even coverage','Choosing a horn for a target beamwidth','Reading a loudspeaker polar plot']::text[],'intermediate','DI = 10·log₁₀(Q)','The directivity index in decibels equals ten times the base-ten logarithm of the directivity factor.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Source directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '0b4edd52-58ef-5c24-90b2-3b78ca8148e4','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='0b4edd52-58ef-5c24-90b2-3b78ca8148e4') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='0b4edd52-58ef-5c24-90b2-3b78ca8148e4');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'c22a2de7-7a5f-59a7-92d5-1db55b1ddbc8','Receiver directivity','The direction-dependent sensitivity of a receiver such as a microphone, ear, or hydrophone, describing how its response varies with the angle of an arriving sound. It is characterised by a polar pattern and, like a source, by a directivity factor and directivity index; by reciprocity a transducer''s receiving directivity mirrors its behaviour as a source. Higher receiver directivity improves discrimination against off-axis sound and raises the direct-to-reverberant ratio.','Receiver directivity is how a microphone or ear favours some directions. On-axis sound is picked up strongest. Off-axis sound is rejected. A tighter pattern hears more of the source and less of the room.','It sets how well a receiver rejects unwanted directions, controlling pickup of noise, room sound, and feedback.','Engineers pick microphone polar patterns by their receiver directivity to reject spill, room sound, and feedback.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Polar pattern','Directivity factor','Directivity index','Microphone','Source directivity']::text[],ARRAY['Assuming all microphones are omnidirectional','Confusing receiver directivity with sensitivity or gain','Ignoring that polar patterns change with frequency']::text[],ARRAY['Choosing a cardioid microphone to reject spill','Aiming a shotgun microphone at a distant source','Reducing feedback by exploiting microphone directivity']::text[],'intermediate','DI = 10·log₁₀(Q)','The receiver directivity index in decibels equals ten times the base-ten logarithm of its directivity factor.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Receiver directivity');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'c22a2de7-7a5f-59a7-92d5-1db55b1ddbc8','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='c22a2de7-7a5f-59a7-92d5-1db55b1ddbc8') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='c22a2de7-7a5f-59a7-92d5-1db55b1ddbc8');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '34d96e96-d889-5174-93f2-e19f99b57b5e','Baffling','The use of a rigid surface, or baffle, to separate the front and rear radiation of a source and so alter its radiation, especially at low frequencies. Without a baffle the out-of-phase front and rear waves of a dipole-like source cancel, weakening bass; mounting the source in a baffle lengthens the acoustic path between the two sides, reducing this cancellation and raising low-frequency output. In the limit of an infinite baffle the source radiates into a half-space with no rear cancellation.','Baffling means putting a source in a panel to block its rear sound. The front and back waves of a bare driver cancel and kill the bass. A baffle keeps them apart. This restores low-frequency output.','It controls radiation by preventing front-to-back cancellation, mainly to recover low-frequency output from a dipole-like source.','Loudspeaker designers mount drivers on baffles or in enclosures to stop rear-wave cancellation and preserve bass.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Baffle','Dipole','Enclosure','Radiation','Low-frequency response']::text[],ARRAY['Ignoring rear-wave cancellation when mounting a bare driver','Assuming a small baffle helps at all low frequencies','Confusing an infinite baffle with a sealed enclosure']::text[],ARRAY['Mounting a driver on a baffle to test its response','Explaining thin bass from an unbaffled loudspeaker','Designing an open-baffle loudspeaker']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Baffling');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '34d96e96-d889-5174-93f2-e19f99b57b5e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='34d96e96-d889-5174-93f2-e19f99b57b5e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='34d96e96-d889-5174-93f2-e19f99b57b5e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '37066fb6-bf2c-5df1-abcc-ac59d2c03585','Tonal noise','Noise that carries one or more prominent discrete-frequency (tonal) components standing audibly above the surrounding broadband spectrum. Acoustic standards judge tonality objectively by comparing the level in a critical band centred on the tone with the level of the neighbouring bands, using measures such as the tone-to-noise ratio or the prominence ratio; a tone judged prominent typically triggers a penalty in environmental-noise ratings because tonal content is more noticeable and annoying than broadband noise of the same level.','Tonal noise is noise with a clear pitch inside it. A steady hum or whistle sits on top of the general hiss. The tone stands out because its energy is packed near one frequency. Meters judge it by comparing that band with the bands beside it. A strong tone is treated as more annoying than plain broadband noise.','Identifies noise whose energy concentrates at discrete frequencies, so it can be rated, penalised, and treated differently from broadband noise in assessments and control.','Technicians meet it when a transformer hum, fan blade tone, or switch-mode whine shows as a sharp spectral spike; environmental noise reports add a tonal penalty when prominence criteria are met.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Prominence','Tone-to-noise ratio','Broadband noise','Narrowband noise','Steady noise']::text[],ARRAY['Calling any spectral peak tonal without checking it meets a prominence or tone-to-noise criterion','Confusing a tonal noise component with a laboratory pure tone','Assuming a tone is unimportant just because its overall level is low']::text[],ARRAY['Flagging transformer hum as a prominent tone in a community noise survey','Diagnosing a fan blade-pass tone from a spike in the spectrum','Applying a tonal penalty when rating industrial noise']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Tonal noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '37066fb6-bf2c-5df1-abcc-ac59d2c03585','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='37066fb6-bf2c-5df1-abcc-ac59d2c03585') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='37066fb6-bf2c-5df1-abcc-ac59d2c03585');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '491273c2-462d-57fa-b7b3-c9d6fcff25b2','Fluctuating noise','Noise whose sound pressure level varies continuously and appreciably over the observation period, without settling to a steady value. Because the level moves throughout the measurement, an instantaneous reading is not representative, so fluctuating noise is characterised by time-averaged and statistical descriptors such as the equivalent continuous level and percentile levels rather than by a single steady value.','Fluctuating noise is noise whose loudness keeps changing. The level rises and falls all through the measurement. It never holds still long enough for one reading to describe it. So we use a time-averaged level instead. Percentile levels also show how often it was loud or quiet.','Signals that the level is time-varying, so measurements must use averaging and statistics rather than a single snapshot reading.','Technicians use an integrating meter to capture an equivalent level and percentile statistics for traffic, crowd, or wind-driven noise that never holds a steady value.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Steady noise','Intermittent noise','Equivalent continuous sound level','Percentile level','Time weighting']::text[],ARRAY['Reporting a single instantaneous reading as if it represents fluctuating noise','Confusing fluctuating noise with intermittent noise that drops to silence between events','Using too short an averaging time to capture the true spread of levels']::text[],ARRAY['Measuring road traffic noise that rises and falls with passing vehicles','Logging an equivalent level for varying crowd noise at a venue','Choosing a long enough measurement time for wind-driven noise']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Fluctuating noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '491273c2-462d-57fa-b7b3-c9d6fcff25b2','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='491273c2-462d-57fa-b7b3-c9d6fcff25b2') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='491273c2-462d-57fa-b7b3-c9d6fcff25b2');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '5c28d266-719a-530a-ac00-667f9fbd74e3','Intermittent noise','Noise that is present only during separated periods and falls back to the background level between events, so that identifiable quiet intervals occur. It is distinguished from steady and fluctuating noise by these on-and-off episodes, and is assessed both by the level during each event and by the duration and number of events, often using event descriptors and an equivalent continuous level over the whole period.','Intermittent noise comes in separate bursts. It is there for a while, then it stops. Between the bursts the sound drops back to the background. Each burst has its own level and length. We count the events and average over the whole time.','Describes noise that switches on and off, so that both the event level and how often events occur must be captured.','Technicians log pass-by events, plant that cycles on and off, or intermittent machinery, recording both each event level and an overall equivalent level.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Steady noise','Fluctuating noise','Equivalent continuous sound level','Sound exposure level','Background noise']::text[],ARRAY['Confusing intermittent noise with fluctuating noise that never returns to background','Ignoring the number of events and reporting only a single event level','Letting a short quiet gap hide the true energy of repeated events']::text[],ARRAY['Measuring aircraft fly-over events at a monitoring station','Assessing a compressor that cycles on and off through the day','Logging intermittent forklift reversing alarms in a warehouse']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Intermittent noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '5c28d266-719a-530a-ac00-667f9fbd74e3','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='5c28d266-719a-530a-ac00-667f9fbd74e3') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='5c28d266-719a-530a-ac00-667f9fbd74e3');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '44e10374-7e20-5d49-90e6-20efdee07fdf','Steady noise','Noise whose sound pressure level shows only negligibly small fluctuations over the observation period, so a short reading is representative of the whole. Because the level is essentially constant, steady noise can be described by a single time-weighted level, and it serves as the simplest case against which fluctuating, intermittent, and impulsive noise are contrasted.','Steady noise holds a roughly constant level. It does not swing up and down much while you measure. Because it stays put, one short reading describes it well. A fan or a steady hiss is a good example. It is the simplest kind of noise to measure.','Marks the simple case where the level is stable, so a single reading is trustworthy and averaging is straightforward.','Technicians take a short spot reading of a steady fan, motor, or ventilation hiss, confident the value represents the ongoing level.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Fluctuating noise','Intermittent noise','Broadband noise','Time weighting','Equivalent continuous sound level']::text[],ARRAY['Assuming noise is steady without watching the meter long enough to confirm it','Treating slowly drifting noise as steady when the level actually wanders','Believing a steady level means the noise is harmless']::text[],ARRAY['Reading the level of a steady ventilation fan','Checking a machine hum that holds a constant level','Using a short measurement for a stable background hiss']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Steady noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '44e10374-7e20-5d49-90e6-20efdee07fdf','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='44e10374-7e20-5d49-90e6-20efdee07fdf') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='44e10374-7e20-5d49-90e6-20efdee07fdf');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '30a794b6-5f2f-5d8b-95d7-3c75729ead6e','Low-frequency noise','Noise whose energy is concentrated in the low-frequency region of the audible spectrum, conventionally the range from roughly 10 Hz up to about 200 Hz. Low-frequency noise is significant because hearing sensitivity falls off steeply at low frequencies, walls and barriers attenuate it poorly, and it can excite structural resonances, so it often demands special weighting and assessment beyond the ordinary A-weighted level.','Low-frequency noise is noise made mostly of low pitches. Its energy sits down at the bass end of what we can hear. Our ears are less sensitive there, so it can be strong yet feel dull. Walls block it poorly, so it travels far. It can also make floors and windows buzz.','Highlights bass-heavy noise that ordinary weighting can understate and that passes easily through building structure.','Technicians investigate complaints about distant plant, bass from clubs, or HVAC where a low-frequency spectrum, not the A-weighted number, tells the real story.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Infrasound','Rumble','Broadband noise','A-weighting','Structural resonance']::text[],ARRAY['Relying on the A-weighted level, which strongly discounts low-frequency energy','Confusing low-frequency noise with infrasound below the hearing limit','Assuming a lightweight barrier will block low-frequency noise']::text[],ARRAY['Investigating a low bass complaint from a nightclub','Measuring rumble from a rooftop chiller into a flat below','Adding low-frequency analysis when A-weighted levels look acceptable']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Low-frequency noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '30a794b6-5f2f-5d8b-95d7-3c75729ead6e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='30a794b6-5f2f-5d8b-95d7-3c75729ead6e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='30a794b6-5f2f-5d8b-95d7-3c75729ead6e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '201f3ac1-e730-515b-adc7-2de10714f093','Infrasound','Acoustic energy at frequencies below the usual lower limit of human hearing, conventionally taken as below about 20 Hz. Infrasound is a real pressure oscillation that instruments can measure even though it is normally inaudible; at high levels it may be perceived as pressure or vibration rather than pitch, and it is generated by large slow sources such as wind, machinery, and natural events.','Infrasound is sound too low for people to hear. It sits below about twenty cycles per second. The pressure waves are real and can be measured. At strong levels you may feel it more than hear it. Big slow sources like wind and heavy machines make it.','Names the sub-audible low end that still exists physically, so it can be measured and controlled even though listeners cannot hear a pitch.','Technicians use extended-range microphones and analysers to capture ventilation, wind-turbine, or transport infrasound that ordinary weighted meters ignore.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Low-frequency noise','Ultrasound','Rumble','Hertz','Audibility threshold']::text[],ARRAY['Assuming infrasound is not there because nobody can hear a pitch','Confusing felt vibration from infrasound with airborne audible sound','Expecting a standard A-weighted meter to show infrasonic energy']::text[],ARRAY['Measuring infrasound near a wind turbine','Checking sub-20 Hz output from a large ventilation system','Investigating a felt pressure complaint with no audible tone']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Infrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '201f3ac1-e730-515b-adc7-2de10714f093','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='201f3ac1-e730-515b-adc7-2de10714f093') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='201f3ac1-e730-515b-adc7-2de10714f093');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '2be7061d-2fcd-5769-954f-9ee6f314a31a','Ultrasound','Acoustic energy at frequencies above the usual upper limit of human hearing, conventionally taken as above about 20 kHz. Ultrasound is a mechanical vibration of the medium that behaves like audible sound but at shorter wavelengths, giving it more directional beams and stronger absorption in air; it is exploited in ranging, cleaning, and medical imaging and is measured with transducers designed for the extended range.','Ultrasound is sound too high for people to hear. It sits above about twenty thousand cycles per second. It is still a real sound wave, just very high-pitched. Its short waves travel in tight beams. We use it for cleaning, sensing, and medical scans.','Names the above-audible high end so it can be generated, aimed, and measured for sensing, cleaning, and imaging uses.','Technicians work with ultrasonic transducers in cleaning baths, distance sensors, and imaging gear, using instruments rated well above the audio band.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Infrasound','Frequency','Wavelength','Transducer','Hertz']::text[],ARRAY['Believing ultrasound cannot affect equipment because people cannot hear it','Confusing ultrasound with merely very loud high-pitched audible sound','Trying to measure ultrasound with a microphone rolled off above 20 kHz']::text[],ARRAY['Operating an ultrasonic parts-cleaning bath','Using an ultrasonic sensor for distance measurement','Selecting a wide-band microphone to capture energy above 20 kHz']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Ultrasound');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '2be7061d-2fcd-5769-954f-9ee6f314a31a','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='2be7061d-2fcd-5769-954f-9ee6f314a31a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='2be7061d-2fcd-5769-954f-9ee6f314a31a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f98a2f3c-e1e5-52b6-be2e-87473e16994d','Rumble','A low-frequency noise, broadband or partly tonal, perceived as a deep continuous rolling sound, typically arising from mechanical vibration coupled into the air or structure. In audio playback the term also names the standardised low-frequency disturbance from a turntable''s bearing and drive, quantified with a rumble weighting curve; more generally it describes low-end noise from traffic, machinery, or ventilation.','Rumble is a deep, rolling low-pitched noise. You feel its heaviness as much as hear it. It usually comes from something vibrating, like a motor or a bearing. In record players it means the low hum from the turntable. Traffic and big machines also cause rumble.','Labels deep, low-frequency noise so it can be identified and reduced, whether from playback gear, structure, or outside sources.','Technicians high-pass filter turntable and stage rumble, and trace building rumble back to vibrating plant carried through the structure.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Low-frequency noise','Infrasound','High-pass filter','Structural resonance','Steady noise']::text[],ARRAY['Confusing broadband rumble with a single low tone','Trying to fix structure-borne rumble with airborne absorption only','Assuming a high-pass filter removes rumble without checking the corner frequency']::text[],ARRAY['Applying a rumble filter to a turntable feed','Tracing floor rumble to a vibrating rooftop fan','Cutting low-end stage rumble picked up by microphones']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Rumble');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f98a2f3c-e1e5-52b6-be2e-87473e16994d','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f98a2f3c-e1e5-52b6-be2e-87473e16994d') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f98a2f3c-e1e5-52b6-be2e-87473e16994d');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '8a521906-c7f6-5296-a081-9031df69d902','Whine','A noise perceived as a sustained high- or mid-frequency tone, usually arising from rotating or resonating machinery such as motors, gears, bearings, or switch-mode power supplies. As a largely tonal noise its energy concentrates near one or a few frequencies, so it is both readily identified by ear and traceable in a spectrum to the rotational or switching rate that produces it.','A whine is a steady high-pitched tone. It cuts through other noise because it has a clear pitch. Spinning parts like motors, gears, and fans often cause it. Switch-mode power supplies can whine too. You can trace it to the speed of the part that makes it.','Names a tonal high-frequency noise so it can be identified by ear and matched in a spectrum to its mechanical or electrical source.','Technicians track a whine to a bearing, gear mesh, cooling fan, or switch-mode supply by matching its frequency to the part''s operating rate.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Tonal noise','Electrical noise','Prominence','Frequency']::text[],ARRAY['Assuming any high-pitched noise is electrical rather than mechanical','Confusing a mechanical whine with switch-mode power-supply whine','Trying to filter a whine without first finding its source frequency']::text[],ARRAY['Diagnosing a cooling-fan bearing whine from a spectral peak','Tracing a switch-mode power-supply whine in an amplifier','Matching a gear whine to the gear mesh frequency']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Whine');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '8a521906-c7f6-5296-a081-9031df69d902','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='8a521906-c7f6-5296-a081-9031df69d902') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='8a521906-c7f6-5296-a081-9031df69d902');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '67c59476-efd5-5e66-b4f7-84addc92692e','Masking noise','Noise that reduces or removes the audibility of another sound by raising its threshold of detection, an effect known as masking. The masking noise dominates within critical bands near the target sound''s frequencies, so the target must be raised in level to be heard; masking is exploited deliberately for privacy and to cover distracting sounds, and it underlies perceptual audio coding.','Masking noise is noise that hides another sound. It fills the ears near the wanted sound''s pitch. That forces the wanted sound to be louder before you notice it. Offices use it to cover speech for privacy. The same idea lets audio codecs drop hidden detail.','Explains and uses the way one sound covers another, for speech privacy, comfort masking, and perceptual coding decisions.','Technicians set sound-masking systems in offices and pick codec bitrates knowing that louder nearby energy hides quieter detail.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Masking','Critical band','Audibility threshold','Broadband noise','Signal-to-noise ratio']::text[],ARRAY['Thinking masking works only when the masker is louder across all frequencies','Ignoring that masking is strongest for sounds near the masker''s frequency','Confusing masking with simply turning the wanted sound down']::text[],ARRAY['Tuning an office sound-masking system for speech privacy','Explaining why quiet detail disappears under loud background noise','Relating perceptual codec choices to masking thresholds']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Masking noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '67c59476-efd5-5e66-b4f7-84addc92692e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='67c59476-efd5-5e66-b4f7-84addc92692e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='67c59476-efd5-5e66-b4f7-84addc92692e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'f40f7790-3524-5ba2-8749-1d5956fc7770','Electrical noise','Unwanted electrical fluctuation added to a signal within electronic circuits and interconnections, distinct from acoustic noise. It includes fundamental sources such as thermal (Johnson) noise and shot noise, device flicker noise, and externally coupled interference such as mains hum, radio-frequency pickup, and ground-loop currents; it sets the noise floor of audio systems and is managed by circuit design, shielding, and grounding.','Electrical noise is unwanted noise made inside the wiring and circuits. It is not sound in the air. Some of it comes from heat jostling electrons in parts. Some is picked up from mains hum or radio signals. It sets how quiet a system can be.','Names the electrical noise floor of a system so it can be minimised through design, shielding, and correct grounding.','Technicians chase hum and hiss with proper grounding, shielded cable, and gain staging to keep the electrical noise floor below the wanted signal.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Noise floor','Thermal noise','Hum','Ground loop','Signal-to-noise ratio']::text[],ARRAY['UNSAFE: lifting a mains earth pin to cure hum instead of fixing the ground loop, defeating protective earthing','Blaming a room for hiss that is actually electrical noise in the chain','Assuming all electrical noise is interference rather than fundamental thermal noise']::text[],ARRAY['Tracing a mains hum through a ground loop in a rack','Estimating the noise floor set by a preamp''s thermal noise','Shielding a cable run to stop radio-frequency pickup']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Electrical noise');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'f40f7790-3524-5ba2-8749-1d5956fc7770','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='f40f7790-3524-5ba2-8749-1d5956fc7770') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='f40f7790-3524-5ba2-8749-1d5956fc7770');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6e7ff55c-6b27-528d-8ad0-d7187e9b1f48','Audibility threshold','The lowest sound pressure level of a specified signal that a listener can just detect under stated conditions of frequency, presentation, and background. Because hearing sensitivity varies strongly with frequency, the threshold traces a curve across the spectrum; the standardised threshold in quiet for normal-hearing young listeners is most sensitive near 3 to 4 kHz and rises steeply toward low and very high frequencies, and it anchors the reference for audiometry.','The audibility threshold is the quietest sound you can just hear. It depends on the sound''s pitch. Ears hear best around three to four thousand cycles per second. Much lower or higher sounds must be louder to be noticed. This lowest-level curve sets the baseline for hearing tests.','Defines the quietest detectable sound versus frequency, giving the reference floor for hearing tests and for loudness and audibility work.','Technicians and audiologists relate measured levels to this threshold when setting hearing-test references or judging whether a faint sound is audible.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Threshold of hearing','Equal-loudness contour','Pain threshold','Sound pressure level','Masking noise']::text[],ARRAY['Treating the threshold as one fixed level instead of a frequency-dependent curve','Confusing the threshold in quiet with a masked threshold in noise','Assuming everyone shares the same threshold regardless of hearing status']::text[],ARRAY['Referencing audiometer levels to the standard hearing threshold','Judging whether a faint tone is audible in a quiet room','Explaining why low-frequency sounds need more level to be heard']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Audibility threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6e7ff55c-6b27-528d-8ad0-d7187e9b1f48','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6e7ff55c-6b27-528d-8ad0-d7187e9b1f48') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6e7ff55c-6b27-528d-8ad0-d7187e9b1f48');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '891448cd-042a-5226-820e-ab6c28fc486a','Pain threshold','The sound pressure level at which sound is perceived as physically painful, conventionally cited near 120 to 140 dB SPL depending on the individual and criterion. It marks the upper end of the auditory dynamic range, well above levels that cause hearing damage, so it is a perceptual landmark rather than a safe-exposure limit; exposure guidance is set far lower to protect against noise-induced hearing loss.','The pain threshold is where sound starts to hurt. It sits very high, around 120 to 140 decibels. It marks the top of what the ear can take. It is not a safe limit at all. Hearing damage happens well below this point.','Marks the top of the hearing range as a perceptual landmark, while making clear that safe-exposure limits sit far below it.','Technicians cite it to bound the dynamic range of hearing but rely on much lower exposure limits when protecting crew and audiences.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Threshold of hearing','Dynamic range','Sound pressure level','Noise exposure','Hearing damage']::text[],ARRAY['UNSAFE: treating the pain threshold as a safe exposure limit, since damage occurs at far lower levels','Assuming everyone feels pain at exactly the same level','Confusing the onset of pain with the onset of hearing damage']::text[],ARRAY['Describing the upper bound of the hearing dynamic range','Contrasting the pain level with much lower exposure limits','Explaining why loud shows still risk damage below the pain point']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Pain threshold');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '891448cd-042a-5226-820e-ab6c28fc486a','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='891448cd-042a-5226-820e-ab6c28fc486a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='891448cd-042a-5226-820e-ab6c28fc486a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '21d692a8-f965-5cca-be8d-628965383c6a','Prominence','The degree to which a spectral feature, usually a tone, perceptually stands out from the surrounding noise. It is made objective in noise assessment through the prominence ratio, which compares the sound pressure level in the critical band containing the candidate tone with the average level of the two adjacent critical bands; a tone exceeding a defined prominence criterion is treated as a prominent discrete tone and may attract a rating penalty.','Prominence is how much a tone stands out from the noise around it. A tone with high prominence grabs attention. Meters judge it by comparing the tone''s frequency band with the bands next door. If the tone sticks out far enough, it counts as prominent. Prominent tones are treated as more annoying.','Turns the sense of a tone standing out into a measurable quantity, so tonal noise can be judged and penalised consistently.','Technicians compute a prominence ratio from a spectrum to decide whether a fan, transformer, or motor tone triggers a tonal penalty in a noise report.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Tonal noise','Tone-to-noise ratio','Critical band','Masking noise','Narrowband noise']::text[],ARRAY['Treating any visible peak as prominent without applying the prominence criterion','Confusing prominence with the tone''s absolute level','Ignoring the adjacent-band comparison that defines the prominence ratio']::text[],ARRAY['Computing a prominence ratio for a suspected transformer tone','Deciding whether a fan tone earns a tonal penalty','Comparing a tone''s critical band with its neighbours in a survey']::text[],'advanced',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Prominence');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '21d692a8-f965-5cca-be8d-628965383c6a','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='21d692a8-f965-5cca-be8d-628965383c6a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='21d692a8-f965-5cca-be8d-628965383c6a');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '324d8207-99ee-5ea1-ad36-6a214254cb57','Modulation transfer','The extent to which the amplitude modulations of a signal are preserved as it passes through a system or room, expressed as the modulation transfer function giving the ratio of output to input modulation depth as a function of modulation frequency. Reverberation, noise, and distortion all reduce this ratio; the concept underlies the speech transmission index, which weights the reduction in modulation across bands into a single intelligibility metric.','Modulation transfer measures how well the ups and downs of a sound survive a room or system. Speech carries meaning in how its level rises and falls. Echoes and noise smear those changes and fill the dips. The modulation transfer value is the output swing divided by the input swing. Low values mean speech gets harder to understand.','Quantifies how much a room or system blurs a signal''s level changes, forming the basis of objective speech-intelligibility metrics.','Technicians derive the speech transmission index from band modulation transfer values to rate intelligibility of paging and announcement systems.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Modulation transfer function','Speech transmission index','Reverberation time','Signal-to-noise ratio','Intelligibility']::text[],ARRAY['Treating modulation transfer as a simple frequency response rather than a modulation-domain measure','Ignoring background noise, which fills modulation dips and lowers the ratio','Assuming a flat frequency response guarantees good modulation transfer']::text[],ARRAY['Measuring the speech transmission index of a station paging system','Assessing how reverberation degrades announcement intelligibility','Comparing modulation transfer before and after acoustic treatment']::text[],'advanced','m = m_out / m_in','Modulation transfer equals the output modulation depth divided by the input modulation depth, evaluated at each modulation frequency.','c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Modulation transfer');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '324d8207-99ee-5ea1-ad36-6a214254cb57','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'advanced' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='324d8207-99ee-5ea1-ad36-6a214254cb57') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='324d8207-99ee-5ea1-ad36-6a214254cb57');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '07be9d1b-eec5-51e8-8583-7f32b863793e','Measurement height','The vertical distance of the measurement microphone above the floor or ground, fixed by the applicable standard because level and spectrum change with height through reflections and source directivity. Typical prescribed values include heights around 1.2 to 1.5 m for occupied-space and community measurements, with greater heights specified for some outdoor and facade assessments to control ground-reflection effects.','Measurement height is how high the microphone sits above the floor or ground. It matters because reflections change with height. Standards fix the height so results can be compared. Common indoor heights are about 1.2 to 1.5 metres. Outdoor jobs may call for a greater height.','Standardises where the microphone sits vertically so measurements are repeatable and ground reflections are controlled.','Technicians set the microphone to the height named in the standard, using a tripod, so their readings match others and account for reflections.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Ground reflection','Reference distance','Microphone orientation','Free-field condition','Incidence angle']::text[],ARRAY['Guessing a height instead of using the value the standard specifies','Ignoring how ground reflections shift the level with height','Placing the microphone at ear height when the standard asks for another height']::text[],ARRAY['Setting a 1.5 m microphone height for a community noise survey','Choosing a facade measurement height per the standard','Using a tripod to hold a repeatable measurement height']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Measurement height');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '07be9d1b-eec5-51e8-8583-7f32b863793e','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='07be9d1b-eec5-51e8-8583-7f32b863793e') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='07be9d1b-eec5-51e8-8583-7f32b863793e');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'aeb292a3-35bd-503e-bf78-c813478ceb80','Microphone orientation','The direction the microphone diaphragm faces relative to the incoming sound, chosen to match the microphone''s designed field response. A free-field microphone is aimed directly at the source so sound arrives at normal (0 degree) incidence, for which its response is corrected, whereas a random-incidence or pressure microphone is oriented as its type specifies; wrong orientation introduces frequency-response errors at high frequencies.','Microphone orientation is the way the mic is pointed at the sound. Each mic type is built for a certain direction. A free-field mic should point straight at the source. A random-incidence mic is aimed as its instructions say. Pointing it wrong adds errors at high frequencies.','Ensures the microphone faces the sound in the way its design assumes, so its frequency response stays correct.','Technicians aim a free-field measurement microphone at the source and set random-incidence types per the manual to avoid high-frequency response errors.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Incidence angle','Random-incidence microphone','Free-field condition','Measurement height','Instrument response']::text[],ARRAY['Pointing a free-field microphone away from the source','Confusing which orientation a free-field versus random-incidence type needs','Assuming orientation does not matter because errors are small at low frequencies']::text[],ARRAY['Aiming a free-field microphone straight at a loudspeaker under test','Orienting a random-incidence microphone in a diffuse room','Correcting a high-frequency error caused by wrong microphone aim']::text[],'beginner',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Microphone orientation');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'aeb292a3-35bd-503e-bf78-c813478ceb80','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'beginner' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='aeb292a3-35bd-503e-bf78-c813478ceb80') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='aeb292a3-35bd-503e-bf78-c813478ceb80');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT '6f165f08-4862-5b79-b9e5-6e51a08da262','Incidence angle','The angle between the direction of sound propagation and the microphone''s principal (reference) axis, with zero degrees denoting sound arriving head-on. The incidence angle governs how the microphone''s response deviates from its calibrated free-field response, because diffraction around the microphone body raises the high-frequency response for axial incidence and alters it at oblique angles; standards therefore state the incidence for which a microphone is corrected.','Incidence angle is the angle sound makes with the mic''s main axis. Zero degrees means the sound hits it head-on. The angle changes how the mic responds at high frequencies. This is because sound bends around the mic body. Standards say which angle a mic is corrected for.','Describes the arrival angle of sound, which sets how far a microphone departs from its calibrated response.','Technicians control incidence angle in anechoic and calibration work, aligning the microphone so the sound arrives at the angle for which it is corrected.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Microphone orientation','Free-field condition','Random-incidence microphone','Diffraction','Instrument response']::text[],ARRAY['Assuming incidence angle only matters at low frequencies','Confusing incidence angle with the microphone''s polar pattern','Ignoring the angle a microphone''s free-field correction assumes']::text[],ARRAY['Aligning a microphone for normal-incidence anechoic measurement','Explaining a high-frequency lift from head-on incidence','Setting arrival angle in a loudspeaker directivity test']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Incidence angle');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT '6f165f08-4862-5b79-b9e5-6e51a08da262','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='6f165f08-4862-5b79-b9e5-6e51a08da262') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='6f165f08-4862-5b79-b9e5-6e51a08da262');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'a01549ac-5c9e-5d78-a2cf-1326590ba4f0','Random-incidence microphone','A measurement microphone whose frequency response is corrected for sound arriving simultaneously from all directions, as in a diffuse (reverberant) field, rather than from a single frontal direction. Its diffuse-field correction averages the diffraction effects over all incidence angles, so it reads accurately where sound is randomly incident, and it is the type specified for reverberation-room and many building-acoustics measurements.','A random-incidence microphone is built for sound coming from every direction at once. That happens in a very reflective room. Its response is corrected by averaging over all arrival angles. So it reads correctly in a diffuse field. It is the type used for reverberation-room tests.','Provides accurate readings where sound arrives from all directions, as in diffuse fields and reverberation rooms.','Technicians choose a random-incidence microphone for reverberation-room absorption tests and diffuse-field building-acoustics work.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Diffuse field','Incidence angle','Microphone orientation','Reverberant condition','Free-field condition']::text[],ARRAY['Using a free-field microphone where sound is actually diffuse','Assuming random-incidence and free-field microphones read the same at high frequencies','Orienting a random-incidence microphone as if only frontal sound mattered']::text[],ARRAY['Measuring absorption in a reverberation room','Selecting a diffuse-field microphone for building-acoustics tests','Reading levels in a highly reflective enclosed space']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Random-incidence microphone');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'a01549ac-5c9e-5d78-a2cf-1326590ba4f0','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='a01549ac-5c9e-5d78-a2cf-1326590ba4f0') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='a01549ac-5c9e-5d78-a2cf-1326590ba4f0');
INSERT INTO glossary (id,term,definition,plain_english,purpose_function,practical_application,category,related_terms,common_mistakes,scenario_contexts,difficulty,formula_symbolic,formula_words,achievement_id) SELECT 'b49650af-427b-5e78-9fea-7f167e1e591a','Windscreen correction','A correction that accounts for the change a windscreen imposes on the microphone''s frequency response, chiefly a small high-frequency attenuation (insertion loss) caused by the foam or fabric cover. Sound level meter standards require the windscreen''s effect to be characterised and, where significant, corrected so that measured levels remain within tolerance while the windscreen reduces wind and turbulence noise outdoors.','A windscreen correction fixes the small change a foam cover adds. The cover cuts wind noise but also softens very high frequencies a little. The correction adds that lost bit back so readings stay accurate. Meter standards require this effect to be known. It keeps outdoor levels within tolerance.','Compensates for the windscreen''s small high-frequency loss so protected outdoor measurements stay within accuracy limits.','Technicians apply the maker''s windscreen correction, or use a characterised windscreen, when measuring outdoors with a foam cover fitted.','Sound Physics, Measurement & Acoustic Quantities',ARRAY['Wind-induced noise','Windscreen','Instrument response','Free-field condition','Meteorological condition']::text[],ARRAY['Ignoring the small high-frequency loss a windscreen adds','Assuming every windscreen has the same correction','Leaving the windscreen off outdoors and blaming wind noise on the meter']::text[],ARRAY['Correcting high-frequency levels when a windscreen is fitted outdoors','Choosing a characterised windscreen for a survey','Balancing wind-noise reduction against response change']::text[],'intermediate',NULL,NULL,'c6987d6b-2547-441b-8cd1-88847ade6bae' WHERE NOT EXISTS (SELECT 1 FROM glossary WHERE term='Windscreen correction');
INSERT INTO glossary_topics (glossary_id,achievement_id,is_primary,difficulty) SELECT 'b49650af-427b-5e78-9fea-7f167e1e591a','c6987d6b-2547-441b-8cd1-88847ade6bae',true,'intermediate' WHERE EXISTS (SELECT 1 FROM glossary WHERE id='b49650af-427b-5e78-9fea-7f167e1e591a') AND NOT EXISTS (SELECT 1 FROM glossary_topics WHERE glossary_id='b49650af-427b-5e78-9fea-7f167e1e591a');
